-- ----------------------------
-- Table structure for approve_log
-- ----------------------------
DROP TABLE IF EXISTS `approve_log`;
CREATE TABLE `approve_log`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `document_type` smallint(6) NOT NULL COMMENT '单据交易类型 1采购入库 2退货出库 3领料出库 4退料入库 5调拨 6盘点 7报废 8采购单 9采购退货单 10采购换货单 11退库清单12维修工单13保养工单14巡点检记录 15空罐卷封检验报告 16内涂模检验报告 17顶盖/底盖检验报告 18热缩膜检验报告 19纸皮进货验报告 20原料标签标识报告 21空罐进货检验报告 22战马空罐检验报告 23原材料使用通知单 24成品入库单',
  `document_id` int(11) NOT NULL COMMENT '单据id',
  `user_id` int(10) NOT NULL COMMENT '提审人id',
  `operation_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作类型',
  `operation_id` smallint(6) NOT NULL COMMENT '操作类型id 1提交 2待审批 3审批通过 4驳回 5撤回 6中止执行 7仓库待确认 8仓库已确认 9仓库已驳回 10其他人已处理11领料人待确认12领料人已确认13其它人已领取14:发料撤回15调入仓待确认16调入仓已确认 17调入仓已驳回18调入仓其他人已处理19反审20删除21作废',
  `operation_time` timestamp NULL DEFAULT NULL COMMENT '操作时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_final` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否最终审批步骤',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 79985 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '审批日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for certificate_report_apply
-- ----------------------------
DROP TABLE IF EXISTS `certificate_report_apply`;
CREATE TABLE `certificate_report_apply`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `name_level` tinyint(1) NOT NULL DEFAULT 1 COMMENT '证照级别id 1=公司级；2=员工级',
  `name_level_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证照级别名称',
  `name_id` int(11) NULL DEFAULT NULL COMMENT '证照名称id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证照名称',
  `type_id` tinyint(1) NULL DEFAULT NULL COMMENT '证照类型id',
  `type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证照类型',
  `file_type_id` tinyint(1) NULL DEFAULT NULL COMMENT '文件类型id 1=电子档；2=纸质档',
  `file_type_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件类型',
  `apply_type_id` tinyint(1) NULL DEFAULT NULL COMMENT '申请类型id 1=借阅；2=查阅',
  `apply_type_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请类型',
  `apply_uid` int(10) NULL DEFAULT NULL COMMENT '申请人id',
  `apply_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请人',
  `apply_dept_id` int(10) NULL DEFAULT NULL COMMENT '申请人部门id',
  `apply_dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请人部门',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请原因',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提审；1=待验收；2=待办理；3=驳回；4=撤回；5=办理待确认；6=待归还；7=归还待确认；8=已完成；9=已作废',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `manage_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '办理备注',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '办理附件',
  `scene_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场照片',
  `apply_back_date` datetime NULL DEFAULT NULL COMMENT '申请归还时间',
  `sure_back_date` datetime NULL DEFAULT NULL COMMENT '确认归还时间',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '证照借阅、查阅提报申请' ROW_FORMAT = Dynamic;

