-- ----------------------------
-- Table structure for d_ck_date
-- ----------------------------
DROP TABLE IF EXISTS `d_ck_date`;
CREATE TABLE `d_ck_date`  (
  `date_cat` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '日期类型：d, w, m',
  `date_id` date NOT NULL COMMENT '日期id：yyyy-mm-dd',
  `year_month` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'yyyy-mm',
  `year` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'yyyy',
  `quarter` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'q',
  `year_quarter` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'yyyy-q',
  `month` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'mm',
  `day` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'dd',
  `week` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '周几',
  `quarter_start_date` date NOT NULL COMMENT '季起日',
  `quarter_end_date` date NOT NULL COMMENT '季止日',
  `month_start_date` date NOT NULL COMMENT '月起日',
  `month_end_date` date NOT NULL COMMENT '月止日',
  `week_start_date` date NOT NULL COMMENT '周起日',
  `week_end_date` date NOT NULL COMMENT '周止日',
  `monthend` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '是否月末',
  `weekend` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '是否周末',
  `week_in_month` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'w',
  `year_month_week` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'yyyy-mm-w',
  `prior_date_id` date NOT NULL COMMENT '上一个环比日',
  `next_date_id` date NOT NULL COMMENT '下一个环比日',
  `update_ts` int(10) UNSIGNED NOT NULL,
  PRIMARY KEY (`date_cat`, `date_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin COMMENT = '日期维表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for dept_list
-- ----------------------------
DROP TABLE IF EXISTS `dept_list`;
CREATE TABLE `dept_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '权限ID',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '部门名称',
  `pid` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '父id,0顶级',
  `top_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '最顶级ID',
  `rank` int(10) NULL DEFAULT 0 COMMENT '菜单排序,越大越前',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `n-p`(`name`, `pid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '部门列表' ROW_FORMAT = Dynamic;

-- ----------------------------
