-- ----------------------------
-- Table structure for emis_energy_hierarchy_statistic_plan_config
-- ----------------------------
DROP TABLE IF EXISTS `emis_energy_hierarchy_statistic_plan_config`;
CREATE TABLE `emis_energy_hierarchy_statistic_plan_config`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '权限ID',
  `type` tinyint(1) UNSIGNED NOT NULL COMMENT '方案类型；1：区域；2：车间；3：产线；4：具体位置；5：综合能耗；6：基地',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '统计名称；如：统计区域名称',
  `area_category_id` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '区域类别id',
  `area_category_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '区域类别名称',
  `workshop_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '车间id',
  `workshop_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '车间名字',
  `line_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '所属线别id',
  `line_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '线别名称',
  `water_formula_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '水公式文本（回显用）',
  `water_formula_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '水公式结构化数据JSON（token数组）',
  `electric_formula_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电公式文本（回显用）',
  `electric_formula_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '电公式结构化数据JSON（token数组）',
  `steam_formula_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '蒸汽公式文本（回显用）',
  `steam_formula_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '蒸汽公式结构化数据JSON（token数组）',
  `gas_formula_text` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '燃气公式文本（回显用）',
  `gas_formula_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '燃气公式结构化数据JSON（token数组）',
  `rank` int(10) NULL DEFAULT 0 COMMENT '菜单排序,越大越前',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基地层级统计方案配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
