  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基地层级统计方案配置明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_energy_statistics_plan
-- ----------------------------
DROP TABLE IF EXISTS `emis_energy_statistics_plan`;
CREATE TABLE `emis_energy_statistics_plan`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '方案名称',
  `dimension` tinyint(1) NOT NULL COMMENT '统计维度 1-按月统计 2-按天统计 3-按班次统计',
  `type` tinyint(1) NOT NULL COMMENT '抄表类型；0：电表；1：水表；2：蒸汽表 3：燃气表',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `total_power_consumption_formula` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '总用电量计算公式',
  `total_power_loss_formula` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '总电损量计算公式',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '能源统计方案设定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_energy_statistics_plan_one
-- ----------------------------
DROP TABLE IF EXISTS `emis_energy_statistics_plan_one`;
CREATE TABLE `emis_energy_statistics_plan_one`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '能源统计方案设定表id',
  `type` tinyint(1) NOT NULL COMMENT '统计类型 1-标题 2-层级 3-仪表 4-小计 5-总计',
  `level` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪表层级',
  `energy_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '能源仪表',
  `rel_id` int(10) NULL DEFAULT NULL COMMENT '仪表id',
  `group_id` int(10) NULL DEFAULT NULL COMMENT '仪表分组id',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 341 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '能源统计方案设定表-统计内容设定' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_energy_statistics_plan_two
-- ----------------------------
DROP TABLE IF EXISTS `emis_energy_statistics_plan_two`;
CREATE TABLE `emis_energy_statistics_plan_two`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '能源统计方案设定表id',
  `title` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标题',
  `calculation_formula` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计算公式',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '能源统计方案设定表-差值/损耗计算' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_equipment_config
-- ----------------------------
DROP TABLE IF EXISTS `emis_equipment_config`;
CREATE TABLE `emis_equipment_config`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备型号(类型)',
  `trans_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '数据传输方式；1：主动；2：被动',
  `tab_type` tinyint(1) NULL DEFAULT 1 COMMENT 'tab类型；1：设备部；2：行政部；',
  `ip` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP/ID',
  `port` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '端口',
  `transformer_val` decimal(10, 2) NULL DEFAULT NULL COMMENT '互感器倍率',
  `eq_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备名称',
  `base` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基地标识',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；1：正常；2：异常',
  `address` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '地点',
  `frequency_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '采集频率',
  `station_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '站号',
  `upper_limit_range_val` int(11) NULL DEFAULT NULL COMMENT '量程上限值',
  `multiplier` decimal(8, 2) NULL DEFAULT NULL COMMENT '流量倍率',
  `file_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `module_type` tinyint(1) NULL DEFAULT 5 COMMENT '0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统	',
  `mtype` tinyint(1) NULL DEFAULT NULL COMMENT '所属模块；0：设备管理；1：质量管理；2：生产管理；3：行政管理',
  `order_type` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据类型,多个用逗号隔开',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `base`(`base`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `ip`(`ip`) USING BTREE,
  INDEX `port`(`port`) USING BTREE,
  INDEX `station_no`(`station_no`) USING BTREE,
  INDEX `category`(`category`) USING BTREE,
  INDEX `mtype`(`mtype`) USING BTREE,
  INDEX `eq_type`(`category`, `ip`, `port`, `station_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_equipment_config_log
-- ----------------------------
DROP TABLE IF EXISTS `emis_equipment_config_log`;
CREATE TABLE `emis_equipment_config_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `document_id` int(10) UNSIGNED NOT NULL COMMENT '对应记录id',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `before_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作前数据',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `replacement_id`(`document_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采集配置操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for emis_gas_meter_config
-- ----------------------------
DROP TABLE IF EXISTS `emis_gas_meter_config`;
CREATE TABLE `emis_gas_meter_config`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `eq_id` int(11) NULL DEFAULT NULL COMMENT '设备ID',
  `rel_id` int(11) NOT NULL DEFAULT 0 COMMENT '采集表名id',
  `rel_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '远程仪表名称',
  `eq_type` int(11) NULL DEFAULT NULL COMMENT '仪表类型ID',
  `director_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集负责人id，多个用,隔开',
  `last_gather_time` datetime NULL DEFAULT NULL COMMENT '最近采集时间',
  `auto_rule_type` tinyint(1) NULL DEFAULT NULL COMMENT '自动抄表规则 0 不自动 1 按班次 2 按每天 3 按每月',
  `is_join_calc` tinyint(1) NULL DEFAULT 1 COMMENT '是否参与核算；1：否；2：是',
  `is_statistics` tinyint(1) NULL DEFAULT 2 COMMENT '是否统计用量；1：否；2：是',
  `monthly_upper_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '每月上限值',
  `annual_upper_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '年度上限值',
  `num` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '读数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `daily_upper_num` decimal(10, 2) NULL DEFAULT NULL COMMENT '每日预警上限值',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `night_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '夜班预警上限值',
  `day_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '白班预警上限值',
  `middle_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '中班预警上限值',
  `area_id` tinyint(1) NULL DEFAULT NULL COMMENT '采集表区域id；1：生产区；2：生活区；',
  `group_id` int(11) NULL DEFAULT NULL COMMENT '所属分组id',
  `hierarchy_type` tinyint(1) NULL DEFAULT NULL COMMENT '层级类型id',
  `process` tinyint(2) NULL DEFAULT NULL COMMENT '工序id',
  `multiplier` decimal(8, 2) NULL DEFAULT 1.00 COMMENT '倍率',
  `monthly_max_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最大值',
  `monthly_min_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最小值',
  `director_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集负责人文本，多个用,隔开',
  `meter_lower_num` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '表码数下限',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `auto_rule_type`(`auto_rule_type`) USING BTREE,
  INDEX `eq_id`(`eq_id`) USING BTREE,
  INDEX `rel_id`(`rel_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '燃气表采集配置记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_log
-- ----------------------------
DROP TABLE IF EXISTS `emis_log`;
CREATE TABLE `emis_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `document_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '对应单据id',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `before_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作前数据',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `replacement_id`(`document_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 655 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '抄表记录操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for emis_meter_abnormal_log
-- ----------------------------
DROP TABLE IF EXISTS `emis_meter_abnormal_log`;
CREATE TABLE `emis_meter_abnormal_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '抄表类型；0：电表；1：水表；2：蒸汽表 3：燃气表',
  `task_id` int(11) NULL DEFAULT NULL COMMENT '关联的任务id',
  `rel_id` int(11) NULL DEFAULT NULL COMMENT '采集表id',
  `rel_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '远程仪表名称',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；1：未处理；2：已处理',
  `deal_uid` int(11) NULL DEFAULT NULL COMMENT '处理人uid',
  `deal_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理人名字',
  `config_id` int(11) NULL DEFAULT NULL COMMENT '配置记录id',
  `reason_type` tinyint(1) NULL DEFAULT NULL COMMENT '能源采集异常类型；1：数据采集异常；2：连接异常（小曾-无效）；3：连接异常（小曾-设备断开）；4：连接异常（监控时长报警）',
  `res_json_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '接口相关数据,json格式',
  `last_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '上次读数',
  `next_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '下次读数',
  `result_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '处理结果',
  `data_type` tinyint(1) NULL DEFAULT NULL COMMENT '日志类型；1：旧版（已废弃）；2：新版',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `deal_uid`(`deal_uid`) USING BTREE,
  INDEX `config_id`(`config_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23432 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '抄表异常日志' ROW_FORMAT = Dynamic;

