-- ----------------------------
-- Table structure for emis_meter_group
-- ----------------------------
DROP TABLE IF EXISTS `emis_meter_group`;
CREATE TABLE `emis_meter_group`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '权限ID',
  `type` tinyint(1) UNSIGNED NOT NULL COMMENT '抄表类型；0：电表；1：水表；2：蒸汽表 3：燃气表系统',
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分组名称',
  `pid` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '父id,0顶级',
  `top_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '最顶级ID',
  `area_id` tinyint(1) NULL DEFAULT NULL COMMENT '所属区域id；1：生产区；2：生活区；3：办公区；',
  `hierarchy_type` tinyint(1) NULL DEFAULT NULL COMMENT '层级类型;1：基地总表；2：区域分表；3：车间子表；4：设备仪表；5：产线仪表',
  `hierarchy_type_name` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '层级类型名称',
  `workshop` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间',
  `line_id` int(10) NULL DEFAULT NULL COMMENT '产线id',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产线',
  `rank` int(10) NULL DEFAULT 0 COMMENT '菜单排序,越大越前',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `n-p`(`name`, `pid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 75 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采集表分组列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_meter_list
-- ----------------------------
DROP TABLE IF EXISTS `emis_meter_list`;
CREATE TABLE `emis_meter_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rel_id` int(11) NOT NULL COMMENT '远程仪表ID',
  `rel_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '远程仪表名称',
  `use_type` tinyint(1) NULL DEFAULT NULL COMMENT '用电类型；1：供电局用电；2：光伏用电',
  `collector` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集负责人多个用逗号隔开',
  `monthly_max_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最大值',
  `monthly_min_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最小值',
  `night_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '夜班预警上限值',
  `day_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '白班预警上限值',
  `middle_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '中班预警上限值',
  `multiplier` decimal(8, 2) NULL DEFAULT 1.00 COMMENT '倍率',
  `area_id` tinyint(1) NULL DEFAULT NULL COMMENT '采集表区域id；1：生产区；2：生活区；3：办公区',
  `hierarchy_type` tinyint(1) NULL DEFAULT NULL COMMENT '层级类型id',
  `group_id` int(11) NULL DEFAULT NULL COMMENT '所属分组id',
  `rule` tinyint(1) NOT NULL DEFAULT 1 COMMENT '自动抄表规则 0 不自动 1 按班次 2 按每天 3 按每月',
  `eq_type` int(11) NULL DEFAULT NULL COMMENT '仪表类型ID',
  `eq_id` int(11) NULL DEFAULT NULL COMMENT '仪表ID',
  `savetype` tinyint(1) NULL DEFAULT 0 COMMENT '获取标识；当=0时，福建基地通过api/thedata/querybyid获取读数；否则通过thedata/querybyid_dyn获取',
  `daily_upper_num` decimal(18, 2) NULL DEFAULT NULL COMMENT '每日预警上限值',
  `is_join_calc` tinyint(1) NULL DEFAULT 1 COMMENT '是否参与核算；1：否；2：是',
