  `area_id` tinyint(1) NULL DEFAULT NULL COMMENT '采集表区域id；1：生产区；2：生活区；',
  `group_id` int(11) NULL DEFAULT NULL COMMENT '所属分组id',
  `hierarchy_type` tinyint(1) NULL DEFAULT NULL COMMENT '层级类型id',
  `process` tinyint(2) NULL DEFAULT NULL COMMENT '工序id',
  `multiplier` decimal(8, 2) NULL DEFAULT 1.00 COMMENT '倍率',
  `monthly_max_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最大值',
  `monthly_min_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最小值',
  `director_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集负责人文本，多个用,隔开',
  `meter_lower_num` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '表码数下限',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `auto_rule_type`(`auto_rule_type`) USING BTREE,
  INDEX `eq_id`(`eq_id`) USING BTREE,
  INDEX `rel_id`(`rel_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '蒸汽表采集配置记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emis_water_meter_config
-- ----------------------------
DROP TABLE IF EXISTS `emis_water_meter_config`;
CREATE TABLE `emis_water_meter_config`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `eq_id` int(11) NULL DEFAULT NULL COMMENT '设备ID',
  `rel_id` int(11) NOT NULL DEFAULT 0 COMMENT '采集表名id',
  `rel_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '远程仪表名称',
  `eq_type` int(11) NULL DEFAULT NULL COMMENT '仪表类型ID',
  `director_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集负责人id，多个用,隔开',
  `director_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集负责人文本，多个用,隔开',
  `last_gather_time` datetime NULL DEFAULT NULL COMMENT '最近采集时间',
  `auto_rule_type` tinyint(1) NULL DEFAULT NULL COMMENT '自动抄表规则 0 不自动 1 按班次 2 按每天 3 按每月',
  `num` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '读数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `daily_upper_num` decimal(18, 2) NULL DEFAULT NULL COMMENT '每日预警上限值',
  `is_join_calc` tinyint(1) NULL DEFAULT 1 COMMENT '是否参与核算；1：否；2：是',
  `is_statistics` tinyint(1) NULL DEFAULT 2 COMMENT '是否统计用量；1：否；2：是',
  `monthly_upper_num` decimal(18, 2) NULL DEFAULT NULL COMMENT '每月上限值',
  `annual_upper_num` decimal(18, 2) NULL DEFAULT NULL COMMENT '年度上限值',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `monthly_max_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最大值',
  `monthly_min_num` float(18, 4) NULL DEFAULT NULL COMMENT '月度最小值',
  `night_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '夜班预警上限值',
  `day_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '白班预警上限值',
  `middle_shift_upper_num` float(18, 4) NULL DEFAULT NULL COMMENT '中班预警上限值',
  `area_id` tinyint(1) NULL DEFAULT NULL COMMENT '采集表区域id；1：生产区；2：生活区；',
  `hierarchy_type` tinyint(1) NULL DEFAULT NULL COMMENT '层级类型id',
  `group_id` int(11) NULL DEFAULT NULL COMMENT '所属分组id',
  `process` tinyint(2) NULL DEFAULT NULL COMMENT '工序id',
  `multiplier` decimal(8, 2) NULL DEFAULT 1.00 COMMENT '倍率',
  `meter_lower_num` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '表码数下限',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `auto_rule_type`(`auto_rule_type`) USING BTREE,
  INDEX `eq_id`(`eq_id`) USING BTREE,
  INDEX `rel_id`(`rel_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '水表采集配置记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for employee_inspection_record
-- ----------------------------
DROP TABLE IF EXISTS `employee_inspection_record`;
CREATE TABLE `employee_inspection_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `relation_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联单据编号（体检计划）',
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '类型 1-非计划体检 2-计划体检',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '岗位id',
  `job_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称',
  `uid` int(11) NULL DEFAULT NULL COMMENT '员工id',
  `name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '员工姓名',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '员工部门id',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门名称',
  `sixth_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间',
  `fifth_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组',
  `place_id` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作地点',
  `job_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工种类型',
  `hazard_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '职业病危害因素文本',
  `source` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源或产生途径 1=原料；2=设备',
  `physical_exam_type` tinyint(1) NULL DEFAULT 2 COMMENT '体检项目类型 1-常规体检 2-职业病体检',
  `item` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体检项目 1=粉尘；2=噪声；3=电磁辐射；4=高温；5=化学因素；6=健康证',
  `source_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '来源文本',
  `item_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '体检项目文本',
  `type_index` tinyint(1) NULL DEFAULT NULL COMMENT '种类 1=在岗期间；2=岗前；3=离岗时',
  `sdate` datetime NULL DEFAULT NULL COMMENT '体检开始时间',
  `edate` datetime NULL DEFAULT NULL COMMENT '体检结束时间',
  `result_index` tinyint(1) NULL DEFAULT NULL COMMENT '职检结论 1=未见异常；2=复查；3=疑似；4=禁忌症；5=其他疾患',
  `company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体检机构',
  `order_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体检报告编号',
  `is_leave` tinyint(1) NULL DEFAULT NULL COMMENT '是否调离岗位 1=否；2=是',
  `note` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体检结论及处理意见',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据备注',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提审；1=待验收；2=已完成；3=已驳回；4=已撤回；5=已作废',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '0=正常；1=已删除',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE,
  INDEX `job_id`(`job_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '员工体检记录' ROW_FORMAT = Dynamic;

