  `order_id` int(11) NOT NULL COMMENT '维修单ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '日志类型 0 操作类型 1 审批类型',
  `act` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人名字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '日常维修记录单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for fin_daily_maint_record
-- ----------------------------
DROP TABLE IF EXISTS `fin_daily_maint_record`;
CREATE TABLE `fin_daily_maint_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `repair_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '维修单号',
  `duty_order_id` int(11) NULL DEFAULT NULL COMMENT '当班误时登记单id，维修类型为0的全部通过当班误时登记单自动创建',
  `duty_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '误时登记单号',
  `fault_repair_uid` int(11) NULL DEFAULT NULL COMMENT '故障维修负责人uid',
  `waste_num` int(11) NULL DEFAULT NULL COMMENT '造成废品数量',
  `is_create_fault_order` tinyint(1) NULL DEFAULT 0 COMMENT '是否已创建故障分析单；0：未创建；1：已创建',
  `delay` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备件误时（分钟数）',
  `delay_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备件误时文本',
  `delay_reason_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '误时原因文本',
  `delay_reason_id` int(11) NULL DEFAULT NULL COMMENT '误时原因id',
  `class_no_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次文本',
  `class_no` int(11) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `date_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期（年月日）',
  `equipment_id` int(11) NOT NULL COMMENT '登记设备ID',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '维修单状态 -1 已删除 0 = 待提审 1 = 待验收 2 = 已完成 3 = 已驳回 4 = 已撤回 5 = 已作废',
  `occurrence_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发生时间',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组id',
  `class_type_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组文本',
  `repair_user_id` int(11) NOT NULL COMMENT '报修人',
  `fault_body` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备部位',
  `product_line` int(11) NULL DEFAULT NULL COMMENT '所属产线',
  `fault_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障描述',
  `save_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存放位置，用逗号隔开',
  `fault_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '故障图片 多张',
  `repair_type` tinyint(1) NULL DEFAULT 1 COMMENT '维修类型 1 常见故障维修 2 突发性故障维修3 = 计划项目维修 4 = 不正当使用维修',
  `fault_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障类型 1 电气故障 2 机械故障 3 其他故障',
  `fault_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障原因 来源基础设置表 多个用逗号隔开',
  `repair_director` int(11) NULL DEFAULT NULL COMMENT '维修负责人 默认创建人',
  `other_repair_director` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他维修人员',
  `repair_start_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '维修开始时间',
  `repair_end_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修结束时间',
  `is_stop` tinyint(1) NULL DEFAULT NULL COMMENT '是否停机 0 否 1是',
  `stop_time` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '累计停机时间（分钟）',
  `repair_duration` int(11) NULL DEFAULT NULL COMMENT '维修时长（分钟数）',
  `repair_duration_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修时长文本',
  `outsourcing_id` int(11) NULL DEFAULT NULL COMMENT '外委单位ID',
  `repair_price` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '维修费用',
  `repair_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修描述',
  `repair_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '维修照片',
  `is_replace` tinyint(1) NULL DEFAULT 0 COMMENT '是否更换配件 0 不更换 1更换',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `chage_date` datetime NULL DEFAULT NULL COMMENT '换上时间',
  `down_date` datetime NULL DEFAULT NULL COMMENT '换下时间',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `fault_repair_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障维修负责人名字',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `equipment_id`(`equipment_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `repair_director`(`repair_director`) USING BTREE,
  INDEX `repair_user_id`(`repair_user_id`) USING BTREE,
  INDEX `fault_reason`(`fault_reason`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `repair_type`(`repair_type`) USING BTREE,
  INDEX `repair_no`(`repair_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '日常维修记录单记录' ROW_FORMAT = Dynamic;

-- ----------------------------
