  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '部门月度安全费用' ROW_FORMAT = Dynamic;

