-- ----------------------------
-- Table structure for final_goods
-- ----------------------------
DROP TABLE IF EXISTS `final_goods`;
CREATE TABLE `final_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '商品编码',
  `goods_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `weight` decimal(10, 5) NULL DEFAULT NULL COMMENT '单位重量',
  `coefficient` decimal(10, 3) NULL DEFAULT NULL COMMENT '标箱折算系数',
  `category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料大类',
  `cate_id` int(11) NULL DEFAULT NULL COMMENT '品项id',
  `cate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品项',
  `object` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报表项目',
  `is_gift` tinyint(1) NULL DEFAULT NULL COMMENT '是否礼盒装0否1是',
  `is_enable` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '是否启用1是0否',
  `sort` int(10) NULL DEFAULT 0 COMMENT '排序',
  `is_have_tag` tinyint(1) NULL DEFAULT 0 COMMENT '是否箱内码促销0否1是',
  `unit` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'CAR' COMMENT '单位',
  `goods_type` tinyint(1) NULL DEFAULT NULL COMMENT '物料类型 1.红牛普通型 2.红牛强化型 3.瓶装战马 4.罐装战马 5.国产芙丝 6.进口芙丝 7.神农明珠 8.战马新口味',
  `outer_box_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '外包装箱价格',
  `has_chip` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '是否促销物料 0否1是',
  `has_box_code` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '是否消费者促销 0否1是',
  `has_cap_code` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '是否五码合一 0否1是',
  `has_cap_text` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '是否线下促销 0否1是',
  `length` int(11) NULL DEFAULT NULL COMMENT '长(mm)',
  `width` int(11) NULL DEFAULT NULL COMMENT '宽(mm)',
  `height` int(11) NULL DEFAULT NULL COMMENT '高(mm)',
  `sealing_id` int(11) NULL DEFAULT NULL COMMENT '封箱id',
  `sealing_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封箱方式',
  `has_inner_film` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有内膜 0否1是',
  `has_outer_film` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '是否有外膜 0否1是',
  `inner_pack_form` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '箱内包装形式',
  `release_area` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '投放区域',
  `box_count` int(11) NULL DEFAULT NULL COMMENT '箱内数量',
  `is_inner_gift` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '箱内是否礼品 0否1是',
  `shelf_life` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品保质期',
  `material_id` int(11) NULL DEFAULT NULL COMMENT '材质id',
  `material` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '材质',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `distribution_qty` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分配量',
  `promotion_plan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '促销方案',
  `shelf_life_warning` int(11) NULL DEFAULT NULL COMMENT '保质期预警(天)',
  `from_date` date NULL DEFAULT '2025-01-01' COMMENT '有效期起',
  `expiry_date` date NULL DEFAULT '9999-12-31' COMMENT '有效期止',
  `goods_img` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品主图',
  `goods_sub_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '商品副图',
  `delivery_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交货单位',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for final_goods_box_price_exp
-- ----------------------------
DROP TABLE IF EXISTS `final_goods_box_price_exp`;
CREATE TABLE `final_goods_box_price_exp`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) UNSIGNED NOT NULL COMMENT '商品列表ID',
  `box_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '纸箱价格',
  `from_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '有效期起',
  `expiry_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '有效期止',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品信息价格有效期' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for final_goods_exp
-- ----------------------------
DROP TABLE IF EXISTS `final_goods_exp`;
CREATE TABLE `final_goods_exp`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) UNSIGNED NOT NULL COMMENT '商品列表ID',
  `weight` decimal(10, 5) NULL DEFAULT NULL COMMENT '单位重量',
  `from_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '有效期起',
  `expiry_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '有效期止',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '上一次备份',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品信息重量系数有效期' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for final_goods_price_exp
-- ----------------------------
DROP TABLE IF EXISTS `final_goods_price_exp`;
CREATE TABLE `final_goods_price_exp`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) UNSIGNED NOT NULL COMMENT '商品列表ID',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '货值',
  `from_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '有效期起',
  `expiry_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '有效期止',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品信息货值有效期' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for goods_class
-- ----------------------------
DROP TABLE IF EXISTS `goods_class`;
CREATE TABLE `goods_class`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物料组描述（分类名称）',
  `group_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料组编码',
  `name_two` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对于物料组的描述2',
  `pid` int(10) NULL DEFAULT 0 COMMENT '父级id',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE,
  INDEX `name`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 227 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for goods_list
-- ----------------------------
DROP TABLE IF EXISTS `goods_list`;
CREATE TABLE `goods_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `barcode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品编码',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `company` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司',
  `price` decimal(18, 2) NULL DEFAULT NULL COMMENT '参考价格',
  `img_url` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称/物料组',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `is_aux_measure` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用多单位；1：不启用；2：启用',
  `aux_measure_data` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '多单位设置（辅助单位设置）',
  `show_measure_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位（带多单位的计量单位文本）',
  `goods_class` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货品分类',
  `ss_num` decimal(4, 0) NULL DEFAULT NULL COMMENT '安全库存',
  `order_point` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '订货点',
  `is_stop_using` tinyint(1) NULL DEFAULT 0 COMMENT '是否停用；0：否；1：是',
  `material_desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料描述',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `exp_day` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '保质期',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  `exp_warning_day` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '保质期预警天数',
  `delivery_warning_day` int(10) NULL DEFAULT NULL COMMENT '交货期预警天数',
  `is_unique_identify` tinyint(1) NULL DEFAULT 0 COMMENT '是否唯一标识管理（全生命周期管理）；0：不是；1：是',
  `is_expensed_assets` tinyint(1) NULL DEFAULT 0 COMMENT '是否费用化资产（固定资产）；0：不是；1：是',
  `film` tinyint(4) NULL DEFAULT NULL COMMENT '热缩膜类型 1 普通版 2 强化版 3 PE彩膜',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `purchase_price` decimal(18, 2) NULL DEFAULT NULL COMMENT '默认采购价',
  `img_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片信息',
  `abc_mark` tinyint(1) NULL DEFAULT NULL COMMENT 'ABC标识：1：A类、2：B类、3：类型',
  `is_raw_mat` tinyint(1) NULL DEFAULT 1 COMMENT '是否原材料；1：不是；2：是',
  `tax_rate` tinyint(2) NULL DEFAULT 13 COMMENT '税率,默认13',
  `mat_category` tinyint(1) NULL DEFAULT NULL COMMENT '物料大类id',
  `mat_category_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料大类名称',
  `delivery_days` int(11) NULL DEFAULT NULL COMMENT '货期天数',
  `mat_class` tinyint(1) NULL DEFAULT NULL COMMENT '物料标签大类id',
  `mat_type` tinyint(1) NULL DEFAULT NULL COMMENT '物料标签类型id',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `coefficient` decimal(10, 3) NULL DEFAULT NULL COMMENT '标箱折算系数',
  `is_have_tag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0没有贴标1有贴标',
  `sc_barcode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-物料编码',
  `cate_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-物料品类',
  `mat_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-物料描述',
  `ownership_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-物料归属',
  `is_check` tinyint(1) NULL DEFAULT NULL COMMENT '供应链-是否检测 0-否 1-是',
  `qc_release_issued` tinyint(1) NULL DEFAULT NULL COMMENT '供应链-是否品管出具内容物使用通知单 0-否 1-是',
  `requires_external_inspection` tinyint(1) NULL DEFAULT NULL COMMENT '供应链-质检转非限制是否需要外检 0-否 1-是',
  `arrival_external_inspection` tinyint(1) NULL DEFAULT NULL COMMENT '供应链-到货是否外检 0-否 1-是',
  `storage_condition` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-储存条件',
  `consumption_per_10k_cans` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-万罐单耗',
  `online_promotion` tinyint(1) NULL DEFAULT NULL COMMENT '供应链-线上促销 0-否 1-是',
  `promotion_plan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-促销方案',
  `promotion_start_date` date NULL DEFAULT NULL COMMENT '供应链-促销活动有效期起',
  `promotion_end_date` date NULL DEFAULT NULL COMMENT '供应链-促销活动有效期止',
  `winning_ratio` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-中奖比例',
  `validity_start_date` date NULL DEFAULT NULL COMMENT '供应链-有效期起',
  `validity_end_date` date NULL DEFAULT NULL COMMENT '供应链-有效期止',
  `purchase_max_quantity` decimal(12, 2) NULL DEFAULT NULL COMMENT '供应链-采购上限量',
  `arrival_packaging` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应链-到货包装形式',
  `length` decimal(12, 2) NULL DEFAULT NULL COMMENT '供应链-长度',
  `width` decimal(12, 2) NULL DEFAULT NULL COMMENT '供应链-宽度',
  `height` decimal(12, 2) NULL DEFAULT NULL COMMENT '供应链-高度',
  `weight` decimal(12, 2) NULL DEFAULT NULL COMMENT '供应链-重量',
  `socure_type` tinyint(1) NULL DEFAULT 1 COMMENT '创建来源；1：数智工厂；2：供应链',
  `available_status` tinyint(1) NULL DEFAULT 1 COMMENT '供应链-可用状态，1：启用；2：禁用',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `title`(`title`) USING BTREE,
  INDEX `class_name`(`class_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE,
  INDEX `available_status`(`available_status`) USING BTREE,
  INDEX `is_stop_using`(`is_stop_using`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6843 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '商品列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for goods_operate_log
-- ----------------------------
DROP TABLE IF EXISTS `goods_operate_log`;
CREATE TABLE `goods_operate_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) UNSIGNED NOT NULL COMMENT '货品id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5166 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '货品操作日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for goods_supplier
-- ----------------------------
DROP TABLE IF EXISTS `goods_supplier`;
CREATE TABLE `goods_supplier`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `contact` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系人',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商编码',
  `sort_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商简称',
  `type_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商类型id，多个用,隔开',
  `company_size` tinyint(1) NULL DEFAULT NULL COMMENT '企业规模，1 ：一般纳税人；2：小规模纳税人；',
  `category_id` tinyint(1) NULL DEFAULT NULL COMMENT '供应商大类id',
  `category_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商大类文本',
  `is_mail_push` tinyint(1) NULL DEFAULT 1 COMMENT '是否邮件推送；0：不推送；1：推送',
  `mobile` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `e_mail` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮件',
  `address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '街道（原地址）',
  `acct_nm` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户银行',
  `pan` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '银行卡号',
  `license_pic` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '营业执照图',
  `city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市',
  `acc_group_id` int(11) NULL DEFAULT NULL COMMENT '账户组ID',
  `acc_group_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账户组名称',
  `sup_level_id` int(11) NULL DEFAULT NULL COMMENT '供应商等级ID',
  `sup_level_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商等级名称',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `is_stop_using` tinyint(1) NULL DEFAULT 0 COMMENT '是否禁用；0：否；1：是',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `name`(`name`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE,
  INDEX `is_mail_push`(`is_mail_push`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1397 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for goods_supplier_acc_group
-- ----------------------------
DROP TABLE IF EXISTS `goods_supplier_acc_group`;
CREATE TABLE `goods_supplier_acc_group`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账户组编码',
  `desc_one` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述1',
  `desc_two` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述2',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商账户组管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for goods_supplier_aptitude
-- ----------------------------
DROP TABLE IF EXISTS `goods_supplier_aptitude`;
CREATE TABLE `goods_supplier_aptitude`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `sup_id` int(10) NOT NULL COMMENT '所属供应商id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资质名称',
  `code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资质编码',
