  `upload_time` datetime NULL DEFAULT NULL COMMENT '上传时间',
  `upload_uid` int(10) NULL DEFAULT NULL COMMENT '上传者uid',
  `upload_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上传者名字',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人uid',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人uid',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `name`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商资质信息' ROW_FORMAT = Dynamic;

