  `contract_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同编号',
  `term_type` int(10) NULL DEFAULT NULL COMMENT '期限类型id',
  `term` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '期限类型',
  `start_date` date NULL DEFAULT NULL COMMENT '生效日期',
  `over_date` date NULL DEFAULT NULL COMMENT '终止日期',
  `contract_term` tinyint(1) NULL DEFAULT NULL COMMENT '合同期限 0=1年；1=2年；2=3年；3=4年；4=5年；5=6年；6=7年；7=8年；8=9年；9=10年；10=无期限',
  `month` tinyint(1) NULL DEFAULT NULL COMMENT '合同期限月份 1 = 1个月； 2 = 2个月 ；3 = 3个月...',
  `signing_date` date NULL DEFAULT NULL COMMENT '签订日期',
  `company_id` int(11) NULL DEFAULT NULL COMMENT '法人公司id',
  `company` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '法人公司',
  `signing_num` int(10) NULL DEFAULT NULL COMMENT '签订次数',
  `contract_type_id` int(10) NULL DEFAULT NULL COMMENT '合同类型id',
  `contract_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同类型',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同备注',
  `files_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '合同附件',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1：待审核；2=已完成；3=驳回；4=撤回；5=已失效；6=已归档',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `confirm_date` date NULL DEFAULT NULL COMMENT '转正日期',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `ct_dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门id',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `term_type`(`term_type`) USING BTREE,
  INDEX `start_date`(`start_date`) USING BTREE,
  INDEX `over_date`(`over_date`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `employee_number`(`employee_number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '合同管理' ROW_FORMAT = Dynamic;

