) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '宿舍客房安全卫生检查清单身份标识' ROW_FORMAT = Dynamic;

