-- ----------------------------
-- Table structure for hr_dorm_checkout_apply_form_order
-- ----------------------------
DROP TABLE IF EXISTS `hr_dorm_checkout_apply_form_order`;
CREATE TABLE `hr_dorm_checkout_apply_form_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `apply_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请人uid',
  `apply_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请人姓名',
  `contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系方式',
  `room_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '宿舍号',
  `room_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '宿舍号id（维修地点id）',
  `entry_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入职时间',
  `checkout_apply_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请退租时间',
  `expected_cleaning_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '预计物品清理完成时间',
  `request_recover_items` tinyint(1) NOT NULL DEFAULT 1 COMMENT '入职时是否申请寝室物品：1=否，2=是',
  `checkout_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退租申请原因',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `file_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `full_status` tinyint(1) NULL DEFAULT 1 COMMENT '检查状态；1：待检查；2：已检查',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `check_bed_status` tinyint(1) NULL DEFAULT NULL COMMENT '铁床/木床是否完好：1=完好，2=有破损，3=未配置',
  `check_cabinet_status` tinyint(1) NULL DEFAULT NULL COMMENT '铁柜/木柜是否完好：1=完好，2=有破损，3=未配置',
  `check_desk_status` tinyint(1) NULL DEFAULT NULL COMMENT '桌子是否完好：1=完好，2=有破损，3=未配置',
  `check_chair_status` tinyint(1) NULL DEFAULT NULL COMMENT '凳子是否完好：1=完好，2=有破损，3=未配置',
  `check_ac_status` tinyint(1) NULL DEFAULT NULL COMMENT '空调是否完好：1=完好，2=有破损，3=未配置',
  `check_washer_status` tinyint(1) NULL DEFAULT NULL COMMENT '洗衣机是否完好：1=完好，2=有破损，3=未配置',
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人签字图片',
  `apply_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退租申请人签字图片',
  `confirm_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认时间',
  `confirm_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '确认信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '单据状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7=待检查',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门id',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `dept_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所在部门id',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所在部门名称',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '所在岗位id',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流人员id集合',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no`) USING BTREE,
  INDEX `apply_uid`(`apply_uid`) USING BTREE,
  INDEX `room_number`(`room_number`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 46 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '宿舍退租申请表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_dorm_costs
-- ----------------------------
DROP TABLE IF EXISTS `hr_dorm_costs`;
CREATE TABLE `hr_dorm_costs`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `record_month` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计费月份',
  `water_usage` decimal(10, 2) NULL DEFAULT NULL COMMENT '水用量（吨）',
  `water_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '水费（元）',
  `electric_usage` decimal(10, 2) NULL DEFAULT NULL COMMENT '电量（度）',
  `electric_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '电费（元）',
  `steam_usage` decimal(10, 2) NULL DEFAULT NULL COMMENT '蒸汽用量（吨）',
  `steam_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '蒸汽费（元）',
  `total_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '费用总和（元）',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `record_month`(`record_month`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '宿舍费用记录表' ROW_FORMAT = Dynamic;

