  `weight` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总质量',
  `weight2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准牵引总质量',
  `people_num` int(10) NULL DEFAULT NULL COMMENT '核定载人数',
