  `spouse_residence` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-配偶居住地',
  `party_org_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-党组织关系所在地',
  `home_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-家庭电话',
  `office_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-办公地址',
  `emergency_contact` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-紧急联系人',
  `relationship_with_person_id` int(10) NULL DEFAULT NULL COMMENT '个人信息-与本人关系id',
  `relationship_with_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-与本人关系',
  `emergency_contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-紧急联系人电话',
  `work_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人信息-工作地点',
  `employee_status` tinyint(1) NULL DEFAULT NULL COMMENT '用工信息-员工状态；1：试用；2：正式 3-离职',
  `entry_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-入职日期',
  `entry_source` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-入职来源',
  `estimated_service_years` int(11) NULL DEFAULT NULL COMMENT '用工信息-累计司龄（年）',
  `estimated_service_months` int(11) NULL DEFAULT NULL COMMENT '用工信息-累计司龄（月）',
  `estimated_service_days` int(11) NULL DEFAULT NULL COMMENT '用工信息-累计司龄（天）',
  `confirmation_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-转正日期',
  `part_work_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-参加工作日期',
  `employment_rel_id` tinyint(1) NULL DEFAULT NULL COMMENT '用工信息-雇佣关系id',
  `prob_month` int(11) NULL DEFAULT NULL COMMENT '用工信息-试用期月数',
  `employment_rel_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-雇佣关系文本',
  `employment_form_id` tinyint(1) NULL DEFAULT NULL COMMENT '用工信息-用工形式id',
  `employment_form_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-用工形式文本',
  `virtual_manager_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-虚线经理',
  `direct_manager_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-直线经理',
  `direct_manager_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-直线经理邮箱',
  `virtual_manager_email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-虚线经理邮箱',
  `old` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-old',
  `dept_epk_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-对应部门EPK组织代码',
  `first_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-一级组织',
  `second_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-二级组织',
  `third_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-三级组织',
  `fourth_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-四级组织',
  `fifth_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-五级组织',
  `sixth_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-六级组织',
  `seventh_level_org` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-七级组织',
  `job_sequence` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-职务序列',
  `job_title_id` int(10) NULL DEFAULT NULL COMMENT '用工信息-职等id',
  `job_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-职等',
  `employee_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工信息-工号（不分词）',
  `core_personnel` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-核心人员;1:是；2:否',
  `core_personnel_date` date NULL DEFAULT NULL COMMENT '标签信息-核心人员认证日期',
  `security_staff` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-保全工;1:是；2:否',
  `security_staff_date` date NULL DEFAULT NULL COMMENT '标签信息-保全工认证日期',
  `union_committee_member` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-工会委员;1:是；2:否',
  `part_time_staff_id` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-兼职人员id 1 安全 2 内审 3 安全/内审',
  `part_time_staff_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息-兼职人员文本',
  `part_time_staff_date` date NULL DEFAULT NULL COMMENT '标签信息-兼职人员认证日期',
  `part_time_staff_date1` date NULL DEFAULT NULL COMMENT '标签信息-兼职人员认证日期1',
  `talent_pool` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-储备人才;1:是；2:否',
  `talent_pool_date` date NULL DEFAULT NULL COMMENT '标签信息-储备人才认证日期',
  `position_master` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-岗位师傅;1:是；2:否',
  `position_master_date` date NULL DEFAULT NULL COMMENT '标签信息-岗位师傅认证日期',
  `employee_rep` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-职工代表;1:是；2:否',
  `internal_trainer` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-内训师;1:是；2:否',
  `internal_trainer_date` date NULL DEFAULT NULL COMMENT '标签信息-内训师认证日期',
  `veteran` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-退伍军人;1:是；2:否',
  `talent_bank` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-人才库;1:是；2:否',
  `talent_bank_date` date NULL DEFAULT NULL COMMENT '标签信息-人才库认证日期',
  `multi_skill_worker` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-多能工;1:是；2:否',
  `multi_skill_worker_date` date NULL DEFAULT NULL COMMENT '标签信息-多能工认证日期',
  `cert_level_id` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-认证星级id',
  `cert_level_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息-认证星级文本',
  `cert_position_ids` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息-认证岗位id,多个用逗号隔开',
  `cert_position_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息-认证岗位文本',
  `responsible_machine_id` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-责任机台id',
  `responsible_machine_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标签信息-责任机台文本',
  `job_pacesetter` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-岗位标兵;1:是；2:否',
  `excellent_staff` tinyint(1) NULL DEFAULT NULL COMMENT '标签信息-优秀员工;1:是；2:否',
  `grading_job` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息;岗位分级-岗位',
  `grading_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息;岗位分级-级别',
  `talent_grade` tinyint(4) NULL DEFAULT NULL COMMENT '标签信息;人才梯队等级 1 初级 2 中级 3 高级',
  `talent_grade_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息;人才梯队等级',
  `grading_level_date` date NULL DEFAULT NULL COMMENT '标签信息;人才梯队认证日期',
  `talent_manager_status` tinyint(4) NULL DEFAULT NULL COMMENT '储备干部信息-是否储备干部；1:是；2:否',
  `talent_manager_date` date NULL DEFAULT NULL COMMENT '储备干部信息-认证时间',
  `talent_manager_job_id` int(11) NULL DEFAULT NULL COMMENT '储备干部信息-储备岗位ID',
  `talent_manager_job_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '储备干部信息-储备岗位文本',
  `team_training_status` tinyint(4) NULL DEFAULT NULL COMMENT '是否班组培养人员；1:是；2:否',
  `job_title_level` int(11) NULL DEFAULT NULL COMMENT '职称等级信息-职称等级ID（外键）',
  `job_title_level_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职称等级信息-职称等级文本',
  `job_title_level_date` date NULL DEFAULT NULL COMMENT '职称等级信息-认证时间',
  `job_title_cert` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职称等级信息-职称证书名称或编号',
  `key_job_status` tinyint(4) NULL DEFAULT NULL COMMENT '关键岗位信息-是否关键岗位；1:是；2:否',
  `key_job_cert_date` date NULL DEFAULT NULL COMMENT '关键岗位信息-认证时间',
  `key_job_category` int(11) NULL DEFAULT NULL COMMENT '关键岗位信息-岗位类别ID',
  `key_job_category_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关键岗位信息-岗位类别文本',
  `dormitory_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息-宿舍号',
  `room_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签信息-宿舍id，（维修地点id）',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `legal_retirement_date` date NULL DEFAULT NULL COMMENT '法定退休日期',
  `is_retire_remind` tinyint(1) NULL DEFAULT 0 COMMENT '临近退休推送 0 否 1 是',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `employee_number`(`employee_number`) USING BTREE,
  INDEX `smart_fty_dept_id`(`smart_fty_dept_id`) USING BTREE,
  INDEX `smart_fty_job_id`(`smart_fty_job_id`) USING BTREE,
  INDEX `marital_status_id`(`marital_status_id`) USING BTREE,
  INDEX `legal_retirement_date`(`legal_retirement_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 217 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '员工档案信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_employee_retire_set
-- ----------------------------
DROP TABLE IF EXISTS `hr_employee_retire_set`;
CREATE TABLE `hr_employee_retire_set`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '退休临近',
  `remind_uids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提醒通知谁，多个用逗号隔开',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '退休管理-提醒条件设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_eval_basic_score_config
-- ----------------------------
DROP TABLE IF EXISTS `hr_eval_basic_score_config`;
CREATE TABLE `hr_eval_basic_score_config`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `score_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考核基础分名称',
  `base_score` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基础分值',
  `category` tinyint(3) UNSIGNED NOT NULL COMMENT '所属绩效大类：1=综合工时，2=标准工时',
  `job_ids` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '岗位ID集合，多个用逗号分隔（来源job_list.job_id）',
  `job_names` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称集合，多个用逗号分隔',
  `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 2 COMMENT '状态：1=禁用，2=启用',
  `rank` int(11) NULL DEFAULT 0 COMMENT '排序值（越大越靠前）',
  `color` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '显示颜色（可选）',
  `is_set_score_range` tinyint(1) NULL DEFAULT 1 COMMENT '是否设置考核分数范围；1：未设置；2：已设置',
  `is_set_result_level` tinyint(1) NULL DEFAULT 1 COMMENT '是否设置考核结果等级；1：未设置；2：已设置',
  `is_set_ratio_percent` tinyint(1) NULL DEFAULT 1 COMMENT '是否设置比例；1：未设置；2：已设置',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '创建人ID',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人姓名',
  `up_uid` int(10) UNSIGNED NOT NULL COMMENT '更新人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人姓名',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `rank`(`rank`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '绩效考核设置-月度绩效汇总规则置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_eval_basic_score_detail
-- ----------------------------
DROP TABLE IF EXISTS `hr_eval_basic_score_detail`;
CREATE TABLE `hr_eval_basic_score_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `config_id` int(10) UNSIGNED NOT NULL COMMENT '所属配置表id',
  `metric` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'P' COMMENT '度量标识：固定为P（考核分值范围）',
  `min_val` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核分值范围，最小值',
  `op1` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '考核分值范围，第一个符号（下限）：1<，2<=，3=，4>，5>=',
  `op2` tinyint(3) UNSIGNED NULL DEFAULT NULL COMMENT '考核分值范围，第二个符号（上限）：1<，2<=，3=，4>，5>=',
  `max_val` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核分值范围，最大值',
  `result_level` tinyint(3) UNSIGNED NOT NULL COMMENT '考核结果等级：1=S，2=A+，3=A，4=B+，5=B，6=B-，7=C+，8=C，9=C-',
  `ratio_percent` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '比例（百分比0-100，例如10.00）',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '创建人ID',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人姓名',
  `up_uid` int(10) UNSIGNED NOT NULL COMMENT '更新人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人姓名',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `config_id`(`config_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '绩效考核设置-考核基础分配置规则明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_event
-- ----------------------------
DROP TABLE IF EXISTS `hr_event`;
CREATE TABLE `hr_event`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '活动主题',
  `event_type_id` int(10) NULL DEFAULT NULL COMMENT '活动类别id',
  `event_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '活动类别',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '活动地点',
  `join_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '参加成员',
  `uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '参加员工ID',
  `join_uids_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '参加员工文本',
  `dept_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '活动部门',
  `dept_name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '活动部门',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '活动内容',
  `sdate` date NULL DEFAULT NULL COMMENT '活动开始时间',
  `edate` date NULL DEFAULT NULL COMMENT '活动结束时间',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '活动费用',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '活动照片',
  `code_url` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签到二维码',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=未开始；1=待审核；2=已完成；3=驳回；4=撤回；5=进行中',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人id',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `event_type_id`(`event_type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '团队活动' ROW_FORMAT = Dynamic;

