-- ----------------------------
-- Table structure for hr_health_inspection
-- ----------------------------
DROP TABLE IF EXISTS `hr_health_inspection`;
CREATE TABLE `hr_health_inspection`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `date` date NULL DEFAULT NULL COMMENT '检查年月',
  `check_sdate` date NULL DEFAULT NULL COMMENT '检查开始时间',
  `check_edate` date NULL DEFAULT NULL COMMENT '检查结束时间',
  `uid` int(10) NULL DEFAULT NULL COMMENT '检查人id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人姓名',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '部门id',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门名称',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '岗位id',
  `job_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `files_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1：待审核；2=已完成；3=驳回；4=撤回',
  `check_status` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果 1=正常；2=部分正常；3=异常',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `review_uids` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人id',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '卫生检查管理' ROW_FORMAT = Dynamic;

