  `honor_received` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所获荣誉',
  `act_award_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '获得奖励;1:奖金 2:证书 3:奖金',
  `act_award_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '获得奖励文本',
  `act_money` decimal(10, 2) NULL DEFAULT NULL COMMENT '奖金金额',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：待确认；1：待审核；2：已确认；3：已驳回；4：已撤回',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息',
  `record_type` tinyint(1) NOT NULL COMMENT '记录类型,1:荣誉记 2:大事记',
  `record_type_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录类型文本',
  `confirm_uid` int(11) NULL DEFAULT NULL COMMENT '确认人uid',
  `event_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事记编号',
  `event_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时间',
  `honor_level` tinyint(1) NULL DEFAULT NULL COMMENT '荣誉等级；1：国家级；2：省级；3：市级；4：区级',
  `honor_level_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '荣誉等级文本',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '建单部门id',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_job_id` int(10) NULL DEFAULT NULL COMMENT '建单人岗位id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批附件',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 132 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '大事记/荣誉表' ROW_FORMAT = Dynamic;

