  `evaluation_id` int(11) NULL DEFAULT NULL COMMENT '考核记录id',
  `approve_id` int(11) NULL DEFAULT NULL COMMENT '认证记录id',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE,
  INDEX `employee_number`(`employee_number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '内训师报名' ROW_FORMAT = Dynamic;

