-- ----------------------------
-- Table structure for hr_key_events_sign
-- ----------------------------
DROP TABLE IF EXISTS `hr_key_events_sign`;
CREATE TABLE `hr_key_events_sign`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NULL DEFAULT NULL COMMENT '关联记录id',
  `uid` int(10) NULL DEFAULT NULL COMMENT '考核人id',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核人名称',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '考核人部门id',
