-- ----------------------------
-- Table structure for hr_log
-- ----------------------------
DROP TABLE IF EXISTS `hr_log`;
CREATE TABLE `hr_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事件',
