  `act` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `ct_uid` int(10) NOT NULL COMMENT '创建人id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 222 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '维修管理节点日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_maintain_manage_list
-- ----------------------------
DROP TABLE IF EXISTS `hr_maintain_manage_list`;
CREATE TABLE `hr_maintain_manage_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '报修单号',
  `area_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '报修区域id',
  `area_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报修区域文本',
  `place` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '维修地点',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '维修状态；1：待审核；2：待维修；3：已完成；4：已关闭 5 待验收 6 费用审核',
  `project_id` int(11) NULL DEFAULT NULL COMMENT '维修项目id',
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修项目名称',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '维修内容',
  `time` datetime NULL DEFAULT NULL COMMENT '报修时间',
  `repair_uid` int(11) NOT NULL COMMENT '报修人uid',
  `repair_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报修人名字',
  `contact_info` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '联系方式',
  `belong_dept_id` int(11) NOT NULL COMMENT '所属部门id',
  `belong_dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属部门名称',
  `before_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报修前图片',
  `after_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '维修后图片',
  `suit_time_start` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '合适维修时间段-开始',
  `suit_time_end` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '合适维修时间段-结束',
  `is_repair` tinyint(1) NULL DEFAULT NULL COMMENT '维修提报审核状态；1：安排内部维修；2：不给予维修（关闭）；3：安排外部维修',
  `is_repair_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修提报审核备注',
  `assign_repair_uid` int(11) NULL DEFAULT NULL COMMENT '指派维修人uid',
  `assign_repair_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '指派维修人名字',
  `copy_uid` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修抄送人ID，多个用逗号隔开',
  `copy_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修抄送人名称，多个用逗号隔开',
  `approve_id` int(11) NULL DEFAULT NULL COMMENT '报修审核人uid',
  `approve_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报修审核人名字',
  `submit_uid` int(11) NULL DEFAULT NULL COMMENT '提报人uid',
  `submit_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提报人名字',
  `repair_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修时间',
  `amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '维修费用',
  `labor_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '人工费',
  `material_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '材料费',
  `maintenance_notes` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修情况备注',
  `director_user_id` int(11) NULL DEFAULT NULL COMMENT '部门负责人ID',
  `director_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门负责人名称',
  `no_pass_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `ct_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `star_rating` tinyint(1) NULL DEFAULT NULL COMMENT '评价星级',
  `evaluate_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评价内容',
  `code_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '委外维修供应商二维码',
  `cost_imgs` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '费用图片',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 202 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '维修管理' ROW_FORMAT = Dynamic;

