-- ----------------------------
-- Table structure for hr_maintain_notice_task
-- ----------------------------
DROP TABLE IF EXISTS `hr_maintain_notice_task`;
CREATE TABLE `hr_maintain_notice_task`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_id` int(11) NULL DEFAULT NULL COMMENT '维修项目id',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；1：未消费；2：已消费',
