) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '维修预警日志任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_maintain_project
-- ----------------------------
DROP TABLE IF EXISTS `hr_maintain_project`;
CREATE TABLE `hr_maintain_project`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目名称',
  `project_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目编号',
  `area_id` int(11) NOT NULL COMMENT '所属区域id',
  `area_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属区域名称',
  `init_repair_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '初始维修期',
  `repair_cycle_val` int(11) NULL DEFAULT NULL COMMENT '维修周期',
  `repair_cycle_val_update` tinyint(1) NULL DEFAULT NULL COMMENT '维修周期更新 1：按天更新；其它按月更新',
  `notice_uids` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '提醒接收人uid，多个用逗号隔开',
  `interval_day_num` int(11) NULL DEFAULT NULL COMMENT '维修间隔天数',
  `last_repair_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近维修时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '保养状态；0待提审；1：待验证；2：已完成；3：已驳回；4：已撤回',
  `task_update_time` datetime NULL DEFAULT NULL COMMENT '提醒任务最后更新时间',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '项目描述（备注）',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `project_no`(`project_no`) USING BTREE,
  INDEX `area_id`(`area_id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '非生产性维修项目' ROW_FORMAT = Dynamic;

