  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1018 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '非生产性维修项目操作日志' ROW_FORMAT = DYNAMIC;

