  `meeting_imgs` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会议现场照片',
  `dept_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '可见范围部门',
  `dept_ids_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '可见范围部门id',
  `user_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '可见范围用户',
  `user_ids_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '可见范围用户id',
  `range_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '可见范围文本',
  `status` tinyint(1) NOT NULL DEFAULT 5 COMMENT '状态 0=待提交；1：待审核；2=已完成；3=驳回；4=撤回；5=未开始；6=进行中',
  `archive_status` tinyint(255) NULL DEFAULT NULL COMMENT '存档状态；1：未存档；2：已存档；',
  `archive_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存档后对应知识库记录id数组',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
