  INDEX `status`(`status`) USING BTREE,
  INDEX `rank`(`rank`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '绩效考核设置-考核基础分配置表' ROW_FORMAT = Dynamic;

