) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '绩效考核设置-月度绩效汇总规则置表规则明细' ROW_FORMAT = Dynamic;

