-- ----------------------------
-- Table structure for hr_monthly_revenue_settlement_assoc
-- ----------------------------
DROP TABLE IF EXISTS `hr_monthly_revenue_settlement_assoc`;
CREATE TABLE `hr_monthly_revenue_settlement_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '月度营收结算单据身份标识' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_monthly_revenue_settlement_expend_detail
-- ----------------------------
DROP TABLE IF EXISTS `hr_monthly_revenue_settlement_expend_detail`;
CREATE TABLE `hr_monthly_revenue_settlement_expend_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '所属单据id',
  `item` tinyint(1) NULL DEFAULT NULL COMMENT '项目：1收入，2支出，3调料主食库存',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位（如：红牛/兑盖等）',
  `unit_id` int(11) NULL DEFAULT NULL COMMENT '单位id（参考 hr_account_unit_config.id）',
  `subject_id` int(11) NULL DEFAULT NULL COMMENT '科目id（参考 hr_receipt_subject_list.id）',
  `subject_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '科目名称（冗余）',
  `rel_type` tinyint(1) NULL DEFAULT NULL COMMENT '关联数据源类型：0电费，1水费，3燃气',
  `amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '金额（元）',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件图片',
  `tag` tinyint(1) NULL DEFAULT NULL,
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `item`(`item`) USING BTREE,
  INDEX `unit_id`(`unit_id`) USING BTREE,
  INDEX `subject_id`(`subject_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '月度营收结算单据详情（支出）' ROW_FORMAT = Dynamic;

-- ----------------------------
