  `unit_id` int(11) NULL DEFAULT NULL COMMENT '单位id（参考 hr_account_unit_config.id）',
  `subject_id` int(11) NULL DEFAULT NULL COMMENT '科目id（参考 hr_receipt_subject_list.id）',
  `subject_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '科目名称（冗余）',
  `rel_type` tinyint(1) NULL DEFAULT NULL COMMENT '关联数据源类型：0电费，1水费，3燃气',
  `amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '金额（元）',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件图片',
  `tag` tinyint(1) NULL DEFAULT NULL,
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `item`(`item`) USING BTREE,
  INDEX `unit_id`(`unit_id`) USING BTREE,
  INDEX `subject_id`(`subject_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '月度营收结算单据详情（收入）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_monthly_revenue_settlement_log
-- ----------------------------
DROP TABLE IF EXISTS `hr_monthly_revenue_settlement_log`;
CREATE TABLE `hr_monthly_revenue_settlement_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '所属单据id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `before_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作前数据',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 113 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '月度营收结算单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_monthly_revenue_settlement_order
-- ----------------------------
DROP TABLE IF EXISTS `hr_monthly_revenue_settlement_order`;
CREATE TABLE `hr_monthly_revenue_settlement_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `record_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '记录年月，格式如：2025-10-07',
  `total_income` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '收入合计',
  `total_expend` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '支出合计',
  `profit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '本月利润',
  `real_profit` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '本月实际利润',
  `cost_rate` decimal(18, 2) NULL DEFAULT NULL COMMENT '综合成本率',
  `staple_food_last_stock_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '调料主食库存-上月库存金额',
  `staple_food_cur_stock_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '调料主食库存-本月库存金额',
  `staple_food_balance_stock_amount` decimal(18, 2) NULL DEFAULT NULL COMMENT '调料主食库存-库存结余金额',
  `staple_food_last_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调料主食库存-上月库存备注',
  `staple_food_cur_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调料主食库存-本月库存备注',
  `staple_food_balance_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调料主食库存-库存结余备注',
  `water_amount` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '水总支出',
  `electricity_amount` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '电总支出',
  `gas_amount` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '燃气总支出',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `dept_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人部门id',
  `dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人部门名称',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_order_no`(`order_no`) USING BTREE,
  INDEX `register_date`(`record_date`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '月度营收结算单据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_notice_list
-- ----------------------------
DROP TABLE IF EXISTS `hr_notice_list`;
CREATE TABLE `hr_notice_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '编号',
  `document_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文号编码',
  `document_number_id` int(11) NULL DEFAULT NULL COMMENT '文号编码id',
  `type_id` int(11) NOT NULL COMMENT '公告类型ID',
  `sort` int(11) NULL DEFAULT 0 COMMENT '显示顺序',
  `dept_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发布范围，部门ids',
  `user_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发布范围，用户ids',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发布内容',
  `file` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` tinyint(1) NOT NULL DEFAULT 2 COMMENT '状态 0=待提交；1=待审核；2=已完成；3=已驳回；4=已撤回；5=回退',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签字',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '部门id',
  `dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门文本',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `name`(`name`) USING BTREE,
  INDEX `type_id`(`type_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '人事管理-公告列表' ROW_FORMAT = Dynamic;

