-- Table structure for hr_onboard_order
-- ----------------------------
DROP TABLE IF EXISTS `hr_onboard_order`;
CREATE TABLE `hr_onboard_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `is_recruit` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=不关联；1=关联',
  `recruit_id` int(11) NULL DEFAULT NULL COMMENT '关联招聘id',
  `recruit_order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '招聘单据编号',
  `is_employee` tinyint(1) NULL DEFAULT 0 COMMENT '是否完善档案 0 否 1 是',
  `employee_id` int(11) NULL DEFAULT NULL COMMENT '关联人员档案记录id',
  `employee_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '工号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `entry_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入职日期',
  `phone_number` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '手机号码/账号',
  `is_create_no` tinyint(1) NULL DEFAULT 0 COMMENT '是否开通数智工厂账号 0 否 1 是',
  `uid` int(11) NULL DEFAULT NULL COMMENT '通数智工厂账号ID',
  `smart_fty_dept_id` int(10) NOT NULL COMMENT '数智工厂部门id',
  `smart_fty_dept_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数智工厂部门文本',
  `smart_fty_job_id` int(10) NOT NULL COMMENT '数智工厂岗位id',
  `smart_fty_job_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数智工厂岗位文本',
  `gender` tinyint(1) NOT NULL COMMENT '性别,1:男;2:女',
  `cert_type_id` tinyint(1) NULL DEFAULT NULL COMMENT '证件类型id',
  `cert_type_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证件类型文本',
  `cert_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '证件号码',
  `birth_date` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出生日期',
  `age` int(11) NULL DEFAULT NULL COMMENT '年龄',
  `native_id` int(11) NULL DEFAULT NULL COMMENT '籍贯id',
  `native_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '籍贯文本',
  `ethnicity_id` int(11) NULL DEFAULT NULL COMMENT '民族ID',
  `ethnicity_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '民族文本',
  `pol_status_id` tinyint(1) NULL DEFAULT NULL COMMENT '政治面貌id',
  `pol_status_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '政治面貌文本',
  `marital_status_id` tinyint(1) NULL DEFAULT NULL COMMENT '婚姻状况id',
  `marital_status_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '婚姻状况文本',
  `graduation_school` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '毕业学校名称',
  `highest_degree_id` tinyint(1) NULL DEFAULT NULL COMMENT '最高学历id',
  `highest_degree_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最高学历文本',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息(入职附件)',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '单据状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门id',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批人id',
  `signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入职签字',
  `signature_date` datetime NULL DEFAULT NULL COMMENT '签字时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `employee_number`(`employee_number`) USING BTREE,
  INDEX `is_employee`(`is_employee`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '入职管理单据' ROW_FORMAT = Dynamic;

