-- ----------------------------
-- Table structure for hr_rationaliza_suggest
-- ----------------------------
DROP TABLE IF EXISTS `hr_rationaliza_suggest`;
CREATE TABLE `hr_rationaliza_suggest`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '建议单号',
  `title` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建议标题',
  `source` tinyint(1) NULL DEFAULT NULL COMMENT '建议来源 1 合理化建议收集 2 意见箱 3 月度面谈',
  `time` datetime NULL DEFAULT NULL COMMENT '提报时间',
  `commit_uid` int(11) NULL DEFAULT NULL COMMENT '提报人ID',
  `commit_user_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提报人名称',
  `commit_mobile` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提报人联系方式',
  `commit_dept` int(11) NULL DEFAULT NULL COMMENT '提报人所属部门',
  `commit_dept_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提报人所属部门',
  `commit_bg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提报内容',
  `reviewers` int(11) NULL DEFAULT NULL COMMENT '审核/验收人ID',
  `reviewers_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核/验收人',
  `suggest_content` varchar(520) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建议描述',
  `note` varchar(520) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `commit_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提报图片,多个用逗号隔开',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0 待审核 1 待执行 2 待验收 3 已完成 4 已关闭 5 驳回 6=待复核 7=撤回',
  `commit_status` tinyint(1) NULL DEFAULT 0 COMMENT '建议状态 1 采纳建议 2 不给予采纳(关闭建议)',
  `sug_uid` int(11) NULL DEFAULT NULL COMMENT '建议执行落实人ID',
  `sug_user_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建议执行落实人名称',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '不采纳原因',
  `sug_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建议采纳备注',
  `last_execute_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '落实最晚期限',
  `execute_effect` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行效果 1节约费用 2 节约能耗 3 提升工作效率 多个用逗号隔开',
  `execute_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行落实时间',
  `exec_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行措施',
  `exec_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '执行附件,多个用逗号隔开',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `save_costs` decimal(10, 2) NULL DEFAULT NULL COMMENT '节约费用（元）',
  `save_water` decimal(10, 2) NULL DEFAULT NULL COMMENT '节约水量（t）',
  `save_electricity` decimal(10, 2) NULL DEFAULT NULL COMMENT '节约电量（kwh）',
  `save_steam` decimal(10, 2) NULL DEFAULT NULL COMMENT '节约蒸汽（t）',
  `save_gas` decimal(10, 2) NULL DEFAULT NULL COMMENT '节约燃气（m²）',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `ct_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `ct_dept_id` int(10) NULL DEFAULT NULL COMMENT '创建人部门id',
  `ct_job_id` int(10) NULL DEFAULT NULL COMMENT '创建人岗位id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批人id',
  `three_meet_id` int(11) NULL DEFAULT NULL COMMENT '关联三会召开记录id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `source`(`source`) USING BTREE,
  INDEX `time`(`time`) USING BTREE,
  INDEX `title`(`title`) USING BTREE,
  INDEX `commit_uid`(`commit_uid`) USING BTREE,
  INDEX `reviewers`(`reviewers`) USING BTREE,
  INDEX `sug_uid`(`sug_uid`) USING BTREE,
  INDEX `execute_effect`(`execute_effect`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '合理化建议' ROW_FORMAT = Dynamic;

