-- ----------------------------
-- Table structure for hr_rationaliza_suggest_log
-- ----------------------------
DROP TABLE IF EXISTS `hr_rationaliza_suggest_log`;
CREATE TABLE `hr_rationaliza_suggest_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '操作类型',
