  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `act` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
