-- ----------------------------
-- Table structure for hr_receipt_subject_list
-- ----------------------------
DROP TABLE IF EXISTS `hr_receipt_subject_list`;
CREATE TABLE `hr_receipt_subject_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `subject_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '收支科目名称',
  `item` tinyint(1) NULL DEFAULT NULL COMMENT '收支项目：1收入，2支出',
  `unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收支单位',
  `unit_id` int(11) NULL DEFAULT NULL COMMENT '收支单位id',
  `rel_type` tinyint(1) NULL DEFAULT NULL COMMENT '关联数据源类型：0电费，1水费，3燃气',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '状态 1禁用，2启用',
  `rank` int(11) NULL DEFAULT 0 COMMENT '显示顺序，值越大，越靠前',
