  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `tag` tinyint(1) NOT NULL DEFAULT 1 COMMENT '利润统计标识 1=纳入实际利润统计；2=不纳入实际利润统计',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `item`(`item`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '收支科目设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_reception_management
-- ----------------------------
DROP TABLE IF EXISTS `hr_reception_management`;
CREATE TABLE `hr_reception_management`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
