-- ----------------------------
-- Table structure for hr_reception_management_log
-- ----------------------------
DROP TABLE IF EXISTS `hr_reception_management_log`;
CREATE TABLE `hr_reception_management_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 99 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '接待管理日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_reception_management_meals
-- ----------------------------
DROP TABLE IF EXISTS `hr_reception_management_meals`;
CREATE TABLE `hr_reception_management_meals`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NULL DEFAULT NULL COMMENT '单据ID',
  `date` datetime NULL DEFAULT NULL COMMENT '记账日期',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '费用金额（元）',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '接待管理-餐食费用' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_reception_management_room
-- ----------------------------
DROP TABLE IF EXISTS `hr_reception_management_room`;
CREATE TABLE `hr_reception_management_room`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NULL DEFAULT NULL COMMENT '单据ID',
  `date` datetime NULL DEFAULT NULL COMMENT '记录日期',
  `rooms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '房间号',
  `buy_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '布草新购金额（元）',
  `clean_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '布草清洗金额（元）',
  `name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '布草名称',
  `name_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '布草数量信息',
  `change_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '易耗品更换金额（元）',
  `name2` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '易耗品名称',
  `name2_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '易耗品数量信息',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人ID',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `name`(`name`) USING BTREE,
  INDEX `name2`(`name2`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '接待管理-入住房间费用' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_reception_management_room_config
-- ----------------------------
DROP TABLE IF EXISTS `hr_reception_management_room_config`;
CREATE TABLE `hr_reception_management_room_config`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `item` tinyint(1) NULL DEFAULT 0 COMMENT '分类 0=布草； 1=易耗品；2=客房价格',
  `type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；1：启用；2：禁用；',
  `sort_val` int(11) NULL DEFAULT 0 COMMENT '排序值，数值越大，越靠前',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注信息',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '新购单价(元)',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `rooms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '客房',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `type_name`(`type_name`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE,
  INDEX `sort_val`(`sort_val`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客房设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_reception_management_stay
-- ----------------------------
DROP TABLE IF EXISTS `hr_reception_management_stay`;
CREATE TABLE `hr_reception_management_stay`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NULL DEFAULT NULL COMMENT '单据ID',
  `date` datetime NULL DEFAULT NULL COMMENT '记账日期',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '住宿金额（元）',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `rooms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '房间信息',
  `rooms_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '房间入住天数',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 59 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '接待管理-住宿费用' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_reception_management_type
-- ----------------------------
DROP TABLE IF EXISTS `hr_reception_management_type`;
CREATE TABLE `hr_reception_management_type`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '接待类型' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_recruit
-- ----------------------------
DROP TABLE IF EXISTS `hr_recruit`;
CREATE TABLE `hr_recruit`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `date` date NULL DEFAULT NULL COMMENT '应聘日期',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '姓名',
  `sex` tinyint(1) NULL DEFAULT NULL COMMENT '性别 1=男；2=女',
  `native_id` int(10) NULL DEFAULT NULL COMMENT '籍贯id',
  `native_txt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '籍贯文本',
  `marriage_id` tinyint(1) NULL DEFAULT NULL COMMENT '婚姻状况id',
  `marriage_txt` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '婚姻状况文本',
  `birth_day` date NULL DEFAULT NULL COMMENT '出生日期',
  `postion_id` int(10) NULL DEFAULT NULL COMMENT '应聘职务id',
  `postion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应聘职务',
  `salary` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '期望待遇',
  `politics_status_id` tinyint(1) NULL DEFAULT NULL COMMENT '政治面貌id',
  `politics_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '政治面貌',
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `residential_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '户籍地址',
  `id_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `graduate_school` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '毕业院校',
  `postal_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '通信地址',
  `major` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '专业',
  `highest_degree_id` tinyint(1) NULL DEFAULT NULL COMMENT '最高学历id',
  `highest_degree` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最高学历',
  `graduation_date` date NULL DEFAULT NULL COMMENT '毕业日期',
  `school_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '学校地点',
  `highest_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最高职称',
  `evaluation_year` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评定年份',
  `speciality` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作专长',
  `hobby` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人爱好',
  `foreign_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外语等级',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '电子邮箱',
  `type_id` int(10) NULL DEFAULT NULL COMMENT '招聘信息来源id',
  `type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '招聘信息来源',
  `is_stay` tinyint(1) NULL DEFAULT NULL COMMENT '是否住宿 1=是；2=否',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应聘备注',
  `files_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '应聘附件',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1：待审核；2=已完成；3=驳回；4=撤回；5=待筛选；6=初筛淘汰；7=待面试；8=待评估；9=待背调；10=面试淘汰；11=背调淘汰；12=已归档',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `apply_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_dept_id` int(10) NULL DEFAULT NULL COMMENT '创建人部门id',
  `ct_job_id` int(10) NULL DEFAULT NULL COMMENT '创建人岗位id',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `review_uids` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人id',
  `view_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '面试状态 0=等待安排面试；1=面试中；2=终止面试',
  `view_uid` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '面试官id',
  `is_applet` tinyint(1) NOT NULL DEFAULT 0 COMMENT '来源 0=PC；1=小程序',
  `onboard_order_id` int(11) NULL DEFAULT NULL COMMENT '入职管理id',
  `join_dept_id` int(11) NULL DEFAULT NULL COMMENT '拟定数智工厂部门ID',
  `join_job_id` int(11) NULL DEFAULT NULL COMMENT '拟定数智工厂岗位ID',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `date`(`date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '招聘管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_recruit_assoc
-- ----------------------------
DROP TABLE IF EXISTS `hr_recruit_assoc`;
CREATE TABLE `hr_recruit_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '招聘管理关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_recruit_config
-- ----------------------------
DROP TABLE IF EXISTS `hr_recruit_config`;
CREATE TABLE `hr_recruit_config`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '类型 1=招聘信息来源；2=面试综合评述项',
  `type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查项目',
  `option_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '选项配置',
  `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 2 COMMENT '状态：1=禁用，2=启用',
  `rank` int(11) NULL DEFAULT 0 COMMENT '排序值（越大越靠前）',
  `color` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '显示颜色（可选）',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_check` tinyint(1) NULL DEFAULT NULL COMMENT '是否需要背调 0=不需要；1=需要',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '创建人ID',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人姓名',
  `up_uid` int(10) UNSIGNED NOT NULL COMMENT '更新人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人姓名',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `rank`(`rank`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '招聘配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_recruit_home
-- ----------------------------
DROP TABLE IF EXISTS `hr_recruit_home`;
CREATE TABLE `hr_recruit_home`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `recruit_id` int(11) NULL DEFAULT NULL COMMENT '关联id',
  `relation_id` tinyint(1) NULL DEFAULT NULL COMMENT '关系id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '姓名',
  `age` int(10) NULL DEFAULT NULL COMMENT '年龄',
  `politics_status_id` tinyint(1) NULL DEFAULT NULL COMMENT '政治面貌id',
  `comapny_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作单位',
  `postion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职务',
  `mobile` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `recruit_id`(`recruit_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '家庭情况' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_recruit_interview
-- ----------------------------
DROP TABLE IF EXISTS `hr_recruit_interview`;
CREATE TABLE `hr_recruit_interview`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `recruit_id` int(11) NULL DEFAULT NULL COMMENT '关联id',
  `uid` int(10) NULL DEFAULT NULL COMMENT '面试官id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '面试官姓名',
  `date` datetime NULL DEFAULT NULL COMMENT '面试时间',
  `options_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '面试结果综合评述',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '补充说明',
  `result` tinyint(1) NULL DEFAULT NULL COMMENT '1=拟定试用；2=列入考虑；3=不予考虑',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '数智工厂部门id',
  `dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门名称',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '数智工厂岗位id',
  `job_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称',
  `signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '面试官签字',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=面试中；1=完成面试评述',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `recruit_id`(`recruit_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '招聘面试信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_recruit_job
-- ----------------------------
DROP TABLE IF EXISTS `hr_recruit_job`;
CREATE TABLE `hr_recruit_job`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `recruit_id` int(11) NULL DEFAULT NULL COMMENT '关联id',
  `comapny_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位名称',
  `postion` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职务',
  `sdate` date NULL DEFAULT NULL COMMENT '开始日期',
  `edate` date NULL DEFAULT NULL COMMENT '结束日期',
  `salary` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '薪资待遇',
  `leave_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '离职原因',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `recruit_id`(`recruit_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工作经历' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_recruit_log
-- ----------------------------
DROP TABLE IF EXISTS `hr_recruit_log`;
CREATE TABLE `hr_recruit_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_in_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 150 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '招聘管理日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_resign
-- ----------------------------
DROP TABLE IF EXISTS `hr_resign`;
CREATE TABLE `hr_resign`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `resign_uid` int(10) NOT NULL COMMENT '离职员工id',
  `resign_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '离职员工',
  `employee_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工号',
  `dept` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门',
  `entry_date` date NULL DEFAULT NULL COMMENT '入职日期',
  `position` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职位',
  `employment_form` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用工形式',
  `apply_date` date NOT NULL COMMENT '申请日期',
  `expect_resign_date` date NOT NULL COMMENT '预计离职日期',
  `resign_reason_id` int(10) NOT NULL COMMENT '离职原因表ID',
  `resign_reason` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '离职原因',
  `resign_type_id` int(11) NULL DEFAULT NULL COMMENT '离职类型ID',
  `resign_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '离职类型名称',
  `hr_review_uid` int(10) NOT NULL COMMENT 'HR审批人id',
  `hr_review_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'HR审批人',
  `file` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件',
  `filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件名称',
  `status` tinyint(1) NOT NULL COMMENT '单据状态；0：待确认；1：待审核；2：已完成；3：已驳回；4：已撤回；5：已反审',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  `is_create` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否创建宿舍退租单 0=否；1=是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `year`(`apply_date`) USING BTREE,
  INDEX `month`(`expect_resign_date`) USING BTREE,
  INDEX `employee_number`(`employee_number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '离职表' ROW_FORMAT = Dynamic;

