-- ----------------------------
-- Table structure for hr_reward_punish
-- ----------------------------
DROP TABLE IF EXISTS `hr_reward_punish`;
CREATE TABLE `hr_reward_punish`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `date` date NULL DEFAULT NULL COMMENT '申报日期',
  `uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '奖惩人员集合',
  `uid` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '奖惩人员id',
  `uid_str` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '奖惩人员文本',
  `employee_number` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '员工工号',
  `number` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖惩文号',
  `type_id` int(10) NULL DEFAULT NULL COMMENT '奖惩类型ID',
  `type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖惩类型',
  `type2_id` int(10) NULL DEFAULT NULL COMMENT '申报类型ID',
  `type2_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申报类型',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申报原因',
  `money` decimal(10, 2) NULL DEFAULT NULL COMMENT '奖惩金额',
  `describe` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事件描述',
  `imgs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '申报图片',
  `reason_analyse` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原因分析',
  `is_testing` tinyint(1) NULL DEFAULT NULL COMMENT '是否经过检测 0=否；1=是',
  `profit_analyse` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收益分析',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奖惩备注',
  `files_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '奖惩附件',
  `explain` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '奖惩说明',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1：待审核；2=已完成；3=驳回；4=撤回；',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_dept_id` int(10) NULL DEFAULT NULL COMMENT '创建人部门id',
  `ct_job_id` int(10) NULL DEFAULT NULL COMMENT '创建人岗位id',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `review_uids` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人id',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `date`(`date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '奖惩管理' ROW_FORMAT = Dynamic;

