-- ----------------------------
-- Table structure for hr_reward_punish_config
-- ----------------------------
DROP TABLE IF EXISTS `hr_reward_punish_config`;
CREATE TABLE `hr_reward_punish_config`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '类型 1=奖惩类型；2=申报类型',
