  `items3` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '考核项目(三级)',
  `weight3` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '权重%(三级)',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '考核内容',
  `standard` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评分标准',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 146 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准工时考核细则明细' ROW_FORMAT = Dynamic;

