-- ----------------------------
-- Table structure for hr_standard_rules_config
-- ----------------------------
DROP TABLE IF EXISTS `hr_standard_rules_config`;
CREATE TABLE `hr_standard_rules_config`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rule_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '月度绩效汇总规则名称',
  `status` tinyint(3) UNSIGNED NOT NULL DEFAULT 2 COMMENT '状态：1=禁用，2=启用',
  `rank` int(11) NULL DEFAULT 0 COMMENT '排序值（越大越靠前）',
  `color` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '显示颜色（可选）',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_need` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需要上下级复评 0=不需要；1=需要',
  `is_assessed_sign` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否需被考核人签字确认 0=不需要；1=需要',
  `ratio` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '自评占比',
  `ratio2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复评1占比',
  `ratio3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复评2占比',
  `day` int(10) NULL DEFAULT NULL COMMENT '绩效考核推送日期，默认每月最后一天',
  `day_num` int(10) NULL DEFAULT NULL COMMENT '超时推送日期（天）',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '创建人ID',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人姓名',
  `up_uid` int(10) UNSIGNED NOT NULL COMMENT '更新人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '更新人姓名',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `rank`(`rank`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准工时绩效考核设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_standard_rules_detail
-- ----------------------------
DROP TABLE IF EXISTS `hr_standard_rules_detail`;
CREATE TABLE `hr_standard_rules_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `config_id` int(10) UNSIGNED NOT NULL COMMENT '所属配置表id',
  `job_ids` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '岗位ID集合，多个用逗号分隔（来源job_list.job_id）',
  `job_names` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称集合，多个用逗号分隔',
  `is_cross_month` tinyint(1) NULL DEFAULT NULL COMMENT '绩效汇总周期，是否跨月；1：跨月；2：不跨月',
  `last_month_val` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '绩效汇总周期，上月值',
  `cur_month_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '绩效汇总周期，当月值',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '绩效汇总部门id',
  `dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '绩效汇总部门名称',
  `level_id` int(10) NULL DEFAULT NULL COMMENT '考核级别id',
  `level_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核级别',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人姓名',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人姓名',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `config_id`(`config_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准工时绩效考核设置明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_standard_working
-- ----------------------------
DROP TABLE IF EXISTS `hr_standard_working`;
CREATE TABLE `hr_standard_working`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rules_id` int(11) NULL DEFAULT NULL COMMENT '绩效规则id',
