  `dept_id` int(10) NULL DEFAULT NULL COMMENT '部门id',
  `dept` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门',
  `people_num` int(10) NULL DEFAULT NULL COMMENT '考核人数',
  `uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '考核员工id',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1=审核中；2=已完成；3=驳回；4=撤回',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编制签字',
  `signature2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核签字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批人签字',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人id',
  `level_id` int(10) NULL DEFAULT NULL COMMENT '考核级别id',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `rules_id`(`rules_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 84 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准工时绩效' ROW_FORMAT = Dynamic;

