-- ----------------------------
-- Table structure for hr_standard_working_user
-- ----------------------------
DROP TABLE IF EXISTS `hr_standard_working_user`;
CREATE TABLE `hr_standard_working_user`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NULL DEFAULT NULL COMMENT '关联绩效id',
  `uid` int(10) NULL DEFAULT NULL COMMENT '考核员工id',
  `work_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工号',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核员工姓名',
  `is_need` int(1) NULL DEFAULT 0 COMMENT '是否需要上下级复评 0=不需要；1=需要',
  `is_assessed_sign` int(1) NULL DEFAULT 0 COMMENT '是否需被考核人签字确认 0=不需要；1=需要	',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '考核员工部门id',
  `dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核员工部门',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '考核员工岗位id',
  `job_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核员工岗位',
  `rules_id` int(11) NULL DEFAULT NULL COMMENT '绩效考核明细id',
  `config_id` int(11) NULL DEFAULT NULL COMMENT '绩效考核id',
  `rule_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '绩效考核名称',
  `level_id` int(10) NULL DEFAULT NULL COMMENT '绩效考核明细等级id',
  `level_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '绩效考核明细等级名称',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核细则标题',
  `standard_id` int(11) NULL DEFAULT NULL COMMENT '考核细则id',
  `date` date NULL DEFAULT NULL COMMENT '考核月份',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1=审核中；2=已完成；3=驳回；4=撤回；5=待员工确认；6=已申诉',
  `appeal_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申诉信息',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批人签字',
  `content` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '填写内容',
  `content2` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '填写内容2',
  `content3` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '填写内容3',
  `content4` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '填写内容4（这里表示下月工作计划）',
  `self_evaluation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自评',
  `re_evaluation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复评',
  `re_evaluation_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复评签名',
  `re_evaluation_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复评备注',
  `re_evaluation2` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复评2',
  `re_evaluation2_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复评2签名',
  `re_evaluation2_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复评2备注',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评级',
  `review_uids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人id',
  `re_evaluation_uids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复评人id',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '考核分配置',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `review_uids`(`review_uids`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1094 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准工时绩效考核员工' ROW_FORMAT = Dynamic;

