-- ----------------------------
-- Table structure for hr_talent_pool
-- ----------------------------
DROP TABLE IF EXISTS `hr_talent_pool`;
CREATE TABLE `hr_talent_pool`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `uid` int(10) NULL DEFAULT NULL COMMENT '员工ID',
