-- ----------------------------
DROP TABLE IF EXISTS `hr_trai_plan_list`;
CREATE TABLE `hr_trai_plan_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号(计划编号)',
  `trai_topic` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '培训课题',
  `trai_category` int(11) NOT NULL COMMENT '培训类别id',
  `trai_category_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训类别文本',
  `trai_goods_id` int(11) NULL DEFAULT NULL COMMENT '培训物ID',
  `trai_goods` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训物名称',
  `trai_dept_ids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '培训部门id,多个用逗号隔开',
  `trai_dept_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训部门文本',
  `trainer_uids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '培训人uid,多个用逗号隔开',
  `trainer_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '培训人文本',
  `trainee_uids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '受训人uid,多个用逗号隔开',
  `trainee_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '受训人文本',
  `notice_receiver_uids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提醒接收人,多个用逗号隔开',
  `notice_receiver_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提醒接收人文本',
  `plan_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '计划信息',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息',
  `estimate_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '估算费用',
  `trai_method` tinyint(1) NOT NULL COMMENT '培训方式;1:内训;2:外训;3:公开课;',
  `schedule_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时间安排年月',
  `notice_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '计划提醒类型,多个用逗号隔开;1:截止前30天；2：截止前15天；3：截止前7天',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：待执行；1：执行中；2：已完成；3：已终止；4=待提交；5=待审核 6=已驳回；7=已撤回；8=已逾期；9=延期待确认',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '建单部门id',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `trai_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训地点',
  `trai_times` int(10) NULL DEFAULT NULL COMMENT '培训时长',
  `trai_learn` int(10) NULL DEFAULT NULL COMMENT '培训必学',
  `trai_modality` int(10) NULL DEFAULT NULL COMMENT '培训形式',
  `is_textbook` tinyint(4) NULL DEFAULT 0 COMMENT '是否有教材 0：无；1：有',
  `trai_textbook` int(10) NULL DEFAULT NULL COMMENT '培训教材',
  `trai_type` int(10) NULL DEFAULT NULL COMMENT '培训类型',
  `trai_assess` int(10) NULL DEFAULT NULL COMMENT '考核方式',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人id',
  `overdue_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '延期时间安排年月',
  `overdue_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '延期原因',
  `overdue_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '延期附件',
  `overdue_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '延期审核签字',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 169 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训计划表' ROW_FORMAT = Dynamic;

