  `order_id` int(10) UNSIGNED NOT NULL COMMENT '对应单据id',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '日志类型；1：操作日志；2：系统日志',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `before_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作前数据',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 170 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训类型表操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for hr_training_monthly_report
-- ----------------------------
DROP TABLE IF EXISTS `hr_training_monthly_report`;
CREATE TABLE `hr_training_monthly_report`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `date` date NULL DEFAULT NULL COMMENT '统计年月',
  `rule_id` int(11) NULL DEFAULT NULL COMMENT '月度规则id',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '部门id',
  `dept_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门名称',
  `start_date` date NULL DEFAULT NULL COMMENT '汇总开始时间',
  `over_date` date NULL DEFAULT NULL COMMENT '汇总结束时间',
  `total_num` int(10) NULL DEFAULT NULL COMMENT '总场数',
  `total_minutes` decimal(10, 2) NULL DEFAULT NULL COMMENT '总时长',
  `again_num` int(10) NULL DEFAULT NULL COMMENT '复训场数',
  `valid_num` int(10) NULL DEFAULT NULL COMMENT '有效场数',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1=待审核；2=已完成；3=已驳回；4=已撤回',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人id',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `rule_id`(`rule_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训月报' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_training_monthly_report_assoc
-- ----------------------------
DROP TABLE IF EXISTS `hr_training_monthly_report_assoc`;
CREATE TABLE `hr_training_monthly_report_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训月报关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_training_monthly_report_log
-- ----------------------------
DROP TABLE IF EXISTS `hr_training_monthly_report_log`;
CREATE TABLE `hr_training_monthly_report_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_in_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训月报日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_training_record
-- ----------------------------
DROP TABLE IF EXISTS `hr_training_record`;
CREATE TABLE `hr_training_record`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `training_plan_type` tinyint(1) NULL DEFAULT NULL COMMENT '培训类型 0=计划外培训 1=计划内培训',
  `plan_id` int(10) NULL DEFAULT NULL COMMENT '关联培训计划id',
  `plan_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联培训计划编号',
  `training_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训课题',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训编号',
  `training_category_id` int(10) NULL DEFAULT NULL COMMENT '培训类别id',
  `training_category` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训类别',
  `trai_goods_id` int(11) NULL DEFAULT NULL COMMENT '培训物ID',
  `trai_goods` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训物名称',
  `training_department` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '培训部门',
  `training_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训地点',
  `training_uid` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '培训人id,多个用逗号隔开',
  `training_uid_name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '培训人名称，多个用逗号隔开',
  `trainee_uids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '受训人',
  `position` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '职务-培训人岗位',
  `training_date` date NULL DEFAULT NULL COMMENT '培训日期',
  `training_over_date` date NULL DEFAULT NULL COMMENT '培训结束日期',
  `training_start_time` time NOT NULL COMMENT '培训开始时间',
  `training_end_time` time NULL DEFAULT NULL COMMENT '培训结束时间',
  `training_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训内容',
  `training_way` tinyint(1) NULL DEFAULT NULL COMMENT '培训方式 1：内训；2：外训；3：公开课',
  `training_cost_choose` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训费用选项',
  `training_cost_other` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训费用其它',
  `training_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '培训费用',
  `training_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `training_file` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件url',
  `training_filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件名称',
  `training_imgs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '培训现场照片',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '0：未开始；1：进行中(开始会议)；2：评估中(结束会议)；3：已完成：4：已终止 5 待验收 6=待审核',
  `review_status` tinyint(4) NULL DEFAULT 0 COMMENT '评估审批状态 0：待评估； 1：提交人评估；2：部门审批评估；3：主管审批评估；4：公司领导审批评估',
  `no_pass_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `accep_uid` int(11) NULL DEFAULT NULL COMMENT '验收人ID',
  `accep_user` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '验收人',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `start_date` datetime NULL DEFAULT NULL COMMENT '培训开始时间（年月日时分秒）',
  `end_date` datetime NULL DEFAULT NULL COMMENT '培训结束时间（年月日时分秒）',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终止原因',
  `evaluation_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '评估状态 0：未完成；1：已完成',
  `statistical_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '统计状态 0：未完成；1：已完成',
  `code_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签到二维码链接',
  `organization_department` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '组织部门',
  `is_again` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否复训 0：否；1：是',
  `is_textbook` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否有教材 0：无；1：有',
  `trai_textbook` int(10) NULL DEFAULT NULL COMMENT '培训教材',
  `trai_textbook_mb` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否有模板 0=无；1=有',
  `trai_textbook_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手动输入培训教材文本',
  `trai_period` int(10) NULL DEFAULT NULL COMMENT '培训时段',
  `trai_method` int(10) NULL DEFAULT NULL COMMENT '培训方法',
  `trai_divide` int(10) NULL DEFAULT NULL COMMENT '培训内容划分',
  `trai_type` int(10) NULL DEFAULT NULL COMMENT '培训类型',
  `trai_assess` int(10) NULL DEFAULT NULL COMMENT '考核方式',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `review_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核附件',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人id',
  `sign_check` tinyint(1) NOT NULL DEFAULT 0 COMMENT '签到电子围栏 0=关闭；1=开启',
  `province` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '省份名称',
  `city` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '城市名称',
  `district` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区名称',
  `town` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '街道名称',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `fence_radius` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签到限制范围',
  `longitude` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '纬度',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `training_category_id`(`training_category_id`) USING BTREE,
  INDEX `start_date`(`start_date`) USING BTREE,
  INDEX `end_date`(`end_date`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 179 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_training_record_assoc
-- ----------------------------
DROP TABLE IF EXISTS `hr_training_record_assoc`;
CREATE TABLE `hr_training_record_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_training_record_detail
-- ----------------------------
DROP TABLE IF EXISTS `hr_training_record_detail`;
CREATE TABLE `hr_training_record_detail`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NULL DEFAULT NULL COMMENT '关联单据id',
  `evaluation_mode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核方式',
  `training_effect_evaluation` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训效果评估',
  `training_effect_tracking` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训效果追踪',
  `personal_summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人总结',
  `department_assessment_status` tinyint(1) NULL DEFAULT NULL COMMENT '受训人所在部门评估结果 0：未达到预期；1：达到预期',
  `department_assessment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受训人所在部门评估',
  `supervisor_evaluation_status` tinyint(1) NULL DEFAULT NULL COMMENT '培训主管部门评估结果 0：未达到预期；1：达到预期',
  `supervisor_evaluation` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训主管部门评估',
  `company_evaluation_status` tinyint(1) NULL DEFAULT NULL COMMENT '公司领导评估结果 0：未达到预期；1：达到预期',
  `company_evaluation` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司领导评估',
  `conclusion_status` tinyint(1) NULL DEFAULT NULL COMMENT '结论结果 0：未达到预期；1：达到预期',
  `conclusion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结论',
  `department_id` int(11) NULL DEFAULT NULL COMMENT '部门审批人id',
  `department_date` datetime NULL DEFAULT NULL COMMENT '部门审批时间',
  `department_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门审批签字',
  `supervisor_id` int(11) NULL DEFAULT NULL COMMENT '主管审批人ID',
  `supervisor_date` datetime NULL DEFAULT NULL COMMENT '主管审批时间',
  `supervisor_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主管审批签字',
  `company_id` int(11) NULL DEFAULT NULL COMMENT '公司领导审批人ID',
  `company_date` datetime NULL DEFAULT NULL COMMENT '公司领导审批时间',
  `company_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '公司领导审批签字',
  `files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '总结附件',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 111 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '培训记录评估意见表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for hr_training_record_evaluate
-- ----------------------------
DROP TABLE IF EXISTS `hr_training_record_evaluate`;
CREATE TABLE `hr_training_record_evaluate`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `training_id` int(10) NULL DEFAULT NULL COMMENT '培训记录ID',
  `uid` int(10) NULL DEFAULT NULL COMMENT '受训人ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受训人名称',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '受训人部门ID',
  `dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受训人部门',
  `anonymity` tinyint(1) NOT NULL DEFAULT 0 COMMENT '匿名 0：否；1：是',
  `e_result` tinyint(1) NULL DEFAULT NULL COMMENT '课程安排合理程度 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result2` tinyint(1) NULL DEFAULT NULL COMMENT '课程内容的深度和理解性 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result3` tinyint(1) NULL DEFAULT NULL COMMENT '课程内容对实际工作的帮助程度 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result4` tinyint(1) NULL DEFAULT NULL COMMENT '培训师课件准备程度 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result5` tinyint(1) NULL DEFAULT NULL COMMENT '培训师语言表达和讲课态度 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result6` tinyint(1) NULL DEFAULT NULL COMMENT '培训师对培训内容的个人见解 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result7` tinyint(1) NULL DEFAULT NULL COMMENT '培训方式多样性和培训氛围 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result8` tinyint(1) NULL DEFAULT NULL COMMENT '您对本次课程的总体评价 1=很不满意；2=不满意；3=一般；4=满意；5=很满意',
  `e_result9` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '您认为培训师授课还需在哪些方面提高?',
  `e_result10` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '您希望公司提供哪些相关的培训课程及内容?',
