-- ----------------------------
DROP TABLE IF EXISTS `hr_training_record_statistics`;
CREATE TABLE `hr_training_record_statistics`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `training_id` int(10) NULL DEFAULT NULL COMMENT '关联培训记录id',
  `uid` int(10) NULL DEFAULT NULL COMMENT '受训人id',
