-- ----------------------------
-- Table structure for hr_vehicle_accident
-- ----------------------------
DROP TABLE IF EXISTS `hr_vehicle_accident`;
CREATE TABLE `hr_vehicle_accident`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `date` date NULL DEFAULT NULL COMMENT '事故日期',
  `car_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车牌号',
  `car_number_id` int(11) NULL DEFAULT NULL COMMENT '车牌号ID',
  `drive_uid` int(10) NULL DEFAULT NULL COMMENT '事故驾驶员ID',
  `drive_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事故驾驶员',
  `other_index` tinyint(1) NULL DEFAULT NULL COMMENT '事故责任方下标 0=主责方；1=次责方',
  `other` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事故责任方',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事故地点',
  `content` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '情况描述',
  `risk_index` tinyint(1) NULL DEFAULT NULL COMMENT '出险类别 0=商业险；1=雇主险；2=超赔险；3=盗抢险；4=车损险',
  `risk` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出险类别',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '赔付金额(元)',
  `price2` decimal(10, 2) NULL DEFAULT NULL COMMENT '事故维修费用(元)',
  `total_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '总金额(元)',
  `note` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待确认；1=待审核；2=已完成；3=驳回；4=撤回；5=作废',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `ct_dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门id',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `car_number`(`car_number`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `risk_index`(`risk_index`) USING BTREE,
  INDEX `car_number_id`(`car_number_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '车辆事故记录' ROW_FORMAT = Dynamic;

