-- Table structure for hr_vehicle_apply
-- ----------------------------
DROP TABLE IF EXISTS `hr_vehicle_apply`;
CREATE TABLE `hr_vehicle_apply`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `is_out` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=内部；2=外部',
  `apply_uid` int(10) NULL DEFAULT NULL COMMENT '申请人id',
  `apply_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请人',
  `use_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '用车人类型 0-=内部；1=外部',
  `use_uid` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用车人id',
  `use_name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用车人',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '申请部门id',
  `dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请部门',
  `mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用车人电话',
  `use_index` tinyint(1) NULL DEFAULT NULL COMMENT '用车类型 0=市内；1=市外',
  `reasons` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用车事由',
  `rotes` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行驶路线',
  `start_date` datetime NULL DEFAULT NULL COMMENT '用车起始时间',
  `over_date` datetime NULL DEFAULT NULL COMMENT '用车结束时间',
  `people_num` int(10) NULL DEFAULT NULL COMMENT '乘车人数',
  `week` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '星期',
  `duration` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用车时长',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用车备注',
  `files_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '用车附件',
  `driver_id` int(10) NULL DEFAULT NULL COMMENT '司机id',
  `driver_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出车司机',
  `car_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车牌号',
  `car_number_id` int(10) NULL DEFAULT NULL COMMENT '车id',
  `other_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他要求',
  `mileage_limit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '止公里数',
  `return_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换车备注',
  `return_files_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '还车附件',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态 0=待提交；1=待审核；2-已完成；3=已驳回；4=审核撤回；7=派车撤回',
  `car_status` tinyint(1) NOT NULL DEFAULT 2 COMMENT '0=待派车；1=待还车；2=已还车',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `review_uids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `use_index`(`use_index`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `start_date`(`start_date`) USING BTREE,
  INDEX `car_number`(`car_number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用车申请' ROW_FORMAT = Dynamic;

