-- ----------------------------
-- Table structure for hr_vehicle_file
-- ----------------------------
DROP TABLE IF EXISTS `hr_vehicle_file`;
CREATE TABLE `hr_vehicle_file`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `car_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车牌号',
  `car_number_id` int(11) NULL DEFAULT NULL COMMENT '车牌号ID',
  `car_color` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车辆颜色',
  `big_upkeep` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养周期(大保)',
  `small_upkeep` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养周期(小保)',
  `expire_date` date NULL DEFAULT NULL COMMENT '交强险到期日期',
  `gearbox` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '变速箱',
  `gearbox_index` tinyint(1) NULL DEFAULT NULL COMMENT '变速箱下标 0=自动挡；1=手动挡；2=其它',
  `expire_date2` date NULL DEFAULT NULL COMMENT '商业险到期日期',
  `annual_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年审周期',
  `displacement` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排量',
  `scrapping_period` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报废信息',
  `scrapped_kilometers` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报废公里数',
  `sale_price` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '变卖价格(元)',
  `disposal_date` date NULL DEFAULT NULL COMMENT '处置日期',
  `car_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '车辆照片',
  `brand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `date` date NULL DEFAULT NULL COMMENT '车辆购置日期',
  `price` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '购置价格',
  `engine_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发动机号',
  `vehicle_identification_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车架号',
  `use` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用性质',
  `use_index` tinyint(1) NULL DEFAULT NULL COMMENT '使用性质 0=非运营；1=运营',
  `status` tinyint(1) NOT NULL DEFAULT 2 COMMENT '状态 2=生效中；3=归档',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `car_number`(`car_number`) USING BTREE,
  INDEX `car_number_id`(`car_number_id`) USING BTREE,
  INDEX `brand`(`brand`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '车辆档案' ROW_FORMAT = Dynamic;

