  `document_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `stock_qty` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '库存数量',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称(上线时候去掉这个字段)',
  `transaction_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '交易日期',
  `warehouse_id` int(11) NOT NULL COMMENT '仓库id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `ws_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架位',
  `pro_time` datetime NULL DEFAULT NULL COMMENT '生产日期',
  `exp_time` datetime NULL DEFAULT NULL COMMENT '到期日期',
  `is_gen_uniq` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成唯一；0:不生成,1:生成',
  `sup_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id（本字段是做原料入库送检单时候加的）',
  `in_detail_id` int(11) NULL DEFAULT NULL COMMENT '入库时关联的明细id（一般只有原料入库单才记录）',
  `procure_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采购单号',
  `in_wh_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库单号（记录初始入库单号）',
  `price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '单价（含税单价）',
  `stock_price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '在库金额',
  `in_wh_date` datetime NULL DEFAULT NULL COMMENT '入库日期',
  `stock_id` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '库存明细id,记录入库时通过哪个库存明细入库的',
  `available_status` tinyint(1) NULL DEFAULT 0 COMMENT '可用状态；0：可用（非限制）；1：待修；2：报废；3：限制（质量检查）；4：冻结 ；5 占用',
  `exp_day` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '保质期',
  `exp_warning_day` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '保质期预警天数',
  `is_expensed_assets` tinyint(1) NULL DEFAULT 0 COMMENT '是否费用化资产；0：不是；1：是',
  `initial_in_wh_date` datetime NULL DEFAULT NULL COMMENT '初始入库日期，记录最早的入库日期',
  `initial_stock_id` int(11) NULL DEFAULT NULL COMMENT '初始入库库存id',
  `detail_ctime` datetime NULL DEFAULT NULL COMMENT '从库存出入明细同步过来的create_time,留作后期备用',
  `sap_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP采购凭证',
  `sap_wl_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP物料凭证',
  `sap_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP凭证日期',
  `ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次号（内部批次）',
  `original_ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '入库类型；0：采购入库/正常入库；1：冲销入库 2：食材入库',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `in_use_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '占用数（单据占用）',
  `use_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已用数（单据完结）',
  `reserve_decimal` tinyint(1) NULL DEFAULT 0 COMMENT '保留小数',
  `is_complete` tinyint(1) NULL DEFAULT NULL COMMENT '是否外观完整； 0:否,1:是',
  `is_weigh` tinyint(1) NULL DEFAULT NULL COMMENT '是否入库称重； 0:否,1:是',
  `is_check_pk` tinyint(1) NULL DEFAULT NULL COMMENT '是否核对外包装：0:否,1:是',
  `is_info_accord` tinyint(1) NULL DEFAULT NULL COMMENT '是否条码包装信息一致：0:否,1:是',
  `batch_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次',
  `pack_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '包号',
  `ph_pack_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次包号，中间用-隔开',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `is_batch` tinyint(1) NULL DEFAULT 0 COMMENT '是否多批次录入；0：不是；1：是',
  `is_rev` tinyint(1) NULL DEFAULT 0 COMMENT '是否关联入库检查单 0 否 1 是',
  `factory_id` int(11) NULL DEFAULT NULL COMMENT '厂商id（供应商id）',
  `factory_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '产线id',
  `line_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产线名称',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人UID',
  `snapshot_date` date NOT NULL COMMENT '快照日期',
  `go_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '去税单价',
  `go_tax_total_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '去税小计',
  `tax_rate` tinyint(2) NULL DEFAULT NULL COMMENT '税率,默认13',
  `avg_before_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '平均单价(去税)',
  `avg_go_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '平均单价(含税)',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_src_date`(`src_id`, `snapshot_date`) USING BTREE,
  INDEX `ws_code`(`ws_code`) USING BTREE,
  INDEX `batch_number`(`batch_number`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `inventory_id`(`inventory_id`) USING BTREE,
  INDEX `goods_id_ws`(`goods_id`, `ws_code`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `original_ph_no_pack`(`original_ph_no`, `pack_no`) USING BTREE,
  INDEX `batch_pack_no`(`batch_no`, `pack_no`) USING BTREE,
  INDEX `snapshot_date`(`snapshot_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 692417 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存明细快照表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for inventory_stocks_unique
-- ----------------------------
DROP TABLE IF EXISTS `inventory_stocks_unique`;
CREATE TABLE `inventory_stocks_unique`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `inventory_id` int(11) NULL DEFAULT NULL COMMENT '库存总表id',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：在库；1：已出库；2：待使用；3：上线中；4：使用中；5：下线中；6：已下线；',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `num` int(11) UNSIGNED NULL DEFAULT 1 COMMENT '数量',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人UID',
  `unique_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '唯一值',
  `sort` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '排序值',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2627 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存明细唯一标识表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for inventory_stocks_unique_label_record
-- ----------------------------
DROP TABLE IF EXISTS `inventory_stocks_unique_label_record`;
CREATE TABLE `inventory_stocks_unique_label_record`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '单据id',
  `detail_id` int(10) NOT NULL COMMENT '单据明细id',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '商品id',
  `operate_status` tinyint(1) NOT NULL COMMENT '操作类型；0：新增/编辑-未完成；1：删除-未完成 2：审批-已完成',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '更换类型；1：换上设备；2：换下设备',
  `stock_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '库存明细id',
  `unique_code` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '唯一标签',
  `order_type` smallint(5) NULL DEFAULT NULL COMMENT '单据类型；1采购入库 2退货出库 3领料出库 4退料入库 5调拨 6盘点 7报废 8采购单 9采购退货单 10采购换货单 11换上设备 12换下设备；',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `unique_code`(`unique_code`) USING BTREE,
  INDEX `document_type`(`order_type`) USING BTREE,
  INDEX `unique_code_2`(`unique_code`, `order_type`) USING BTREE,
  INDEX `operate_status`(`operate_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1428 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存唯一标签使用明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for job_hazard_project
-- ----------------------------
DROP TABLE IF EXISTS `job_hazard_project`;
CREATE TABLE `job_hazard_project`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `job_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工种类型',
  `job_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位id，多个用逗号隔开',
  `work_day` decimal(10, 2) NULL DEFAULT NULL COMMENT '接触天',
  `work_hour` decimal(10, 2) NULL DEFAULT NULL COMMENT '接触小时/天',
  `dense_type` tinyint(1) NULL DEFAULT NULL COMMENT '岗位浓度类型 1=相对稳定；2=相对不稳定',
  `place_id` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作地点',
  `source` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源或产生途径 1=原料；2=设备',
  `item` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体检项目 1=粉尘；2=噪声；3=电磁辐射；4=高温；5=化学因素；6=健康证',
  `use_situation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '个人防护及用品使用情况',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=正常；1=已删除',
  `detail_num` int(10) NULL DEFAULT NULL COMMENT '职业病危害因素数量',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `job_id`(`job_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '职业危害项目' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for job_hazard_project_detail
-- ----------------------------
DROP TABLE IF EXISTS `job_hazard_project_detail`;
CREATE TABLE `job_hazard_project_detail`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NULL DEFAULT NULL COMMENT '关联单据id',
  `factor` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '职业病危害因素',
  `source` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源或产生途径 1=原料；2=设备',
  `item` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体检项目 1=粉尘；2=噪声；3=电磁辐射；4=高温；5=化学因素；6=健康证',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 67 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '职业危害项目详情' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for job_list
-- ----------------------------
DROP TABLE IF EXISTS `job_list`;
CREATE TABLE `job_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '部门ID',
  `rank` int(10) NULL DEFAULT 0 COMMENT '菜单排序,越大越前',
  `pay_min` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '建议薪资最小',
  `pay_max` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '建议薪资最大',
  `requirement` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '就职条件',
  `describe` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '岗位职责',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态；1：启用；0：未启用；',
  `place_id` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作地点',
  `place_text` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作地点文本',
  `job_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作内容',
  `people_num` int(10) NULL DEFAULT NULL COMMENT '岗位标配人数',
  `job_system` tinyint(1) NULL DEFAULT NULL COMMENT '工作班制 1=白班制；2=三班制',
  `job_type` tinyint(1) NULL DEFAULT NULL COMMENT '岗位作业类型 1=固定；2=流动',
  `job_day` int(10) NULL DEFAULT NULL COMMENT '工作天制',
  `job_hour` decimal(10, 1) NULL DEFAULT NULL COMMENT '工作小时/天',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(10) NULL DEFAULT NULL,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `up_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '岗位管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_air_compressor_daily_operation_record
-- ----------------------------
DROP TABLE IF EXISTS `mro_air_compressor_daily_operation_record`;
CREATE TABLE `mro_air_compressor_daily_operation_record`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `date` date NOT NULL COMMENT '检查日期',
  `check_uid` int(10) NOT NULL COMMENT '检查人id',
  `check_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检查人',
  `device` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备（多个用,隔开）',
  `device_status` tinyint(1) NULL DEFAULT NULL COMMENT '设备状态 1-开机 0-停机',
  `operate_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '运行情况',
  `workshop_id` int(10) NULL DEFAULT NULL COMMENT '车间id',
  `workshop_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名字',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '空压机日常运行记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_air_compressor_daily_operation_record_assoc
-- ----------------------------
DROP TABLE IF EXISTS `mro_air_compressor_daily_operation_record_assoc`;
CREATE TABLE `mro_air_compressor_daily_operation_record_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '空压机日常运行记录表id',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '空压机日常运行记录表关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_air_compressor_daily_operation_record_list
-- ----------------------------
DROP TABLE IF EXISTS `mro_air_compressor_daily_operation_record_list`;
CREATE TABLE `mro_air_compressor_daily_operation_record_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '空压机日常运行记录表ID',
  `time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检查时间',
  `pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '压力',
  `temperature` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '温度',
  `power_consumption` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '耗电量',
  `tank_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '储罐压力',
  `air_dryer_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '冷干机压力',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) NOT NULL COMMENT '创建人',
