  `order_type` tinyint(1) NULL DEFAULT NULL COMMENT '抄表类型；0：电表；1：水表；2：蒸汽表；3：燃气表',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `before_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作前数据',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `replacement_id`(`document_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 606 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '抄表记录操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for mro_energy_meter_records
-- ----------------------------
DROP TABLE IF EXISTS `mro_energy_meter_records`;
CREATE TABLE `mro_energy_meter_records`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `serial_number_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '抄表流水号',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '抄表类型；0：电表；1：水表；2：蒸汽表 3：燃气表',
  `rel_id` int(11) NULL DEFAULT NULL COMMENT '远程仪表ID',
  `rel_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集表名/远程仪表名称',
  `rule` tinyint(1) NULL DEFAULT 0 COMMENT '自动抄表规则 0 不自动 1 按班次 2 按每天 3 按每月',
  `equipment_id` int(11) NULL DEFAULT NULL COMMENT '表计设备id',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称/仪表名称',
  `is_produce` tinyint(1) NULL DEFAULT NULL COMMENT '是否生产；0：否；1：是',
  `equipment_type_id` int(11) NULL DEFAULT 0 COMMENT '表计类型(设备类型id)',
  `equipment_type_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪表类型名称',
  `start_time` datetime NULL DEFAULT NULL COMMENT '起码时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '止码时间',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '固定资产编号/仪表编码',
  `class_type` int(11) NULL DEFAULT 0 COMMENT '班次(来自基础数据同品质班组)',
  `class_no` tinyint(2) UNSIGNED NULL DEFAULT 0 COMMENT '班别 1早 2中 3晚',
  `start_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '起码读数',
  `end_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '止码读数',
  `dosage_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '用量',
  `real_dosage_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '实际用量',
  `multiplier` decimal(18, 2) NULL DEFAULT 1.00 COMMENT '倍率',
  `purpose` tinyint(2) NULL DEFAULT NULL COMMENT '用途；0：生产；1：清洁；2：其他',
  `use_addr` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '使用位置，用逗号隔开',
  `use_addr_text` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用位置',
  `last_meter_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上次抄表时间',
  `this_meter_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '本次抄表时间',
  `meter_readings_time` datetime NULL DEFAULT NULL COMMENT '抄表时间',
  `meter_readings_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '抄表人id',
  `time` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抄表时分',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `is_valid` tinyint(1) NULL DEFAULT 1 COMMENT '是否有效 0 无效 1 有效',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `class_type`(`class_type`, `class_no`) USING BTREE,
  INDEX `type`(`equipment_type_id`) USING BTREE,
  INDEX `is_produce`(`is_produce`) USING BTREE,
  INDEX `rule`(`rule`) USING BTREE,
  INDEX `type_3`(`type`, `rel_id`, `this_meter_time`) USING BTREE,
  INDEX `this_meter_time`(`this_meter_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43253 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '抄表记录表' ROW_FORMAT = Dynamic;

