  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 266 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备交接班记录表日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_eq_shift_record
-- ----------------------------
DROP TABLE IF EXISTS `mro_eq_shift_record`;
CREATE TABLE `mro_eq_shift_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `date_time` date NOT NULL COMMENT '交接日期（年月日）',
  `class_no` int(11) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_no_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次文本',
  `class_type` int(11) NULL DEFAULT NULL COMMENT '班组id',
  `class_type_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组文本',
  `workshop_tools_res` tinyint(1) NULL DEFAULT NULL COMMENT '车间工具是否齐全 1:是 2:否',
  `keys_res` tinyint(1) NULL DEFAULT NULL COMMENT '机修间、配电房、库房、工具柜钥匙是否齐全 1:是 2:否',
  `clean_res` tinyint(1) NULL DEFAULT NULL COMMENT '洁净工具专用车工具清洁且完整 1:是 2:否',
  `yield_num_total` decimal(18, 4) NULL DEFAULT NULL COMMENT '累计产量(万罐)',
  `liquid_total` decimal(18, 4) NULL DEFAULT NULL COMMENT '累计液位(ml)',
  `duty_mechanic_uid` int(11) NULL DEFAULT NULL COMMENT '当班机修工uid',
  `duty_mechanic_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班机修工文本',
  `shift_mechanic_uid` int(11) NULL DEFAULT NULL COMMENT '接班机修工uid',
  `shift_mechanic_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接班机修工文本',
  `duty_elec_uid` int(11) NULL DEFAULT NULL COMMENT '当班电工uid',
  `duty_elec_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班电工文本',
  `shift_elec_uid` int(11) NULL DEFAULT NULL COMMENT '接班电工uid',
  `shift_elec_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接班电工文本',
  `sign_status` tinyint(1) NULL DEFAULT NULL COMMENT '签字状态；0：未签字；1：已签字',
  `precautions` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注意事项',
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师签字图片',
  `signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '签字图片（审核签字图片）',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态  0:待提审 1:待审核 2:已完成 3:已驳回 4:已撤回 5:已反审 6:已作废',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人名',
  `ct_uid` int(11) NOT NULL COMMENT '制单人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 70 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备交接班记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment`;
CREATE TABLE `mro_equipment`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pid` int(11) NULL DEFAULT 0 COMMENT '父级ID',
  `equipment_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '唯一设备登记号',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '固定资产编号',
  `barcode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备条码',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `brand` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备品牌名称',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `out_inst_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外部机构id，多个用逗号隔开',
  `out_inst_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外部机构名称',
  `equipment_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备编码',
  `equipment_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型，层级用逗号隔开',
  `equipment_type_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型id',
  `assist_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '辅助分类id',
  `sap_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP类别',
  `power` decimal(6, 2) NULL DEFAULT NULL COMMENT '功率',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '序列号',
  `export_type` tinyint(1) NULL DEFAULT NULL COMMENT '出口类型 1国产 2进口',
  `factory_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出厂编号',
  `mileage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '里程',
  `accuracy` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准确度',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片',
  `product_line` int(11) NULL DEFAULT NULL COMMENT '所属产线',
  `note` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '可用状态 0停用 1正常 2闲置 3待报废 4已报废',
  `num` decimal(9, 3) NULL DEFAULT 1.000 COMMENT '数量',
  `use_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门ID，层级用逗号隔开',
  `duty_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任部门ID，层级用逗号隔开',
  `use_duty_user` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '使用负责人ID,多个用逗号隔开',
  `open_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资本化日期',
  `use_year` int(5) NULL DEFAULT NULL COMMENT '折旧年限(年)',
  `expire_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预计到期',
  `save_addr` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置，用逗号隔开',
  `cost_center` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成本中心',
  `sap_cost_center` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP成本中心',
  `produce_line_id` int(10) NULL DEFAULT NULL COMMENT '产线工序id',
  `produce_line_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产线工序',
  `scrap_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报废日期',
  `scrap_reason` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '报废原因',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商ID 来源物流基础资料供应商',
  `production_id` int(11) NULL DEFAULT NULL COMMENT '生产厂商ID 来源物流基础资料供应商',
  `purchase_uid` int(11) NULL DEFAULT NULL COMMENT '采购人员ID',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '原始价值',
  `spoiled_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '残值率',
  `spolied` decimal(9, 2) NULL DEFAULT NULL COMMENT '残值',
  `depreciation_type` tinyint(2) NULL DEFAULT 2 COMMENT '折旧方法 1 不计提折旧 2 平均年限法 3 年数总和法 4 双倍余额法',
  `accout_type` tinyint(1) NULL DEFAULT NULL COMMENT '会计分类 1 费用化资产 2 资本化资产',
  `equipment_in_goods_id` int(11) NULL DEFAULT NULL COMMENT '资产入库申请单明细id,不为nul则表示通过采购入库生成的',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `equipment_no`(`equipment_no`) USING BTREE,
  INDEX `save_addr`(`save_addr`) USING BTREE,
  INDEX `use_duty_user`(`use_duty_user`) USING BTREE,
  INDEX `open_date`(`open_date`) USING BTREE,
  INDEX `use_dept_id`(`use_dept_id`) USING BTREE,
  INDEX `asset_no`(`asset_no`, `barcode`, `brand`, `spec`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE,
  INDEX `expire_date`(`expire_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 976 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备管理登记表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_chage_parts
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_chage_parts`;
CREATE TABLE `mro_equipment_chage_parts`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `assos_id` int(11) NOT NULL COMMENT '关单单号ID',
  `type` tinyint(1) NOT NULL COMMENT '触发类型 0 维修单 1 保养单',
  `parts_id` int(11) NOT NULL COMMENT '换下备件明细ID',
  `stock_id` int(11) NULL DEFAULT NULL COMMENT '库存明细id',
  `down_num` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '换下数量',
  `down_date` datetime NOT NULL COMMENT '换下时间',
  `reserve_decimal` tinyint(1) NULL DEFAULT 0 COMMENT '保留小数点个数',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `ct_uid` int(11) NOT NULL COMMENT '创建人ID',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `assos_id`(`assos_id`, `type`, `parts_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '关联单据换下备件信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_file
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_file`;
CREATE TABLE `mro_equipment_file`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `equipment_id` int(11) NOT NULL COMMENT '设备ID',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件链接',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '1 设备图片 2设备文档 3图纸 4课件 5停机报告 6经验分享报告',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `download_num` int(11) NULL DEFAULT 0 COMMENT '下载次数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '上传者',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `equipment_id`(`equipment_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备相关文件' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_inspection_item
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_inspection_item`;
CREATE TABLE `mro_equipment_inspection_item`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '点巡检主题',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '岗位id',
  `job_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备点巡检项目' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_inspection_item_content
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_inspection_item_content`;
CREATE TABLE `mro_equipment_inspection_item_content`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '芙丝-设备点巡检项目id',
  `project` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查项目/部位',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查内容',
  `standard` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查标准',
  `method` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查方法',
  `tool` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查工具',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '检查频次类型 1-班 2-天',
  `cycle` int(10) NULL DEFAULT NULL COMMENT '检查频次 （类型为1时：1-三班制 2-两班制；类型为2时：天数）',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 90 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备点巡检项目-点巡检内容' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_inspection_item_eq
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_inspection_item_eq`;
CREATE TABLE `mro_equipment_inspection_item_eq`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '芙丝-设备点巡检项目id',
  `site_eq_id` int(10) NULL DEFAULT NULL COMMENT '现场设备清单id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场设备名称',
  `workshop` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属车间',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属产线',
  `manage_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备负责人',
  `place` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备所在位置',
  `equipment_id` int(11) NULL DEFAULT NULL COMMENT '设备id',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '固定资产编号',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备点巡检项目-适用设备' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_inspection_order
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_inspection_order`;
CREATE TABLE `mro_equipment_inspection_order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `plan_id` int(10) NOT NULL COMMENT '芙丝-设备点巡检计划id',
  `plan_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划编号',
  `date` date NULL DEFAULT NULL COMMENT '生成日期',
  `number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '点巡检主题',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '岗位id',
  `job_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位',
  `start_date` date NOT NULL COMMENT '计划执行时间-开始',
  `end_date` date NOT NULL COMMENT '计划执行时间-结束',
  `site_eq_id` int(10) NULL DEFAULT NULL COMMENT '现场设备清单id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场设备名称',
  `workshop` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属车间',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属产线',
  `manage_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备负责人',
  `place` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备所在位置',
  `equipment_id` int(11) NULL DEFAULT NULL COMMENT '设备id',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '固定资产编号',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '检查频次类型 1-班 2-天',
  `cycle` int(10) NULL DEFAULT NULL COMMENT '检查频次 （类型为1时：1-三班制 2-两班制；类型为2时：天数）',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1-早 2-中 3-晚',
  `execute_uid` int(10) NULL DEFAULT NULL COMMENT '执行人uid',
  `execute_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行人',
  `execute_time_start` datetime NULL DEFAULT NULL COMMENT '执行时间-开始',
  `execute_time_end` datetime NULL DEFAULT NULL COMMENT '执行时间-结束',
  `execute_during_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行时长',
  `is_replace` tinyint(1) NULL DEFAULT NULL COMMENT '是否更换配件 0 不更换 1更换',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '执行状态 0-待执行 1-待审批 2-已完成 3-已驳回 4-已撤回 7-已逾期 8-停产未检',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `class_no`(`class_no`) USING BTREE,
  INDEX `execute_uid`(`execute_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 145 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备点巡检工单' ROW_FORMAT = Dynamic;

