  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `ct_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人ID',
