) ENGINE = InnoDB AUTO_INCREMENT = 526 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备保养计划-点巡检内容' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_maintenance_plan_cycle
-- ----------------------------
