  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备保养计划-触发时间' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_maintenance_plan_eq
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_maintenance_plan_eq`;
CREATE TABLE `mro_equipment_maintenance_plan_eq`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '芙丝-设备保养计划id',
  `site_eq_id` int(10) NULL DEFAULT NULL COMMENT '现场设备清单id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场设备名称',
  `workshop` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属车间',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属产线',
  `manage_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备负责人',
  `place` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备所在位置',
  `equipment_id` int(11) NULL DEFAULT NULL COMMENT '设备id',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '固定资产编号',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备保养计划-适用设备' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_nfc
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_nfc`;
CREATE TABLE `mro_equipment_nfc`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `asset_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '固定资产编号',
  `nfc_url` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'nfc码',
  `is_write` tinyint(1) NULL DEFAULT 1 COMMENT '是否已写入；1：未写入；2：已写入；',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `sap_cost_center` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP成本中心',
  `sap_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP类别',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `asset_no`(`asset_no`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1669 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备管理登记表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_parts
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_parts`;
CREATE TABLE `mro_equipment_parts`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `equipment_id` int(11) NOT NULL COMMENT '设备登记ID',
  `good_id` int(11) NOT NULL COMMENT '备件ID',
  `parts_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '备件编码',
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '备件名称',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '型号',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备件部位备注',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `max_num` int(10) NULL DEFAULT NULL COMMENT '最大装机数量',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `equipment_id`(`equipment_id`, `parts_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备关联备件' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair`;
CREATE TABLE `mro_equipment_repair`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '维修类型 0 设备维修（停机误时维修单） 1 叉车维修',
  `repair_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '维修单号',
  `duty_order_id` int(11) NULL DEFAULT NULL COMMENT '当班误时登记单id，维修类型为0的全部通过当班误时登记单自动创建',
  `duty_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '误时登记单号',
  `fault_repair_uid` int(11) NULL DEFAULT NULL COMMENT '故障维修负责人uid（当班维修人员uid）',
  `fault_repair_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障维修负责人名字（当班维修人人员名字）',
  `waste_num` int(11) NULL DEFAULT NULL COMMENT '灌装停机误时分钟数（造成废品）',
  `is_create_fault_order` tinyint(1) NULL DEFAULT 0 COMMENT '是否已创建故障分析单；0：未创建；1：已创建',
  `delay` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备件误时（分钟数）',
  `delay_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备件误时文本',
  `delay_reason_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '误时原因文本',
  `delay_reason_id` int(11) NULL DEFAULT NULL COMMENT '误时原因id',
  `stop_desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '停机描述',
  `class_no_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次文本',
  `class_no` int(11) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `date_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期（年月日）',
  `equipment_id` int(11) NOT NULL COMMENT '登记设备ID',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '维修单状态 -1 已删除 0 = 待提审 1 = 待验收 2 = 已完成 3 = 已驳回 4 = 已撤回 5 = 已作废',
  `occurrence_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '发生时间',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组id',
  `class_type_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组文本',
  `repair_user_id` int(11) NULL DEFAULT NULL COMMENT '报修人',
  `fault_body` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备部位',
  `product_line` int(11) NULL DEFAULT NULL COMMENT '所属产线',
  `fault_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障描述',
  `save_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存放位置，用逗号隔开',
  `fault_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '故障图片 多张',
  `repair_type` tinyint(1) NULL DEFAULT 1 COMMENT '维修类型 1 常见故障维修 2 突发性故障维修3 = 计划项目维修 4 = 不正当使用维修',
  `fault_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障类型 1 电气故障 2 机械故障 3 其他故障',
  `fault_reason` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障原因 来源基础设置表 多个用逗号隔开',
  `repair_director` int(11) NULL DEFAULT NULL COMMENT '维修负责人 默认创建人',
  `other_repair_director` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他维修人员',
  `repair_start_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '维修开始时间',
  `repair_end_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修结束时间',
  `is_stop` tinyint(1) NULL DEFAULT NULL COMMENT '是否停机 0 否 1是',
  `stop_time` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '累计停机时间（分钟）',
  `repair_duration` int(11) NULL DEFAULT NULL COMMENT '维修时长（分钟数）',
  `repair_duration_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修时长文本',
  `outsourcing_id` int(11) NULL DEFAULT NULL COMMENT '外委单位ID',
  `repair_price` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '维修费用',
  `repair_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修描述',
  `repair_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '维修照片',
  `is_replace` tinyint(1) NOT NULL COMMENT '是否更换配件 0 不更换 1更换',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `chage_date` datetime NULL DEFAULT NULL COMMENT '换上时间',
  `down_date` datetime NULL DEFAULT NULL COMMENT '换下时间',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `equipment_id`(`equipment_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `repair_director`(`repair_director`) USING BTREE,
  INDEX `repair_user_id`(`repair_user_id`) USING BTREE,
  INDEX `fault_reason`(`fault_reason`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `repair_type`(`repair_type`) USING BTREE,
  INDEX `repair_no`(`repair_no`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 369 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备故障维修单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair_assoc
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair_assoc`;
CREATE TABLE `mro_equipment_repair_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `assoc_id` int(10) UNSIGNED NOT NULL COMMENT '维修单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5提审抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`, `assoc_id`, `assoc_type`) USING BTREE,
  INDEX `assoc_id`(`assoc_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 746 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '维修单审批关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair_log
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair_log`;
CREATE TABLE `mro_equipment_repair_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `assoc_id` int(11) NOT NULL COMMENT '维修单ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '日志类型 0 操作类型 1 审批类型',
  `content` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日志信息',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批意见',
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `assoc_id`(`assoc_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1407 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备维修日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair_order
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair_order`;
CREATE TABLE `mro_equipment_repair_order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `type` tinyint(1) NOT NULL COMMENT '维修类型 1-生产性维修 2-非生产性维修',
  `date` date NOT NULL COMMENT '报修日期',
  `site_eq_id` int(10) NULL DEFAULT NULL COMMENT '现场设备清单id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '现场设备名称',
  `equipment_id` int(11) NULL DEFAULT NULL COMMENT '设备id',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '固定资产编号',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `place_id` int(10) NULL DEFAULT NULL COMMENT '厂区管控位置id',
  `place` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂区管控位置',
  `fault_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障描述',
  `is_stop` tinyint(1) NULL DEFAULT NULL COMMENT '是否停机 0-否 1-是',
  `eq_delay` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备误时',
  `canning_delay` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装误时',
  `engineer_uid` int(10) NULL DEFAULT NULL COMMENT '工程师uid',
  `engineer_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师',
  `fault_type` tinyint(1) NULL DEFAULT NULL COMMENT '故障类型 1-机械故障 2-电气故障 3-其他故障',
  `fault_cate` tinyint(1) NULL DEFAULT NULL COMMENT '故障分类 1-常见故障维修 2-突发性故障维修 3-计划项目维修 4-不正当使用维修',
  `fault_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障原因',
  `solution` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '解决方法',
  `repair_uid` int(10) NULL DEFAULT NULL COMMENT '维修员uid',
  `repair_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修员',
  `group_id` int(10) NULL DEFAULT NULL COMMENT '所属班组id',
  `group_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属班组',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '所属班次 1-早 2-中 3-晚',
  `repair_time_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行维修时间-开始',
  `repair_time_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行维修时间-结束',
  `repair_during_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行时长',
  `repair_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修描述',
  `repair_file` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '维修图片',
  `is_out` tinyint(1) NULL DEFAULT NULL COMMENT '是否委外 0-否 1-是',
  `is_replace` tinyint(1) NULL DEFAULT 0 COMMENT '是否更换配件 0 不更换 1更换',
  `out_dept` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '委外单位',
  `out_price` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '委外费用',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0-暂存 1-待审批 2-已完成 7-待确认 8-待维修',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  `source_type` tinyint(1) NULL DEFAULT NULL COMMENT '来源类型；1；自主建单；2：芙丝工厂-保养工单自动生成；',
  `source_order_id` int(11) NULL DEFAULT NULL COMMENT '来源单据id',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `number`(`number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备维修工单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair_order_assoc`;
CREATE TABLE `mro_equipment_repair_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '芙丝-设备维修工单id',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备维修工单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair_order_log
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair_order_log`;
CREATE TABLE `mro_equipment_repair_order_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '芙丝-设备维修工单ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '芙丝-设备维修工单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair_parts
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair_parts`;
CREATE TABLE `mro_equipment_repair_parts`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据类型；0：维修单；1：保养工单；2：自主点检报修单',
  `repair_id` int(11) NOT NULL COMMENT '单据ID',
  `rec_detail_id` int(11) NOT NULL COMMENT '领料单明细id',
  `re_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '领料单号',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联单号',
  `eq_id` int(11) NOT NULL COMMENT '设备ID',
  `order_status` tinyint(1) NULL DEFAULT 0 COMMENT '关联的单据状态，0：未完结；1：已完结',
  `stock_id` int(11) NULL DEFAULT NULL COMMENT '库存明细id',
  `goods_id` int(11) NOT NULL COMMENT '商品ID',
  `out_date` datetime NULL DEFAULT NULL COMMENT '出库日期',
  `chage_date` datetime NULL DEFAULT NULL COMMENT '换上时间',
  `down_date` datetime NULL DEFAULT NULL COMMENT '换下时间',
  `down_num` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '换下数量',
  `out_ware_id` int(11) NULL DEFAULT NULL COMMENT '出库仓库ID',
  `out_ware` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出库仓库名',
  `barcode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '条码',
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '名称',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格型号',
  `brand` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `class_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类',
  `measure_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `received_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已发数量',
  `price` decimal(6, 2) NULL DEFAULT 0.00 COMMENT '单价',
  `in_wh_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库时间',
  `sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商',
  `use_addr` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用位置',
  `use_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '使用数',
  `is_online` tinyint(1) NULL DEFAULT 1 COMMENT '设备是否在线；0：不在线；1：在线；',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `reserve_decimal` tinyint(1) NULL DEFAULT 0 COMMENT '保留小数点个数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `repair_id`(`repair_id`) USING BTREE,
  INDEX `eq_id`(`eq_id`) USING BTREE,
  INDEX `repair_id_2`(`repair_id`, `rec_detail_id`, `type`) USING BTREE,
  INDEX `type`(`type`, `eq_id`, `order_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 164 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '关联领用单明细信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_repair_reason
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_repair_reason`;
CREATE TABLE `mro_equipment_repair_reason`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产线名称',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备故障原因' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_special
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_special`;
CREATE TABLE `mro_equipment_special`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `equipment_id` int(10) NULL DEFAULT NULL COMMENT '设备管理登记表id',
  `register_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备注册代码(许可)',
  `use_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用证编号',
  `register_date` date NULL DEFAULT NULL COMMENT '登记日期',
  `issue_date` date NULL DEFAULT NULL COMMENT '发证日期',
  `internal_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位内部编号',
  `factory_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品(出厂)编号',
  `register_dept` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登记机关',
  `eq_manager_dept` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备管理机关',
  `register_date_two` date NULL DEFAULT NULL COMMENT '注册登记日期',
  `register_status` tinyint(1) NOT NULL DEFAULT 2 COMMENT '注册登记状态 1-未登记 2-已登记 3-已注销',
  `use_certificate` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '使用证',
  `use_sign` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '使用标志',
  `use_dept_id` int(10) NULL DEFAULT NULL COMMENT '使用单位id',
  `use_dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用单位',
  `credit_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位代码',
  `contact_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位电话',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位地址',
  `check_dept` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验单位',
  `maintenance_dept` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维保单位',
  `put_use_date` date NULL DEFAULT NULL COMMENT '投用日期',
  `use_end_time` date NULL DEFAULT NULL COMMENT '使用截止日期',
  `cate` tinyint(1) NULL DEFAULT NULL COMMENT '特种设备种类,定义在getSpecialCateList中',
  `cate_text` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特种设备种类文本',
  `class` tinyint(1) NULL DEFAULT NULL COMMENT '特种设备类别',
  `class_text` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '特种设备类别文本',
  `safe_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备安全员id,多个用逗号隔开',
  `safe_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备安全员文本',
  `safe_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备安全员电话',
  `license_plate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '场内机动车牌号',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '制单人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `equipment_id`(`equipment_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备管理登记表-特种设备信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_watch
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_watch`;
CREATE TABLE `mro_equipment_watch`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `eq_id` int(11) NOT NULL DEFAULT 0 COMMENT '设备ID',
  `rel_id` int(11) NOT NULL DEFAULT 0 COMMENT '绑定关联',
  `mult` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '倍率',
  `num` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '读数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `eq_id`(`eq_id`) USING BTREE,
  UNIQUE INDEX `rel_id`(`rel_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备表计信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_equipment_watch_detail
-- ----------------------------
DROP TABLE IF EXISTS `mro_equipment_watch_detail`;
CREATE TABLE `mro_equipment_watch_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `watch_id` int(11) NOT NULL COMMENT '关联的设备表ID',
  `num` decimal(9, 2) NOT NULL DEFAULT 0.00 COMMENT '表读数',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `watch_id`(`watch_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备表计读数表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_fault_analysis_assoc
-- ----------------------------
DROP TABLE IF EXISTS `mro_fault_analysis_assoc`;
CREATE TABLE `mro_fault_analysis_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '采购单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 97 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养工单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_fault_analysis_log
-- ----------------------------
DROP TABLE IF EXISTS `mro_fault_analysis_log`;
CREATE TABLE `mro_fault_analysis_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '所属单据id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `before_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 132 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养工单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_fault_analysis_order
-- ----------------------------
DROP TABLE IF EXISTS `mro_fault_analysis_order`;
CREATE TABLE `mro_fault_analysis_order`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '类型 0 设备',
  `fault_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障时间',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `repair_id` int(11) NULL DEFAULT NULL COMMENT '关联的停机维修单id',
  `repair_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '停机维修单号',
  `plan_id` int(11) NULL DEFAULT NULL COMMENT '计划id',
  `plan_details_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划明细单号',
  `equipment_type_id` int(11) NOT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `equipment_id` int(11) NOT NULL COMMENT '设备id',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0待提审；1：待验收；2：已完成；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `cycle_type` tinyint(2) NULL DEFAULT NULL COMMENT '周期类型；0：1个月；1：3个月；2：12个月；3：24个月',
  `cycle_class` tinyint(1) NULL DEFAULT 1 COMMENT '周期类型；1：按月；2：按天',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `barcode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '设备条码',
  `img_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片信息',
  `plan_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养计划名称',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '固定资产编号',
  `use_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门id，层级用逗号隔开',
  `save_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置，用逗号隔开',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `is_replace` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '是否更换备件；0：不更换；1：更换；',
  `outsourced_units` int(11) NULL DEFAULT NULL COMMENT '委外单位',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '所属线别id;',
  `line_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别名称',
  `job_id` int(11) NULL DEFAULT NULL COMMENT '岗位id',
  `job_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称',
  `fault_repair_uid` int(11) NULL DEFAULT NULL COMMENT '维修员uid',
  `fault_repair_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修员名字',
  `delay_duration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备件误时（分钟数）',
  `repair_duration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修时长（分钟数）',
  `repair_duration_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修时长文本',
  `delay_duration_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备件误时文本',
  `fault_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障类型 1 电气故障 2 机械故障 3 其他故障',
  `fault_reason` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障原因 来源基础设置表 多个用逗号隔开',
  `fault_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标题',
  `fault_phenom` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '故障现象',
  `solve_meth` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '解决方法',
  `cause_analysis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原因分析',
  `improve_sugg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '改善建议',
  `deal_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '处理结果',
  `replace_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '更换备件',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `chage_date` datetime NULL DEFAULT NULL COMMENT '换上时间',
  `down_date` datetime NULL DEFAULT NULL COMMENT '换下时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `review_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批意见',
  `delay_reason_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '误时原因文本',
  `delay_reason_id` int(11) NULL DEFAULT NULL COMMENT '误时原因id',
  `stop_desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '停机描述',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `equipment_type_id`(`equipment_type_id`) USING BTREE,
  INDEX `equipment_id`(`equipment_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `equipment_type_id_2`(`equipment_type_id`, `status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '故障分析改善记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_file_auth
-- ----------------------------
DROP TABLE IF EXISTS `mro_file_auth`;
CREATE TABLE `mro_file_auth`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `file_id` int(11) NOT NULL COMMENT '文件id',
  `type` tinyint(1) NOT NULL COMMENT '权限类型1仅查看2仅上传和查看3仅查看、下载、移动和复制4全部权限(除编辑)5全部权限',
  `auth` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '权限集合1查看2上传3下载4复制5移动6删除7编辑(重命名)',
  `dept_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '部门id集合',
  `uids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '用户id集合',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `file_id`(`file_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 652 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文件权限表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_file_download_log
-- ----------------------------
DROP TABLE IF EXISTS `mro_file_download_log`;
CREATE TABLE `mro_file_download_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `file_id` int(11) NOT NULL COMMENT '文件id',
  `dl_uid` int(11) NULL DEFAULT NULL COMMENT '下载者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '下载传时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `file_id`(`file_id`) USING BTREE,
  INDEX `dl_uid`(`dl_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 86 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文件下载记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_file_manage
-- ----------------------------
DROP TABLE IF EXISTS `mro_file_manage`;
CREATE TABLE `mro_file_manage`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pid` int(11) NOT NULL COMMENT '父id',
  `tid` int(11) NOT NULL COMMENT '顶级id',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件链接',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '1文件夹2文件',
  `file_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件类型',
  `file_source` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1上传2移动3复制',
  `review_num` int(11) NULL DEFAULT 0 COMMENT '查看次数',
  `download_num` int(11) NULL DEFAULT 0 COMMENT '下载次数',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '上传者',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `pid`(`pid`) USING BTREE,
  INDEX `tid`(`tid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3373 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文件管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_file_tag
-- ----------------------------
DROP TABLE IF EXISTS `mro_file_tag`;
CREATE TABLE `mro_file_tag`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pid` int(11) NOT NULL COMMENT '父id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标签名',
  `color` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '颜色',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '0禁用1启用',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_default` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1是默认标签',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `pid`(`pid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文件标签' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_file_tag_relation
-- ----------------------------
DROP TABLE IF EXISTS `mro_file_tag_relation`;
CREATE TABLE `mro_file_tag_relation`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `file_id` int(11) NOT NULL COMMENT '文件id',
  `tag_id` int(11) NOT NULL COMMENT '标签id',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `file_id`(`file_id`) USING BTREE,
  INDEX `tag_id`(`tag_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 705 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文件标签关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_forkift_mileage
-- ----------------------------
DROP TABLE IF EXISTS `mro_forkift_mileage`;
CREATE TABLE `mro_forkift_mileage`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '记录编号',
  `equipment_id` int(11) NOT NULL COMMENT '登记设备ID',
  `equipment_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '资产名称',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '序列号',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '唯一码',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `equipment_type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `save_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置',
  `use_dept_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门名称',
  `use_duty_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '使用负责人名称',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态 0 未确认 1 已确认',
  `use_driver_id` int(11) NULL DEFAULT NULL COMMENT '使用司机ID',
  `use_driver_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '使用司机',
  `start_date` datetime NULL DEFAULT NULL COMMENT '使用时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `start_mileage` decimal(9, 2) NULL DEFAULT NULL COMMENT '开始里程',
  `end_mileage` decimal(9, 2) NULL DEFAULT NULL COMMENT '结束里程',
  `commit_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认签名',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 166 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '叉车里程记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_lend_in_assoc
-- ----------------------------
DROP TABLE IF EXISTS `mro_lend_in_assoc`;
CREATE TABLE `mro_lend_in_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '所属单据id',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5调出仓库待确认,6调出仓库确认,7调出仓库驳回,8调入仓库待确认,9调入仓库确认,10调入仓库驳回,',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：调出仓确认；3：调入仓确认；4：抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '借入申请单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_lend_in_list
-- ----------------------------
DROP TABLE IF EXISTS `mro_lend_in_list`;
CREATE TABLE `mro_lend_in_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `lend_base_id` int(2) UNSIGNED NOT NULL COMMENT '借用基地id；0：贵州基地 1：广东基地 2：江苏基地 3：湖北基地 4：辽宁基地 5：北京基地 6：福建基地',
  `lend_out_order_id` int(11) NULL DEFAULT NULL COMMENT '战略备件出库单id',
  `lend_out_order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '战略备件出库单号',
  `lend_out_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '出库数量（战略备件出库单出库数量）',
  `return_sign` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '归还人签名图片',
  `return_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请归还时间',
  `apply_uid` int(10) UNSIGNED NOT NULL COMMENT '申请人uid',
  `apply_user_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请人名字',
  `apply_sign` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '借用人签名',
  `apply_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '申请日期',
