  `client_agent` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作HTTP_USER_AGENT',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `title`(`title`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备日志记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_maintenance_log
-- ----------------------------
DROP TABLE IF EXISTS `mro_maintenance_log`;
CREATE TABLE `mro_maintenance_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `document_id` int(10) UNSIGNED NOT NULL COMMENT '对应单据id',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `type` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '日志类型；0：保养项目；1：保养计划；2：保养工单',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `before_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作前数据',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `replacement_id`(`document_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1093 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养操作日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for mro_maintenance_order
-- ----------------------------
DROP TABLE IF EXISTS `mro_maintenance_order`;
CREATE TABLE `mro_maintenance_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '类型 0 设备 1 叉车',
  `maintenance_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '保养单号',
  `plan_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划编号',
  `plan_id` int(11) NOT NULL COMMENT '计划id',
  `plan_details_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划明细单号',
  `equipment_type_id` int(11) NOT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备类型名称',
  `equipment_id` int(11) NOT NULL COMMENT '设备id',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '保养状态；0待提审；1：待验证；2：已完成；3：已驳回；4：已撤回 5：已反审',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `maintenance_start_time` datetime NULL DEFAULT NULL COMMENT '保养开始时间',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '保养完成时间',
  `plan_start_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间',
  `next_execute_time` datetime NULL DEFAULT NULL COMMENT '下次执行时间',
  `reminder_time` datetime NULL DEFAULT NULL COMMENT '﻿提醒时间',
  `maintenance_level` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '保养级别',
  `maintenance_cost` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '保养费用',
  `equipment_cost` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '备件费用',
  `cycle_type` tinyint(2) NOT NULL COMMENT '周期类型；0：1个月；1：3个月；2：12个月；3：24个月',
  `cycle_class` tinyint(1) NULL DEFAULT 1 COMMENT '周期类型；1：按月；2：按天',
  `director_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养负责人id，多个用,隔开',
  `other_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其它保养人id，多个用,隔开',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `barcode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '设备条码',
  `img_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片信息',
  `plan_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养计划名称',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '固定资产编号',
  `use_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门id，层级用逗号隔开',
  `save_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置，用逗号隔开',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `is_replace` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '是否更换备件；0：不更换；1：更换；',
  `outsourced_units` int(11) NULL DEFAULT NULL COMMENT '外委单位',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '所属线别id;',
  `line_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别名称',
  `job_id` int(11) NULL DEFAULT NULL COMMENT '岗位id',
  `job_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位名称',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `maintenance_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '保养描述',
  `chage_date` datetime NULL DEFAULT NULL COMMENT '换上时间',
  `down_date` datetime NULL DEFAULT NULL COMMENT '换下时间',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `equipment_type_id`(`equipment_type_id`) USING BTREE,
  INDEX `equipment_id`(`equipment_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `main_order_no`(`maintenance_order_no`) USING BTREE,
  INDEX `plan_no`(`plan_no`) USING BTREE,
  INDEX `maintenance_level`(`maintenance_level`) USING BTREE,
  INDEX `equipment_type_id_2`(`equipment_type_id`, `status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 333 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养工单表' ROW_FORMAT = Dynamic;

