  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `cycle_type`(`cycle_type`) USING BTREE,
  INDEX `is_maintain`(`is_maintain`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 656 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养工单表' ROW_FORMAT = Dynamic;

-- ----------------------------
