) ENGINE = InnoDB AUTO_INCREMENT = 674 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养计划周期明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
