-- ----------------------------
-- Table structure for mro_mechanic_shift_record
-- ----------------------------
DROP TABLE IF EXISTS `mro_mechanic_shift_record`;
CREATE TABLE `mro_mechanic_shift_record`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `date` date NOT NULL COMMENT '交接日期',
  `group_id` int(10) NOT NULL COMMENT '班组id',
  `group_name` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组',
  `class_no` tinyint(1) NOT NULL COMMENT '班次 1-早 2-中 3-晚',
  `class_no_text` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次文本',
  `mechanic_on_uid` int(10) NOT NULL COMMENT '当班机修工id',
  `mechanic_on_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班机修工',
  `mechanic_off_uid` int(10) NOT NULL COMMENT '接班机修工id',
  `mechanic_off_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接班机修工',
  `work_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '工作记录',
  `inspect` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '岗前检查',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `group_id`(`group_id`) USING BTREE,
  INDEX `class_no`(`class_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '机修岗位交接班记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_mechanic_shift_record_assoc
-- ----------------------------
DROP TABLE IF EXISTS `mro_mechanic_shift_record_assoc`;
CREATE TABLE `mro_mechanic_shift_record_assoc`  (
