  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '机修岗位交接班记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_mechanic_shift_record_list
-- ----------------------------
DROP TABLE IF EXISTS `mro_mechanic_shift_record_list`;
CREATE TABLE `mro_mechanic_shift_record_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '机修岗位交接班记录ID',
