-- ----------------------------
-- Table structure for mro_meter_month_report
-- ----------------------------
DROP TABLE IF EXISTS `mro_meter_month_report`;
CREATE TABLE `mro_meter_month_report`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
