-- ----------------------------
-- Table structure for mro_point_check_except_order
-- ----------------------------
DROP TABLE IF EXISTS `mro_point_check_except_order`;
CREATE TABLE `mro_point_check_except_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '异常单号',
  `p_id` int(11) NOT NULL COMMENT '点巡检记录ID',
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '类型：1、安全；2：设备；3：财务',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '暂不处理原因',
  `h_id` int(11) NULL DEFAULT NULL COMMENT '整改单ID',
  `h_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改单编号',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态 0 暂存 1待处理 2已处理 3处理不通过 4 撤回 5 暂不处理',
  `check_date` date NULL DEFAULT NULL COMMENT '检查日期',
  `deal_dept_id` int(11) NULL DEFAULT NULL COMMENT '处理部门ID',
  `deal_dept_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处理部门ID',
  `duty_uid` int(11) NULL DEFAULT NULL COMMENT '部门负责人ID',
  `duty_username` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门负责人',
  `addr_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置ID',
  `addr` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隐患位置',
  `address` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细位置',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场图片，多张用逗号隔开',
  `grade` tinyint(1) NULL DEFAULT NULL COMMENT '评估分级 1 一般事故隐患 2 重大事故隐患',
  `risk` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险类别 1 人的不安全行为 2 管理上的缺陷 3 物的不安全状态 4 环境的不安全因素 ；多选用逗号隔开',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全隐患描述',
  `involve_risk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '存在风险',
  `hazard_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '隐患类型',
  `acts` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '法律法规依据',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人ID',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人名',
  `ct_uid` int(11) NOT NULL COMMENT '制单人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `p_id`(`p_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 95 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备点检单-异常记录单' ROW_FORMAT = Dynamic;

