) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '点巡检月度执行统计表日志（设备）' ROW_FORMAT = Dynamic;

