CREATE TABLE `mro_point_check_monthly_report_eq`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '统计月份，格式：2024-07',
