  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别id',
  `line_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别文本',
  `equipment_id` int(11) NULL DEFAULT NULL COMMENT '设备id',
  `eq_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备名称',
  `cycle_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '循环周期类型；1：按班次；2：每天；3：按CIP；4：每月',
  `cycle_type_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '循环周期类型文本',
  `day_num` int(11) NULL DEFAULT NULL COMMENT '执行天数',
  `use_uid` int(11) NULL DEFAULT NULL COMMENT '资产使用负责人uid',
  `use_user_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资产使用负责人文本',
  `executor_uid` int(11) NULL DEFAULT NULL COMMENT '执行人uid',
  `executor_user_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行人文本',
  `engineer_uid` int(11) NULL DEFAULT NULL COMMENT '工程师uid',
  `engineer_names_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师文本',
  `manager_uid` int(11) NULL DEFAULT NULL COMMENT '主管uid',
  `manager_names_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主管文本',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人名',
  `ct_uid` int(11) NOT NULL COMMENT '制单人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '点巡检月度执行统计表（设备）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_point_check_order
-- ----------------------------
DROP TABLE IF EXISTS `mro_point_check_order`;
CREATE TABLE `mro_point_check_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `point_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '点检计划任务单号',
  `plant_id` int(11) NOT NULL COMMENT '计划ID',
  `plan_details_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划明细单号',
  `plan_end_time` datetime NULL DEFAULT NULL COMMENT '计划执行结束时间-当执行时间规则为按固定周期时，该字段必填',
  `executive_rule_type` tinyint(255) NULL DEFAULT 0 COMMENT '执行规则类型；0：按上次执行时间；1：按固定周期',
  `plan_start_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果；1：正常；2：异常',
  `eq_id` int(11) NULL DEFAULT NULL COMMENT '登记设备ID',
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '类型：1、安全；2：设备；3：财务',
  `use_dept_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责部门ID，多个用逗号隔开',
  `use_dept_names` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责部门名称，多个用逗号隔开',
  `task_time_start` datetime NOT NULL COMMENT '任务开始时间',
  `task_time_end` datetime NULL DEFAULT NULL COMMENT '任务结束时间',
  `executor_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行人ID，多个用逗号隔开',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `cycle_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '循环周期类型；0：每月；1：每季',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场拍照图片',
  `assoc_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关联图片',
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签名',
  `status` tinyint(1) NOT NULL COMMENT '点检任务执行单状态 -2已过期 -1 已删除 0 = 待提审 1 = 待验收 2 = 已完成 3 = 已驳回 4 = 已撤回 5 = 已作废 6 = 已反审',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `rectify_problem` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整改问题（故障描述）',
  `rectify_uid` int(11) NULL DEFAULT NULL COMMENT '整改负责人uid（维修负责人uid）',
  `is_report_rectify` tinyint(1) NULL DEFAULT 0 COMMENT '是否上报整改（是否报修）；0：否；1：是；',
  `execpt_order_id` int(11) NULL DEFAULT NULL COMMENT '异常上报ID',
  `execpt_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常上报单号',
  `h_id` int(11) NULL DEFAULT NULL COMMENT '安全隐患排查单ID',
  `h_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全隐患排查单编号',
  `report_repair_status` tinyint(1) NULL DEFAULT NULL COMMENT '报修状态；0：待维修；1：维修中；2：已维修；3：无需维修；',
  `rectify_status` tinyint(1) NULL DEFAULT 0 COMMENT '整改状态；0：待提交整改；1：已整改',
  `rectify_time` datetime NULL DEFAULT NULL COMMENT '整改时间',
  `rectify_feedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整改反馈',
  `rectify_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整改后照片，格式为json数组',
  `rectify_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '异常整改内容',
  `barcode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备条码',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `save_addr` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置，用逗号隔开',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '固定资产编号',
  `equipment_type_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型id',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人名',
  `ct_uid` int(11) NOT NULL COMMENT '制单人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `engineer_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师uid,多个用,隔开',
  `engineer_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师签字图片，多个用,隔开',
  `manager_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经理uid,多个用,隔开',
  `manager_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经理签字图片，多个用,隔开',
  `already_inspection_num` int(11) NULL DEFAULT NULL COMMENT '已检查次数',
  `inspection_num` int(11) NULL DEFAULT NULL COMMENT '需检查次数',
  `is_has_complete` tinyint(1) NULL DEFAULT 1 COMMENT '是否完成过；主要用于判断反审之后的场景；1：未完成过；2：已完成过；',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plant_id`(`plant_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status_2`(`status`, `is_report_rectify`, `rectify_status`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `h_id`(`h_id`) USING BTREE,
  INDEX `rectify_status`(`rectify_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1721 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备点检单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_point_check_order_cip
-- ----------------------------
DROP TABLE IF EXISTS `mro_point_check_order_cip`;
CREATE TABLE `mro_point_check_order_cip`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '点检计划任务单号',
  `plan_id` int(11) NOT NULL COMMENT '计划ID',
  `plan_group_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '点巡检计划组名',
  `plan_group_id` int(11) NULL DEFAULT NULL COMMENT '点巡检计划组id',
  `plan_details_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划明细单号',
  `plan_start_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间开始',
  `plan_end_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间结束',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果；1：正常；2：异常;3：停机异常',
  `class_no` tinyint(4) NULL DEFAULT NULL COMMENT '班次(循环周期为按班次时必填) 1早 2中 3夜',
  `line_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别id，多个用逗号隔开',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间id',
  `equipment_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备id,多个用逗号隔开',
  `task_time_start` datetime NOT NULL COMMENT '任务开始时间',
  `task_time_end` datetime NULL DEFAULT NULL COMMENT '任务结束时间',
  `morning_plan_start_time` datetime NULL DEFAULT NULL COMMENT '早班任务执行时间-开始',
  `morning_plan_end_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '早班任务执行时间-结束',
  `middle_plan_start_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '中班任务执行时间-开始',
  `middle_plan_end_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '中班任务执行时间-结束',
  `night_plan_start_time` datetime NULL DEFAULT NULL COMMENT '晚班任务执行时间-开始',
  `night_plan_end_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '晚班任务执行时间-结束',
  `executor_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行人ID，多个用逗号隔开',
  `cycle_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '循环周期类型；1：按班次；2：每天；3：按CIP；4：每月',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场拍照图片',
  `assoc_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关联图片',
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行人签名',
  `signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批人签字图片(用于存储审批时候的所有签字，多个用逗号隔开)\'',
  `morning_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '早班执行人签名',
  `middle_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '中班执行人签名',
  `night_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '晚班执行人签名',
  `morning_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '早班现场拍照图片',
  `middle_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '中班现场拍照图片',
  `night_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '晚班现场拍照图片',
  `is_up_plan` tinyint(1) NULL DEFAULT 0 COMMENT '是否已更新周期；0：未更新；1：已更新',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态  0:待提审 1:待验收 2:已完成 3:已驳回 4:已撤回 5:已作废',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `rectify_problem` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '故障描述',
  `rectify_uid` int(11) NULL DEFAULT NULL COMMENT '维修负责人uid',
  `is_report_rectify` tinyint(1) NULL DEFAULT 0 COMMENT '是否报修；0：否；1：是；',
  `report_repair_status` tinyint(1) NULL DEFAULT NULL COMMENT '报修状态；0：待维修；1：维修中；2：已维修；3：无需维修；',
  `equipment_type_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型id',
  `inspection_num` int(11) NULL DEFAULT NULL COMMENT '需检查次数',
  `already_inspection_num` int(11) NULL DEFAULT NULL COMMENT '已检查次数',
  `engineer_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师uid,多个用,隔开',
  `manager_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主管uid,多个用,隔开',
  `engineer_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师签字图片，多个用,隔开',
  `manager_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主管签字图片，多个用,隔开',
  `plan_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对应计划开始时间的年月日',
  `is_must_pho` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否必须拍照；0：不是；1：是；',
  `is_must_sig` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否必须执行人签名；0：不是；1：是；',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人名',
  `ct_uid` int(11) NOT NULL COMMENT '制单人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `open_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开/停机状态，开机时间',
  `open_status` tinyint(1) NULL DEFAULT 0 COMMENT '开/停机状态，开机状态 1 开机 0不开机',
  `close_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开/停机状态，关机时间',
  `close_status` tinyint(1) NULL DEFAULT 0 COMMENT '开/停机状态，关机状态 1 关机 0不关机',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status_2`(`status`, `is_report_rectify`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `equipment_ids`(`equipment_ids`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 150 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Cip点检单' ROW_FORMAT = Dynamic;

