  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `executor_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划执行人id，多个用,隔开',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `inspect_item_id`(`inspect_item_id`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 836 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '巡点检计划周期明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_point_inspect_plan_eq
-- ----------------------------
DROP TABLE IF EXISTS `mro_point_inspect_plan_eq`;
CREATE TABLE `mro_point_inspect_plan_eq`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `plan_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划编号',
  `inspection_num` int(11) NULL DEFAULT 1 COMMENT '检查次数',
  `interval` int(11) NULL DEFAULT NULL COMMENT '间隔值',
  `interval_type` tinyint(1) NULL DEFAULT NULL COMMENT '间隔类型；1：天；2：小时',
  `plan_group_id` int(11) NULL DEFAULT NULL COMMENT '点巡检计划组id',
  `plan_group_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '点巡检计划组名',
  `engineer_uid` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师uid,多个用,隔开',
  `engineer_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工程师签字图片，多个用,隔开',
  `manager_uid` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主管uid,多个用,隔开',
  `manager_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主管签字图片，多个用,隔开',
  `resp_area_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重点责任区id，多个用逗号隔开；1：灌装；2：包装；99：其他',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关联图片',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间ID;1：一车间；2：二车间；3：三车间；',
  `workshop_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名字',
  `line_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划所属线别id，多个用逗号隔开',
  `cip_cycle_day_nums` int(11) NULL DEFAULT NULL COMMENT 'CIP周期天数',
  `cip_delay_day_nums` int(11) NULL DEFAULT NULL COMMENT 'CIP可推迟天数',
  `already_inspection_num` int(11) NULL DEFAULT 0 COMMENT '已检查次数',
  `cycle_type` tinyint(2) NULL DEFAULT 0 COMMENT '循环周期类型；1：按班次；2：每天；3：按CIP；4：每月',
  `check_type` tinyint(1) NULL DEFAULT NULL COMMENT '点巡检类型；1、机修 2、电工 3、水暖工 4、其他',
  `plan_details_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划明细单号',
  `equipment_type_id` int(11) NOT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `equipment_ids` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备id,多个用逗号隔开',
  `is_must_pho` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否必须拍照；0：不是；1：是；',
  `is_must_sig` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否必须执行人签名；0：不是；1：是；',
  `plan_start_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间-开始（每天、CIP、每月用这个字段）',
  `plan_end_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间-结束（每天、CIP、每月用这个字段）',
  `morning_plan_start_time` datetime NULL DEFAULT NULL COMMENT '早班计划执行时间-开始（按班次用这个字段）',
  `morning_plan_end_time` datetime NULL DEFAULT NULL COMMENT '早班计划执行时间-结束（按班次用这个字段）',
  `middle_plan_start_time` datetime NULL DEFAULT NULL COMMENT '中班计划执行时间-开始（按班次用这个字段）',
  `middle_plan_end_time` datetime NULL DEFAULT NULL COMMENT '中班计划执行时间-结束（按班次用这个字段）',
  `night_plan_start_time` datetime NULL DEFAULT NULL COMMENT '晚班计划执行时间-开始（按班次用这个字段）',
  `night_plan_end_time` datetime NULL DEFAULT NULL COMMENT '晚班计划执行时间-结束（按班次用这个字段）',
  `executor_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划执行人id，多个用,隔开',
  `notice_day` int(11) NULL DEFAULT NULL COMMENT '提醒时间（天数），提前N天通知提醒，默认0则不提前通知',
  `notice_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提醒时间（时分），为空不提醒，仅到计划执行时间时发送通知',
  `last_start_time` datetime NULL DEFAULT NULL COMMENT '上次执行时间',
  `morning_last_start_time` datetime NULL DEFAULT NULL COMMENT '早班上次执行时间',
  `middle_last_start_time` datetime NULL DEFAULT NULL COMMENT '中班上次执行时间',
  `night_last_start_time` datetime NULL DEFAULT NULL COMMENT '晚班上次执行时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '计划状态；0未开始；1：待检查；2：检查中；3：待审核；4：停用；',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_no`(`plan_no`) USING BTREE,
  INDEX `plan_group_id`(`plan_group_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `night_plan_end_time`(`night_plan_end_time`) USING BTREE,
  INDEX `plan_end_time`(`plan_end_time`) USING BTREE,
  INDEX `status_2`(`status`, `cycle_type`) USING BTREE,
  INDEX `cycle_type`(`cycle_type`, `plan_end_time`) USING BTREE,
  INDEX `cycle_type_2`(`cycle_type`, `night_plan_end_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 161 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备点巡检计划表' ROW_FORMAT = Dynamic;

