-- ----------------------------
-- Table structure for mro_production_cycle_issue
-- ----------------------------
DROP TABLE IF EXISTS `mro_production_cycle_issue`;
CREATE TABLE `mro_production_cycle_issue`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '维修类型 1-生产性维修 2-非生产性维修',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：待提审；1：待验收；2：已完成；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  `problem_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '生产问题描述',
  `solution` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '解决方法',
  `repair_uid` int(11) NULL DEFAULT NULL COMMENT '维修负责人uid',
  `repair_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修负责人',
  `repair_start_time` datetime NULL DEFAULT NULL COMMENT '维修开始时间',
  `repair_end_time` datetime NULL DEFAULT NULL COMMENT '维修结束时间',
  `repair_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '维修描述',
  `is_replace` tinyint(1) NULL DEFAULT 0 COMMENT '是否更换备件 0-否 1-是',
  `equipment_type_id` int(11) NULL DEFAULT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `equipment_id` int(11) NULL DEFAULT NULL COMMENT '设备id',
  `line_id` int(10) NULL DEFAULT NULL COMMENT '产线id',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产线',
  `place_id` int(10) NULL DEFAULT NULL COMMENT '使用地点id',
  `place` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用地点',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `repair_uid`(`repair_uid`) USING BTREE,
  INDEX `repair_start_time`(`repair_start_time`) USING BTREE,
  INDEX `repair_end_time`(`repair_end_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '生产周期问题表' ROW_FORMAT = Dynamic;

