  `check_order_type` tinyint(1) NULL DEFAULT 0 COMMENT '自动创建单据类型；0：设备点巡检；1：cip点巡检',
  `signature_picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签名图片',
  `point_order_id` int(11) NULL DEFAULT NULL COMMENT '点巡检记录id；不为空则表示是通过点检触发；否则表示手动创建',
  `plan_details_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划明细单号',
  `equipment_ids` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备id,多个用逗号隔开',
  `equipment_type_id` int(11) NULL DEFAULT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：待维修',
  `use_dept_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门ID，层级用逗号隔开',
  `use_dept_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门文本信息',
  `use_duty_user` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用负责人',
  `use_duty_user_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用负责人文本信息',
  `save_addr` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用位置，用逗号隔开',
  `save_addr_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用位置文本',
  `rectify_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报修时间',
  `report_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报修人uid',
  `report_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报修人文本信息',
  `rectify_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修负责人uid',
  `rectify_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修负责人文本信息',
  `rectify_problem` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障描述',
  `urgent_level` tinyint(1) NULL DEFAULT NULL COMMENT '紧急程度 1-紧急 2-不紧急',
  `rectify_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '故障图片',
  `scene_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场图片',
  `repair_uid` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修员uid',
  `repair_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修员文本信息',
  `repair_start_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修开始时间',
  `repair_end_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修结束时间',
  `repair_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修描述',
  `repair_picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '维修图片',
  `is_replace` tinyint(1) NULL DEFAULT NULL COMMENT '是否更换备件；0：不更换；1：更换；',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `chage_date` datetime NULL DEFAULT NULL COMMENT '换上时间',
  `down_date` datetime NULL DEFAULT NULL COMMENT '换下时间',
  `replace_eq_id` int(11) NULL DEFAULT NULL COMMENT '备件上机设备id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `equipment_id`(`equipment_ids`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `main_order_no`(`order_no`) USING BTREE,
  INDEX `equipment_type_id_2`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 318 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备报修单(自主点检报修单)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_report_repair_order_item
-- ----------------------------
DROP TABLE IF EXISTS `mro_report_repair_order_item`;
CREATE TABLE `mro_report_repair_order_item`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '所属单据id',
  `order_item_id` int(11) NULL DEFAULT NULL COMMENT '关联的点巡检明细id，为空则表示手动创建的',
  `clean_addr` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洁位置',
  `clean_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洁内容',
  `driver_status` tinyint(1) NULL DEFAULT NULL COMMENT '设备状态；1：运行；2：停机',
  `inspect_item_id` int(11) NULL DEFAULT NULL COMMENT '点巡检标准明细id',
  `item_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '检查内容',
  `method` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '检验方法/工具/依据',
  `record_method` tinyint(1) NULL DEFAULT NULL COMMENT '记录方式;0：单选；1：多选；2：数值；3：长文本',
  `std_explain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '任务检查标准说明',
  `result_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '结果选项，json格式',
  `upper_limit_val` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '上限值',
  `lower_limit_val` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '下限值',
  `default_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '默认值',
  `line_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '线别id，多个用逗号隔开',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(11) NOT NULL DEFAULT 0 COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 400 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备报修单检查项目明细' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for mro_shutdown_maintenance_order
-- ----------------------------
DROP TABLE IF EXISTS `mro_shutdown_maintenance_order`;
CREATE TABLE `mro_shutdown_maintenance_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `plan_id` int(10) NOT NULL COMMENT '停机检修计划id',
  `number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `equipment_type_id` int(11) NOT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `equipment_id` int(11) NOT NULL COMMENT '设备id',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备名称',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备唯一码',
  `barcode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备条码',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `use_status` tinyint(1) NULL DEFAULT 1 COMMENT '可用状态 0停用 1正常 2闲置 3待报废 4已报废',
  `status_text` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '可用状态',
  `save_addr_text` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置，用逗号隔开',
  `use_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门ID，层级用逗号隔开',
  `use_dept_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门文本',
  `plan_execute_month` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划执行月份',
  `last_start_time` datetime NULL DEFAULT NULL COMMENT '上次执行时间',
  `line_id` int(10) NOT NULL COMMENT '计划所属线别id',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划所属线别',
  `execute_uid` int(10) NULL DEFAULT NULL COMMENT '检修执行人id',
  `execute_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检修执行人',
  `execute_start_time` datetime NULL DEFAULT NULL COMMENT '任务开始时间',
  `execute_end_time` datetime NULL DEFAULT NULL COMMENT '任务结束时间',
  `desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检修描述',
  `photo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '检修照片',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '工单状态：0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 1-是 0-否',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_no`(`plan_id`) USING BTREE,
  INDEX `equipment_type_id`(`equipment_type_id`) USING BTREE,
  INDEX `plan_execute_month`(`plan_execute_month`) USING BTREE,
  INDEX `bar_title`(`bar_title`) USING BTREE,
  INDEX `asset_no`(`asset_no`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修工单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_shutdown_maintenance_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `mro_shutdown_maintenance_order_assoc`;
CREATE TABLE `mro_shutdown_maintenance_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '停机检修工单ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `maintenance_order_id`(`order_id`) USING BTREE,
  INDEX `maintenance_order_id_2`(`order_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修工单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_shutdown_maintenance_order_log
-- ----------------------------
DROP TABLE IF EXISTS `mro_shutdown_maintenance_order_log`;
CREATE TABLE `mro_shutdown_maintenance_order_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '停机检修工单id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `procure_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修工单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_shutdown_maintenance_order_new
-- ----------------------------
DROP TABLE IF EXISTS `mro_shutdown_maintenance_order_new`;
CREATE TABLE `mro_shutdown_maintenance_order_new`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `plan_id` int(10) NOT NULL COMMENT '停机检修计划（新）id',
  `plan_number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划编号',
  `number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '编号',
  `equipment_type_id` int(11) NOT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `equipment_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备id，多个用逗号隔开',
  `check_month` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检修月份',
  `workshop` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '车间',
  `line_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属线别id',
  `line` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属线别',
  `has_maintenance` tinyint(1) NOT NULL COMMENT '是否包含保养计划 0-否 1-是',
  `has_repair` tinyint(1) NOT NULL COMMENT '是否包含设备报修 0-否 1-是',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；1-处理中 2-已处理',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 1-是 0-否',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_no`(`number`) USING BTREE,
  INDEX `equipment_type_id`(`equipment_type_id`) USING BTREE,
  INDEX `plan_execute_month`(`check_month`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修工单表（新）' ROW_FORMAT = Dynamic;

