) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修工单表（新）日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_shutdown_maintenance_order_one
-- ----------------------------
DROP TABLE IF EXISTS `mro_shutdown_maintenance_order_one`;
CREATE TABLE `mro_shutdown_maintenance_order_one`  (
