) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修工单-保养内容' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_shutdown_maintenance_order_two
-- ----------------------------
DROP TABLE IF EXISTS `mro_shutdown_maintenance_order_two`;
CREATE TABLE `mro_shutdown_maintenance_order_two`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '停机检修工单id',
  `inspect_item_id` int(11) NULL DEFAULT NULL COMMENT '点巡检标准明细id',
  `inspect_items_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '点巡检内容组',
  `item_project` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '点巡检项目',
  `item_content` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '点巡检内容',
  `method` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '点巡检方法',
  `std_explain` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '点巡检标准',
