) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修工单-点巡检异常项' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for mro_shutdown_maintenance_plan
-- ----------------------------
DROP TABLE IF EXISTS `mro_shutdown_maintenance_plan`;
CREATE TABLE `mro_shutdown_maintenance_plan`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划编号',
  `equipment_type_id` int(11) NOT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备类型名称',
  `equipment_ids` int(11) NOT NULL COMMENT '设备id，多个用逗号隔开',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备名称',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备唯一码',
  `plan_execute_month` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划执行月份',
  `line_id` int(10) NOT NULL COMMENT '计划所属线别id',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划所属线别',
  `last_execute_uid` int(10) NULL DEFAULT NULL COMMENT '上次执行人id',
  `last_execute_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上次执行人',
  `last_execute_time` datetime NULL DEFAULT NULL COMMENT '上次执行时间',
  `abnormal_cycle_start_time` date NULL DEFAULT NULL COMMENT '异常周期开始日期',
  `abnormal_cycle_end_time` date NULL DEFAULT NULL COMMENT '异常周期结束日期',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '计划状态；0未开始；1：待检修；2：检修中；3：已完成；',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 1-是 0-否',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_no`(`number`) USING BTREE,
  INDEX `equipment_type_id`(`equipment_type_id`) USING BTREE,
  INDEX `plan_execute_month`(`plan_execute_month`) USING BTREE,
  INDEX `bar_title`(`bar_title`) USING BTREE,
  INDEX `asset_no`(`asset_no`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '停机检修计划表' ROW_FORMAT = Dynamic;

