DROP TABLE IF EXISTS `mro_spare_parts_inventory_use`;
CREATE TABLE `mro_spare_parts_inventory_use`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NOT NULL COMMENT '备件库存表id',
  `number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `related_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联单号',
  `type` tinyint(1) NOT NULL COMMENT '单据类型 1-保养工单(设备) 2-报修工单 3-维修工单(设备) 4-生产问题工单',
  `use_time` datetime NULL DEFAULT NULL COMMENT '使用时间',
  `num` int(10) NOT NULL DEFAULT 0 COMMENT '使用数量',
  `replace_num` int(10) NOT NULL DEFAULT 0 COMMENT '可替换数量',
  `place_id` int(10) NULL DEFAULT NULL COMMENT '使用地点id',
  `place` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用地点',
  `eq_id` int(10) NULL DEFAULT NULL COMMENT '设备id',
  `asset_no` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '唯一码',
  `eq_barcode` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资产编码',
  `save_addr` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备位置',
  `is_replaced` tinyint(1) NULL DEFAULT NULL COMMENT '是否替换备件 0-否1-是',
  `replacement_number` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '替换单据编号',
  `replacement_num` int(10) NULL DEFAULT NULL COMMENT '替换数量',
  `on_machine_time` datetime NULL DEFAULT NULL COMMENT '上机时间',
  `usage_duration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用时长（分钟）',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态 1-占用 2-生效',
  `ct_uid` int(10) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '更新人id',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `line_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别id，多个用逗号隔开',
  `line_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别，多个用逗号隔开',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 320 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '备件库存表-使用记录' ROW_FORMAT = Dynamic;

