-- Table structure for os_au_auth
-- ----------------------------
DROP TABLE IF EXISTS `os_au_auth`;
CREATE TABLE `os_au_auth`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '权限ID',
  `auth_title` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '权限名称',
  `pid` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '父id,0顶级',
  `module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模块(小写)',
  `controller` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '控制器(首字母大写)',
  `action` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作方法(小写)',
  `page_path` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '页面路径',
  `hide` tinyint(1) NULL DEFAULT 0 COMMENT '0显示,1隐藏',
  `rank` int(10) NULL DEFAULT 0 COMMENT '菜单排序,越大越前',
  `icon` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'layui-icon-set-fill' COMMENT '图标',
  `module_types` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '所属模块id，多个用逗号隔开;0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `mark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '菜单标记',
  `is_manual` tinyint(1) NULL DEFAULT 0 COMMENT '是否人工导入的菜单；1：是；0：否',
  `version` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本号',
  `tag_cate` tinyint(1) NULL DEFAULT NULL COMMENT '1新增功能；2优化功能',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_menu` tinyint(1) NULL DEFAULT 1 COMMENT '是否菜单；1：是；2：否',
  `local_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '本地映射路径',
  `expect_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预计开发完成时间',
  `en_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '英文名称标识',
  `btn_identity` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '按钮标识',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `m_c_a`(`module`, `controller`, `action`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `pid`(`pid`) USING BTREE,
  INDEX `rank`(`rank`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '后台-权限' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_au_log
-- ----------------------------
DROP TABLE IF EXISTS `os_au_log`;
CREATE TABLE `os_au_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事件',
  `text` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '触发人ID',
  `hide` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0显示(内容),1隐藏',
  `client_ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作IP',
  `client_agent` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作HTTP_USER_AGENT',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `title`(`title`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 69013 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '后台-日志记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_au_operate_log
-- ----------------------------
DROP TABLE IF EXISTS `os_au_operate_log`;
CREATE TABLE `os_au_operate_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '操作类型1登入2退出',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '触发人ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '管理员昵称',
  `user` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '所属部门',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '岗位',
  `token` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'token',
  `client_ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作IP',
  `address` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '地址',
  `client_agent` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作HTTP_USER_AGENT',
  `time` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '登入时长',
  `out` tinyint(1) NOT NULL DEFAULT 0 COMMENT '退出标识1已退出0未退出',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14582 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户操作（登入）日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_au_order_operate_list
-- ----------------------------
DROP TABLE IF EXISTS `os_au_order_operate_list`;
CREATE TABLE `os_au_order_operate_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据类型；1：库存明细报表；',
  `set_json_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置内容，json数组',
  `uid` int(10) NULL DEFAULT NULL COMMENT '所属用户id',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `type`(`type`, `uid`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户单据操作设置记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_au_role
-- ----------------------------
DROP TABLE IF EXISTS `os_au_role`;
CREATE TABLE `os_au_role`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '角色ID，0:物料模块系统管理员;-2:设备系统管理员;-3:安全系统管理员;-4:品质系统管理员;-5:生产系统管理员;-6:能源系统管理员;-7:运营中心系统管理员;-8:行政人事系统管理员;-9:财务系统管理员',
  `role_title` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色组名',
  `ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '权限ids字符串:1,2,5',
  `is_out` tinyint(1) NULL DEFAULT 1 COMMENT '是否外部角色；1：内部角色；2：外部角色',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门id',
  `dept_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门名字',
  `remark` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '角色权限备注',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '1正常,0禁用',
  `data_per` tinyint(1) NULL DEFAULT 0 COMMENT '数据权限0个人,1全部',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_type` tinyint(2) NOT NULL DEFAULT 0 COMMENT '所属模块类型，0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统；6：运营中心管理系统；7：行政人事管理系统；8：财务管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `role_title`(`role_title`, `module_type`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_id`(`module_type`) USING BTREE,
  INDEX `is_out`(`is_out`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 119 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '后台-角色' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_au_user
-- ----------------------------
DROP TABLE IF EXISTS `os_au_user`;
CREATE TABLE `os_au_user`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `role_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属角色ID,-1超级管理员;0物料管理员;-2设备管理员;-3安全管理员;-4品质管理员;-5生产管理员;-6能源管理员',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '管理员昵称',
  `user` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账号',
  `pwd` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT 'md5密码',
  `openid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'openid',
  `unionid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'unionid',
  `dd_userid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '钉钉userid',
  `dd_unionid` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '钉钉unionId',
  `head_url` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '头像',
  `work_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工号',
  `work_card_code` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工卡编码',
  `warehouse_id` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属仓库多个',
  `wh_arr` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '查看权限数组',
  `base_id` tinyint(1) NULL DEFAULT 0 COMMENT '账号所属基地；0：贵州基地 1：广东基地 2：江苏基地 3：湖北基地 4：辽宁基地 5：北京基地 6：福建基地',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '所属部门',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '岗位',
  `is_leader` tinyint(1) NULL DEFAULT NULL COMMENT '1是部门管理员0不是',
  `is_dept_director` tinyint(1) NULL DEFAULT 0 COMMENT '是否部门负责人；0：不是；1：是',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '1正常,0禁用',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_types` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '所属模块id，多个用逗号隔开;0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `is_white_user` tinyint(1) NULL DEFAULT 0 COMMENT '是否白名单账号；0：不是；1：是',
  `is_first_login` tinyint(1) NULL DEFAULT 1 COMMENT '是否首次登录 0 否 1是',
  `is_visitor` tinyint(1) NULL DEFAULT 0 COMMENT '1访客注册；2：维修供应商；3：监控维修外部维修单位 4 招聘来源',
  `is_out` tinyint(1) NULL DEFAULT 1 COMMENT '是否外部账号；1：内部账号；2：外部账号',
  `source` tinyint(1) NULL DEFAULT 0 COMMENT '来源 0 直接新增 1 访客获取 2 招聘获取',
  `out_inst_id` int(11) NULL DEFAULT NULL COMMENT '所属外部机构id',
  `out_inst_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属外部机构名称',
  `workbench_config_id` int(10) NULL DEFAULT NULL COMMENT '工作台自定义配置id',
  `sort_val` int(11) NULL DEFAULT NULL,
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签名',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `baidu_ai_model` tinyint(1) NOT NULL DEFAULT 1 COMMENT '百度AI模型 1-llama-4-maverick-17b-128e-instruct 2-deepseek-vl2 3-deepseek-vl2-small',
  `power_white` tinyint(1) NOT NULL DEFAULT 0 COMMENT '人事行政权限白名单 0=否；1=是',
  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸图像',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `user`(`user`) USING BTREE,
  UNIQUE INDEX `openid`(`openid`) USING BTREE,
  UNIQUE INDEX `unionid`(`unionid`) USING BTREE,
  UNIQUE INDEX `dd_userid`(`dd_userid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `work_no`(`work_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 981 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '后台-管理员' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_au_user_ai_model_set
-- ----------------------------
DROP TABLE IF EXISTS `os_au_user_ai_model_set`;
CREATE TABLE `os_au_user_ai_model_set`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `uid` int(11) NOT NULL COMMENT '用户id',
  `document_type` int(11) NOT NULL COMMENT '单据类型；0：安全隐患整改单（默认）；1：隐患上报；2：外部检查记录',
  `baidu_ai_model` tinyint(1) NOT NULL DEFAULT 1 COMMENT '百度AI模型 1-llama-4-maverick-17b-128e-instruct 2-deepseek-vl2 3-deepseek-vl2-small',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `uid`(`uid`, `document_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户ai模型设置记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_au_workbench_list
-- ----------------------------
DROP TABLE IF EXISTS `os_au_workbench_list`;
CREATE TABLE `os_au_workbench_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '工作台名称',
  `desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作台描述',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '工作台状态；1：启用；2：禁用',
  `sort_val` int(11) NULL DEFAULT 0 COMMENT '排序值',
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '类型；1：个人；2：非个人',
  `job_arr` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '适用对象-岗位id，多个用逗号隔开',
  `workbench_config_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置内容，json数组',
  `common_use_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '常用速达区，json数组',
  `is_default` tinyint(1) NULL DEFAULT 1 COMMENT '是否系统默认；1：不是；2：是',
  `uid` int(10) NULL DEFAULT NULL COMMENT '所属用户id',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `sort_val`(`sort_val`) USING BTREE,
  INDEX `is_default`(`is_default`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `status_2`(`status`, `type`) USING BTREE,
  INDEX `uid`(`uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工作台管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_config
-- ----------------------------
DROP TABLE IF EXISTS `os_config`;
CREATE TABLE `os_config`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置项',
  `value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 51 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '系统全局配置（不方便写在config文件经常改的配置）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_institution_list
-- ----------------------------
DROP TABLE IF EXISTS `os_institution_list`;
CREATE TABLE `os_institution_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '外部机构名称',
  `sort_val` int(11) NULL DEFAULT NULL COMMENT '排序值，数值越大，越靠前',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '所属部门id',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 18 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '外部机构管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for os_ip_restrict
-- ----------------------------
DROP TABLE IF EXISTS `os_ip_restrict`;
CREATE TABLE `os_ip_restrict`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `ip` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP',
  `pc_status` tinyint(1) NULL DEFAULT 0 COMMENT 'pc端限制；0：开启；1：关闭',
  `wx_status` tinyint(1) NULL DEFAULT 0 COMMENT '小程序端限制；0：开启；1：关闭',
  `ct_uid` int(10) NOT NULL COMMENT '创建人uid',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '最后修改人uid',
  `desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `ip`(`ip`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 304 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'ip限制表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for ou_as_certificate
-- ----------------------------
DROP TABLE IF EXISTS `ou_as_certificate`;
CREATE TABLE `ou_as_certificate`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name_id` int(10) NULL DEFAULT NULL COMMENT '证照名称id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '证照名称',
  `name_type_id` int(10) NULL DEFAULT NULL COMMENT '证照类型id',
  `file_type_id` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `record_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备案编号',
  `regist_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登记日期',
  `exp_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '到期日期',
  `handler_user` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '经办人用户名',
  `handler_uid` int(10) NULL DEFAULT NULL COMMENT '经办人uid',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提审；1=待验收；2=已完成；3=已驳回；4=已撤回；5=已作废',
