  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `procure_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5262 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for procure_change_assoc
