  `order_id` int(10) UNSIGNED NOT NULL COMMENT '需求单列表ID',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '申请部门id',
  `dept_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请部门名称',
  `warehouse_id` int(10) NULL DEFAULT NULL COMMENT '仓库id',
  `warehouse_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `stock` decimal(18, 4) NULL DEFAULT NULL COMMENT '当前库存 ',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物料名称',
  `goods_warning_qty` decimal(18, 4) NULL DEFAULT NULL COMMENT '订货点（风险库存）',
  `monthly_consume_qty` decimal(18, 4) NULL DEFAULT NULL COMMENT '月消耗量',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '货品id',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物料条码(商品编码)',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格/型号',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单价',
  `num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '需求数量(原始)',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量(待采购数量)',
  `theory_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '理论计划量',
  `diff_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '差异量',
  `total_price` decimal(18, 4) NULL DEFAULT NULL COMMENT '小计（总价）',
  `delivery_warning_day` int(11) NULL DEFAULT NULL COMMENT '货期天数',
  `budget_item` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预算科目',
  `purpose` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '用途',
  `purchase_reason_type` tinyint(1) NULL DEFAULT NULL COMMENT '请购原因id',
  `purchase_reason_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '请购原因文本',
  `demand_type` tinyint(2) NULL DEFAULT NULL COMMENT '需求类型id',
  `demand_type_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求类型文本',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '需求计划商品' ROW_FORMAT = Dynamic;

