-- ----------------------------
-- Table structure for procure_goods
-- ----------------------------
DROP TABLE IF EXISTS `procure_goods`;
CREATE TABLE `procure_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `procure_id` int(10) UNSIGNED NOT NULL COMMENT '采购单列表ID',
  `demand_goods_id` int(10) NULL DEFAULT NULL COMMENT '需求计划单货品明细id',
  `demand_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求计划单号',
  `demand_order_id` int(10) NULL DEFAULT NULL COMMENT '需求计划单id',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称(短文本)(商品名称)',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物料条码(商品编码)',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `price` decimal(18, 7) NULL DEFAULT 0.0000000 COMMENT '含税单价(元)(采购单价)',
  `total_price` decimal(18, 4) NULL DEFAULT NULL COMMENT '小计',
  `go_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '去税单价',
  `tax_rate` tinyint(3) NULL DEFAULT 13 COMMENT '税率,默认13',
  `num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '采购订单数量(原始)',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余采购(变动)(也指待入数量)',
  `rec_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '入库数量',
  `ret_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '采购退回数量',
  `supplier_id` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '供应商id',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `delivery_time` datetime NULL DEFAULT NULL COMMENT '交货期',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同号',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `dept_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求部门id，多个用逗号隔开',
  `goods_id` int(10) NULL DEFAULT NULL,
  `every_price` decimal(18, 2) NULL DEFAULT 1.00 COMMENT '每（价格单位)',
  `every_price_rate` decimal(18, 4) NULL DEFAULT NULL COMMENT 'PBXX金额/每单价(SAP单价)',
  `net_price` decimal(18, 4) NULL DEFAULT NULL COMMENT '净价',
  `warehouse_id` int(10) NULL DEFAULT NULL COMMENT '库存地点id(仓库id)',
  `submit_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交日期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `procure_id`(`procure_id`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2823 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购单商品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for procure_list
-- ----------------------------
DROP TABLE IF EXISTS `procure_list`;
CREATE TABLE `procure_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `procure_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '采购单号',
  `brand` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品大类;ND1 红牛 ND2 战马',
  `all_price` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '采购总价',
  `all_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '采购数量',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0待提审,1待审核,2待入库,3已完成,4已撤回,5已驳回,6已作废,8反审',
  `checkout_status` tinyint(1) NULL DEFAULT 1 COMMENT '结算状态；1：未结算；2：已结算',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `purpose` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '采购事由',
  `sap_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP采购凭证',
  `sap_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP凭证日期',
  `procure_type` tinyint(1) NULL DEFAULT NULL COMMENT '采购订单类型id',
  `method` tinyint(1) NULL DEFAULT 0 COMMENT '采购方式；0：直接采购；1：按需采购；3：供应链推送',
  `demand_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '需求年月',
  `demand_order_id` int(11) NULL DEFAULT NULL COMMENT '需求计划单id',
  `warehouse_id` int(10) NULL DEFAULT NULL COMMENT '库存地点id(仓库id)',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `sup_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `demand_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求计划单号',
  `source_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源单据编号',
  `request_ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建单端ip',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `procure_no`(`procure_no`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `ct_name`(`ct_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 933 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购单列表' ROW_FORMAT = Dynamic;

