  `max_target` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '标准值范围大值',
  `complete` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '实际完成',
  `is_standard` tinyint(1) NULL DEFAULT 1 COMMENT '是否达标',
  `total_complete` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '累计完成',
  `total_is_standard` tinyint(1) NULL DEFAULT 1 COMMENT '累计是否达标',
