  INDEX `base_id`(`base_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1969 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '基地生产考核指标' ROW_FORMAT = Dynamic;

