-- ----------------------------
-- Table structure for produce_canning
-- ----------------------------
DROP TABLE IF EXISTS `produce_canning`;
CREATE TABLE `produce_canning`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品批号',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `cate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型',
  `sku` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型编码',
  `goods_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品物料编码',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `on_time` time NULL DEFAULT NULL COMMENT '开机时间',
  `off_time` time NULL DEFAULT NULL COMMENT '关机时间',
  `filling_rate` int(11) NULL DEFAULT NULL COMMENT '灌装速度',
  `filling_volume` int(11) NULL DEFAULT NULL COMMENT '灌装量',
  `sample` int(11) NULL DEFAULT NULL COMMENT '取样量',
  `discard` int(11) NULL DEFAULT NULL COMMENT '废罐量',
  `empty_cans` int(11) NULL DEFAULT NULL COMMENT '设备调整消耗空罐',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `clearing_record_operator_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封口机清理记录清洁人1',
  `clearing_record_operator_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封口机清理记录清洁人2',
  `clearing_record_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封口机清理记录时间1',
  `clearing_record_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封口机清理记录时间2',
  `clearing_record_watchdog_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封口机清理记录监督人1',
  `clearing_record_watchdog_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '封口机清理记录监督人2',
  `clearing_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '封口机清理记录',
  `disinfection_record_o3` tinyint(1) NULL DEFAULT NULL COMMENT '环境消毒记录O3',
  `disinfection_record_clo2` tinyint(1) NULL DEFAULT NULL COMMENT '环境消毒记录ClO2',
  `disinfection_record_operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '环境消毒记录操作工',
  `disinfection_record_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '环境消毒记录时间',
  `disinfection_record_watchdog` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '环境消毒记录监督人',
  `alcohol_addition_record_time` time NULL DEFAULT NULL COMMENT '酒精添加记录时间',
  `alcohol_addition_record_num` int(11) NULL DEFAULT NULL COMMENT '酒精添加记录更换量',
  `alcohol_addition_record_operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '酒精添加记录操作工',
  `alcohol_addition_record_watchdog` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '酒精添加记录监督人',
  `operation_status` tinyint(1) NULL DEFAULT 1 COMMENT '工序运作状况1正常0不正常',
  `operation_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '工序运作详情',
  `breakdown_status` tinyint(1) NULL DEFAULT 0 COMMENT '故障和维修记录0无1有',
  `breakdown_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障和维修记录详情',
  `liquid_level` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '液位',
  `nitrogen_injection` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '注氮',
  `clean_time` int(11) NULL DEFAULT NULL COMMENT '清洗时间',
  `last_in_use` int(11) NULL DEFAULT NULL COMMENT '上期在用量',
  `use_total` int(11) NULL DEFAULT NULL COMMENT '本期领用量',
  `in_use` int(11) NULL DEFAULT NULL COMMENT '本期在用量',
  `input` int(11) NULL DEFAULT NULL COMMENT '本期投入量',
  `leakage_status` tinyint(1) NULL DEFAULT 1 COMMENT '管路与接头等处渗漏情况1正常0不正常',
  `leakage_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '管路与接头等处渗漏情况详情',
  `safe_status` tinyint(1) NULL DEFAULT 1 COMMENT '安全状况1合格0不合格',
  `sanitation_status` tinyint(1) NULL DEFAULT 1 COMMENT '卫生状况1合格0不合格',
  `cleanroom_temperature` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '洁净间温度',
  `cleanroom_humidity` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '洁净间湿度',
  `dressingroom_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更衣室压差',
  `cleanroom_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '洁净间压差',
  `document_status` tinyint(1) NULL DEFAULT 1 COMMENT '岗位文件1齐全0不齐全',
  `tool_status` tinyint(1) NULL DEFAULT 1 COMMENT '岗位工具1齐全0不齐全',
  `hygrothermograph_status` tinyint(1) NULL DEFAULT 1 COMMENT '温湿度计1正常0不正常',
  `barometer_status` tinyint(1) NULL DEFAULT 1 COMMENT '气压表1正常0不正常',
  `saccharimeter_status` tinyint(1) NULL DEFAULT 1 COMMENT '糖度计1正常0不正常',
  `electronic_scale_status` tinyint(1) NULL DEFAULT 1 COMMENT '电子秤1正常0不正常',
  `stop_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '停机时间',
  `equipment_cleanliness_status` tinyint(1) NULL DEFAULT 1 COMMENT '设备清洁状况1合格0不合格',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '订单状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `signature_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字3待复核人签字4待主管签字',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `assay_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '化验员签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接班签字',
  `signatory_three` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '复核人签字',
  `signatory_four` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主管签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 698 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '灌装工序' ROW_FORMAT = Dynamic;

