  `time` time NULL DEFAULT NULL COMMENT '时间',
  `water_temperature` decimal(6, 2) NULL DEFAULT NULL COMMENT '洗罐水温（℃）',
  `product_temperature` decimal(6, 2) NULL DEFAULT NULL COMMENT '板交后产品温度（℃）',
  `heat_time` int(10) NULL DEFAULT NULL COMMENT '加热杀菌时间（s）',
  `into_machine` decimal(6, 2) NULL DEFAULT NULL COMMENT '产品进入灌注机（℃）',
  `valve_temperature` decimal(6, 2) NULL DEFAULT NULL COMMENT '灌装阀温度（℃）',
  `filling_rate` decimal(6, 2) NULL DEFAULT NULL COMMENT '灌装速度（CPM）',
  `steam_pressure` decimal(6, 2) NULL DEFAULT NULL COMMENT '减压后蒸汽压力（MPa）',
  `water_pressure` decimal(6, 2) NULL DEFAULT NULL COMMENT '洗罐水压力（kgf/cm²）',
  `inlet_pressure` decimal(6, 2) NULL DEFAULT NULL COMMENT '陶瓷过滤器进口压力（MPa）',
  `sugar_degree` decimal(6, 2) NULL DEFAULT NULL COMMENT '糖度',
  `operator` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '检查人',
  `produce_temperature` decimal(6, 3) NULL DEFAULT NULL COMMENT '加热后产品温度（℃）',
  `center_temperature` decimal(6, 3) NULL DEFAULT NULL COMMENT '中央缸温度（℃）',
  `bag_pressure` decimal(6, 3) NULL DEFAULT NULL COMMENT '袋式过滤器压力差（MPa）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '备注',
  `attachment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '附件',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `canning_id`(`canning_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 886 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '灌装工序记录' ROW_FORMAT = Dynamic;

