  `end_date` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '起始时间',
  `o_sign2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '滤芯浸泡-操作员签字',
  `o_sign3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '滤芯清洗-操作员签字',
  `excep_note2` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '滤芯清洗-异常说明',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；1：待确认 2-已完成',
