-- ----------------------------
-- Table structure for produce_code_set
-- ----------------------------
DROP TABLE IF EXISTS `produce_code_set`;
CREATE TABLE `produce_code_set`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称重标准名称',
  `uid` int(10) UNSIGNED NOT NULL COMMENT '创建UID',
  `sku` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `w_num` int(10) UNSIGNED NULL DEFAULT 1 COMMENT '称重次数',
  `v_start` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单罐体积起(ml)',
  `v_end` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单罐体积尾(ml)',
  `avg_num` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '平均净含量(ml)',
  `whole_lot` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整批标准[大于,百分比]',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '最后更新UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '打码称重标准' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for produce_coding
-- ----------------------------
DROP TABLE IF EXISTS `produce_coding`;
CREATE TABLE `produce_coding`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品批号',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `cate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型',
  `sku` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型编码',
  `goods_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品物料编码',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `on_time` time NULL DEFAULT NULL COMMENT '开机时间',
  `off_time` time NULL DEFAULT NULL COMMENT '关机时间',
  `expiration_date` date NULL DEFAULT NULL COMMENT '保质期至',
  `produce_info_date` date NULL DEFAULT NULL COMMENT '生产信息日期',
  `produce_info_time` time NULL DEFAULT NULL COMMENT '生产信息时间',
  `produce_info_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '生产信息批号',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `sample_size` int(10) NULL DEFAULT NULL COMMENT '化验取样量',
  `avg_weight` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均重量',
  `consumable_replacement_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '耗材更换时间',
  `consumable_replacement_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '耗材更换记录',
  `correction_entries_status` tinyint(1) NULL DEFAULT 1 COMMENT '空罐机1正常0不正常',
  `correction_entries` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '液位检测仪矫正记录',
  `recycled_water_status` tinyint(1) NULL DEFAULT 1 COMMENT '循环水感官1正常0不正常',
  `recycled_water_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '循环水感官详情',
  `recycled_water_ph` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '循环水PH',
  `recycled_water_brix` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '循环水Brix',
  `operation_status` tinyint(1) NULL DEFAULT 1 COMMENT '工序运作状况1正常0不正常',
  `operation_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '工序运作详情',
  `operation_operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '工序运作操作工',
  `breakdown_status` tinyint(1) NULL DEFAULT 0 COMMENT '故障和维修记录0无1有',
  `breakdown_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障和维修记录详情',
  `breakdown_operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障和维修记录操作工',
  `safe_status` tinyint(1) NULL DEFAULT 1 COMMENT '安全状况1合格0不合格',
  `sanitation_status` tinyint(1) NULL DEFAULT 1 COMMENT '卫生状况1合格0不合格',
  `process_quality` int(11) NULL DEFAULT NULL COMMENT '工序正品量',
  `waste_amount` int(11) NULL DEFAULT NULL COMMENT '本工序废品量',
  `heat_waste_amount` int(11) NULL DEFAULT NULL COMMENT '热缩工序废品量',
  `packing_waste_amount` int(11) NULL DEFAULT NULL COMMENT '包装工序废品量',
  `palletize_waste_amount` int(11) NULL DEFAULT NULL COMMENT '码垛工序废品量',
  `sample` int(11) NULL DEFAULT NULL COMMENT '取样量',
  `qualify` decimal(10, 7) NULL DEFAULT NULL COMMENT '合格率',
  `last_can_expiration_date` date NULL DEFAULT NULL COMMENT '最后一罐保质期',
  `last_can_produce_date` date NULL DEFAULT NULL COMMENT '最后一罐生产日期',
  `last_can_produce_time` time NULL DEFAULT NULL COMMENT '最后一罐生产时间',
  `last_can_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一罐批次',
  `last_box_expiration_date` date NULL DEFAULT NULL COMMENT '最后一箱保质期',
  `last_box_produce_date` date NULL DEFAULT NULL COMMENT '最后一箱生产日期',
  `last_box_status` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '1' COMMENT '最后一箱1合格0不合格',
  `last_box_batch_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱批号1',
  `last_box_batch_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱批号2',
  `total_box` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '共多少箱',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '订单状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `signature_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字3待复核人签字4待主管签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接班签字',
  `signatory_three` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '复核人签字',
  `signatory_four` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主管签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 696 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '打码工序' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_coding_assoc
-- ----------------------------
DROP TABLE IF EXISTS `produce_coding_assoc`;
CREATE TABLE `produce_coding_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
