-- ----------------------------
-- Table structure for produce_duty_delay_list
-- ----------------------------
DROP TABLE IF EXISTS `produce_duty_delay_list`;
CREATE TABLE `produce_duty_delay_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `date_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产日期（年月日）',
  `class_no` int(11) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_no_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次文本',
  `class_type` int(11) NULL DEFAULT NULL COMMENT '班组id',
  `class_type_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组文本',
  `reg_uid` int(11) NOT NULL COMMENT '登记人uid',
  `reg_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登记人名字',
  `reg_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '登记时间',
  `raw_total_delay` int(11) NULL DEFAULT NULL COMMENT '原材料累计误时',
  `person_total_delay` int(11) NULL DEFAULT NULL COMMENT '人员累计误时',
  `eq_total_delay` int(11) NULL DEFAULT NULL COMMENT '设备累计误时',
  `maint_total_delay` int(11) NULL DEFAULT NULL COMMENT '运维累计误时',
  `craft_total_delay` int(11) NULL DEFAULT NULL COMMENT '工艺累计误时',
  `other_total_delay` int(11) NULL DEFAULT NULL COMMENT '其他累计误时',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态  0:待提审 1:待验收 2:已完成 3:已驳回 4:已撤回 5:已反审 6:已作废',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人名',
  `ct_uid` int(11) NOT NULL COMMENT '制单人',
  `up_uid` int(11) NOT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status_2`(`status`) USING BTREE,
  INDEX `class_no`(`class_no`) USING BTREE,
  INDEX `class_type`(`class_type`) USING BTREE,
  INDEX `class_no_2`(`class_no`, `class_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 167 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '当班误时信息登记表' ROW_FORMAT = Dynamic;

