  `dev_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '偏差值(克)',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '是否合格；0：不合格；1：合格',
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '操作类型：1创建，2移除',
  `weigher` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称量人(复核人)',
  `is_mixed_batch` tinyint(1) NULL DEFAULT NULL COMMENT '是否混批；0：不是；1：是',
  `bucket_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '桶号',
  `source` tinyint(1) NOT NULL DEFAULT 1 COMMENT '来源1系统2手录',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '创建UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `original_ph_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次，多个用,隔开',
  `factory_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称，多个用,隔开',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 409 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '香精称重明细日志' ROW_FORMAT = Dynamic;

