  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称,自定义分类',
  `rela_type` tinyint(1) NULL DEFAULT NULL COMMENT '关联单据类型 1 盛料桶记录表 2 复合香精记录',
  `sort` int(5) NULL DEFAULT NULL COMMENT '显示顺序',
