  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `sku`(`sku`, `status`) USING BTREE,
  INDEX `rela_type`(`rela_type`, `sort`) USING BTREE,
  INDEX `sku_2`(`sku`, `barcode`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 168 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'bom清单（物料称重标准）' ROW_FORMAT = Dynamic;

