  `reviewer_check_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
