-- ----------------------------
-- Table structure for produce_fj_cip
-- ----------------------------
DROP TABLE IF EXISTS `produce_fj_cip`;
CREATE TABLE `produce_fj_cip`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `line_id` int(10) NULL DEFAULT NULL COMMENT '产线ID',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `cip_type` tinyint(1) NULL DEFAULT NULL COMMENT 'cip类型1开机CIP，2停机CIP，3连续生产阶段性CIP，4换型改线CIP，5内部CIP，6停产维护性CIP，7设备维修性CIP',
  `cleaner_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗剂名称',
  `cleaner_amount` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗剂用量',
  `cleaning_solution_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液配制量',
  `cleaning_solution_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液浓度',
  `other_solution_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他溶液用量',
  `other_solution_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他配制溶剂量',
  `other_solution_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他溶液浓度',
  `clo2_solution_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二氧化氯溶液用量',
  `clo2_solution_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二氧化氯配制溶剂量',
  `clo2_solution_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二氧化氯溶液浓度',
  `citric_acid_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '柠檬酸溶液用量',
  `lemon_use_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '柠檬酸溶液使用详情',
  `citric_acid_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '柠檬酸配制溶剂量',
  `citric_acid_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '柠檬酸溶液浓度',
  `pre_flush_ro_water_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配料RO用水量',
  `pre_flush_ro_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配料RO水温度',
  `ceramic_filter_replaced` tinyint(1) NULL DEFAULT NULL COMMENT '陶瓷过滤器拆洗情况：1是，0否',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '1柠檬酸2二氧化氯3其他',
  `other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他值',
  `result` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结果',
  `material_staff` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配料操作人员',
  `steam_inlet_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装间蒸汽进口压力',
  `solution_sterilize_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液杀菌时间起',
  `solution_sterilize_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液杀菌时间止',
  `hot_ro_flush_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO冲洗时间起',
  `hot_ro_flush_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO冲洗时间止',
  `hot_ro_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO水温度',
  `peracetic_acid_fumigation_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '过氧乙酸熏蒸时间起',
  `peracetic_acid_fumigation_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '过氧乙酸熏蒸时间止',
  `ozone_uv_sterilize_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '臭氧/紫外线杀菌时间起',
  `ozone_uv_sterilize_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '臭氧/紫外线杀菌时间止',
  `clean_room_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洁净间温度',
  `clean_room_humidity` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洁净间湿度',
  `clean_room_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洁净间压差',
  `filter_bag_replaced` tinyint(1) NULL DEFAULT NULL COMMENT '袋式过滤器更换情况：1是，0否',
  `pipeline_filter_cleaned` tinyint(1) NULL DEFAULT NULL COMMENT '管道过滤器拆洗：1是，0否',
  `vestigital_type` tinyint(1) NULL DEFAULT NULL COMMENT '1柠檬酸2二氧化氯3其他',
  `vestigital_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他值',
  `vestigital_result` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结果',
  `sampling_person_filter` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '过滤器样取样人',
  `unsealed_sample_person` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '未封口样取样人',
  `sealed_sample_person` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '封口后罐样取样人',
  `process_content_one` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容1：1完成，0未完成',
  `process_content_two` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容2：1完成，0未完成',
  `process_content_three` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容3：1完成，0未完成',
  `process_content_four` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容4：1完成，0未完成',
  `process_content_five` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容5：1完成，0未完成',
  `process_content_six` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容6：1完成，0未完成',
  `process_content_seven` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容7：1完成，0未完成',
  `process_content_eight` tinyint(1) NULL DEFAULT NULL COMMENT '过程内容8：1完成，0未完成',
  `filling_operator` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '灌装操作人员',
  `check_verify` tinyint(1) NULL DEFAULT NULL COMMENT '检查验证：1完成，0未完成',
  `lab_technician_sign` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '化验员签字',
  `process_operation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序运转情况',
  `status` tinyint(1) NOT NULL COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `class_no`(`class_no`) USING BTREE,
  INDEX `cip_type`(`cip_type`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '福建cip工序记录' ROW_FORMAT = Dynamic;

