  `coding_waste_amount` int(11) NULL DEFAULT NULL COMMENT '打码工序废品量',
  `canning_waste_amount` int(11) NULL DEFAULT NULL COMMENT '灌装工序废品量',
  `heat_waste_amount` int(11) NULL DEFAULT NULL COMMENT '热缩工序废品量',
  `packing_waste_amount` int(11) NULL DEFAULT NULL COMMENT '包装工序废品量',
  `stacking_waste_amount` int(11) NULL DEFAULT NULL COMMENT '堆垛废品量',
  `operations_waste_amount` int(11) NULL DEFAULT NULL COMMENT '运维废品量',
  `material_waste_amount` int(11) NULL DEFAULT NULL COMMENT '原材料废品量',
  `other_waste_amount` int(11) NULL DEFAULT NULL COMMENT '其他废品量',
  `total_waste_amount` int(11) NULL DEFAULT NULL COMMENT '合计废品量',
  `coding_defective_amount` int(11) NULL DEFAULT NULL COMMENT '打码工序次品量',
  `canning_defective_amount` int(11) NULL DEFAULT NULL COMMENT '灌装工序次品量',
  `heat_defective_amount` int(11) NULL DEFAULT NULL COMMENT '热缩工序次品量',
  `packing_defective_amount` int(11) NULL DEFAULT NULL COMMENT '包装工序次品量',
  `stacking_defective_amount` int(11) NULL DEFAULT NULL COMMENT '堆垛次品量',
  `operations_defective_amount` int(11) NULL DEFAULT NULL COMMENT '运维次品量',
  `material_defective_amount` int(11) NULL DEFAULT NULL COMMENT '原材料次品量',
  `other_defective_amount` int(11) NULL DEFAULT NULL COMMENT '其他次品量',
  `total_defective_amount` int(11) NULL DEFAULT NULL COMMENT '合计次品量',
  `recycled_water_ph` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '循环水PH',
  `water_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '用水量',
  `filter_net_cleaning_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '过滤网清洗时间',
  `exception_description` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '异常说明',
  `level_detector_verification_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '液位检测仪验证时间1',
  `level_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '液位检测仪验证时间2',
  `level_detector_verification_result_one` tinyint(1) NULL DEFAULT 1 COMMENT '液位检测仪验证结果11正常0异常',
  `level_detector_verification_result_two` tinyint(1) NULL DEFAULT 1 COMMENT '液位检测仪验证结果21正常0异常',
  `ink_code_detector_verification_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '墨码检测仪验证时间1',
  `ink_code_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '墨码检测仪验证时间2',
  `ink_code_detector_verification_result_one` tinyint(1) NULL DEFAULT 1 COMMENT '墨码检测仪验证结果11正常0异常',
  `ink_code_detector_verification_result_two` tinyint(1) NULL DEFAULT 1 COMMENT '墨码检测仪验证结果21正常0异常',
  `cap_detector_verification_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '异盖检测仪验证时间1',
  `cap_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '异盖检测仪验证时间2',
  `cap_detector_verification_result_one` tinyint(1) NULL DEFAULT 1 COMMENT '异盖检测仪验证结果11正常0异常',
  `cap_detector_verification_result_two` tinyint(1) NULL DEFAULT 1 COMMENT '异盖检测仪验证结果21正常0异常',
  `inverted_can_detector_verification_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '倒罐检测仪验证时间1',
  `inverted_can_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '倒罐检测仪验证时间2',
  `inverted_can_detector_verification_result_one` tinyint(1) NULL DEFAULT 1 COMMENT '倒罐检测仪验证结果11正常0异常',
  `inverted_can_detector_verification_result_two` tinyint(1) NULL DEFAULT 1 COMMENT '倒罐检测仪验证结果21正常0异常',
  `internal_pressure_detector_verification_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '内压检测仪验证时间1',
  `internal_pressure_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '内压检测仪验证时间2',
  `internal_pressure_detector_verification_result_one` tinyint(1) NULL DEFAULT 1 COMMENT '内压检测仪验证结果11正常0异常',
  `internal_pressure_detector_verification_result_two` tinyint(1) NULL DEFAULT 1 COMMENT '内压检测仪验证结果21正常0异常',
  `abnormal_explain` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '检测设备验证异常说明',
  `consumable_replacement_record` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '耗材更换记录',
  `operation_status` tinyint(1) NULL DEFAULT 1 COMMENT '工序运作状况1正常0不正常',
  `operation_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '工序运作状况详情',
  `safe_status` tinyint(1) NULL DEFAULT 1 COMMENT '安全状况1合格0不合格',
  `sanitation_status` tinyint(1) NULL DEFAULT 1 COMMENT '卫生状况1合格0不合格',
  `measuring_status` tinyint(1) NULL DEFAULT 1 COMMENT '计量器具1合格0不合格',
  `last_can_expiration_date` date NULL DEFAULT NULL COMMENT '最后一罐保质期',
  `last_can_produce_date` date NULL DEFAULT NULL COMMENT '最后一罐生产日期',
  `last_can_produce_time` time NULL DEFAULT NULL COMMENT '最后一罐生产时间',
  `last_can_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一罐批次',
  `last_box_expiration_date` date NULL DEFAULT NULL COMMENT '最后一箱保质期',
  `last_box_produce_date` date NULL DEFAULT NULL COMMENT '最后一箱生产日期',
  `last_box_status` tinyint(1) NULL DEFAULT 1 COMMENT '最后一箱1合格0不合格',
  `last_box_batch_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱批号',
  `last_box_batch_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱序列号',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `signature_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字3待复核人签字4待主管签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接班签字',
  `signatory_three` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核人签字',
  `signatory_four` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主管签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 559 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '福建基地打码工序' ROW_FORMAT = DYNAMIC;

