  `produce_date` date NOT NULL COMMENT '生产日期',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `sku` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品编号',
  `produce_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品名称',
  `goods_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产品类型',
  `produce_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '大批次号',
  `line_id` int(10) NOT NULL COMMENT '产线id',
  `line_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产线名称',
  `class_type` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '班组',
  `class_no` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '班次1早2中3晚',
  `operator` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作工',
  `check` tinyint(1) NULL DEFAULT NULL COMMENT '内容物外观及性状检查1正常0异常',
  `check_result` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内容物外观及性状检查描述',
  `is_bag_sugar` tinyint(1) NULL DEFAULT NULL COMMENT '是否使用袋糖1是0否',
  `bag_sugar_goods` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '袋糖物料信息',
  `batch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次',
  `weight` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重量',
  `weighing_quantity` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称量数量',
  `weighing_person` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '袋糖称量人',
  `review_person` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '袋糖复核人',
  `filling_batch_limit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装截止批次',
  `remaining_tons` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '剩余吨数',
  `ambient_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '室内温度',
  `ambient_humidity` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '室内湿度',
  `safe` tinyint(1) NULL DEFAULT NULL COMMENT '安全、卫生状况1：正常；0：异常；',
  `cabinet_one` tinyint(1) NULL DEFAULT NULL COMMENT '一更消毒柜1：正常；0：异常；',
  `cabinet_two` tinyint(1) NULL DEFAULT NULL COMMENT '二更消毒柜1：正常；0：异常；',
  `inspection_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查时间1',
  `inspection_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查时间2',
  `ro_ceramic_filter` tinyint(1) NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器；1：检查；2：更换；',
  `ro_ceramic_filter_inlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器进口1',
  `ro_ceramic_filter_inlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器进口2',
  `ro_ceramic_filter_outlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器出口1',
  `ro_ceramic_filter_outlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器出口2',
  `bag_filter` tinyint(1) NULL DEFAULT NULL COMMENT '袋式过滤器；1：检查；2：更换；',
  `bag_filter_inlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器进口1',
  `bag_filter_inlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器进口2',
  `bag_filter_outlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器出口1',
  `bag_filter_outlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器出口2',
  `uv_sterilizer_one` tinyint(1) NULL DEFAULT NULL COMMENT 'UV杀菌机1；1：正常；0：异常；',
  `uv_sterilizer_two` tinyint(1) NULL DEFAULT NULL COMMENT 'UV杀菌机2；1：正常；0：异常；',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `work_situation_status` tinyint(1) NULL DEFAULT NULL COMMENT '工序运转情况1正常0异常',
  `work_situation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序运转情况',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `sku`(`sku`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `class_type`(`class_type`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 382 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '福建配料工序记录' ROW_FORMAT = Dynamic;

