-- ----------------------------
-- Table structure for produce_fj_weighing_position
-- ----------------------------
DROP TABLE IF EXISTS `produce_fj_weighing_position`;
CREATE TABLE `produce_fj_weighing_position`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `date` date NULL DEFAULT NULL COMMENT '称量日期',
  `produce_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称',
  `sku` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'sku',
  `hygiene` tinyint(1) NULL DEFAULT NULL COMMENT '卫生清洁1是0否',
  `container` tinyint(1) NULL DEFAULT NULL COMMENT '设施容器清洁、完好1是0否',
  `accuracy_verification` tinyint(1) NULL DEFAULT NULL COMMENT '计量器具清洁及准确性验证1是0否',
  `temperature` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '室内温度',
  `humidness` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '室内湿度',
  `weigher` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '称量员',
  `reviewer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员',
  `loader` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '混装员',
  `one_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '一线箱号',
  `two_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '二线箱号',
  `bucket` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '桶号',
  `bucket_num` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '桶数',
  `feeder_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投料员签字',
  `reviewer_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复合员签字',
  `delivery_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '送料人签字',
  `carrier_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '承运人签字',
  `recipient_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '物料接收人签字',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '制单人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `date`(`date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '福建称料岗位工序记录' ROW_FORMAT = Dynamic;

