-- ----------------------------
-- Table structure for produce_formula_cont_review_order
-- ----------------------------
DROP TABLE IF EXISTS `produce_formula_cont_review_order`;
CREATE TABLE `produce_formula_cont_review_order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `gy_mixing_id` int(10) NOT NULL COMMENT '贵州配料工序id',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '大批次',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产线',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早(白) 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装	',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：未确认；2：已确认；',
