-- ----------------------------
-- Table structure for produce_gd_class_meeting_record
-- ----------------------------
DROP TABLE IF EXISTS `produce_gd_class_meeting_record`;
CREATE TABLE `produce_gd_class_meeting_record`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `date` date NULL DEFAULT NULL COMMENT '日期',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次',
  `place` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '会议室' COMMENT '地点',
  `subject` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '班前会' COMMENT '会议主题',
  `status` tinyint(4) NULL DEFAULT 0 COMMENT '状态；0：待确认；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：确认中；8：待提审',
  `is_appearance_qualified` tinyint(1) NULL DEFAULT 1 COMMENT '仪容仪表是否合格 0-不合格 1-合格',
  `appearance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '仪容仪表',
  `has_health_issue` tinyint(1) NULL DEFAULT 0 COMMENT '健康状况结果 0-无 1-有',
  `health_issue` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '健康状况',
  `has_leave_shift` tinyint(1) NULL DEFAULT 0 COMMENT '请假换班情况 0-无 1-有',
  `leave_shift` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '请假换班',
  `is_material_changed` tinyint(1) NULL DEFAULT NULL COMMENT '本班是否变更原材料 0-否 1-是',
  `material_change_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原材料变更情况',
  `safety_notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全注意事项',
  `commendation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '总结表彰',
  `company_announcement` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '公司通报',
  `due_figures` int(10) NULL DEFAULT NULL COMMENT '应到人数',
  `real_num` int(10) NULL DEFAULT NULL COMMENT '实到人数',
  `new_emp_intro` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '新员工介绍',
  `pre_shift_chk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '班前排查',
  `summarize` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总结表扬',
  `task_allocation` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工作任务及人员分配（福建：上班运行情况＆工作计划）',
  `company_information` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '传达公司信息',
  `slogan` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '口号',
  `meeting_host_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '会议主持人签字',
  `inspector_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '巡检员签字',
  `material_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '称料签字',
  `unpack_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '拆包签字',
  `code_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '打码签字',
  `pack_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '包装签字',
  `cleaning_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '保洁签字',
  `scanner_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扫码员签字',
  `dosing_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配料签字',
  `filling_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '灌装签字',
  `thermal_shrinkage_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '热缩签字',
  `palletizing_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '码垛签字',
  `new_employee_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '新员工签字',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '制单人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '广东班前会记录' ROW_FORMAT = Dynamic;

