  `alcohol_addition_record_watchdog` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '酒精添加记录监督人',
  `top_clean_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自动上盖机切刀清洁检查记录',
  `product_check` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '出口成品检查',
