-- ----------------------------
-- Table structure for produce_gy_cip
-- ----------------------------
DROP TABLE IF EXISTS `produce_gy_cip`;
CREATE TABLE `produce_gy_cip`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `line_id` int(10) NULL DEFAULT NULL COMMENT '产线ID',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '编号',
  `cip_type` tinyint(1) NULL DEFAULT NULL COMMENT 'cip类型1开班CIP，2收班CIP，3定期CIP，4停机CIP，5大修后维护性CIP',
  `naoh_solution_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'NaOH溶液用量',
  `naoh_solution_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'NaOH配制溶剂量',
  `naoh_solution_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'NaOH溶液浓度',
  `clo2_solution_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二氧化氯溶液用量',
  `clo2_solution_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二氧化氯配制溶剂量',
  `clo2_solution_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二氧化氯溶液浓度',
  `citric_acid_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '柠檬酸溶液用量',
  `lemon_use_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '柠檬酸溶液使用详情',
  `citric_acid_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '柠檬酸配制溶剂量',
  `citric_acid_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '柠檬酸溶液浓度',
  `steam_pressure_total` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '蒸汽总表压力',
  `steam_pressure_after_reduction` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '减压后蒸汽压力',
  `compressed_air_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '压缩空气压力',
  `ro_water_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO水用量',
  `heating_water_temperature` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '加热水温',
  `filling_temperature` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进入灌装温度',
  `start_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `finish_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成时间',
  `clean_one` tinyint(1) NULL DEFAULT NULL COMMENT '项目1是否实施：1是，0否',
  `clean_two` tinyint(1) NULL DEFAULT NULL COMMENT '项目2是否实施：1是，0否',
  `clean_three` tinyint(1) NULL DEFAULT NULL COMMENT '项目3是否实施：1是，0否',
  `clean_four` tinyint(1) NULL DEFAULT NULL COMMENT '项目4是否实施：1是，0否',
  `clean_five` tinyint(1) NULL DEFAULT NULL COMMENT '项目5是否实施：1是，0否',
  `clean_six` tinyint(1) NULL DEFAULT NULL COMMENT '项目6是否实施：1是，0否',
  `check_one_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查项目1检测值',
  `check_one_result` tinyint(1) NULL DEFAULT NULL COMMENT '检查项目1结果：1合格，0不合格',
  `check_two_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查项目2检测值',
  `check_two_result` tinyint(1) NULL DEFAULT NULL COMMENT '检查项目2结果：1合格，0不合格',
  `check_three_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查项目3检测值',
  `check_three_result` tinyint(1) NULL DEFAULT NULL COMMENT '检查项目3结果：1合格，0不合格',
  `check_four_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查项目4检测值',
  `check_four_result` tinyint(1) NULL DEFAULT NULL COMMENT '检查项目4结果：1合格，0不合格',
  `check_verify` tinyint(1) NULL DEFAULT NULL COMMENT '结论：1合格，0不合格',
  `reasons` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '不合格原因',
  `allocate` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配置人员',
  `cleaner` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '清洗人员',
  `assay` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '化验员签字',
  `status` tinyint(1) NOT NULL COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `class_no`(`class_no`) USING BTREE,
  INDEX `cip_type`(`cip_type`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '贵州cip工序记录' ROW_FORMAT = Dynamic;

