  `ink_change_time_four` time NULL DEFAULT NULL COMMENT '墨水更换时间4',
  `ink_change_time_five` time NULL DEFAULT NULL COMMENT '墨水更换时间5',
  `ink_change_time_six` time NULL DEFAULT NULL COMMENT '墨水更换时间6',
  `ink_change_time_seven` time NULL DEFAULT NULL COMMENT '墨水更换时间7',
  `diluent_change` tinyint(1) NULL DEFAULT NULL COMMENT '稀释剂更换记录',
  `diluent_change_position` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '稀释剂更换位置',
  `diluent_change_time` time NULL DEFAULT NULL COMMENT '稀释剂更换时间',
  `diluent_change_time_two` time NULL DEFAULT NULL COMMENT '稀释剂更换时间2',
  `diluent_change_time_three` time NULL DEFAULT NULL COMMENT '稀释剂更换时间3',
  `diluent_change_time_four` time NULL DEFAULT NULL COMMENT '稀释剂更换时间4',
  `diluent_change_time_five` time NULL DEFAULT NULL COMMENT '稀释剂更换时间5',
  `diluent_change_time_six` time NULL DEFAULT NULL COMMENT '稀释剂更换时间6',
  `diluent_change_time_seven` time NULL DEFAULT NULL COMMENT '稀释剂更换时间7',
  `clean_position` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '墨码机清洗位置',
  `clean_time` time NULL DEFAULT NULL COMMENT '墨码机清洗时间',
  `clean_time_two` time NULL DEFAULT NULL COMMENT '墨码机清洗时间2',
  `clean_time_three` time NULL DEFAULT NULL COMMENT '墨码机清洗时间3',
  `clean_time_four` time NULL DEFAULT NULL COMMENT '墨码机清洗时间4',
  `clean_time_five` time NULL DEFAULT NULL COMMENT '墨码机清洗时间5',
  `clean_time_six` time NULL DEFAULT NULL COMMENT '墨码机清洗时间6',
  `clean_time_seven` time NULL DEFAULT NULL COMMENT '墨码机清洗时间7',
  `detector_time_one` time NULL DEFAULT NULL COMMENT '检测仪验证时间1',
  `detector_time_two` time NULL DEFAULT NULL COMMENT '检测仪验证时间2',
  `detector_signature_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测仪验证签字1',
  `detector_signature_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测仪验证签字2',
  `detector_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测仪验证备注',
  `recycled_water_status` tinyint(1) NULL DEFAULT NULL COMMENT '循环水感官1正常0不正常',
  `recycled_water_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '循环水感官详情',
  `recycled_water_ph` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '循环水PH',
  `recycled_water_brix` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '循环水Brix',
  `operation_status` tinyint(1) NULL DEFAULT NULL COMMENT '工序运作状况1正常0不正常',
  `operation_operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '工序运作操作工',
  `breakdown_status` tinyint(1) NULL DEFAULT NULL COMMENT '故障和维修记录0无1有',
  `breakdown_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障和维修记录详情',
  `breakdown_operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障和维修记录操作工',
  `safe_status` tinyint(1) NULL DEFAULT NULL COMMENT '安全状况1合格0不合格',
  `sanitation_status` tinyint(1) NULL DEFAULT NULL COMMENT '卫生状况1合格0不合格',
  `measuring_status` tinyint(1) NULL DEFAULT NULL COMMENT '计量器具1合格0不合格',
  `waste_amount` int(11) NULL DEFAULT NULL COMMENT '本工序废品量',
  `canning_waste_amount` int(11) NULL DEFAULT NULL COMMENT '灌装工序废品量',
  `heat_waste_amount` int(11) NULL DEFAULT NULL COMMENT '热缩工序废品量',
  `packing_waste_amount` int(11) NULL DEFAULT NULL COMMENT '包装工序废品量',
  `palletize_waste_amount` int(11) NULL DEFAULT NULL COMMENT '码垛工序废品量',
  `qrcode_waste_amount` int(11) NULL DEFAULT NULL COMMENT '二维码废品量',
  `other_waste_amount` int(11) NULL DEFAULT NULL COMMENT '其他废品量',
  `sample` int(11) NULL DEFAULT NULL COMMENT '取样量',
  `qualify` decimal(10, 7) NULL DEFAULT NULL COMMENT '合格率',
  `last_can_expiration_date` date NULL DEFAULT NULL COMMENT '最后一罐保质期',
  `last_can_produce_date` date NULL DEFAULT NULL COMMENT '最后一罐生产日期',
  `last_can_produce_time` time NULL DEFAULT NULL COMMENT '最后一罐生产时间',
  `last_can_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一罐批次',
  `last_box_expiration_date` date NULL DEFAULT NULL COMMENT '最后一箱保质期',
  `last_box_produce_date` date NULL DEFAULT NULL COMMENT '最后一箱生产日期',
  `last_box_status` tinyint(1) NULL DEFAULT NULL COMMENT '最后一箱1合格0不合格',
  `last_box_batch_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱批号1',
  `last_box_batch_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱批号2',
  `total_box` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '共多少箱',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `signature_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字3待复核人签字4待主管签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接班签字',
  `signatory_three` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核人签字',
  `signatory_four` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主管签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 697 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '贵州基地打码工序' ROW_FORMAT = DYNAMIC;

