-- Table structure for produce_gy_coding_record
-- ----------------------------
DROP TABLE IF EXISTS `produce_gy_coding_record`;
CREATE TABLE `produce_gy_coding_record`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `coding_id` int(11) NOT NULL COMMENT '打码工序id',
  `batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批号',
  `start_time` time NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` time NULL DEFAULT NULL COMMENT '结束时间',
  `qualified` int(11) NULL DEFAULT NULL COMMENT '合格品',
  `waste` int(11) NULL DEFAULT NULL COMMENT '废品',
  `sample` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '样品量',
  `sample_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '取样时间',
  `change_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '箱改码时间',
  `operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '改码复核人',
  `avg_weight` decimal(6, 2) NULL DEFAULT NULL COMMENT '平均重量',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `coding_id`(`coding_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1775 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '贵州基地打码工序记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_gy_essence_bucket_goods
-- ----------------------------
DROP TABLE IF EXISTS `produce_gy_essence_bucket_goods`;
CREATE TABLE `produce_gy_essence_bucket_goods`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `bucket_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '桶号',
  `barcode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '条码',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料名称',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '物料id',
  `stock_id` int(11) NULL DEFAULT NULL COMMENT '库存id',
  `batch_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内部批号',
  `original_ph_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原始批次',
  `weight` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '重量',
  `weigh_date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称重日期',
  `w_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称重人名称',
  `in_date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库日期',
  `source_order` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源单据',
  `sup_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `factory_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0 称料间 1 可用 2 已用 3 退库中 4 待处理 5 报废中 6 已报废 7 待分配',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `bucket_number`(`bucket_number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 114 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '配方桶配方信息' ROW_FORMAT = Dynamic;

