  `time_lapse_two` tinyint(1) NULL DEFAULT NULL COMMENT '作业方法误时1有0无',
  `time_lapse_three` tinyint(1) NULL DEFAULT NULL COMMENT '原材料情况误时1有0无',
  `work_method` varchar(900) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '作业方法',
  `material_quality_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原物料品质状况',
  `material_quality_details` varchar(900) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原物料品质状况详情',
