-- ----------------------------
-- Table structure for produce_inspection_quality_detail
-- ----------------------------
DROP TABLE IF EXISTS `produce_inspection_quality_detail`;
CREATE TABLE `produce_inspection_quality_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(11) NOT NULL COMMENT '父级ID',
