-- Table structure for produce_instrument_use_assoc
-- ----------------------------
DROP TABLE IF EXISTS `produce_instrument_use_assoc`;
CREATE TABLE `produce_instrument_use_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '仪器使用维护保养记录id',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仪器使用维护保养记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_instrument_use_detail
-- ----------------------------
DROP TABLE IF EXISTS `produce_instrument_use_detail`;
CREATE TABLE `produce_instrument_use_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(11) NOT NULL COMMENT '父级ID',
  `is_normal` tinyint(1) NULL DEFAULT NULL COMMENT '是否正常 0 否 1 是',
  `is_clean` tinyint(1) NULL DEFAULT NULL COMMENT '是否清洁 0 否 1 是',
  `is_repair` tinyint(1) NULL DEFAULT NULL COMMENT '是否维修 0 否 1 是',
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班签字',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '制单人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仪器使用维护保养记录-详情' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_instrument_use_log
-- ----------------------------
DROP TABLE IF EXISTS `produce_instrument_use_log`;
CREATE TABLE `produce_instrument_use_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '仪器使用维护保养记录ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 63 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仪器使用维护保养记录日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_inventory
-- ----------------------------
DROP TABLE IF EXISTS `produce_inventory`;
CREATE TABLE `produce_inventory`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) UNSIGNED NOT NULL COMMENT '商品id',
  `warehouse_id` int(11) UNSIGNED NOT NULL COMMENT '仓库id',
  `stock` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '库存数量',
  `stock_warning_qty` int(11) NULL DEFAULT 0 COMMENT '库存下限（也表示库存预警数量或安全库存）,当设置为0或未设置空时，表示不设置该商品预警值',
  `stock_upper_qty` int(11) NULL DEFAULT 0 COMMENT '库存上限,当设置为0或未设置空时，表示不设置该商品预警值',
  `goods_warning_qty` int(11) NULL DEFAULT 0 COMMENT '订货预警数量,当设置为0或未设置空时，表示不设置该商品预警值',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 120 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_inventory_detail
-- ----------------------------
DROP TABLE IF EXISTS `produce_inventory_detail`;
CREATE TABLE `produce_inventory_detail`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `inventory_id` int(11) NOT NULL COMMENT '库存总表id',
  `batch_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批次号',
  `document_type` smallint(2) NOT NULL COMMENT '单据交易类型 1:vb12入库；2:领用移库单-VB12',
  `document_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `transaction_type` smallint(2) UNSIGNED NOT NULL DEFAULT 1 COMMENT '交易类型 1入库 2出库 3恢复库存',
  `transaction_quantity` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '交易数量',
  `balance_quantity` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '结余数量',
  `transaction_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '交易日期',
  `warehouse_id` int(11) NOT NULL COMMENT '仓库id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细表id',
  `ws_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架位',
  `pro_time` datetime NULL DEFAULT NULL COMMENT '生产日期',
  `exp_time` datetime NULL DEFAULT NULL COMMENT '到期日期',
  `is_gen_uniq` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成唯一；0:不生成,1:生成',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `in_wh_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库单号',
  `price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '单价',
  `stock_price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '在库金额',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '出入库类型；0：其他出入库\\正常出入库；1：冲销出入库',
  `in_wh_date` datetime NULL DEFAULT NULL COMMENT '入库日期',
  `exp_day` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '保质期',
  `is_complete` tinyint(1) NULL DEFAULT NULL COMMENT '是否外观完整； 0:否,1:是',
  `is_weigh` tinyint(1) NULL DEFAULT NULL COMMENT '是否入库称重； 0:否,1:是',
  `is_check_pk` tinyint(1) NULL DEFAULT NULL COMMENT '是否核对外包装：0:否,1:是',
  `is_info_accord` tinyint(1) NULL DEFAULT NULL COMMENT '是否条码包装信息一致：0:否,1:是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `batch_number`(`batch_number`) USING BTREE,
  INDEX `transaction_type`(`transaction_type`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 876 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存明细流水表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for produce_inventory_stocks
-- ----------------------------
DROP TABLE IF EXISTS `produce_inventory_stocks`;
CREATE TABLE `produce_inventory_stocks`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `inventory_id` int(11) NOT NULL COMMENT '库存总表id',
  `batch_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批次号',
  `document_type` smallint(2) NOT NULL COMMENT '单据交易类型 1:vb12入库；2:领用移库单-VB12',
  `document_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `stock_qty` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '库存数量（剩余）',
  `in_use_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '占用数（单据占用）',
  `use_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已用数（单据完结）',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称(上线时候去掉这个字段)',
  `transaction_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '交易日期',
  `warehouse_id` int(11) NOT NULL COMMENT '仓库id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人UID',
  `ws_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '库位',
  `pro_time` datetime NULL DEFAULT NULL COMMENT '生产日期',
  `exp_time` datetime NULL DEFAULT NULL COMMENT '到期日期',
  `is_gen_uniq` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成唯一；0:不生成,1:生成',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `procure_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采购单号',
  `in_wh_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库单号',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '单价',
  `stock_price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '在库金额',
  `in_wh_date` datetime NULL DEFAULT NULL COMMENT '入库日期',
  `reserve_decimal` tinyint(1) NULL DEFAULT 0 COMMENT '保留小数',
  `stock_id` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '库存明细id,记录入库时通过哪个库存明细入库的',
  `available_status` tinyint(1) NULL DEFAULT 0 COMMENT '可用状态；0：可用；1：待修；2：报废；',
  `exp_day` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '保质期',
  `exp_warning_day` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '保质期预警天数',
  `is_expensed_assets` tinyint(1) NULL DEFAULT 0 COMMENT '是否费用化资产；0：不是；1：是',
  `is_complete` tinyint(1) NULL DEFAULT NULL COMMENT '是否外观完整； 0:否,1:是',
  `is_weigh` tinyint(1) NULL DEFAULT NULL COMMENT '是否入库称重； 0:否,1:是',
  `is_check_pk` tinyint(1) NULL DEFAULT NULL COMMENT '是否核对外包装：0:否,1:是',
  `is_info_accord` tinyint(1) NULL DEFAULT NULL COMMENT '是否条码包装信息一致：0:否,1:是',
  `initial_in_wh_date` datetime NULL DEFAULT NULL COMMENT '初始入库日期，记录最早的入库日期',
  `initial_stock_id` int(11) NULL DEFAULT NULL COMMENT '初始入库库存id',
  `detail_ctime` datetime NULL DEFAULT NULL COMMENT '从库存出入明细同步过来的create_time,留作后期备用',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '入库类型；0：正常入库；1：其它入库',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ws_code`(`ws_code`) USING BTREE,
  INDEX `batch_number`(`batch_number`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `inventory_id`(`inventory_id`) USING BTREE,
  INDEX `goods_id`(`goods_id`, `ws_code`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 354 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_inventory_stocks_log
-- ----------------------------
DROP TABLE IF EXISTS `produce_inventory_stocks_log`;
CREATE TABLE `produce_inventory_stocks_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `stock_id` int(11) NOT NULL COMMENT '库存id',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据ID',
  `document_type` tinyint(1) UNSIGNED NOT NULL COMMENT '单据类型',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '物品ID',
  `warehouse_id` int(11) NULL DEFAULT NULL COMMENT '仓库ID',
  `batch_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物品批次',
  `num` decimal(18, 4) NULL DEFAULT NULL COMMENT '记录数',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_id`(`stock_id`, `order_id`, `document_type`, `warehouse_id`, `goods_id`, `batch_number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '单据库存数记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_inventory_stocks_unique
-- ----------------------------
DROP TABLE IF EXISTS `produce_inventory_stocks_unique`;
CREATE TABLE `produce_inventory_stocks_unique`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `inventory_id` int(11) NULL DEFAULT NULL COMMENT '库存总表id',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：在库；1：已出库；2：待使用；3：上线中；4：使用中；5：下线中；6：已下线；',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `num` int(11) UNSIGNED NULL DEFAULT 1 COMMENT '数量',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人UID',
  `unique_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '唯一值',
  `sort` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '排序值',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存明细唯一标识表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_invert_sugar_order
-- ----------------------------
DROP TABLE IF EXISTS `produce_invert_sugar_order`;
CREATE TABLE `produce_invert_sugar_order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `gy_mixing_id` int(10) NOT NULL COMMENT '贵州配料工序id',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '大批次',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产线',
  `class_no` tinyint(1) NOT NULL COMMENT '班次 1早(白) 2中 3夜',
  `class_type` tinyint(1) NOT NULL COMMENT '班组 (1A、2B、3C)',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：未确认；2：已确认；',
  `sign_status` tinyint(1) NULL DEFAULT NULL COMMENT '签字状态；0：未签字；1：部分签字；2：全部签字',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除	',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '确认人',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `class_no`(`class_no`, `class_type`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 267 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '化糖操作记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_invert_sugar_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `produce_invert_sugar_order_detail`;
CREATE TABLE `produce_invert_sugar_order_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(11) NOT NULL COMMENT '所属单据id',
  `batch_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '白糖批号',
  `batch` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品小批次',
  `start_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束时间',
  `check_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检时间',
  `is_check` tinyint(1) NULL DEFAULT NULL COMMENT '是否送检1是0否',
  `use_weight` decimal(8, 2) NULL DEFAULT NULL COMMENT '使用量',
  `loss_weight` decimal(8, 2) NULL DEFAULT NULL COMMENT '损耗量',
  `use_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '使用明细',
  `sugar_degree` decimal(8, 1) NULL DEFAULT NULL COMMENT '糖度',
  `invert_sugar_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '化糖人签字图片',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '化验员签字图片',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 319 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '化糖操作记录明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_invert_sugar_order_log
-- ----------------------------
DROP TABLE IF EXISTS `produce_invert_sugar_order_log`;
CREATE TABLE `produce_invert_sugar_order_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
