-- ----------------------------
-- Table structure for produce_material_issue
-- ----------------------------
DROP TABLE IF EXISTS `produce_material_issue`;
CREATE TABLE `produce_material_issue`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '类型 1 纸皮 2 热溶胶 3 热缩膜',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '产线ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产线名称',
  `group_id` int(11) NULL DEFAULT NULL COMMENT '班组ID',
  `group_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组名称',
  `class` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1 早班 2 中班 3 晚班',
  `is_isuse_date` date NULL DEFAULT NULL COMMENT '领用日期',
  `isuse_num` int(11) NULL DEFAULT 0 COMMENT '领用数量',
  `package_num` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外包装明示数量/重量',
  `sample` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检标准',
  `sample_date` date NULL DEFAULT NULL COMMENT '抽检日期',
  `sup_id` int(11) NULL DEFAULT NULL COMMENT '供应商ID',
  `sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `pass_rate` decimal(9, 2) NULL DEFAULT NULL COMMENT '合格率',
  `sample_rate` decimal(9, 2) NULL DEFAULT NULL COMMENT '抽检率',
  `test_rate` decimal(9, 2) NULL DEFAULT NULL COMMENT '检测率',
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检员签名',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0待确认 1已完成',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '制单人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `group_id`(`group_id`) USING BTREE,
  INDEX `class`(`class`) USING BTREE,
  INDEX `is_isuse_date`(`is_isuse_date`) USING BTREE,
  INDEX `sample_date`(`sample_date`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '生产物料领用抽检报告' ROW_FORMAT = Dynamic;

