-- Table structure for produce_material_transfer_line_list
-- ----------------------------
DROP TABLE IF EXISTS `produce_material_transfer_line_list`;
CREATE TABLE `produce_material_transfer_line_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
