  `goods_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产品类型',
  `batch_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '大批次号',
  `line_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产线名称',
  `class_type` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '班组',
  `class_no` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '班次1早2中3晚',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：待提交；1：待审批；2：已审批 3：已撤回；4：已驳回；',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '生产主管签字图片，多个用,隔开',
  `ingestion_no` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '盛料桶单号',
  `perfume_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '复合香精单号',
  `check_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配料工序信息',
  `remark` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT 0 COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `submit_node` tinyint(1) NULL DEFAULT 1 COMMENT '表单提交节点 1-记录完成后 2-随时',
  `submit_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '表单提交备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `sku`(`sku`) USING BTREE,
  INDEX `batch_number`(`batch_number`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `class_type`(`class_type`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 510 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '配料工序记录' ROW_FORMAT = Dynamic;

