-- ----------------------------
-- Table structure for produce_new_weighing_essence_position
-- ----------------------------
DROP TABLE IF EXISTS `produce_new_weighing_essence_position`;
CREATE TABLE `produce_new_weighing_essence_position`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `date` date NULL DEFAULT NULL COMMENT '称量日期',
  `intensify_line` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '强化产线',
  `common_line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '普通产线',
  `hygiene` tinyint(1) NULL DEFAULT NULL COMMENT '卫生清洁1是0否',
  `container` tinyint(1) NULL DEFAULT NULL COMMENT '设施容器清洁、完好1是0否',
  `accuracy_verification` tinyint(1) NULL DEFAULT NULL COMMENT '计量器具清洁及准确性验证1是0否',
  `temperature` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '室内温度',
  `humidness` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '室内湿度',
  `check_gas` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '检查气体报警仪器值',
  `check_result` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果1正常0异常',
  `ultraviolet_radiator` tinyint(1) NULL DEFAULT NULL COMMENT '紫外线灯定时开启1是0否',
  `weights_weight` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '砝码重量',
  `weight_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '电子称数组',
  `one_common_num` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一车间普通型配方称量数',
  `one_intensify_num` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一车间强化型配方称量数',
  `two_common_num` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二车间普通型配方称量数',
  `three_common_num` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '三车间普通型配方称量数',
  `one_common_box` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一车间普通型配方箱号',
  `one_intensify_box` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一车间强化型配方箱号',
  `two_common_box` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二车间普通型配方箱号',
  `three_common_box` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '三车间普通型配方箱号',
  `one_common_return_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '一车间普通型退箱信息',
  `one_intensify_return_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '一车间强化型退箱信息',
  `two_common_return_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '二车间普通型退箱信息',
  `three_common_return_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '三车间普通型退箱信息',
  `signature_one` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作员签字',
  `signature_two` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '送料人签字',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `status` tinyint(1) NOT NULL COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `check_num` tinyint(3) UNSIGNED NOT NULL DEFAULT 0 COMMENT '审核次数',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '制单人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `date`(`date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '新称料岗位香精工序记录' ROW_FORMAT = Dynamic;

