  `one_intensify_return_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '一车间强化型退箱信息',
  `two_common_return_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '二车间普通型退箱信息',
  `three_common_return_box` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '三车间普通型退箱信息',
