  `signature_two` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '脱包人签字',
  `signature_three` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '投料人签字',
