) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北：在线库称量损耗-物料信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_operation_overview
