-- ----------------------------
-- Table structure for produce_packaging
-- ----------------------------
DROP TABLE IF EXISTS `produce_packaging`;
CREATE TABLE `produce_packaging`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品批号',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `cate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型',
  `sku` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型编码',
  `goods_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品物料编码',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `on_time` time NULL DEFAULT NULL COMMENT '开机时间',
  `off_time` time NULL DEFAULT NULL COMMENT '关机时间',
  `on_time_two` time NULL DEFAULT NULL COMMENT '开机时间2',
  `off_time_two` time NULL DEFAULT NULL COMMENT '关机时间2',
  `specification` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '规格',
  `pack` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '包装',
  `compressed_air` int(11) NULL DEFAULT NULL COMMENT '压缩空气',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '备注',
  `time_one` time NULL DEFAULT NULL COMMENT '时间1',
  `time_two` time NULL DEFAULT NULL COMMENT '时间2',
  `tunnel_one_temperature_one` int(11) NULL DEFAULT NULL COMMENT '隧道1温度1',
  `tunnel_one_temperature_two` int(11) NULL DEFAULT NULL COMMENT '隧道1温度2',
  `tunnel_two_temperature_one` int(11) NULL DEFAULT NULL COMMENT '隧道2温度1',
  `tunnel_two_temperature_two` int(11) NULL DEFAULT NULL COMMENT '隧道2温度2',
  `glue_record_time_one` time NULL DEFAULT NULL COMMENT '胶温记录时间1',
  `glue_record_time_two` time NULL DEFAULT NULL COMMENT '胶温记录时间2',
  `glue_temperature_one` int(11) NULL DEFAULT NULL COMMENT '胶温记录1',
  `glue_temperature_two` int(11) NULL DEFAULT NULL COMMENT '胶温记录2',
  `document_status` tinyint(1) NULL DEFAULT 1 COMMENT '岗位文件1齐全0不齐全',
  `tool_status` tinyint(1) NULL DEFAULT 1 COMMENT '岗位工具1齐全0不齐全',
  `safe_status` tinyint(1) NULL DEFAULT 1 COMMENT '安全状况1合格0不合格',
  `sanitation_status` tinyint(1) NULL DEFAULT 1 COMMENT '卫生状况1合格0不合格',
  `electronic_scale_status` tinyint(1) NULL DEFAULT 1 COMMENT '电子秤1正常0不正常',
  `platform_scale_status` tinyint(1) NULL DEFAULT 1 COMMENT '台秤1正常0不正常',
  `ambient_hygrograph_status` tinyint(1) NULL DEFAULT 1 COMMENT '环境温湿度计1正常0不正常',
  `relative_humidity` int(11) NULL DEFAULT NULL COMMENT '相对湿度',
  `indoor_temperature` int(11) NULL DEFAULT NULL COMMENT '室温',
  `operation_status` tinyint(1) NULL DEFAULT 1 COMMENT '工序运作状况1正常0不正常',
  `operation_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '工序运作详情',
  `breakdown_status` tinyint(1) NULL DEFAULT 0 COMMENT '故障和维修记录0无1有',
  `breakdown_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障和维修记录详情',
  `film_supplier` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '热缩膜供应商1佛山瑞达普2三水华彩3信谊4其他',
  `film_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '热缩膜供应商其他',
  `carton_supplier` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '纸皮供应商1福华2博太3信谊4其他',
  `carton_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '纸皮供应商其他',
  `glue_supplier` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '热熔胶供应商1欣涛2凯林3其他',
  `glue_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '热熔胶供应商其他',
  `film_last_surplus` decimal(11, 2) NULL DEFAULT NULL COMMENT '热缩膜上班结余量',
  `film_get` decimal(11, 2) NULL DEFAULT NULL COMMENT '热缩膜本班领用量',
  `film_use` decimal(11, 2) NULL DEFAULT NULL COMMENT '热缩膜本班投入量',
  `film_scrap` decimal(11, 2) NULL DEFAULT NULL COMMENT '热缩膜本班报废量',
  `film_return` decimal(11, 2) NULL DEFAULT NULL COMMENT '热缩膜本班退料量',
  `film_surplus` decimal(11, 2) NULL DEFAULT NULL COMMENT '热缩膜本班结存量',
  `carton_last_surplus` int(11) NULL DEFAULT NULL COMMENT '纸箱上班结存量',
  `carton_get` int(11) NULL DEFAULT NULL COMMENT '纸箱领用量',
  `carton_use` int(11) NULL DEFAULT NULL COMMENT '纸箱投入量',
  `carton_scrap` int(11) NULL DEFAULT NULL COMMENT '纸箱报废量',
  `carton_surplus` int(11) NULL DEFAULT NULL COMMENT '纸箱本班结存量',
  `carton_unqualified` int(11) NULL DEFAULT NULL COMMENT '来料不合格纸箱',
  `reheat_shrinkage` int(11) NULL DEFAULT NULL COMMENT '重新热缩量',
  `total_carton` int(11) NULL DEFAULT NULL COMMENT '成品总箱数',
  `total_scrap` int(11) NULL DEFAULT NULL COMMENT '成品报废量',
  `glue_last_surplus` decimal(11, 2) NULL DEFAULT NULL COMMENT '热熔胶上班结存量',
  `glue_get` decimal(11, 2) NULL DEFAULT NULL COMMENT '热熔胶领用量',
  `glue_use` decimal(11, 2) NULL DEFAULT NULL COMMENT '热熔胶投入量',
  `glue_scrap` decimal(11, 2) NULL DEFAULT NULL COMMENT '热熔胶报废量',
  `glue_surplus` decimal(11, 2) NULL DEFAULT NULL COMMENT '热熔胶本班存量',
  `material_balance_one` decimal(10, 7) NULL DEFAULT NULL COMMENT '物料平衡1',
  `material_balance_two` decimal(10, 7) NULL DEFAULT NULL COMMENT '物料平衡2',
  `material_balance_three` decimal(10, 7) NULL DEFAULT NULL COMMENT '物料平衡3',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '订单状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `signature_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字3待复核人签字4待主管签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接班签字',
  `signatory_three` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '复核人签字',
  `signatory_four` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主管签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 688 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '热缩包装工序' ROW_FORMAT = Dynamic;

