  `stock` decimal(18, 4) NULL DEFAULT NULL COMMENT '库存数量',
  `rec_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '移库数量',
  `ph_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内部批次',
  `original_ph_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细表id',
