  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '产线id',
  `line_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产线名称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `mat_rec_id`(`order_id`) USING BTREE,
  INDEX `class_name`(`class_name`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE,
  INDEX `stock_id`(`stock_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 133 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '包材退库-商品' ROW_FORMAT = Dynamic;

