  `time_lapse_two` tinyint(1) NULL DEFAULT NULL COMMENT '作业方法误时1有0无',
  `time_lapse_three` tinyint(1) NULL DEFAULT NULL COMMENT '原材料情况误时1有0无',
  `work_method` varchar(900) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '作业方法',
  `material_quality_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原物料品质状况',
  `material_quality_details` varchar(900) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '原物料品质状况详情',
  `shift_start_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '接班时间',
  `hygiene_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '卫生状况',
  `last_can_expiration_date` date NULL DEFAULT NULL COMMENT '最后一罐保质期',
  `last_can_produce_date` date NULL DEFAULT NULL COMMENT '最后一罐生产日期',
  `last_can_produce_time` time NULL DEFAULT NULL COMMENT '最后一罐生产时间',
  `last_can_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '最后一罐批次',
  `last_box_expiration_date` date NULL DEFAULT NULL COMMENT '最后一箱保质期',
  `last_box_produce_date` date NULL DEFAULT NULL COMMENT '最后一箱生产日期',
