-- ----------------------------
-- Table structure for produce_unpack
-- ----------------------------
DROP TABLE IF EXISTS `produce_unpack`;
CREATE TABLE `produce_unpack`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品批号',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `cate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型',
  `sku` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型编码',
  `goods_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品物料编码',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `on_time` time NULL DEFAULT NULL COMMENT '开机时间',
  `off_time` time NULL DEFAULT NULL COMMENT '关机时间',
  `operation_status` tinyint(1) NULL DEFAULT 1 COMMENT '工序运作状况1正常0不正常',
  `operation_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '工序运作详情',
  `safe_status` tinyint(1) NULL DEFAULT 1 COMMENT '安全状况1合格0不合格',
  `sanitation_status` tinyint(1) NULL DEFAULT 1 COMMENT '卫生状况1合格0不合格',
  `breakdown_status` tinyint(1) NULL DEFAULT 0 COMMENT '故障和维修记录0无1有',
  `breakdown_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '故障和维修记录详情',
  `supplier` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '空罐供应商',
  `supplier_line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐供应商产线',
  `supplier_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐供应商2',
  `last_in_use_tray` int(11) NULL DEFAULT NULL COMMENT '上期在用量托',
  `last_in_use_tier` int(11) NULL DEFAULT NULL COMMENT '上期在用量层',
  `last_in_use_can` int(11) NULL DEFAULT NULL COMMENT '上期在用量罐',
  `last_in_use_total` int(11) NULL DEFAULT NULL COMMENT '上期在用量总罐数',
  `use_tray` int(11) NULL DEFAULT NULL COMMENT '领用量托',
  `use_tier` int(11) NULL DEFAULT NULL COMMENT '领用量层',
  `use_can` int(11) NULL DEFAULT NULL COMMENT '领用量罐',
  `use_total` int(11) NULL DEFAULT NULL COMMENT '领用量总数',
  `sample` int(11) NULL DEFAULT NULL COMMENT '取样量',
  `discard` int(11) NULL DEFAULT NULL COMMENT '剔除废罐数',
  `return_num` int(11) NULL DEFAULT NULL COMMENT '退库量',
  `in_use_tray` int(11) NULL DEFAULT NULL COMMENT '本期末在用量托',
  `in_use_tier` int(11) NULL DEFAULT NULL COMMENT '本期末在用量层',
  `in_use_can` int(11) NULL DEFAULT NULL COMMENT '本期末在用量罐',
  `in_use_total` int(11) NULL DEFAULT NULL COMMENT '本期末在用量总罐数',
  `input` int(11) NULL DEFAULT NULL COMMENT '投入量',
  `qualify` decimal(10, 6) NULL DEFAULT NULL COMMENT '合格率',
  `variant_can` int(11) NULL DEFAULT NULL COMMENT '变形罐',
  `foreign_can` int(11) NULL DEFAULT NULL COMMENT '有异物罐',
  `black_dot_can` int(11) NULL DEFAULT NULL COMMENT '黑点罐',
  `concave_can` int(11) NULL DEFAULT NULL COMMENT '凹坑罐',
  `other_can` int(11) NULL DEFAULT NULL COMMENT '其他',
  `last_tray` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最后一托盘空罐在用层数',
  `last_tray_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一托盘空罐批号',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `signature_status` tinyint(1) NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字3待复核人签字4待主管签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '接班签字',
  `signatory_three` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核人签字',
  `signatory_four` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '主管签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `empty_consumption` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐单耗',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 711 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拆包工序' ROW_FORMAT = Dynamic;

