-- ----------------------------
-- Table structure for produce_use_sugar_sit_order
-- ----------------------------
DROP TABLE IF EXISTS `produce_use_sugar_sit_order`;
CREATE TABLE `produce_use_sugar_sit_order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `gy_mixing_id` int(10) NOT NULL COMMENT '贵州配料工序id',
  `order_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品批号',
  `batch_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '白糖批号',
  `goods` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '白糖物料信息',
  `pre_class_num` float(11, 4) NULL DEFAULT NULL COMMENT '上班在用(kg)',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称',
  `input_num` float(11, 4) NULL DEFAULT NULL COMMENT '投入量(kg)',
  `balance_num` float(11, 4) NULL DEFAULT NULL COMMENT '结余量(kg)',
  `dep_num` float(11, 4) NULL DEFAULT NULL COMMENT '损耗(kg)',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产线',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早(白) 2中 3夜',
  `supplier_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称，多个用逗号隔开',
  `supplier_other` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商其他',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：未确认；2：已确认；',
  `sign_status` tinyint(1) NULL DEFAULT NULL COMMENT '签字状态；0：未签字；1：部分签字；2：全部签字',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除	',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '确认人',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `class_no`(`class_no`, `class_type`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 386 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '白糖使用情况' ROW_FORMAT = Dynamic;

