  `ok_num` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '合格次数',
  `fail_num` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '不合格次数',
  `r_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '极差,最大-最小(ml)',
  `d_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '标差,250ml-平均值',
  `scale_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '电子秤ID',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '整批1合格,0不合格',
  `on_duty_avg_wv` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '平均重量(克)-当班结果',
  `on_duty_avg_vo` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '平均体积(ml)-当班结果',
  `rule_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '计算规则',
  `weighing_standard_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称重标准名称',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '打码称重记录' ROW_FORMAT = Dynamic;

