-- ----------------------------
-- Table structure for produce_weighing_record
-- ----------------------------
DROP TABLE IF EXISTS `produce_weighing_record`;
CREATE TABLE `produce_weighing_record`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '物料id(货品id)',
  `bucket_plan_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '盛料桶计划单号',
  `bucket_number` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '盛料桶号信息',
  `weigher` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称量人',
  `reviewer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核人',
  `pre_residue_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上期剩余单号',
  `pre_residue_v` decimal(18, 0) NULL DEFAULT NULL COMMENT '上期剩余(KG)',
  `ct_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料名称',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单号',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `spec` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `out_wh_id` int(11) NULL DEFAULT NULL COMMENT '称料领出库id',
  `in_wh_id` int(11) NULL DEFAULT NULL COMMENT '配方入库id',
  `ref_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '参考值(克)(配方重量)',
  `err_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '误差值(克)',
  `rec_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '领料重量(克)',
  `dev_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '总误差(克)',
  `total_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '总重量(克)',
  `max_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '最大值(克)',
  `min_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '最小值(克)',
  `avg_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '平均值(克)',
  `rem_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '理论剩余重量(克)',
  `num` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '计量份数',
  `real_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '实际剩余重量(克)',
  `pre_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '上期剩余(克)',
  `dep_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '耗损(克)',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `measure_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签字',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 2 COMMENT '保留小数',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `scale_id` int(11) UNSIGNED NULL DEFAULT NULL COMMENT '电子秤ID',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT NULL COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `category_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品类',
  `is_multi_scale_sync` tinyint(1) NULL DEFAULT 0 COMMENT '是否开启多称同步；0：否；1：是',
  `merge_identify` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标识一样，表示合并',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人uid',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `is_multi_scale_sync`(`is_multi_scale_sync`, `merge_identify`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 496 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重记录' ROW_FORMAT = Dynamic;

