-- ----------------------------
-- Table structure for produce_xn_cip
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_cip`;
CREATE TABLE `produce_xn_cip`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `line_id` int(10) NULL DEFAULT NULL COMMENT '产线ID',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `cip_type` tinyint(1) NULL DEFAULT NULL COMMENT 'cip类型1开机CIP，2停机CIP，3生产阶段性CIP，4改线CIP，5内部CIP，6停产维护性CIP，7季度性/检修后CIP',
  `pre_flush_ro_water_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预冲洗RO用水量',
  `cleaner_name` tinyint(1) NULL DEFAULT NULL COMMENT '清洗剂名称：1柠檬酸，2二氧化氯，3氢氧化钠',
  `cleaning_solution_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液温度',
  `filter_bag_replaced` tinyint(1) NULL DEFAULT NULL COMMENT '滤袋更换情况：1是，0否',
  `pre_flush_ro_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预冲洗RO水温度',
  `cleaner_amount` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗剂用量',
  `flush_ro_water_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冲洗RO水用量',
  `ro_total_water_usage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO水总用量',
  `cleaning_solution_prep_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液配制时间',
  `cleaning_solution_volume` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液配制量',
  `flush_ro_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冲洗RO水温度',
  `citric_acid_test` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '柠檬酸检测',
  `material_staff` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配料操作人员',
  `pre_flush_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预冲洗时间起',
  `pre_flush_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预冲洗时间止',
  `cleaning_solution_temp_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液温度',
  `hot_ro_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO水温度',
  `ceramic_filter_inlet_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '陶瓷过滤器进口压力',
  `ceramic_filter_outlet_pressure` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '陶瓷过滤器出口压力',
  `filler_loop_flow_cleaner` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装回流管路流量-清洗溶液',
  `filler_loop_flow_ro` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装回流管路流量-RO水',
  `ceramic_filter_replaced` tinyint(1) NULL DEFAULT NULL COMMENT '陶瓷过滤器更换：1是，0否',
  `tank_wash_cartridge_action` tinyint(1) NULL DEFAULT NULL COMMENT '洗罐水滤芯清洗：1清洗，2更换',
  `tank_wash_spray_status` tinyint(1) NULL DEFAULT NULL COMMENT '洗罐水喷头检查：1正常，2清洁',
  `cleaning_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '卫生清洁时间起',
  `cleaning_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '卫生清洁时间止',
  `hot_ro_flush_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO冲洗时间起',
  `hot_ro_flush_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO冲洗时间止',
  `peracetic_acid_fumigation_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '过氧乙酸熏蒸时间起',
  `peracetic_acid_fumigation_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '过氧乙酸熏蒸时间止',
  `filler_main_inlet_pressure_cleaner` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装主进管路进口压力-清洗溶液',
  `filler_main_inlet_pressure_ro` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装主进管路进口压力-RO水',
  `ozone_uv_sterilize_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '臭氧/紫外线杀菌时间起',
  `ozone_uv_sterilize_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '臭氧/紫外线杀菌时间止',
  `filter_bag_replaced_two` tinyint(1) NULL DEFAULT NULL COMMENT '滤袋更换：1是，0否',
  `product_heater_drain_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品加热板交循环水排放时间起',
  `product_heater_drain_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品加热板交循环水排放时间止',
  `cleaning_solution_cycle_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液循环时间起',
  `cleaning_solution_cycle_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液循环时间止',
  `hot_ro_cycle_start` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO水循环时间起',
  `hot_ro_cycle_end` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热RO水循环时间止',
  `peracetic_acid_concentration` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '过氧乙酸配置浓度',
  `high_tank_outlet_pressure_cleaner` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '高液位缸出口压力-清洗溶液',
  `high_tank_outlet_pressure_ro` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '高液位缸出口压力-RO水',
  `clean_room_temp` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洁净间温度',
  `clean_room_humidity` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洁净间湿度',
  `pipeline_filter_cleaned` tinyint(1) NULL DEFAULT NULL COMMENT '管道过滤器拆洗：1是，0否',
  `cleaning_solution_ph_after_cycle` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗溶液循环后浓度检测（PH）',
  `ro_water_ph_test` tinyint(1) NULL DEFAULT NULL COMMENT 'RO水PH检测：1是，0否',
  `ro_water_ph_result` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO水PH检测结果',
  `chlorine_dioxide_test` tinyint(1) NULL DEFAULT NULL COMMENT '二氧化氯浓度检测：1是，0否',
  `chlorine_dioxide_result` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二氧化氯浓度检测结果',
  `sampling_time_105` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '105取样口取样时间',
  `sampling_person_105` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '105取样口取样人',
  `unsealed_sample_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '未封口样取样时间',
  `unsealed_sample_person` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '未封口样取样人',
  `sealed_sample_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封口后罐样取样时间',
  `sealed_sample_person` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '封口后罐样取样人',
  `sample_delivery_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样时间',
  `charged_material` tinyint(1) NULL DEFAULT NULL COMMENT '是否进料：1是，0否',
  `charge_material_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进料时间',
  `shutdown_flag` tinyint(1) NULL DEFAULT NULL COMMENT '是否关机：1是，0否',
  `shutdown_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关机时间',
  `filling_operator` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '灌装操作人员',
  `lab_technician_sign` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '化验员签字',
  `process_operation` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序运转情况',
  `status` tinyint(1) NOT NULL COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `class_no`(`class_no`) USING BTREE,
  INDEX `cip_type`(`cip_type`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北cip工序记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_cip_assoc
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_cip_assoc`;
CREATE TABLE `produce_xn_cip_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北cip工序记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_cip_log
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_cip_log`;
CREATE TABLE `produce_xn_cip_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 33 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北cip工序记录日志' ROW_FORMAT = Dynamic;

