  `filter_net_cleaning_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '过滤网清洗时间',
  `detector_check_status` tinyint(1) NULL DEFAULT NULL COMMENT '检测设备验证 1-有 0-无',
  `exception_description` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '异常说明',
