  `ink_code_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '墨码检测仪验证时间2',
  `ink_code_detector_normal_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '墨码检测仪正常击打',
  `ink_code_detector_false_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '墨码检测仪误击打',
  `cap_detector_verification_time_one` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '异盖检测仪验证时间1',
  `cap_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '异盖检测仪验证时间2',
  `cap_detector_normal_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '异盖检测仪正常击打',
  `cap_detector_false_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '异盖检测仪误击打',
  `inverted_can_detector_verification_time_one` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '倒罐检测仪验证时间1',
  `inverted_can_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '倒罐检测仪验证时间2',
  `inverted_can_detector_normal_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '倒罐检测仪正常击打',
  `inverted_can_detector_false_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '倒罐检测仪误击打',
  `internal_pressure_detector_verification_time_one` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内压检测仪验证时间1',
  `internal_pressure_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '内压检测仪验证时间2',
  `internal_pressure_detector_normal_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '内压检测仪正常击打',
  `internal_pressure_detector_false_strike` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '内压检测仪误击打',
  `230ml_can_trial_verification_time_one` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '230ML样罐试机验证时间1',
  `230ml_can_trial_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '230ML样罐试机验证时间2',
  `230ml_can_trial_consumable_change_record` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '230ML样罐试机耗材更换记录',
  `outer_box_code_detector_verification` tinyint(1) NULL DEFAULT NULL COMMENT '外箱码检测仪1有0无',
  `outer_box_code_detector_verification_time_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '外箱码检测仪验证时间1',
  `outer_box_code_detector_verification_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '外箱码检测仪验证时间2',
  `outer_box_code_detector_radiation_alarm_current_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '外箱码检测仪辐射报警仪数据：当前值',
  `outer_box_code_detector_radiation_alarm_accumulated_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '外箱码检测仪辐射报警仪数据：累计值',
  `verification_exception_description` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '验证异常说明',
  `can_management_double_bottom_can` tinyint(1) NULL DEFAULT 1 COMMENT '样罐管理双底盖罐0否1是',
  `can_management_high_pressure_can` tinyint(1) NULL DEFAULT 1 COMMENT '样罐管理高压罐0否1是',
  `can_management_empty_can` tinyint(1) NULL DEFAULT 1 COMMENT '样罐管理空罐0否1是',
  `can_management_230ml_can` tinyint(1) NULL DEFAULT 1 COMMENT '样罐管理230ML罐0否1是',
  `can_management_cap_can` tinyint(1) NULL DEFAULT 1 COMMENT '样罐管理异盖罐0否1是',
  `can_management_inverted_can` tinyint(1) NULL DEFAULT 1 COMMENT '样罐管理倒罐0否1是',
  `can_management_abnormal_ink_code_can` tinyint(1) NULL DEFAULT 1 COMMENT '样罐管理异常墨码罐0否1是',
  `whether_to_replace` tinyint(1) NULL DEFAULT 1 COMMENT '是否更换0否1是',
  `replacement_details` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '是否更换详情',
  `cip_verify` tinyint(1) NULL DEFAULT NULL COMMENT 'cip检查1是0否',
  `outer_box_code_detector_hanzi_verification_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '外箱码检测仪汉字验证时间',
  `outer_box_code_detector_hanzi_verification_result` tinyint(1) NULL DEFAULT 1 COMMENT '外箱码检测仪汉字验证结果1正常0异常',
  `offline_detector_electronic_scale_calibration_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '离线检测仪电子称校准时间',
  `offline_detector_electronic_scale_calibration_result` tinyint(1) NULL DEFAULT 1 COMMENT '离线检测仪电子称校准结果1正常0异常',
  `level_detector_calibration_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '液位检测仪校准时间',
  `level_detector_calibration_result` tinyint(1) NULL DEFAULT 1 COMMENT '液位检测仪校准结果1正常0异常',
  `operation_status` tinyint(1) NULL DEFAULT 1 COMMENT '工序运作状况1正常0不正常',
  `operation_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序运作状况详情',
  `safe_status` tinyint(1) NULL DEFAULT 1 COMMENT '安全状况1合格0不合格',
  `sanitation_status` tinyint(1) NULL DEFAULT 1 COMMENT '卫生状况1合格0不合格',
  `measuring_status` tinyint(1) NULL DEFAULT 1 COMMENT '计量器具1合格0不合格',
  `sample_tank` tinyint(1) NULL DEFAULT 1 COMMENT '样罐1合格0不合格',
  `last_can_expiration_date` date NULL DEFAULT NULL COMMENT '最后一罐保质期',
  `last_can_produce_date` date NULL DEFAULT NULL COMMENT '最后一罐生产日期',
  `last_can_produce_time` time NULL DEFAULT NULL COMMENT '最后一罐生产时间',
  `last_can_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一罐批次',
  `last_box_expiration_date` date NULL DEFAULT NULL COMMENT '最后一箱保质期',
  `last_box_produce_date` date NULL DEFAULT NULL COMMENT '最后一箱生产日期',
  `last_box_status` tinyint(1) NULL DEFAULT 1 COMMENT '最后一箱1合格0不合格',
  `last_box_batch_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱批号',
  `last_box_batch_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '最后一箱序列号',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `signature_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字3待复核人签字4待主管签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接班签字',
  `signatory_three` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核人签字',
  `signatory_four` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '主管签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 559 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北基地打码工序' ROW_FORMAT = DYNAMIC;

