  PRIMARY KEY (`id`) USING BTREE,
  INDEX `coding_id`(`coding_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1031 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北基地打码工序冷却系统检查项目' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_coding_log
