  `ink_code_adhesion` tinyint(1) NULL DEFAULT NULL COMMENT '墨码附着力1合格0不合格',
  `operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '复核人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
