  PRIMARY KEY (`id`) USING BTREE,
  INDEX `coding_id`(`coding_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1337 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北基地打码工序记录' ROW_FORMAT = Dynamic;

