  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '订单号',
  `all_num` int(10) NULL DEFAULT 0 COMMENT '总数量',
  `common_num` int(10) NULL DEFAULT NULL COMMENT '普通型',
  `intensify_num` int(10) NULL DEFAULT NULL COMMENT '强化型',
  `date` date NULL DEFAULT NULL COMMENT '日期',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：未释放；1：部分释放；2：已完成；',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
