  `is_see` tinyint(1) NULL DEFAULT NULL COMMENT '是否见别线',
  `see_line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '见线别',
