  `inspection_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查时间2',
  `ro_ceramic_filter_inlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器进口1',
  `ro_ceramic_filter_inlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器进口2',
  `ro_ceramic_filter_outlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器出口1',
  `ro_ceramic_filter_outlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'RO陶瓷过滤器出口2',
  `bag_filter_inlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器进口1',
  `bag_filter_inlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器进口2',
  `bag_filter_outlet_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器出口1',
  `bag_filter_outlet_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '袋式过滤器出口2',
