DROP TABLE IF EXISTS `produce_xn_shift_alert`;
CREATE TABLE `produce_xn_shift_alert`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '湖北生产作业记录ID',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北生产作业记录-弹窗控制' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_shift_assoc
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_shift_assoc`;
CREATE TABLE `produce_xn_shift_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '湖北生产作业记录id',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 256 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北生产作业记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_shift_log
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_shift_log`;
CREATE TABLE `produce_xn_shift_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '湖北生产作业记录ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 627 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北生产作业记录日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_shift_shutdown
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_shift_shutdown`;
CREATE TABLE `produce_xn_shift_shutdown`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '湖北生产作业记录ID',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '停机类型 1-设备 2-原材料 3-人为 4-其他',
  `eq_id` int(10) NULL DEFAULT NULL COMMENT '故障设备id',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障设备名称',
  `fault_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障类型',
  `shutdown_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '停机时间',
  `goods_id` int(10) NULL DEFAULT NULL COMMENT '故障物料id',
  `title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障物料名称',
  `fault_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '故障描述',
  `repair_uid` int(10) NULL DEFAULT NULL COMMENT '当班维修人员id',
  `repair_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班维修人员',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 373 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北生产作业记录-停机记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_shift_time_lapse
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_shift_time_lapse`;
CREATE TABLE `produce_xn_shift_time_lapse`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '1设备运行情况误时,2\r\n作业方法误时,3原材料情况误时',
  `lapse_type` tinyint(1) NULL DEFAULT NULL COMMENT '误时类型1设备误时；2原材料误时；3运维误时；4人员误时；5工艺误时；6其他误时',
  `time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时间',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原因',
  `lapse` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '误时',
  `canning_lapse` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装停机误时',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_in_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 161 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '福建：生产作业记录误时记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_stacking
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_stacking`;
CREATE TABLE `produce_xn_stacking`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `order_number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '订单号',
  `produce_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品批号',
  `line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产线',
  `cate` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型',
  `sku` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品类型编码',
  `goods_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '产品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品物料编码',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `produce_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `on_time` time NULL DEFAULT NULL COMMENT '开机时间',
  `off_time` time NULL DEFAULT NULL COMMENT '关机时间',
  `specification` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '包装规格',
  `first_box_expiration_date` date NULL DEFAULT NULL COMMENT '第一箱保质期',
  `first_box_status` tinyint(1) NULL DEFAULT 1 COMMENT '第一箱1合格0不合格',
  `first_box_produce_date` date NULL DEFAULT NULL COMMENT '第一箱生产日期',
  `first_box_batch_one` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '第一箱批号',
  `first_box_batch_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '第一箱序列号',
  `verify_record` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '本班验证记录',
  `verify_result` tinyint(1) NULL DEFAULT 1 COMMENT '本班验证结论1合格0不合格',
  `verify_detail` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '本班验证结论详情',
  `tape_supplier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '胶带供应商',
  `tape_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '胶带供应商其他',
  `tape_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '胶带批次',
  `last_surplus` int(11) NULL DEFAULT NULL COMMENT '上班结存量',
  `get` int(11) NULL DEFAULT NULL COMMENT '本班领用',
  `in_use` int(11) NULL DEFAULT NULL COMMENT '本班使用',
  `surplus` int(11) NULL DEFAULT NULL COMMENT '本班结存',
  `unqualified` int(11) NULL DEFAULT NULL COMMENT '不合格品数量',
  `breakdown_status` tinyint(1) NULL DEFAULT NULL COMMENT '设备运转情况1正常2调整参数3调整机械部分4故障5其他',
  `breakdown_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备运转情况详情',
  `tool_status` tinyint(1) NULL DEFAULT 1 COMMENT '工具1正常0异常',
  `sanitation_status` tinyint(1) NULL DEFAULT 1 COMMENT '卫生状况1合格0不合格',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
