  `supplier_line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制罐产线',
  `check_time` time NULL DEFAULT NULL COMMENT '抽检时间',
  `up_time` time NULL DEFAULT NULL COMMENT '上机时间',
  `operator` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '操作工',
  `attachment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '附件',
  `batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `box` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '箱号',
  `use_num` int(11) NULL DEFAULT NULL COMMENT '使用数量',
  `down_num` int(11) NULL DEFAULT NULL COMMENT '下机数量',
  `move_id` int(11) NULL DEFAULT NULL COMMENT '库存id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `ph_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内部批次',
  `original_ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `factory_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `unpack_id`(`unpack_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 757 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北拆包工序拆包记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for produce_xn_water
-- ----------------------------
DROP TABLE IF EXISTS `produce_xn_water`;
CREATE TABLE `produce_xn_water`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `produce_date` date NOT NULL COMMENT '生产日期',
  `class_type` tinyint(1) NOT NULL COMMENT '班组 (1A、2B、3C)',
  `class_no` tinyint(1) NOT NULL COMMENT '班次 1早 2中 3夜',
  `ro_type` tinyint(1) NOT NULL COMMENT '班次 1A 2B 3C',
  `status` tinyint(1) NOT NULL COMMENT '单据状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `signature_status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '签字状态1待当班签字2待接班签字',
  `signatory_one` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '当班签字',
  `signatory_two` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '交班签字',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `orig_water_meter_reading` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原水表数（m³）',
  `orig_water_volume` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原水水量（m³）',
  `boiler_water_meter_reading` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '锅炉用水表数（m³）',
  `naoh_conc` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'NaOH浓度（%）',
  `scale_inhibitor_conc` decimal(5, 2) NULL DEFAULT NULL COMMENT '阻垢剂浓度（%）',
  `workshop_water_meter_num` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间用水水表数（m³）',
  `workshop_ro_water_consumption` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间用RO水量（m³）',
  `boiler_ro_water_output` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '锅炉RO水量（m³）',
  `energy_recov_water_output` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '热能回收水量（m³）',
  `valve_status` tinyint(1) NULL DEFAULT NULL COMMENT '产水气动阀状态;1：正常；2：异常',
  `valve_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产水气动阀时间',
  `clean_status` tinyint(1) NULL DEFAULT NULL COMMENT '罐体及管路是否清洁状态;1：正常；2：异常',
  `uv_status` tinyint(1) NULL DEFAULT NULL COMMENT 'UV杀菌机状态;1：正常；2：异常',
  `raw_water_chroma` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原水色度',
  `raw_water_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原水时间',
  `colorimeter_is_calibrated` tinyint(1) NULL DEFAULT NULL COMMENT '色度仪是否校准 0-否 1-是',
  `raw_water_odor` tinyint(1) NULL DEFAULT NULL COMMENT '原水气味是否正常 1-正常 2-异常',
  `heat` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '热能回收',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `inlet_num` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '膜组进水表数',
  `inlet_quantity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '膜组进水表量',
  `create_num` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '膜组产水表数',
  `create_quantity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '膜组产水量',
  `recycle_num` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '膜组回收水表数',
  `recycle_quantity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '膜组回收水量',
  `water_rate` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产水率',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北基地制水工序' ROW_FORMAT = Dynamic;

