  `expiration_date` date NULL DEFAULT NULL COMMENT '保质期至',
  `canning_flipping_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '灌装翻转器卫生1正常0异常',
  `detector_check_status` tinyint(1) NULL DEFAULT NULL COMMENT '检测设备验证 1-有 0-无',
  `detector_check_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '检测仪验证确认时间',
  `pressure_diff_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '压差值',
  `cooler_ph_value` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '冷却机PH值',
  `avg_liquid_level` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '平均液位',
  `lid_weight` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '罐盖重量',
  `storage_appearance_status` tinyint(1) NULL DEFAULT NULL COMMENT '入库外观1正常0异常',
  `aluminum_shavings_status` tinyint(1) NULL DEFAULT NULL COMMENT '接班封口机铝屑情况1正常0异常',
  `unpack_flipping_status` tinyint(1) NULL DEFAULT NULL COMMENT '拆包翻转器卫生1正常0异常',
  `line_sample_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产线样罐确认时间',
  `line_sample_time_two` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产线样罐确认时间2',
  `line_sample_status` tinyint(1) NULL DEFAULT NULL COMMENT '产线样罐确认情况1正常0异常',
  `line_sample_status_two` tinyint(1) NULL DEFAULT NULL COMMENT '产线样罐确认情况21正常0异常',
  `weighing_upper_limit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整箱称重仪上限',
  `weighing_lower_limit` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整箱称重仪下限',
  `sanitation_status` tinyint(1) NULL DEFAULT NULL COMMENT '卫生/纪律执行情况1正常0异常',
  `check_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '验证列表',
  `operation_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '工序运作状况详情',
  `can_supplier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '空罐供应商',
  `can_supplier_line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '空罐供应商产线',
  `can_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '空罐供应商其他',
  `top_cap_supplier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '顶盖供应商',
  `top_cap_supplier_line` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '顶盖供应商产线',
  `top_cap_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '顶盖供应商其他',
  `film_supplier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '热缩膜供应商',
  `film_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '热缩膜供应商其他',
  `carton_supplier` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '纸皮供应商',
  `carton_supplier_other` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '纸皮供应商其他',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '检测设备验证',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `order_number`(`order_number`) USING BTREE,
  INDEX `produce_batch`(`produce_batch`) USING BTREE,
  INDEX `produce_date`(`produce_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 427 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '湖北巡检工作记录' ROW_FORMAT = Dynamic;

