-- ----------------------------
-- Table structure for qlty_amm‌_ledger
-- ----------------------------
DROP TABLE IF EXISTS `qlty_amm‌_ledger`;
CREATE TABLE `qlty_amm‌_ledger`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '公司编号',
  `eq_id` int(11) NULL DEFAULT NULL COMMENT '固资ID',
