  `eq_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资产名称',
  `production_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产厂商名称',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `factory_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出厂编号',
  `save_addr` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '使用位置ID',
  `accuracy` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准确度',
  `accuracy_unit` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '准确度-单位',
  `mileage` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '里程',
  `mileage_unit` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '里程-单位',
  `type_id` int(11) NULL DEFAULT NULL COMMENT '类型ID',
  `type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类型名称',
  `metering_type` tinyint(1) NULL DEFAULT NULL COMMENT '计量类别 1 工艺计量器 2 质量计量器 3 经营计量器 4 能源计量器',
  `open_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '启用日期',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '使用情况 0 备用 1 在用 2 停用 3 报废 4 外检中 5 维修中 6 内校中',
  `calibration_cycle` int(11) NULL DEFAULT NULL COMMENT '校准周期',
  `calibration_cycle_unit` tinyint(1) NULL DEFAULT 1 COMMENT '校准周期单位 1 月 2 年',
  `verification_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检定日期',
  `next_verification_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下次检定日期',
  `remind_time` datetime NULL DEFAULT NULL COMMENT '提醒时间',
  `check_id` int(11) NULL DEFAULT NULL COMMENT '检定单位-外检机构ID',
  `check_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检定单位-外检机构',
  `check_type` tinyint(1) NULL DEFAULT NULL COMMENT '证书类型 1 检定 2 校准',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `fee` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '总费用',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `next_verification_date`(`next_verification_date`) USING BTREE,
  INDEX `save_addr_id`(`save_addr`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `type_name`(`type_name`) USING BTREE,
  INDEX `eq_name`(`eq_name`) USING BTREE,
  INDEX `remind_time`(`remind_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 99 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '计量台账' ROW_FORMAT = Dynamic;

