-- ----------------------------
-- Table structure for qlty_anomaly_disposal
-- ----------------------------
DROP TABLE IF EXISTS `qlty_anomaly_disposal`;
CREATE TABLE `qlty_anomaly_disposal`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `p_id` int(11) NULL DEFAULT NULL COMMENT '单据ID 0 = 自主发起',
  `re_type` int(11) NULL DEFAULT NULL COMMENT '单据类型',
  `step` tinyint(1) NULL DEFAULT NULL COMMENT '处置节点 1 仓库巡检 2 化验室检测 3 生产领用',
  `name_id` int(11) NULL DEFAULT NULL COMMENT '异常原料名称ID',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常原料名称',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '异常原料类型 1 包材 2 内容物 3 生产领用',
  `check_date` date NULL DEFAULT NULL COMMENT '发起日期',
  `class` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次',
  `group_id` int(11) NULL DEFAULT NULL COMMENT '班组ID',
  `group_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组名称',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '生产产线ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产产线名称',
  `num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '异常处置数量,明细的隔离数+让步数+退库数汇总',
  `unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成签名',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '处置进度 0 隔离中 1 已完成 2 暂存',
  `gl_history_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '隔离数量副本',
  `gl_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '隔离数量,明细隔离数量汇总',
  `gl_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隔离单位',
  `rb_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '让步数量,明细让步数量汇总',
  `rb_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '让步单位',
  `tk_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '退库数量,明细退库数量汇总',
  `tk_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退库单位',
  `d_type` tinyint(1) NULL DEFAULT NULL COMMENT '处置方式 1 隔离 2 让步 3 退库',
  `r_uids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息接收人ID,多个用逗号隔开',
  `r_names` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息接收人,多个用逗号隔开',
  `anomaly_pid` int(11) NULL DEFAULT NULL COMMENT '不良大类ID',
  `anomaly_pname` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '不良大类名称',
  `anomaly_id` int(11) NULL DEFAULT NULL COMMENT '不良类型ID',
  `anomaly_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '不良类型',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处置原因',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `p_id`(`re_type`, `p_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 387 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料质量异常处置' ROW_FORMAT = Dynamic;

