) ENGINE = InnoDB AUTO_INCREMENT = 118 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料质量异常处置-复检不合格信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_anomaly_disposal‌_stock
-- ----------------------------
DROP TABLE IF EXISTS `qlty_anomaly_disposal‌_stock`;
