-- ----------------------------
-- Table structure for qlty_anomaly_disposal_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_anomaly_disposal_log`;
CREATE TABLE `qlty_anomaly_disposal_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `assoc_id` int(11) NOT NULL COMMENT '单据ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '日志类型 0 操作类型 1 审批类型',
  `act` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `act_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `content` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日志信息',
