  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '罐后端尺寸检测仪校准' ROW_FORMAT = Dynamic;

