-- ----------------------------
-- Table structure for qlty_cap_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_cap_order`;
CREATE TABLE `qlty_cap_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sp_id` int(11) NULL DEFAULT NULL COMMENT '拆单父级ID',
  `sp_order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原单据编号',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `supplier_id` int(11) NOT NULL COMMENT '厂商id',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `sup_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `batch_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产批号',
  `pack_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '包号',
  `check_date` date NOT NULL COMMENT '检测日期',
  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `check_ret` tinyint(1) NULL DEFAULT 3 COMMENT '检验结果 0 不及格 1及格',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员签字',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检测员ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名称',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间ID 1 = 一车间 2 = 二车间 3 = 三车间',
  `workshop` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名称',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别ID 1 = 1线，2 = 2线...',
  `line_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别名称',
  `recheck` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员复核信息',
  `status` tinyint(1) NOT NULL COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `adhesion` tinyint(1) NULL DEFAULT 1 COMMENT '防伪附着力检测（普通型） 0 不及格 1及格',
  `code_ret` tinyint(1) NULL DEFAULT NULL COMMENT '二维码检测结果（强化型） 0 不及格 1及格',
  `bule_ret` tinyint(1) NULL DEFAULT 1 COMMENT '蓝点检测结果（强化型） 0 不及格 1及格',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成通知单 0 否 1 是 2 部分生成',
  `version` tinyint(1) NULL DEFAULT NULL COMMENT '顶盖版本 1 促销版 2 非促销',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '版本ID',
  `version_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本名称',
  `goods_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料条码',
  `sample_num` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样数量',
  `sample_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样单位',
  `source_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检来源单号',
  `execp_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常处理单号',
  `is_split` tinyint(1) NULL DEFAULT 0 COMMENT '单据类型0 原单据 1 拆分单据',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `recheck_status`(`recheck_status`) USING BTREE,
  INDEX `source_no`(`source_no`) USING BTREE,
  INDEX `execp_no`(`execp_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 169 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '顶盖/底盖检验报告单' ROW_FORMAT = Dynamic;

