  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`oid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'CIP检测报告文件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_cipmicrobe_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_cipmicrobe_order`;
CREATE TABLE `qlty_cipmicrobe_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `clean_folw` tinyint(1) NULL DEFAULT NULL COMMENT 'CIP类型 1 开机清洗 2 停机清洗 3 连续生产阶段维护性CIP清洗 4 停机期间维护性CIP清洗 5 季度维护性清洗 6 换型改线CIP清洗',
  `clean_microbe` tinyint(1) NULL DEFAULT NULL COMMENT '清洗杀菌 1 无水柠檬菌 2 二氧化氯 3 氢氧化钠',
  `test_type` tinyint(1) NULL DEFAULT NULL COMMENT '测试类型 1 试水 2 试红牛-普通 3 试红牛-强化 4 试战马-灌装',
  `test_type_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '测试类型名称',
  `check_date` date NOT NULL COMMENT '检测日期',
  `make_date` date NOT NULL COMMENT '生产日期',
  `line_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线别ID,多个用逗号隔开',
  `line_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线别名称，多个用逗号隔开',
  `class` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班别 A-I',
  `sample_temperature` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取样温度',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员1签字',
  `check_sign2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员2签字',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不合格 1合格 2 部分合格',
  `report_user_id` int(11) NULL DEFAULT NULL COMMENT '报告人/提交人ID',
  `report_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人/提交人名称',
  `report_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人/提交人签字',
  `batching_cylinder` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配料缸值',
  `bottling_cip_before_end` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '灌装CIP循环结束后值',
  `six_ro_water_ph` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '6吨热RO水pH值',
  `nine_ro_water_ph` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '9吨热RO水pH值',
  `recheck` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员复核信息',
  `status` tinyint(1) NOT NULL COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `count_date1` date NULL DEFAULT NULL COMMENT '统计时间1',
  `count_date2` date NULL DEFAULT NULL COMMENT '统计时间2',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `clean_pro` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗流程',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'CIP微生物检验单据' ROW_FORMAT = Dynamic;

-- ----------------------------
