  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `time`(`oid`, `time`, `sample_no`) USING BTREE,
  INDEX `oid`(`oid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 749 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'CIP微生物检验信息' ROW_FORMAT = Dynamic;

