-- Table structure for qlty_clean_room_suspended_particle_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_clean_room_suspended_particle_order`;
CREATE TABLE `qlty_clean_room_suspended_particle_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `check_date` date NOT NULL COMMENT '监测日期',
