  `sample_pro_type` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采样项目 1 空罐 2 顶盖 3 灌装阀1 4 封口机 5 下盖槽 6止盖刀 7 注氮头 8 进罐护板 9 T型链道 10 培养基专用框 11 无菌台 12 专用毛巾 13 三联支架 14 漏斗 15 专用托盘 16CT 17  罐装阀2',
  `sanple_source` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采样来源',
  `sup_id` int(11) NULL DEFAULT NULL COMMENT '厂家ID',
  `sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂家名称',
  `batch_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `pro_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '状态 1 清洗前 2 清洗后',
  `microbe_coliform_bacteria` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '大肠菌群',
  `microbe_bacterial` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '细菌总数',
  `microbe_bacterial2` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '菌落总数2',
  `microbe_bacterial_avg` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '菌落总数平均值',
  `microbe_saccharomyces` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '酵母菌',
  `microbe_mold` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '霉菌',
  `check_ret` tinyint(2) NULL DEFAULT NULL COMMENT '检测结果；0：不合格；1：合格',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 80 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '接触面涂抹实验信息明细' ROW_FORMAT = Dynamic;

