  `weight` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重量留样',
  `make_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `sample_date` date NULL DEFAULT NULL COMMENT '留样日期',
  `sample_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取样签名',
  `weight_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称量人签名',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核人签名',
  `pg_check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品管复核人签名',
  `check_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核备注',
  `empty_weight` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐重量',
  `total_weight` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总重量',
  `recheck_weight` decimal(8, 2) NULL DEFAULT NULL COMMENT '复核重量',
  `status` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '状态；0：未复核；1：已复核；',
  `is_destroy` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '销毁状态；0：未销毁；1：已销毁；',
  `destory_date` date NULL DEFAULT NULL COMMENT '销毁时间',
  `destory_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销毁备注',
  `destory_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销毁签名',
  `ware_id` int(11) NULL DEFAULT NULL COMMENT '出库仓库ID',
  `ware_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出库仓库名称',
  `source` tinyint(1) NULL DEFAULT NULL COMMENT '留样来源 1 VB12称重 2 内容物外检申请 3 生产送样',
  `sample_source_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '留样来源单号',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_destroy`(`is_destroy`) USING BTREE,
  INDEX `sample_date`(`sample_date`) USING BTREE,
  INDEX `mill_id`(`mill_id`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE,
  INDEX `brand`(`brand`, `content`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 324 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '内容物留样记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_cuvette_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_cuvette_order`;
CREATE TABLE `qlty_cuvette_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `clean_date` date NOT NULL COMMENT '清洗日期',
  `clean_uv` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗UV机台',
  `clean_user_id` int(11) NULL DEFAULT NULL COMMENT '清洗人',
  `clean_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清洗人名称',
  `confirm_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认签名',
  `status` tinyint(1) NOT NULL COMMENT '单据状态 0 未确认 1 已确认',
  `confirm_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `clean_date`(`clean_date`) USING BTREE,
  INDEX `clean_user_id`(`clean_user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '比色皿清洗记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_default_val_code
-- ----------------------------
DROP TABLE IF EXISTS `qlty_default_val_code`;
CREATE TABLE `qlty_default_val_code`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `brand` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1 红牛 ND2 战马',
  `film` tinyint(5) NOT NULL COMMENT '类型 1 普通版 2 强化版 3 PE彩膜',
  `good_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料条码',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `brand`(`brand`, `film`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准值-热缩膜物料条码管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_default_val_version
-- ----------------------------
DROP TABLE IF EXISTS `qlty_default_val_version`;
CREATE TABLE `qlty_default_val_version`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `sku` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1普通型 ND1-2 强化型 ND2-1 战马罐装',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '版本ID',
  `name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本名称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `sku`(`sku`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标准值-纸皮版本管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_default_value
-- ----------------------------
DROP TABLE IF EXISTS `qlty_default_value`;
CREATE TABLE `qlty_default_value`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `item` int(11) NOT NULL COMMENT '类型 1、空罐卷封检验报告 2、内涂模检验报告 3、顶盖/底盖检验报告 4、热缩膜检验报告 5、纸皮进货验报告 6、原料标签标识报告 7、空罐进货检验报告 8、战马空罐检验报告 9、原材料使用通知单',
  `brand` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `sku` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `workshop` tinyint(1) NULL DEFAULT NULL COMMENT '车间/物料编码ID',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别id',
  `base_id` tinyint(11) NULL DEFAULT 0 COMMENT '基地ID',
  `other_id` int(11) NULL DEFAULT NULL COMMENT '其他ID',
  `pro` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目名称',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '名称',
  `en` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '别名',
  `key` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '对应字段名称',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `status` tinyint(1) NOT NULL COMMENT '状态 0 禁用 1启用',
  `sort` int(11) NULL DEFAULT 0 COMMENT '排序值',
  `type` tinyint(1) NOT NULL COMMENT '判断类型 0 =>区间, 1 => 大于,2 => 大于等于, 3 => 小于,4 => 小于等于, 5 => 等于,6 合格/不合格 7 文本 8 ±',
  `lower_limit_val` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下限值',
  `upper_limit_val` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上限值',
  `error_limit_val` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '允许误差',
  `value` tinyint(1) NULL DEFAULT 0 COMMENT '具体值，0 = 否 1 = 是',
  `default_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '具体默认值',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '用户ID',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `key`(`item`, `sku`, `key`, `workshop`, `pro`, `supplier_id`, `line_id`) USING BTREE,
  INDEX `item`(`item`, `sku`) USING BTREE,
  INDEX `base_id`(`base_id`) USING BTREE,
  INDEX `other_id`(`other_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2891 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '质量管理标准值配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_driver_push_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_driver_push_log`;
CREATE TABLE `qlty_driver_push_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NULL DEFAULT NULL COMMENT '单据id',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '单据类型；1、理化及微生物指标检验报告；2、顶盖/底盖检测报告；3、空罐卷封质量检测报告；4、空罐卷封质量检测报告；5、内涂膜检验报告；6、纸皮进货检验报告；7、战马空罐质量检验报告',
  `select_id` int(11) NULL DEFAULT NULL COMMENT '选择的设备id',
  `log_type_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集分类名称',
  `json_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '采集json内容',
  `table_column_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '表头json内容',
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 376 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '品质采集记录日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_ecw_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_ecw_order`;
CREATE TABLE `qlty_ecw_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `supplier_id` int(11) NOT NULL COMMENT '供应商ID',
  `supplier_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商名称',
  `cap_supplier_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖供应商,多个用逗号隔开',
  `cap_supplier_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖供应商',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '空罐线别ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐线别名称',
  `check_date` date NOT NULL COMMENT '检测日期',
  `max_weight` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '最大重量',
  `min_weight` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '最小重量',
  `diff_weight` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '差值重量',
  `avg_weight` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '平均值重量',
  `weight` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '称重数据',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '10个空罐+顶盖重量检测单据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_ecw_order_file
-- ----------------------------
DROP TABLE IF EXISTS `qlty_ecw_order_file`;
CREATE TABLE `qlty_ecw_order_file`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `oid` int(11) NOT NULL COMMENT '单据ID',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件链接',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `download_num` int(11) NULL DEFAULT 0 COMMENT '下载次数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '上传者',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`oid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '10个空罐+顶盖重量检测单文件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_empty_can_photo_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_empty_can_photo_order`;
CREATE TABLE `qlty_empty_can_photo_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `line_id` int(11) NOT NULL COMMENT '线别id',
  `check_date` date NOT NULL COMMENT '检测日期',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果；0：不合格；1：合格',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检测员uid',
  `check_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `reviewer_date` datetime NULL DEFAULT NULL COMMENT '复核日期',
  `reviewer_uid` int(11) NULL DEFAULT NULL COMMENT '复核人uid',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值配置',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_res`(`check_res`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '空罐照相设备验证表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_empty_can_photo_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_empty_can_photo_order_assoc`;
CREATE TABLE `qlty_empty_can_photo_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '标签标识检验报告单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '空罐照相设备验证表记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_empty_can_photo_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_empty_can_photo_order_detail`;
CREATE TABLE `qlty_empty_can_photo_order_detail`  (
