  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '确认人ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人名称',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认签字',
  `cancel_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取消签字',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态 0 待确认 1 已确认',
  `top_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖图片地址',
  `can_body_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '罐身图片地址',
  `bottom_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '底盖图片地址',
  `paper_id` int(11) NULL DEFAULT NULL COMMENT '标签标识ID',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '通知单是否已生成 0 否 1是 2 部分生成',
  `is_send` tinyint(1) NULL DEFAULT 0 COMMENT '总报告是否已生成 0 否 1 是 2 部分生成',
  `sample_num` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样数量',
  `sample_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样单位',
  `source_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检来源单号',
  `dept_id` int(11) NULL DEFAULT 0 COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
