  INDEX `status`(`status`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `check_ret`(`check_ret`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 380 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '空罐卷封检验报告单' ROW_FORMAT = Dynamic;

