-- ----------------------------
-- Table structure for qlty_empty_quality_order_check_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_empty_quality_order_check_detail`;
CREATE TABLE `qlty_empty_quality_order_check_detail`  (
