-- Table structure for qlty_empty_quality_order_check_inner_item
-- ----------------------------
DROP TABLE IF EXISTS `qlty_empty_quality_order_check_inner_item`;
CREATE TABLE `qlty_empty_quality_order_check_inner_item`  (
