  `detail_id` int(10) UNSIGNED NOT NULL COMMENT '空罐质量检验报告检验明细ID',
  `batch_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批号',
  `pro_package_number` int(11) NULL DEFAULT NULL COMMENT '生产包号',
  `sample_no` int(10) NULL DEFAULT NULL COMMENT '样品编号',
  `actual_value` decimal(18, 1) NULL DEFAULT NULL COMMENT '实测值',
  `use_id` int(11) NULL DEFAULT NULL COMMENT '通知单使用ID',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '是否使用;0：未使用；1：已使用',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `batch_no`(`batch_no`, `pro_package_number`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `detail_id`(`detail_id`) USING BTREE,
  INDEX `is_use`(`is_use`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 529 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '内涂膜实测值录入明细' ROW_FORMAT = Dynamic;

