-- ----------------------------
-- Table structure for qlty_essence_entering_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_essence_entering_order`;
CREATE TABLE `qlty_essence_entering_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `supplier_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `supplier_id` int(11) NOT NULL COMMENT '厂商id',
  `sup_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产批次',
  `pro_date` date NOT NULL COMMENT '生产日期',
  `check_date` date NOT NULL COMMENT '检测日期',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `recheck_id` int(11) NULL DEFAULT NULL COMMENT '复检ID',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果；0：不合格；1：合格',
  `sampling_uid` int(11) NULL DEFAULT NULL COMMENT '取样人uid',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检测员uid',
  `check_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `destroy_status` tinyint(1) NULL DEFAULT 0 COMMENT '销毁状态；0：未销毁；1：已销毁',
  `destroy_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '销毁人签名图片',
  `destory_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '销毁备注',
  `destory_uid` int(11) NULL DEFAULT NULL COMMENT '销毁人uid',
  `destroy_date` date NULL DEFAULT NULL COMMENT '销毁日期',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `reviewer_date` datetime NULL DEFAULT NULL COMMENT '复核日期',
  `reviewer_uid` int(11) NULL DEFAULT NULL COMMENT '复核人uid',
  `sample_weight` decimal(9, 2) NULL DEFAULT NULL COMMENT '留样重量',
  `sample_date` date NULL DEFAULT NULL COMMENT '留样时间',
  `sample_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '留样人签名',
  `weight_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称重人签名',
  `sample_re_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '留样复核人签名',
  `goods_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料条码',
  `get_num` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '到货数量',
  `get_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '到货单位',
  `ph_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内部批次',
  `sample_num` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样数量',
  `sample_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样单位',
  `source_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检来源单号',
  `execp_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常处置单号',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值配置',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `is_year_check` tinyint(1) NULL DEFAULT 0 COMMENT '是否年检 0 否 1是',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_res`(`check_res`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 171 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '香精入厂检测记录' ROW_FORMAT = Dynamic;

