  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 262 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '香精入厂检测记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_essence_entering_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_essence_entering_order_detail`;
CREATE TABLE `qlty_essence_entering_order_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '报告单ID',
  `brix_val` decimal(18, 2) NULL DEFAULT NULL COMMENT '外观及理化检测信息-Brix实测值；',
  `color_val` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外观及理化检测信息-色度是否合格 0 不合格 1合格；',
  `density_val` decimal(18, 4) NULL DEFAULT NULL COMMENT '外观及理化检测信息-密度实测值；',
  `appearance_val` tinyint(1) NULL DEFAULT NULL COMMENT '外观及理化检测信息-外观是否合格 0 不合格 1 合格；',
  `arsenic_val` int(11) NULL DEFAULT NULL COMMENT '感官及重金属检测信息-砷实测值；',
  `lead_val` int(11) NULL DEFAULT NULL COMMENT '感官及重金属检测信息-铅实测值；',
  `taste_val` tinyint(1) NULL DEFAULT NULL COMMENT '感官及重金属检测信息-口感是否合格 0 不合格 1 合格',
  `aroma_val` tinyint(1) NULL DEFAULT NULL COMMENT '感官及重金属检测信息-香气是否合格 0 不合格 1 合格',
  `check_time` datetime NULL DEFAULT NULL COMMENT '年检时间',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '年检人',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年检人',
  `check_user_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '年检签名',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '外观及理化检测信息 是否合格 0 不合格 1 合格',
  `recheck_id` int(11) NULL DEFAULT NULL COMMENT '复检ID',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '年复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `year_check_res` tinyint(1) NULL DEFAULT NULL COMMENT '年检是否合格 0 不合格 1 合格',
  `year_recheck_id` int(11) NULL DEFAULT NULL COMMENT '年复检ID',
  `year_recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '年复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '香精入厂检测记录检验信息明细' ROW_FORMAT = DYNAMIC;

