-- ----------------------------
-- Table structure for qlty_gd_water_quality_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_gd_water_quality_order`;
CREATE TABLE `qlty_gd_water_quality_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `source` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '样品来源 1 制水车间 2 一车间 3 二车间 4 三车间 4 井水',
  `group` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '组别',
  `sample_date` date NULL DEFAULT NULL COMMENT '取样日期',
  `sample_user_id` int(11) NULL DEFAULT NULL COMMENT '取样人ID',
  `sample_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取样人名称',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检测人ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测人名称',
  `check_date` date NULL DEFAULT NULL COMMENT '检测日期',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检测结果 null 检验中 0 不合格 1合格',
  `water_quality_type` tinyint(1) NULL DEFAULT NULL COMMENT '水质类型 1 原水 2 RO水',
  `report_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人签字',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `check_user_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员1签字',
  `check_user_sign2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员2签字',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测信息备注',
  `check_conclusion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测结论',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `ct_time` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'CT时间',
  `ct_ret` tinyint(1) NULL DEFAULT NULL COMMENT 'CT检测结果 0 不合格 1 合格',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `source`(`source`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '广东水质检测单据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_gd_water_quality_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_gd_water_quality_order_assoc`;
CREATE TABLE `qlty_gd_water_quality_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '检验报告单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '广东水质检测关联单据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_gd_water_quality_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_gd_water_quality_order_detail`;
CREATE TABLE `qlty_gd_water_quality_order_detail`  (
