  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '广东水质检测单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_gd_water_quality_point_set
-- ----------------------------
DROP TABLE IF EXISTS `qlty_gd_water_quality_point_set`;
CREATE TABLE `qlty_gd_water_quality_point_set`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
