  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `film` tinyint(5) NOT NULL COMMENT '类型 1 普通版 2 强化版 3 PE彩膜',
