  `num` decimal(9, 3) NOT NULL DEFAULT 0.000 COMMENT '到货数量',
  `unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '到货单位',
  `workshop` tinyint(1) NOT NULL DEFAULT 0 COMMENT '使用车间',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检测员ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名称',
  `check_ret` tinyint(1) NULL DEFAULT 3 COMMENT '检验结果 0 不合格 1合格 2 部分合格 3 检验中',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员签字',
