-- ----------------------------
-- Table structure for qlty_ilm_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_ilm_order`;
CREATE TABLE `qlty_ilm_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `type` tinyint(1) NULL DEFAULT 1 COMMENT '检测品类 1 红牛 2 战马 3 速溶咖啡粉',
  `check_date` date NOT NULL COMMENT '检验日期',
  `ct_time` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'CT时间',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检测员ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名称',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不合格 1合格 2 部分合格',
  `report_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人签字',
  `method` tinyint(1) NULL DEFAULT NULL COMMENT '试管发酵法 1 MPN法 2 国标平板法',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_ret`(`check_ret`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 65 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '国际微生物检测记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_ilm_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_ilm_order_assoc`;
CREATE TABLE `qlty_ilm_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '检验报告单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
