) ENGINE = InnoDB AUTO_INCREMENT = 87 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '国际微生物检验报告检验信息明细' ROW_FORMAT = Dynamic;

