-- ----------------------------
-- Table structure for qlty_incubator_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_incubator_order`;
CREATE TABLE `qlty_incubator_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `type` tinyint(1) NOT NULL COMMENT '培养种类 1 成品 2 其他 3 环境检测 4 CIP样品 5 水质 6 实验样品',
  `report_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次/报告编号',
  `temperature` decimal(9, 2) NULL DEFAULT NULL COMMENT '环境条件-室度',
  `use_date` date NOT NULL COMMENT '使用日期',
  `humidity` decimal(9, 2) NOT NULL COMMENT '环境条件-湿度',
  `check_user_id` int(11) NOT NULL COMMENT '检测人ID',
  `check_user_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测人',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间ID',
  `workshop` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名称',
  `end_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理论结束培养时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '-1 删除 0 待确认 1 已确认(待取出) 2 已取出(待复核) 3 已复核 ',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '恒温培养箱使用记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for qlty_incubator_order_assoc
-- ----------------------------
