  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`, `assoc_id`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '恒温培养箱使用记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_incubator_order_batch
