  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`oid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '恒温培养箱使用记录批次信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_incubator_order_checkinfo
-- ----------------------------
DROP TABLE IF EXISTS `qlty_incubator_order_checkinfo`;
CREATE TABLE `qlty_incubator_order_checkinfo`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `oid` int(11) NULL DEFAULT NULL COMMENT '单据ID',
  `check_type` tinyint(1) NULL DEFAULT NULL COMMENT '微生物检验项目；1：菌落总数、大肠菌群24h; 2：菌落总数48h； 3：国标大肠菌群试验24h ；4：大肠菌群确认试验48h ；5 ：国标霉菌、 酵母菌5d;6：霉菌、酵母菌48h',
  `temperature` decimal(9, 2) NULL DEFAULT NULL COMMENT '标准温度',
  `inst_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪器编号',
  `inst_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仪器名称',
  `inst_id` int(11) NULL DEFAULT NULL COMMENT '仪器ID',
  `num` int(11) NULL DEFAULT NULL COMMENT '培养数量',
  `test_time_type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '检测时间段 1 上午 2 晚上',
  `test_temperature` decimal(9, 2) NULL DEFAULT NULL COMMENT '检测温度',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测人签名',
  `check_date` datetime NULL DEFAULT NULL COMMENT '检测人签名时间',
  `theory_end_time` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理论结束时间',
  `end_time` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束日期',
  `out_time` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取出时间',
  `out_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取出人签名',
  `recheck_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核人签名',
  `recheck_date` datetime NULL DEFAULT NULL COMMENT '复核时间',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '-1 删除 0 待确认 1 已确认(待取出) 2 已取出(待复核) 3 已复核 ',
  `ct_uid` int(11) NULL DEFAULT NULL,
  `up_uid` int(11) NULL DEFAULT NULL,
