-- ----------------------------
-- Table structure for qlty_innercoating_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_innercoating_order`;
CREATE TABLE `qlty_innercoating_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `p_id` int(11) NULL DEFAULT NULL COMMENT '确认单ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `batch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产批号',
  `check_date` date NOT NULL COMMENT '检测日期',
  `sample_date` date NULL DEFAULT NULL COMMENT '样品日期',
  `size_id` int(11) NULL DEFAULT NULL COMMENT '空罐尺寸id',
  `version_id` int(11) NOT NULL COMMENT '版本id',
  `version_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本编号',
  `version_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '版本名称',
  `reagent_id` int(11) NULL DEFAULT NULL COMMENT '检测试剂id',
  `line_id` int(11) NOT NULL COMMENT '空罐线别id',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `supplier_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `check_user_id` int(11) NOT NULL COMMENT '检测员ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测员名称',
  `check_ret` tinyint(1) NULL DEFAULT 3 COMMENT '检验结果 0 不合格 1合格 2 部分合格 3 检验中',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员签字',
  `recheck` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员信息',
  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `weld_seam_ret` tinyint(1) NULL DEFAULT 1 COMMENT '焊缝完整性实验检测结果 0 不及格 1及格',
  `electric_ret` tinyint(1) NULL DEFAULT 1 COMMENT '电流检测结果 0 不及格 1及格',
  `code_ret` tinyint(1) NULL DEFAULT 1 COMMENT '墨码检测结果（普通型） 0 不及格 1及格',
  `end_ret` tinyint(1) NULL DEFAULT 1 COMMENT '底盖蓝底检测结果（普通型） 0 不及格 1及格',
  `open_ret` tinyint(1) NULL DEFAULT 1 COMMENT '启破力检测结果（强化型） 0 不及格 1及格',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `p_id`(`p_id`, `status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 487 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '内涂膜检验报告单' ROW_FORMAT = Dynamic;

