  `brand` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品品牌 ND1 红牛；ND2 战马',
  `sku` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `batch_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批号',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `check_res` tinyint(1) NULL DEFAULT 3 COMMENT '检查结果；0 不合格 1合格 2 部分合格 3 检验中',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检测员uid',
  `check_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `recheck_id` int(11) NULL DEFAULT NULL COMMENT '复检ID',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `paper_id` int(11) NULL DEFAULT NULL COMMENT '纸皮图片配置id',
  `top_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖图片地址',
  `can_body_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '罐身图片地址（只有一张则用这个字段）',
  `bottom_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '底盖图片地址',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别名称',
  `execp_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常处置单号',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '版本号id',
  `version_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本号',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `brand`(`brand`) USING BTREE,
  INDEX `sku`(`sku`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `p_id`(`p_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 403 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '标签标识检验报告单' ROW_FORMAT = Dynamic;

