  `num` decimal(18, 4) NULL DEFAULT NULL COMMENT '处置数量',
  `unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '缺陷类型 1 重缺陷 2 中缺陷 3 瑕疵',
  `step` tinyint(1) NULL DEFAULT NULL COMMENT '处置方式 1 返工 2 让步 3 报废 4 退货',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别ID',
  `line_name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别名称',
  `box_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '箱号范围',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '不合格处置-缺陷描述列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_nonconformity‌_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_nonconformity‌_order`;
CREATE TABLE `qlty_nonconformity‌_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
