  `type` tinyint(1) NULL DEFAULT NULL COMMENT '异常类型 1 原材料 2 产品',
  `material_type_id` tinyint(1) NULL DEFAULT NULL COMMENT '原材料类型Id',
  `material_type_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原材料类型名称',
  `factory_id` int(11) NULL DEFAULT NULL COMMENT '厂商Id',
  `factory_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审',
  `step` tinyint(1) NULL DEFAULT 1 COMMENT '处置进度 1 审核环节 2 原因分析 3 上传措施 4 改善环节 5 措施实施 6 待完结 7 完结',
  `defect` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '缺陷描述',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人签字',
  `commit_date` date NULL DEFAULT NULL COMMENT '提交签字日期',
  `pg_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品管部经理签字',
  `pg_date` date NULL DEFAULT NULL COMMENT '提交签字日期',
  `pg_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品管审核备注',
  `detail` tinyint(1) NULL DEFAULT NULL COMMENT '处置 1 返工 2 让步 3 报废 4 退货',
  `fz_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '副总经理签字',
  `fz_date` date NULL DEFAULT NULL COMMENT '副总经理签字日期',
  `fz_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '副总经理审核备注',
  `z_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总经理签字',
  `z_date` date NULL DEFAULT NULL COMMENT '总经理签字日期',
  `z_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总经理审核备注',
  `analys_cause` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原因分析',
  `analys_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分析签字',
  `analys_date` date NULL DEFAULT NULL COMMENT '分析签字日期',
  `analys_files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分析附件',
  `corrective_cause` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '纠正措施',
  `corrective_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '纠正措施签字',
  `corrective_date` date NULL DEFAULT NULL COMMENT '纠正措施签字日期',
  `corrective_files` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '纠正措施附件',
  `question_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问题等到改善签字',
  `question_date` date NULL DEFAULT NULL COMMENT '问题等到改善签字日期',
  `measure_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '措施实施签字',
  `measure_date` date NULL DEFAULT NULL COMMENT '措施实施签字日期',
  `finish_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成签字',
  `finish_date` date NULL DEFAULT NULL COMMENT '完成签字日期',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核签字',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提交人ID',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门ID',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '不合格品处置单' ROW_FORMAT = Dynamic;

-- ----------------------------
