-- ----------------------------
DROP TABLE IF EXISTS `qlty_nonconformity‌_order_assoc`;
CREATE TABLE `qlty_nonconformity‌_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
