  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 66 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '不合格处置关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_nonconformity‌_order_log
-- ----------------------------
