-- ----------------------------
-- Table structure for qlty_operation_abnormal
-- ----------------------------
DROP TABLE IF EXISTS `qlty_operation_abnormal`;
CREATE TABLE `qlty_operation_abnormal`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `workshop` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间',
  `class` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次',
  `class_group` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产班组',
  `class_group_id` int(11) NULL DEFAULT NULL COMMENT '生产班组ID',
  `product_manager_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产主管',
  `product_manager_id` int(11) NULL DEFAULT NULL COMMENT '生产主管ID',
  `check_date` date NULL DEFAULT NULL COMMENT '检验日期',
  `test_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序化验员',
  `test_id` int(11) NULL DEFAULT NULL COMMENT '工序化验员ID',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '类型 1 记录类型 2 处置类型',
  `step` tinyint(1) NULL DEFAULT 0 COMMENT '处理进度；0：记录中；1：已记录 2: 隔离中 3：无需返工 4：返工中 5 返工完成',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：异常；1：异常解除 ；2 无',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '是否被使用 0 否 1 是',
  `anomaly_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '不合格处置单编号',
  `isolation_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隔离单号',
  `return_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '返工单号',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `is_return` tinyint(1) NULL DEFAULT 0 COMMENT '是否需要成品返工 0 否 1 是',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `step`(`step`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 62 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序异常记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_operation_abnormal_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_operation_abnormal_order`;
CREATE TABLE `qlty_operation_abnormal_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `class` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次',
  `class_group` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产班组',
  `class_group_id` int(11) NULL DEFAULT NULL COMMENT '生产班组ID',
  `check_date` date NULL DEFAULT NULL COMMENT '检验日期',
  `product_manager_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产主管',
