  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `err_type_pid`(`err_type_pid`, `err_type_id`, `err_type_cid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序异常记录（作废）' ROW_FORMAT = Dynamic;

