  `ingredient` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '称配料',
  `unpacking` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '拆包',
  `filling` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '灌装',
  `coding` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '打码',
  `wrapping` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '塑封',
  `packaging` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '包装',
  `stacking` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '码垛',
  `warehouse` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '仓库',
  `special_check` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '专检信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `batch_no`(`oid`, `batch_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序控制检验信息' ROW_FORMAT = Dynamic;

