-- ----------------------------
-- Table structure for qlty_operation_return_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_operation_return_order`;
CREATE TABLE `qlty_operation_return_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `p_id` int(11) NULL DEFAULT NULL COMMENT '异常单ID',
  `c_id` int(11) NULL DEFAULT NULL COMMENT '隔离单ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '返工编号',
  `return_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '返工方式',
  `return_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '返工时间',
  `return_batch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际返工批次',
  `return_batch_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际返工批号',
  `return_box_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实际返工箱号',
  `return_sign` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '返工人员签名,多个用逗号隔开',
  `return_box_num` int(11) NULL DEFAULT NULL COMMENT '返工箱数',
  `return_num` int(11) NULL DEFAULT NULL COMMENT '返工数量',
  `scrap_num` int(11) NULL DEFAULT NULL COMMENT '报废数量',
  `loss_price` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '损失金额',
  `o_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '奥瑞金签名',
  `return_source` tinyint(1) NULL DEFAULT NULL COMMENT '返工方 1 奥瑞金 2 运维 3 巡检员',
  `is_repair` tinyint(1) NULL DEFAULT NULL COMMENT '是否补罐 0 否 1 是',
  `is_pack` tinyint(1) NULL DEFAULT NULL COMMENT '是否装箱码垛 0 否 1 是',
  `is_in_ware` tinyint(1) NULL DEFAULT NULL COMMENT '是否入库 0 否 1 是',
  `return_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '返工描述',
  `test_id` int(11) NULL DEFAULT NULL COMMENT '工序化验员ID',
  `test_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序化验员名称',
  `test_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序化验员签名',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `question_num` int(11) NULL DEFAULT NULL COMMENT '问题罐数',
  `o_question_num` int(11) NULL DEFAULT NULL COMMENT '其他问题罐数',
  `is_hot` tinyint(1) NULL DEFAULT NULL COMMENT '是否热缩 0 否 1 是',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `p_id`(`p_id`) USING BTREE,
  INDEX `return_batch_no`(`return_batch_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序异常-返工单' ROW_FORMAT = Dynamic;

