-- ----------------------------
-- Table structure for qlty_operation_roll_inspection_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_operation_roll_inspection_order`;
CREATE TABLE `qlty_operation_roll_inspection_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `check_date` date NOT NULL COMMENT '检测日期',
  `check_time` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测时分',
  `line_id` int(11) NOT NULL COMMENT '线别id',
  `class_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '班组',
  `class_time` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次',
  `brand` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛；ND2 战马',
  `sku` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `node` tinyint(1) NOT NULL COMMENT '工序节点ID',
  `node_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序节点名称',
  `mapping_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机原因',
  `mapping_ret` tinyint(4) NULL DEFAULT 0 COMMENT '调机结果 0 无 1 调机中 2 合格',
  `mapping_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机单号',
  `mapping_date` date NULL DEFAULT NULL COMMENT '调机日期',
  `mapping_uid` int(11) NULL DEFAULT NULL COMMENT '调机检验员ID',
  `mapping_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机检验员名称',
  `mapping_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机检验员签字',
  `mapping_step` tinyint(1) NULL DEFAULT 0 COMMENT '调机进度 0 未完成 1 已完成',
  `mapping_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机备注',
  `mapping_ct_date` datetime NULL DEFAULT NULL COMMENT '调机创建时间',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果；0：不合格；1：合格 2 部分合格',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检测员uid',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值配置',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `is_recheck` tinyint(1) NULL DEFAULT 0 COMMENT '是否已复检 0 否 1 是',
  `recheck_date` date NULL DEFAULT NULL COMMENT '复检日期',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `recheck_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检签名',
  `recheck_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检备注',
  `recheck_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检单号',
  `re_uid` int(11) NULL DEFAULT NULL COMMENT '复检人',
  `re_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检名称',
  `re_step` tinyint(1) NULL DEFAULT 0 COMMENT '复检步骤 0 未完成 1 已完成',
  `re_ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检建单人',
  `re_date` datetime NULL DEFAULT NULL COMMENT '复检创建时间',
  `before_line_id` int(11) NULL DEFAULT NULL COMMENT '换前制罐线别ID',
  `before_line_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换前制罐线别名称',
  `before_version_id` int(11) NULL DEFAULT NULL COMMENT '换前空罐版本ID',
  `before_version_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换前空罐版本名称',
  `before_sup_id` int(11) NULL DEFAULT NULL COMMENT '换前顶/底供应商ID',
  `before_sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换前顶/底供应商名称',
  `before_empty_sup_id` int(11) NULL DEFAULT NULL COMMENT '换前空罐供应商ID',
  `before_empty_sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '换前空罐供应商',
  `empty_sup_id` int(11) NULL DEFAULT NULL COMMENT '空罐供应商ID',
  `empty_sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐供应商名称',
  `can_line_id` int(11) NULL DEFAULT NULL COMMENT '制罐线别ID',
  `can_line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制罐线别名称',
  `can_version_id` int(11) NULL DEFAULT NULL COMMENT '空罐版本ID',
  `can_version_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐版本名称',
  `can_sup_id` int(11) NULL DEFAULT NULL COMMENT '顶/底供应商ID',
  `can_sup_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶/底供应商名称',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `brand`(`brand`) USING BTREE,
  INDEX `sku`(`sku`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE,
  INDEX `mapping_ret`(`mapping_ret`) USING BTREE,
  INDEX `is_recheck`(`is_recheck`) USING BTREE,
  INDEX `mapping_no`(`mapping_no`) USING BTREE,
  INDEX `recheck_no`(`recheck_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 89 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序卷封检验报告' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_operation_roll_inspection_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_operation_roll_inspection_order_assoc`;
CREATE TABLE `qlty_operation_roll_inspection_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 347 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序卷封检测关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
