-- ----------------------------
-- Table structure for qlty_paper_restock_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_paper_restock_order`;
CREATE TABLE `qlty_paper_restock_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `factory_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `factory_id` int(11) NULL DEFAULT NULL COMMENT '厂商ID',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `supplier_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `batch_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批号',
  `brand` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品品牌 ND1 红牛；ND2 战马',
  `sku` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '版本id',
  `version` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本名称',
  `class` tinyint(1) NULL DEFAULT NULL COMMENT '产品类别；1：箱内码；2：无箱内码',
  `workshop` tinyint(1) NULL DEFAULT NULL COMMENT '车间；1：一车间；2：二车间；3：三车间',
  `check_res` tinyint(1) NULL DEFAULT 3 COMMENT '检查结果；0 不合格 1合格 2 部分合格 3 检验中',
  `recheck_id` int(11) NULL DEFAULT NULL COMMENT '复检ID',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `system_serial_number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内部批次',
  `s_date` date NULL DEFAULT NULL COMMENT '样品日期',
  `pro_time` date NULL DEFAULT NULL COMMENT '生产日期',
  `num` int(11) NULL DEFAULT NULL COMMENT '入库数量',
  `unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库单位',
  `goods_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料条码',
  `send_num` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样数量',
  `send_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样单位',
  `source_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检来源单号',
  `stock_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '对应库存ID多个用逗号隔开',
  `execp_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常处置单号',
  `check_time` date NULL DEFAULT NULL COMMENT '检测日期',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检测员uid',
  `check_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名字',
  `paper_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '纸皮图片地址',
  `paper_id` int(11) NULL DEFAULT NULL COMMENT '纸皮图片配置id',
  `size_res` tinyint(1) NULL DEFAULT NULL COMMENT '尺寸检测结果；0：不合格；1：合格',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `weight_res` tinyint(1) NULL DEFAULT NULL COMMENT '重量检测结果；0：不合格；1：合格',
  `exterior_res` tinyint(1) NULL DEFAULT NULL COMMENT '外观检测 0 不合格 1 合格',
  `color_res` tinyint(1) NULL DEFAULT NULL COMMENT '颜色检测结果；0：不合格；1：合格',
  `red_bull_res` tinyint(1) NULL DEFAULT NULL COMMENT '红牛标记检测结果；0：不合格；1：合格',
  `warhorse_res` tinyint(1) NULL DEFAULT NULL COMMENT '战马标记检测结果；0：不合格；1：合格',
  `printing_quality_res` tinyint(1) NULL DEFAULT NULL COMMENT '印刷质量检测结果；0：不合格；1：合格',
  `opening_crack_res` tinyint(1) NULL DEFAULT NULL COMMENT '开合裂度检测结果；0：不合格；1：合格',
  `barcode_res` tinyint(1) NULL DEFAULT NULL COMMENT '条形码检测结果；0：不合格；1：合格',
  `laser_code_res` tinyint(1) NULL DEFAULT NULL COMMENT '激光码检测结果；0：不合格；1：合格',
  `laser_qr_code_res` tinyint(1) NULL DEFAULT NULL COMMENT '激光码、二维码检测结果；0：不合格；1：合格',
  `box_qr_code_res` tinyint(1) NULL DEFAULT NULL COMMENT '箱内二维码检测结果；0：不合格；1：合格',
  `position_res` tinyint(1) NULL DEFAULT NULL COMMENT '位置结果；0：不合格；1：合格',
  `barcode_length_res` tinyint(1) NULL DEFAULT NULL COMMENT '大小结果；0：不合格；1：合格',
  `scan_reading_res` tinyint(1) NULL DEFAULT NULL COMMENT '扫读检测结果；0：不合格；1：合格',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片',
  `check_view` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '检验意见',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值配置',
  `laser_qr_code_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '激光码、二维码检测备注',
  `laser_code_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '激光码检测备注',
  `barcode_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '条形码检测备注',
  `opening_crack_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开合裂度检测备注',
  `printing_quality_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '印刷质量检测备注',
  `warhorse_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '战马标记检测备注',
  `red_bull_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '红牛标记检测备注',
  `color_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '颜色检测结果备注',
  `weight_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重量检测结果备注',
  `exterior_res_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外观检测结果备注',
  `sample_date` date NULL DEFAULT NULL COMMENT '样品日期',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `supplier_id`(`supplier_id`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE,
  INDEX `sku`(`sku`) USING BTREE,
  INDEX `brand`(`brand`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
