  `microbial_check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微生物指标操作员签名图片',
  `microbial_check_user_signature1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微生物指标助手签名图片',
  `physical_check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理化指标检验员签名图片',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `report_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人签字',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `liquid_level_check_res` tinyint(1) NULL DEFAULT NULL COMMENT '液位占比检查结果；0：不合格；1：合格',
  `net_check_res` tinyint(1) NULL DEFAULT NULL COMMENT '净含量平均值检查结果；0：不合格；1：合格',
  `sense_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官四项批次下综合判定 0 不合格 1合格',
  `report_uid` int(11) NOT NULL COMMENT '报告人uid',
  `report_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值配置',
  `recheck_status` tinyint(4) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `avg_weight` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0.00' COMMENT '平均值-重量',
  `avg_net` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0.0' COMMENT '平均值-净含量',
  `avg_pressure` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0.000' COMMENT '平均值-内压',
