  `batch_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批号',
  `batch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号+批次',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `phys_weight_val` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理化指标-重量实测值',
  `phys_net_val` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理化指标-净含量实测值',
  `phys_internal_pressure_val` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理化指标-内压实测值',
  `sense_smell_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-滋味和气味检测结果；0：不合格；1：合格',
  `sense_color_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-色泽检测结果；0：不合格；1：合格',
  `sense_appearance_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-外观检测结果；0：不合格；1：合格',
  `sense_impurity_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-杂质检测结果；0：不合格；1：合格',
  `check_res` float NULL DEFAULT NULL COMMENT '检测结果；0：不合格；1：合格 ;2：暂缓',
  `ph_val` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ph实测值',
  `microbe_statistical_time1` date NULL DEFAULT NULL COMMENT '微生物指标-统计时间1',
  `microbe_statistical_time2` date NULL DEFAULT NULL COMMENT '微生物指标-统计时间2',
  `microbe_coliform_bacteria_val` int(11) NULL DEFAULT NULL COMMENT '微生物指标-大肠菌群结果实测值',
  `microbe_bacterial_val` int(11) NULL DEFAULT NULL COMMENT '微生物指标-细菌总数值',
  `microbe_saccharomyces_val` int(11) NULL DEFAULT NULL COMMENT '微生物指标-酵母菌实测值',
  `microbe_mold_val` int(11) NULL DEFAULT NULL COMMENT '微生物指标-霉菌实测值',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '是否使用；0：未使用；1：已使用；',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '成品版本ID',
  `version_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品版本名称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `batch_no`(`batch_no`, `batch_number`) USING BTREE,
  INDEX `batch`(`batch`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3340 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '理化及微生物检验信息明细' ROW_FORMAT = DYNAMIC;

