-- Table structure for qlty_power_confirm_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_power_confirm_order`;
CREATE TABLE `qlty_power_confirm_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `workshop_id` int(11) NOT NULL COMMENT '车间ID',
  `workshop_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '车间名称',
  `line_id` int(11) NOT NULL COMMENT '线别ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线别名称',
  `check_date` date NOT NULL COMMENT '检测日期',
  `pro_id` int(11) NOT NULL COMMENT 'CIP项目id',
  `pro_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'CIP项目名称',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `laboratory_manager_uid` int(11) NULL DEFAULT NULL COMMENT '化验室负责人uid',
  `ingredient_confirm_uid` int(11) NULL DEFAULT NULL COMMENT '配料确认人uid',
  `check_ret` tinyint(1) NULL DEFAULT 0 COMMENT '检验状态 0 未检测 1部分检测 2 已检测',
  `product_manager_uid` int(11) NULL DEFAULT NULL COMMENT '生产部主管uid',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `pz_manager_uid` int(11) NULL DEFAULT NULL COMMENT '品质部经理uid',
  `product_manag_uid` int(11) NULL DEFAULT NULL COMMENT '生产部经理uid',
  `pz_manager_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品管部经理签名',
  `product_manager_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产部主管签名',
  `product_manag_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产部经理签名',
  `laboratory_manager_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '化验室负责人签名',
  `ingredient_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配料确认人签名',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开机确认单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_power_confirm_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_power_confirm_order_assoc`;
CREATE TABLE `qlty_power_confirm_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '标签标识检验报告单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开机确认单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_power_confirm_order_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_power_confirm_order_detail`;
CREATE TABLE `qlty_power_confirm_order_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `oid` int(11) NOT NULL COMMENT '单据ID',
  `water_microbial_detection` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '试水微生物检测',
  `filling_condition1` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '灌装条件第一组',
  `filling_condition2` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '灌装条件第二组',
  `before_start_water` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开机前过滤器后水样（二氧化氯）',
  `before_start_wip` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开机前红牛半成品',
  `before_start_outwater` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开机前灌装出口水样',
  `open_product` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开机时红牛/战马产品',
  `after_open` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '开机后',
  `work_15min` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '正常生产15分钟后',
  `work_20min` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '正常生产20分钟后',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `oid`(`oid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 92 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'CIP检验信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_power_confirm_order_file
-- ----------------------------
DROP TABLE IF EXISTS `qlty_power_confirm_order_file`;
CREATE TABLE `qlty_power_confirm_order_file`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `oid` int(11) NOT NULL COMMENT '单据ID',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件链接',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `download_num` int(11) NULL DEFAULT 0 COMMENT '下载次数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '上传者',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`oid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开机确认单附件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_power_confirm_order_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_power_confirm_order_log`;
CREATE TABLE `qlty_power_confirm_order_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据id',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 218 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开机确认单记录日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_power_confirm_user_basic
-- ----------------------------
DROP TABLE IF EXISTS `qlty_power_confirm_user_basic`;
CREATE TABLE `qlty_power_confirm_user_basic`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `line_id` int(11) NOT NULL COMMENT '线别id',
  `product_manag_uid` int(11) NULL DEFAULT NULL COMMENT '生产部经理uid',
  `laboratory_manager_uid` int(11) NULL DEFAULT NULL COMMENT '化验室负责人uid',
  `pz_manager_uid` int(11) NULL DEFAULT NULL COMMENT '品质部经理uid',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '开机确认人配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_process_control_inspection
-- ----------------------------
DROP TABLE IF EXISTS `qlty_process_control_inspection`;
CREATE TABLE `qlty_process_control_inspection`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `date` date NULL DEFAULT NULL COMMENT '检测日期',
  `line_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别id',
  `line` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别',
  `class_no` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1早 2中 3夜',
  `class_type` tinyint(1) NULL DEFAULT NULL COMMENT '班组 (1A、2B、3C)',
  `work_shop_id` int(10) NULL DEFAULT NULL COMMENT '车间id',
  `work_shop` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间',
  `check_uid` int(10) NULL DEFAULT NULL COMMENT '检测人id',
  `check_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测人',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态 0=暂存；1=待审核；2=已审核；3=审核驳回；4=撤回',
  `review_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核人签字',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `detail_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一线检查记录备注',
  `detail_note2` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二线检查记录备注',
  `tab_goods_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一线 产品ID 红牛维生素功能饮料 ；红牛维生素功能饮料（牛磺酸强化型）；战马能量型维生素饮料',
  `tab_goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一线 产品名称',
  `tab_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一线 批次号',
  `tab2_goods_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二线 产品ID 红牛维生素功能饮料 ；红牛维生素功能饮料（牛磺酸强化型）；战马能量型维生素饮料',
  `tab2_goods_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二线 产品名称',
  `tab2_batch` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '二线 批次号',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `physical` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '理化指标',
  `temperature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '水温湿度',
  `hourglass` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '跑冒滴漏',
  `subpackage` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '原材料称量及分装情况',
  `control` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '配料过程控制',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'tab1标准值',
  `base_val2` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'tab2标准值',
  `identification` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '成品、原材料码放及标识情况',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 91 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序控制检验记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_process_control_inspection_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_process_control_inspection_assoc`;
CREATE TABLE `qlty_process_control_inspection_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 152 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序控制检验记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_process_control_inspection_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_process_control_inspection_detail`;
CREATE TABLE `qlty_process_control_inspection_detail`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `is_open` tinyint(1) NULL DEFAULT NULL COMMENT '开启 0=关闭；1=开启',
  `order_id` int(10) NULL DEFAULT NULL COMMENT '单据id',
  `tab` tinyint(1) NOT NULL DEFAULT 0 COMMENT '类型 0=-；1=一线；2=二线',
  `batch` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `code_time` time NULL DEFAULT NULL COMMENT '罐底码时间',
  `detect_temperature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测温度',
  `detect_num` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测值',
  `ph` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'PH',
  `senses` tinyint(1) NULL DEFAULT NULL COMMENT '感官 0=异常；1=正常',
  `press` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '罐内压',
  `liquid_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '液位',
  `empty_time` time NULL DEFAULT NULL COMMENT '空罐检测仪时间',
  `empty_result` tinyint(1) NULL DEFAULT NULL COMMENT '空罐检测仪结果 0=异常；1=正常',
  `empty_types` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐剔除种类',
  `empty_quality` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐质量≥2O罐/h',
  `face_quality` tinyint(1) NULL DEFAULT NULL COMMENT '外观质量（12罐/批）0=异常；1=正常',
  `capper` tinyint(1) NULL DEFAULT NULL COMMENT '封口机卫生  0=异常；1=正常',
  `capper1` tinyint(1) NULL DEFAULT NULL COMMENT '封口机卫生2 0=异常；1=正常',
  `sterilization_temperature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '杀菌温度',
  `sterilization_duration` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '杀菌时长',
  `water_temperature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洗罐水温',
  `water_pressure` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洗罐水压力1',
  `water_pressure1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洗罐水压力2',
  `code_quality` tinyint(1) NULL DEFAULT NULL COMMENT '墨码、二维码质量≥20罐/批 0=异常；1=正常',
  `glue_quality` tinyint(1) NULL DEFAULT NULL COMMENT '防伪注胶质量≥10罐/批 0=异常；1=正常',
  `cooling_water_brix` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 Brix',
  `cooling_water_brix1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 Brix1',
  `cooling_water_brix2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 Brix2',
  `cooling_water_brix3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 Brix3',
  `cooling_water_ph` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 PH',
  `cooling_water_ph1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 PH1',
  `cooling_water_ph2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 PH2',
  `cooling_water_ph3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 PH3',
  `cooling_water_lv` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 电导率',
  `cooling_water_lv1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 电导率1',
  `cooling_water_lv2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 电导率2',
  `cooling_water_lv3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 电导率3',
  `cooling_water_tds` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 TDS',
  `cooling_water_tds1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 TDS1',
  `cooling_water_tds2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 TDS2',
  `cooling_water_tds3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 TDS3',
  `cooling_water_sal` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 SAL',
  `cooling_water_sal1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 SAL1',
  `cooling_water_sal2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 SAL2',
  `cooling_water_sal3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冷却机水 SAL3',
  `pyrocondensation_quality` tinyint(1) NULL DEFAULT NULL COMMENT '热缩质量 0=异常；1=正常',
  `out_code_quality` tinyint(1) NULL DEFAULT NULL COMMENT '包装成型及外箱码质量 0=异常；1=正常',
  `out_scan_code_quality` tinyint(1) NULL DEFAULT NULL COMMENT '外箱二维码质量≥5箱/批 0=异常；1=正常',
  `produce_batch` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量1批号',
  `produce_box` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量1箱号',
  `produce_check` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量是否正常 0 异常 1 正常',
  `produce_batch2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量2批号',
  `produce_box2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量2箱号',
  `produce_check2` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量2是否正常 0 异常 1 正常',
  `produce_batch3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量3批号',
  `produce_box3` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量3箱号',
  `produce_check3` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品质量3是否正常 0 异常 1 正常',
  `target_lv` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理化指标电导率',
  `target_ph` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '理化指标PH',
  `temperature` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '水温',
  `hourglass` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '跑冒滴漏',
  `humidity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '环境湿度',
  `subpackage` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原材料称量及分装情况',
  `control` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配料过程控制',
  `identification` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品、原材料码放及标识情况',
  `hygiene` tinyint(1) NULL DEFAULT NULL COMMENT '各岗位人员工艺、劳动纪律及卫生 0=异常；1=正常',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `tab`(`tab`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1420 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '工序控制检验记录详情' ROW_FORMAT = Dynamic;

