  `line_id` int(11) NOT NULL COMMENT '线别id',
  `line_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线别名称',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间ID ',
  `workshop_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名称',
