  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人名称',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认签字图片',
  `version_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品版本ID，多个用逗号隔开',
  `version_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品版本名称，多个用逗号隔开',
  `top_cover_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '顶盖图片地址，多个用逗号隔开',
  `bottom_cover_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '底盖图片地址，多个用逗号隔开',
  `can_body_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '罐身图片地址，多个用逗号隔开',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态 0 待确认 1 已确认',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '绑定成品类型 0 红牛 1 战马',
  `use_id` int(11) NULL DEFAULT NULL COMMENT '生成单据ID',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成总报告 0 未生成 1 已生成 2 部分生成',
  `is_send` tinyint(1) NULL DEFAULT 0 COMMENT '是否生产通知单  未生成 1 已生成 2 部分生成',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT 0 COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
