-- Table structure for qlty_product_dept_finger_membrane_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_product_dept_finger_membrane_order`;
CREATE TABLE `qlty_product_dept_finger_membrane_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `check_date` date NOT NULL COMMENT '检测日期',
