) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '手部涂抹实验检验记录日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_product_external
-- ----------------------------
DROP TABLE IF EXISTS `qlty_product_external`;
CREATE TABLE `qlty_product_external`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
