-- ----------------------------
-- Table structure for qlty_product_label_identify_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_product_label_identify_order`;
CREATE TABLE `qlty_product_label_identify_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `sup_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `cap_supplier_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖供应商id，多个用逗号隔开',
  `cap_supplier_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖供应商名称',
  `pro_date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产日期',
  `batch_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产批次',
  `batch_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批号',
  `check_date` date NOT NULL COMMENT '检测日期',
  `brand` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛；ND2 战马',
  `sku` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `product_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称 ND1-1 红牛维生素功能饮料 ND1-2 红牛维生素功能饮料（牛磺酸强化型） ND2-1 战马能量型维生素饮料',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果；0：不合格；1：合格',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `top_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖图片地址,多个用逗号隔开',
  `bottom_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '底盖图片地址,多个用逗号隔开',
  `can_body_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '罐身图片地址,多个用逗号隔开（只有一张则用这个字段）',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检测员uid',
  `check_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `paper_id` int(11) NULL DEFAULT NULL COMMENT '纸皮图片配置id',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值配置',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `is_promotion` tinyint(1) NULL DEFAULT NULL COMMENT '是否促销 0 否 1 是',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `version_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本号id,多个用逗号隔开',
  `version_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本号,多个用逗号隔开',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '是否使用；0：未使用；1：已使用；',
  `outo_order_id` int(11) NULL DEFAULT NULL COMMENT '成品批号信息确认单id,不为空则说明是通过该单自动创建的',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '产线id',
  `line_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产线',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE,
  INDEX `brand`(`brand`) USING BTREE,
  INDEX `sku`(`sku`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 472 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品标签标识报告检测报告' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_product_label_identify_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_product_label_identify_order_assoc`;
CREATE TABLE `qlty_product_label_identify_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '标签标识检验报告单列表ID',
