  `layout_structure_res` tinyint(1) NULL DEFAULT NULL COMMENT '纸箱检测结果；0：不合格；1：合格',
  `security_point_res` tinyint(1) NULL DEFAULT NULL COMMENT '防伪点检测结果；0：不合格；1：合格',
  `reinspection_items` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检项目,多个用逗号隔开 项目；1:罐底二维码;2:拉环二维码;3:纸箱;4:防伪点; ',
  `reinspection_situation_res` tinyint(1) NULL DEFAULT NULL COMMENT '复检情况检测结果；0：不合格；1：合格',
  `version_id` tinyint(1) NULL DEFAULT NULL COMMENT '促销版本 1 促销版 2 普通版',
  `check_res` float NULL DEFAULT NULL COMMENT '检测结果；0：不合格；1：合格',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2770 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品二维码确认单检验信息明细' ROW_FORMAT = DYNAMIC;

