  `desp` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '假期描述',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '检测状态 0 未确认 1 已确认',
