-- ----------------------------
-- Table structure for qlty_product_roll_inspection_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_product_roll_inspection_order`;
CREATE TABLE `qlty_product_roll_inspection_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
