  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '类型 0 普通 1 全检',
  `batch_no` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次',
  `batch_number` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `reserve_num` int(11) NULL DEFAULT NULL COMMENT '保留时间',
  `can_top` tinyint(1) NULL DEFAULT NULL COMMENT '罐盖 0 × 1 √',
  `can_bottom` tinyint(1) NULL DEFAULT NULL COMMENT '罐底 0 × 1 √',
  `can_body_top` tinyint(1) NULL DEFAULT NULL COMMENT '罐身上 0 ×; 1 √; 2 变形; 3 =>0; 4 =>1;5=>2;6=>3;7=>4;8=>5;9=>6;10=>7;11=>8;12=>9;13=>10;',
  `can_body_bottom` tinyint(1) NULL DEFAULT NULL COMMENT '罐身下 0 ×; 1 √; 2 变形; 3 =>0; 4 =>1;5=>2;6=>3;7=>4;8=>5;9=>6;10=>7;11=>8;12=>9;13=>10;',
  `weld_seam` tinyint(1) NULL DEFAULT NULL COMMENT '焊缝 0 × 1 √',
  `Brix` decimal(9, 1) NULL DEFAULT NULL COMMENT 'Brix',
  `pH` decimal(9, 2) NULL DEFAULT NULL COMMENT 'pH',
  `composition_analysis` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成分分析',
  `purity` tinyint(1) NULL DEFAULT NULL COMMENT '纯净度 0 × 1 √',
  `color` tinyint(1) NULL DEFAULT NULL COMMENT '颜色 0 × 1 √',
  `smell` tinyint(1) NULL DEFAULT NULL COMMENT '气味 0 × 1 √',
  `taste` tinyint(1) NULL DEFAULT NULL COMMENT '滋味 0 × 1 √',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 165 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '产品留样观察记录明细' ROW_FORMAT = Dynamic;

