  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：已确认',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '确认人uid',
  `check_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人名字',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人签名图片',
  `is_destroy` tinyint(1) NULL DEFAULT 0 COMMENT '是否销毁 0 否 1 是',
