-- ----------------------------
-- Table structure for qlty_product_sample_push_list
-- ----------------------------
DROP TABLE IF EXISTS `qlty_product_sample_push_list`;
CREATE TABLE `qlty_product_sample_push_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产订单号',
  `product_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称 ND1-1 红牛维生素功能饮料 ND1-2 红牛维生素功能饮料（牛磺酸强化型） ND2-1 战马能量型维生素饮料',
  `line_id` int(11) NOT NULL COMMENT '线别id',
  `line_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线别名称',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间ID ',
  `workshop_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名称',
  `group_id` int(11) NOT NULL COMMENT '生产班组ID',
  `group_name` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产班组',
  `class` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '生产班次',
  `pro_date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `sample_num` int(11) NULL DEFAULT NULL COMMENT '样品数',
  `sample_time` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '取样时间',
  `push_time` datetime NULL DEFAULT NULL COMMENT '推送时间生产日期+取样时间',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `batch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次',
  `batch_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批号',
  `version_id` int(11) NOT NULL COMMENT '成品版本ID',
  `version_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '成品版本名称',
  `except_uid` int(11) NULL DEFAULT NULL COMMENT '异常标记人ID',
  `except_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常标记人',
  `except_time` datetime NULL DEFAULT NULL COMMENT '异常标记时间',
  `brand` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品大类',
  `sku` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：未送检；1：已送检  2 异常 3 推送失败',
  `msg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '返回结果',
  `excep_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常备注',
  `is_promotion` tinyint(1) NULL DEFAULT NULL COMMENT 'is_promotion',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `batch_no`(`batch_no`, `batch_number`) USING BTREE,
  INDEX `pro_date`(`pro_date`, `sample_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `push_time`(`push_time`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `product_name`(`product_name`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE,
  INDEX `brand`(`brand`, `order_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 268 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品取样信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_product_sample_setting
-- ----------------------------
DROP TABLE IF EXISTS `qlty_product_sample_setting`;
CREATE TABLE `qlty_product_sample_setting`  (
