-- ----------------------------
-- Table structure for qlty_productquantify_order_checkinfo
-- ----------------------------
DROP TABLE IF EXISTS `qlty_productquantify_order_checkinfo`;
CREATE TABLE `qlty_productquantify_order_checkinfo`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `oid` int(11) NOT NULL COMMENT '单据ID',
  `sample_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '样品编号',
  `make_date` date NOT NULL COMMENT '生产日期',
  `batch_no` char(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次',
  `sample_batch_no` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '样品批号',
  `check_times` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测序号',
  `check_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '测定数据',
  `content_x_avg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '平均值',
  `content_x_diff_avg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '绝对差值/平均值x100%',
  `dilute` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '稀释倍数',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '矫正含量',
  `content_x` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '含量x',
  `content_xx` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '含量x',
  `diff_coe` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '差异系数CV',
  `emp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '空白',
  `strength` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '强度',
  `concentration` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '浓度',
  `esc_avg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '平均值',
  `plastid` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '质体比',
  `amount` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '取样量V1',
  `volume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '定容体积V2',
  `clean_amount_v1` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洗脱后定容体积V1',
  `get_amount_v2` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提取液体积V2',
  `clean_amount_v3` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '净化体积V3',
  `pb_absorbance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'Pb浓度',
  `as_absorbance` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'As浓度',
  `unit` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `form` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '形态',
  `times` int(4) NULL DEFAULT NULL COMMENT '次数',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不及格 1及格',
  `is_use` tinyint(1) NULL DEFAULT 0 COMMENT '是否已生成产品定量检验报告 0 否 1是',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '最后修改人uid',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `batch_no`(`oid`, `batch_no`, `sample_batch_no`, `times`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2554 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '定量测定原始记录检验信息' ROW_FORMAT = Dynamic;

