) ENGINE = InnoDB AUTO_INCREMENT = 229 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'QA质量保证-内审任务列表检查信息-执行检查' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_qa_check_list
-- ----------------------------
DROP TABLE IF EXISTS `qlty_qa_check_list`;
CREATE TABLE `qlty_qa_check_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '报告编号',
  `name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审核任务名称',
  `start_date` date NOT NULL COMMENT '规定审核开始日期',
  `end_date` date NOT NULL COMMENT '规定审核结束日期',
  `type` tinyint(1) NOT NULL COMMENT '任务级别 0 公司级 1 班组级',
  `task_status` tinyint(1) NULL DEFAULT 0 COMMENT '任务状态 0 未发布 1 已发布 2 清单待审核 3 清单审核通过 4 清单审核不通过',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态 0 暂存 1 待审核 2 已审核 3 已驳回 4：已撤回；5：已反审；6：已作废',
  `inner_status` tinyint(1) NULL DEFAULT 0 COMMENT '内审状态 0 未指派 1 已指派 2 无需指派',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审批内容',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `check_uid` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内审人员集合，多个用逗号隔开',
  `check_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内审人员名称集合，多个用逗号隔开',
  `push_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `push_uid` int(11) NULL DEFAULT NULL COMMENT '发布人',
  `push_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '发布人',
  `commit_uid` int(11) NULL DEFAULT NULL COMMENT '提交检查清单人',
  `commit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交检查清单人',
  `commit_time` datetime NULL DEFAULT NULL COMMENT '提交检查清单时间',
  `check_date` date NULL DEFAULT NULL COMMENT '检查时间',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果 0 不合格 1 合格 2 部分合格',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `finish_uid` int(11) NULL DEFAULT NULL COMMENT '完成人',
  `finish_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成人',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人签名',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名',
  `record_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '清单审核签名',
  `commit_record_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交清单签名',
  `inner_user_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内审组长签字',
  `inner_user_id` int(11) NULL DEFAULT NULL COMMENT '内审组长ID',
  `inner_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内审组长名称',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '部门ID',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人',
  `check_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批备注',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `task_status`(`task_status`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `inner_status`(`inner_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'QA质量保证-内审任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_qa_check_log
