  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 135 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'QA质量保证-日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_qa_check_user
-- ----------------------------
DROP TABLE IF EXISTS `qlty_qa_check_user`;
CREATE TABLE `qlty_qa_check_user`  (
