-- ----------------------------
-- Table structure for qlty_qa_internal_audit_team
-- ----------------------------
DROP TABLE IF EXISTS `qlty_qa_internal_audit_team`;
CREATE TABLE `qlty_qa_internal_audit_team`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
