) ENGINE = InnoDB AUTO_INCREMENT = 70 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '产品定量检测关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
