-- ----------------------------
-- Table structure for qlty_raw_material_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_raw_material_order`;
CREATE TABLE `qlty_raw_material_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `source` tinyint(1) NULL DEFAULT NULL COMMENT '隔离来源 1 生产领用隔离 2 原材料检测隔离',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '隔离原料类型 1 包材 2 内容物',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隔离原料名称',
  `check_date` date NULL DEFAULT NULL COMMENT '隔离日期',
  `num` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隔离量',
  `unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隔离量-单位',
  `class` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次',
  `class_group` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组',
  `class_group_id` int(11) NULL DEFAULT NULL COMMENT '班组ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别ID',
  `item_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批号',
  `item_pallet_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂托盘号',
  `err_type_pid` int(11) NULL DEFAULT NULL COMMENT '所属问题ID-原材料-不良大类ID',
  `err_type_pname` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属问题ID-原材料-不良大类名称',
  `reason` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隔离原因',
  `conclusion` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结论',
  `product_manager_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产主管',
  `product_manager_id` int(11) NULL DEFAULT NULL COMMENT '生产主管ID',
  `product_manager_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产主管签字',
  `test_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '化验员',
  `test_id` int(11) NULL DEFAULT NULL COMMENT '化验员ID',
  `test_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '化验员签字',
  `ware_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓管员',
  `ware_id` int(11) NULL DEFAULT NULL COMMENT '仓管员ID',
  `ware_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓管员签字',
  `step` tinyint(1) NULL DEFAULT 0 COMMENT '处理进度；0：待隔离；1：已隔离 2: 无需返库 6 退库中 7 已退库',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：待确认；1：已确认 2 部分确认',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `return_id` int(11) NULL DEFAULT NULL COMMENT '退库单ID',
  `return_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退库单据编号',
  `no_return_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '无需返工签名',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `item_no`(`item_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料异常隔离单' ROW_FORMAT = Dynamic;

