  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `batch_no` char(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次号 8位',
  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `product_type` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称 ND1-1 红牛维生素功能饮料 ND1-2 红牛维生素功能饮料（牛磺酸强化型）ND2-1 战马能量型维生素饮料',
  `line_id` int(11) NOT NULL COMMENT '线别ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线别名称',
  `workshop` tinyint(1) NULL DEFAULT NULL COMMENT '车间ID 1 一车间 2 二车间 3 三车间',
  `workshop_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名称',
  `class` tinyint(1) NULL DEFAULT NULL COMMENT '班次 1白 2 中 3夜',
  `group` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组',
  `sample_num` int(11) NULL DEFAULT NULL COMMENT '工序取样量（罐）',
  `net_ret` tinyint(1) NULL DEFAULT NULL COMMENT '净含量平均值 0 不及格 1及格 红牛≥250.0ml，战马≥310.0ml才为合格',
  `check_date` date NOT NULL COMMENT '检测日期',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不及格 1及格',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检测员ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员名称',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员签字',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `recheck` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员复核信息',
  `status` tinyint(1) NOT NULL COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核备注',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 87 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '样品检测单据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_sample_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_sample_order_assoc`;
CREATE TABLE `qlty_sample_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `assoc_id` int(10) UNSIGNED NOT NULL COMMENT '单据ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5提审抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `repair_id`(`assoc_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`, `assoc_id`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 120 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '样品检测关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_sample_order_checkinfo
-- ----------------------------
DROP TABLE IF EXISTS `qlty_sample_order_checkinfo`;
CREATE TABLE `qlty_sample_order_checkinfo`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `oid` int(11) NOT NULL COMMENT '单据ID',
  `check_time` varchar(9) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测时间',
  `batch_no` char(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次',
  `batch_num` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批号',
  `Brix` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'Brix(%)糖度',
  `pH` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'pH酸度',
  `net` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '液位',
  `pressure` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内压',
  `temperature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '温度 （战马显示）',
  `color` tinyint(1) NULL DEFAULT NULL COMMENT '色泽 0 不合格 1合格',
  `scent` tinyint(1) NULL DEFAULT NULL COMMENT '滋味 0 不合格 1合格 （战马显示）',
  `group_status` tinyint(1) NULL DEFAULT NULL COMMENT '组织状态 0 不合格 1合格 （战马显示）',
  `impurity` tinyint(1) NULL DEFAULT NULL COMMENT '杂质 0 无 1 有 （战马显示）',
  `taste` tinyint(1) NULL DEFAULT NULL COMMENT '味道 0 不合格 1 合格 （红牛显示）',
  `purity` varchar(9) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '纯净度 （红牛显示）',
  `check_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '其他检验信息（迭接长度/迭接率/盖钩顶隙/罐钩顶隙/身钩长度/盖钩长度/宽度/厚度）',
  `density` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '紧密度%（战马显示）',
  `wrinkle` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '皱纹度%（红牛显示）',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不合格 1合格',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员签字',
  `is_recheck` int(11) NULL DEFAULT 0 COMMENT '是否复检 0 否 1 是',
  `recheck_ret` tinyint(1) NULL DEFAULT NULL COMMENT '复检结果 null 无 0 不合格 1 合格 2部分合格 3 复检中 ',
  `recheck_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检编号',
  `recheck_uid` int(11) NULL DEFAULT NULL COMMENT '复检人ID',
  `recheck_user` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检人',
  `recheck_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检签字',
  `re_date` date NULL DEFAULT NULL COMMENT '复检日期',
  `re_step` tinyint(1) NULL DEFAULT 0 COMMENT '复检步骤 0 未完成 1 已完成',
  `re_ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检创建人',
  `recheck_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复检备注',
  `is_mapping` int(11) NULL DEFAULT 0 COMMENT '是否调机 0 否 1 是',
  `mapping_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机单号',
  `mapping_ret` tinyint(1) NULL DEFAULT NULL COMMENT '调机结果 null 无 0 不合格 1 合格 2 调机中',
  `mapping_date` date NULL DEFAULT NULL COMMENT '调机日期',
  `mapping_ct_date` datetime NULL DEFAULT NULL COMMENT '调机创建时间',
  `mapping_uid` int(11) NULL DEFAULT NULL COMMENT '调机人ID',
  `mapping_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机人名称',
  `mapping_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机签字',
  `mapping_step` tinyint(1) NULL DEFAULT NULL COMMENT '调机步骤 0 未完成 1 已完成',
  `mapping_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '调机备注',
  `node` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工序节点',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `batch_no`(`oid`, `batch_no`, `batch_num`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 167 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '样品检验信息' ROW_FORMAT = Dynamic;

