-- ----------------------------
-- Table structure for qlty_scale_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_scale_order`;
CREATE TABLE `qlty_scale_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `scaledevice_ids` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '选择的型号/规格电子秤ID，多个用逗号隔开',
  `scaledevice_types` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '选择的型号/规格电子秤，多个用斜杠隔开',
  `check_date` date NOT NULL COMMENT '检测日期',
  `use_place_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '使用地点ID',
  `use_place` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '使用地点',
  `temperature` decimal(9, 2) NOT NULL COMMENT '温度',
  `humidity` decimal(9, 2) NOT NULL COMMENT '温度',
  `weight_val` decimal(9, 2) NULL DEFAULT NULL COMMENT '砝码重量',
  `weight_unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '砝码重量单位',
  `max_val` decimal(9, 2) NULL DEFAULT NULL COMMENT 'MAX重量',
