-- ----------------------------
-- Table structure for qlty_sugar_microbe_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_sugar_microbe_order`;
CREATE TABLE `qlty_sugar_microbe_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `check_date` date NOT NULL COMMENT '检测日期',
  `sample_date` date NOT NULL COMMENT '取样日期',
  `num` decimal(9, 2) NULL DEFAULT NULL COMMENT '进货总数',
  `unit` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进货总数单位',
  `source_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检来源单号',
  `execp_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常处置单号',
  `batch_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批号',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检测员1uid',
  `check_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员1名字',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员1签字',
  `check_uid2` int(11) NULL DEFAULT NULL COMMENT '检测员2uid',
  `check_user2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员2名字',
  `check_sign2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员2签字',
  `commit_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果；0：不合格；1：合格 2 部分合格',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `sample_date`(`sample_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 175 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '白砂糖微生物检验报告' ROW_FORMAT = Dynamic;

