  `microbe_total1` int(11) NULL DEFAULT NULL COMMENT '细菌总数1',
  `microbe_total2` int(11) NULL DEFAULT NULL COMMENT '细菌总数2',
  `microbe_total3` int(11) NULL DEFAULT NULL COMMENT '细菌总数3',
  `stock_id` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存ID',
