CREATE TABLE `qlty_supplier_audit_plan_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据id',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 149 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商审核计划日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_supplier_audit_plan_visit
-- ----------------------------
DROP TABLE IF EXISTS `qlty_supplier_audit_plan_visit`;
CREATE TABLE `qlty_supplier_audit_plan_visit`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '访问人员ID',
  `user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '访问人员名称',
  `dept` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属部门',
  `sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '访问人签名',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商审核计划访问信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_supplier_audit_setting
-- ----------------------------
DROP TABLE IF EXISTS `qlty_supplier_audit_setting`;
CREATE TABLE `qlty_supplier_audit_setting`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL COMMENT '类型 1 分钟 2 小时 3 天',
  `num` int(11) NULL DEFAULT NULL COMMENT '数量',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商审核计划访问提醒' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_syrup_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_syrup_order`;
CREATE TABLE `qlty_syrup_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `check_date` date NULL DEFAULT NULL COMMENT '检测日期',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '完成状态 0 未完成 1 已完成',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '版本类型ID',
  `version_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本名称',
  `class_group` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组',
  `class` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `pro_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产编号',
  `batch_no` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批次',
  `batch_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批号',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '生产产线ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产产线名称',
  `name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不合格 1 合格 2 部分合格',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `class_group`(`pro_no`, `pro_date`, `line_id`, `class`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 130 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '糖浆检验报告' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_syrup_order_checkinfo
-- ----------------------------
DROP TABLE IF EXISTS `qlty_syrup_order_checkinfo`;
CREATE TABLE `qlty_syrup_order_checkinfo`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验时间',
  `batch_no` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次',
  `batch_number` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `brix` decimal(9, 1) NULL DEFAULT NULL COMMENT 'Brix',
  `sample_uid` int(11) NULL DEFAULT NULL COMMENT '送样人ID',
  `sample_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样人名称',
  `sample_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样人签名',
  `sample_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样时间',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检验员ID',
  `check_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员名称',
  `check_user_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员签字',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不合格 1 合格',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `batch_number`(`batch_number`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 71 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '糖浆检验报告-检验信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_template_list
-- ----------------------------
DROP TABLE IF EXISTS `qlty_template_list`;
CREATE TABLE `qlty_template_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `template_module` tinyint(1) NOT NULL COMMENT '所属模块; 0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统 -1 其他',
  `document_type` int(11) NOT NULL COMMENT '表单类型',
  `table_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '表单名称',
  `base_id` tinyint(1) NOT NULL DEFAULT 0 COMMENT '基地',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '表单状态 0 未设置 1 已设置',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `document_type`(`document_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2948 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '自定义模板列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_template_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_template_log`;
CREATE TABLE `qlty_template_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '日志类型 0 操作类型 1 审批类型',
  `act` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日志信息',
  `act_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 188 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '自定义模板配置-日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_template_set
-- ----------------------------
DROP TABLE IF EXISTS `qlty_template_set`;
CREATE TABLE `qlty_template_set`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `p_id` int(11) NOT NULL COMMENT '父级ID',
  `number_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '编号',
  `type` tinyint(1) NOT NULL COMMENT '导出类型 1 单条记录 2 列表数据导出',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态 0 禁用 1 启用',
  `brand` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产品大类',
  `sku` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '产品类型',
  `meter_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集表类型 0：电表；1：水表；2：蒸汽表 3：燃气表；4：柴油',
  `wh_inspect_std_id` tinyint(2) NULL DEFAULT NULL COMMENT '检验项目类型；1：纸皮；2：热缩膜；3：白砂糖；4：热熔胶',
  `pro_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验项目名称',
  `test_type` tinyint(1) NULL DEFAULT NULL COMMENT '测试类型 1 试水 2 试红牛-普通 3 试红牛-强化 4 试战马-灌装',
  `clean_microbe` tinyint(1) NULL DEFAULT NULL COMMENT '清洗杀菌 1 无水柠檬菌 2 二氧化氯 3 氢氧化钠',
  `group` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '组别',
  `export_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '导出命名规则',
  `json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '模板设置数据',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `p_id`(`p_id`, `type`, `brand`, `sku`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 648 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_uv_determine
-- ----------------------------
DROP TABLE IF EXISTS `qlty_uv_determine`;
CREATE TABLE `qlty_uv_determine`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '启用状态 0：停用;1：启用；',
  `open_time` datetime NULL DEFAULT NULL COMMENT '启用时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '截止时间',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `check_time` varchar(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时间',
  `batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次',
  `batch_number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `soluble_solid_val` decimal(18, 1) NULL DEFAULT NULL COMMENT '可溶性固形物',
  `ph_val` decimal(18, 2) NULL DEFAULT NULL COMMENT 'pH',
  `taurine_val` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '牛磺酸',
  `caffeine_val` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '咖啡因',
  `abs_val` decimal(18, 3) NULL DEFAULT NULL COMMENT 'ABS',
  `nm_val` decimal(18, 1) NULL DEFAULT NULL COMMENT 'nm',
  `class_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1:红牛-普通型;ND1-2:红牛-强化型;ND2-1 战马灌装;',
  `ct_uid` int(11) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(11) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `dept_id` int(11) UNSIGNED NULL DEFAULT 0 COMMENT '部门id',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'uk判定表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_vb12_check_list
-- ----------------------------
DROP TABLE IF EXISTS `qlty_vb12_check_list`;
CREATE TABLE `qlty_vb12_check_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检测单号',
  `brand` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型',
  `pro_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `is_first` tinyint(1) NULL DEFAULT 0 COMMENT '是否为首次出库 0 否 1 是',
  `content_smaple_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内容物入库编号',
  `sample_num` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '留样重量',
  `in_wh_date` datetime NULL DEFAULT NULL COMMENT '入库日期',
  `ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次号（内部批次）',
  `original_ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `barcode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料代码',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料名称',
  `stock_id` int(11) NULL DEFAULT NULL COMMENT '库存明细表ID',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不合格 1 合格 2 异常解决',
  `in_wh_original` decimal(11, 4) NULL DEFAULT NULL COMMENT '原入库库存（净重）',
  `in_wh_weight` decimal(11, 4) NULL DEFAULT NULL COMMENT '入库毛重（含瓶）',
  `is_complete` tinyint(1) NULL DEFAULT NULL COMMENT '是否外观完整； 0:否,1:是',
  `is_weigh` tinyint(1) NULL DEFAULT NULL COMMENT '是否入库称重； 0:否,1:是',
  `is_check_pk` tinyint(1) NULL DEFAULT NULL COMMENT '是否核对外包装：0:否,1:是',
  `is_info_accord` tinyint(1) NULL DEFAULT NULL COMMENT '是否条码包装信息一致：0:否,1:是',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '核对人签名',
  `check_time` datetime NULL DEFAULT NULL COMMENT '核对时间',
  `in_wh_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库单号',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `stock_id`(`stock_id`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `original_ph_no`(`original_ph_no`) USING BTREE,
  INDEX `sup_name`(`sup_name`) USING BTREE,
  INDEX `in_wh_date`(`in_wh_date`) USING BTREE,
  INDEX `check_res`(`check_res`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 45 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Vb12入库检测单' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_vb12_user
-- ----------------------------
DROP TABLE IF EXISTS `qlty_vb12_user`;
CREATE TABLE `qlty_vb12_user`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL COMMENT '人员ID',
  `user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '人员名称',
  `user_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '人员编号',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态 0 禁用 1 启用',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'Vb12人员称量编号' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_vb_in_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_vb_in_assoc`;
CREATE TABLE `qlty_vb_in_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'vb12入库单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_vb_in_goods
-- ----------------------------
DROP TABLE IF EXISTS `qlty_vb_in_goods`;
CREATE TABLE `qlty_vb_in_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) NULL DEFAULT 0 COMMENT '物料id(货品id)',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT 'vb12入库单列表ID',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料名称',
  `barcode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '条码',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格型号',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单价',
  `in_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '入库数量',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量(变动)',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `supplier_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `pro_time` datetime NULL DEFAULT NULL COMMENT '生产日期',
  `serial_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流水号',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ph_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批号',
  `warehouse_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '仓库ID',
  `warehouse_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `is_add` tinyint(1) NULL DEFAULT 0 COMMENT '0未入库,1已入库',
  `dept_id` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '部门id',
  `exp_time` datetime NULL DEFAULT NULL COMMENT '到期日期',
  `ws_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '库位',
  `is_gen_uniq` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成唯一；0:不生成,1:生成',
  `is_complete` tinyint(1) NULL DEFAULT 0 COMMENT '是否外观完整；0:否,1:是',
  `is_weigh` tinyint(1) NULL DEFAULT 0 COMMENT '是否入库称重；0:否,1:是',
  `is_check_pk` tinyint(1) NULL DEFAULT 0 COMMENT '是否核对外包装；0:否,1:是',
  `is_info_accord` tinyint(1) NULL DEFAULT 0 COMMENT '是否条码包装信息一致；0:否,1:是',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `exp_day` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '保质期',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id,记录入库时是通过哪个库存明细入库的',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `warehouse_name`(`warehouse_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `ws_code`(`ws_code`) USING BTREE,
  INDEX `is_gen_uniq`(`is_gen_uniq`) USING BTREE,
  INDEX `is_complete`(`is_complete`) USING BTREE,
  INDEX `is_weigh`(`is_weigh`) USING BTREE,
  INDEX `is_check_pk`(`is_check_pk`) USING BTREE,
  INDEX `is_info_accord`(`is_info_accord`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'vb12入库单商品明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_vb_in_list
-- ----------------------------
DROP TABLE IF EXISTS `qlty_vb_in_list`;
CREATE TABLE `qlty_vb_in_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '入库单号',
  `all_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '总价',
  `all_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '总数量',
  `file_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `collator_uid` int(10) NULL DEFAULT NULL COMMENT '核对人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `in_date` date NULL DEFAULT NULL COMMENT '入库日期',
  `in_wh_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '入库仓库ID',
  `in_wh_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库仓库名称',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '入库类型；0：vb12入库',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `wh_in_no`(`order_no`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `ct_name`(`ct_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'vb12入库单列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_vb_in_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_vb_in_log`;
CREATE TABLE `qlty_vb_in_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_in_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'vb12入库单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_version_list
-- ----------------------------
DROP TABLE IF EXISTS `qlty_version_list`;
CREATE TABLE `qlty_version_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `is_open` tinyint(1) NULL DEFAULT 1 COMMENT '是否开启；0：停用；1：开启',
  `class` tinyint(1) NULL DEFAULT NULL COMMENT '（纸皮必填）产品类别 1 箱内码 2 无箱内码',
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '版本类型 0 空罐 1 纸皮',
  `item` tinyint(1) NULL DEFAULT NULL COMMENT '空罐类型 1 促销型 2 非促销',
  `item_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料编号',
  `empty_item_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '空罐物料编号',
  `top_item_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖物料编号',
  `paper_picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '纸皮图片，多个用逗号隔开',
  `top_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '顶盖图片',
  `bottom_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '底盖图片',
  `can_body_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '罐身图片',
  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品分类 ND1 红牛 ND2 战马',
  `sku` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马罐装',
  `version_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本号',
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本名称',
  `order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最后修改人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `version_no`(`version_no`, `name`) USING BTREE,
  INDEX `is_open`(`is_open`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `brand`(`brand`, `sku`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 96 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '版本信息记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_warhorse_product_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_warhorse_product_order`;
CREATE TABLE `qlty_warhorse_product_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `check_date` date NOT NULL COMMENT '检测日期',
  `inspection_basis_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检验依据配置id',
  `inspection_basis_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验依据名称',
  `pro_date` date NOT NULL COMMENT '生产日期',
  `brand` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛；ND2 战马',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；',
  `report_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告编号',
  `report_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `check_result_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '检验结果json数据',
  `ph_soluble_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'ph和可溶性固形物检验员签名',
  `volume_sense_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '净含量与感官指标检验员签名',
  `seaming_inspection_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '卷封检测检验员签名',
  `microbe_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '微生物检验员签名',
  `label_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签标识检验员签名',
  `composition_analysis_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成分分析检验员签名',
  `ph_res` tinyint(1) NULL DEFAULT NULL COMMENT 'ph检测结果；0：不合格；1：合格',
  `soluble_solids_res` tinyint(1) NULL DEFAULT NULL COMMENT '可溶性固形物检测结果；0：不合格；1：合格',
  `volume_res` tinyint(1) NULL DEFAULT NULL COMMENT '净含量检测结果；0：不合格；1：合格',
  `internal_pressure_res` tinyint(1) NULL DEFAULT NULL COMMENT '内压检测结果；0：不合格；1：合格',
  `seaming_inspection_res` tinyint(1) NULL DEFAULT NULL COMMENT '卷封检测结果；0：不合格；1：合格',
  `sense_color_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-色泽检测结果；0：不合格；1：合格',
  `sense_smell_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-滋味和气味检测结果；0：不合格；1：合格',
  `sense_appearance_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-组织状态检测结果；0：不合格；1：合格',
  `sense_impurity_res` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-杂质检测结果；0：不合格；1：合格',
  `microbe_total_colony_res` tinyint(1) NULL DEFAULT NULL COMMENT '微生物-菌落总数检测结果；0：不合格；1：合格',
  `microbe_coliform_bacteria_res` tinyint(1) NULL DEFAULT NULL COMMENT '微生物-大肠菌群检测结果；0：不合格；1：合格',
  `microbe_saccharomyces_res` tinyint(1) NULL DEFAULT NULL COMMENT '微生物-酵母菌检测结果；0：不合格；1：合格',
  `microbe_mold_res` tinyint(1) NULL DEFAULT NULL COMMENT '微生物-霉菌检测结果；0：不合格；1：合格',
  `label_res` tinyint(1) NULL DEFAULT NULL COMMENT '标签标识检测结果；0：不合格；1：合格',
  `composition_analysis_res` tinyint(1) NULL DEFAULT NULL COMMENT '成分分析检测结果；0：不合格；1：合格',
  `ph_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ph测定值',
  `soluble_solids_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '可溶性固形物测定值',
  `volume_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '净含量测定值',
  `internal_pressure_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '内压测定值',
  `seaming_inspection_val` tinyint(1) NULL DEFAULT NULL COMMENT '卷封测定值；0：不符合标准要求；1：符合标准要求',
  `sense_color_val` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-色泽测定值；0：不符合标准要求；1：符合标准要求',
  `sense_smell_val` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-滋味和气味测定值；0：不符合标准要求；1：符合标准要求',
  `sense_appearance_val` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-组织状态测定值；0：不符合标准要求；1：符合标准要求',
  `sense_impurity_val` tinyint(1) NULL DEFAULT NULL COMMENT '感官指标-杂质测定值；0：不符合标准要求；1：符合标准要求',
  `microbe_total_colony_val` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微生物-菌落总数测定值',
  `microbe_coliform_bacteria_val` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微生物-大肠菌群测定值',
  `microbe_saccharomyces_val` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微生物-酵母菌测定值',
  `microbe_mold_val` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '微生物-霉菌测定值',
  `label_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签标识测定值，留空',
  `composition_analysis_val` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成分分析测定值，留空',
  `conclusion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '检测意见',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结论',
  `report_uid` int(11) NULL DEFAULT 0 COMMENT '报告人uid',
  `report_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告人',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果 0 不合格 1 合格 2 部分合格',
  `is_send` tinyint(1) NULL DEFAULT 0 COMMENT '是否发货 0 否 1 是 2 部分发货',
  `dept_id` int(11) NOT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `base_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '标准值配置',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `brand`(`brand`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '战马成品检验结果' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_warhorse_product_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_warhorse_product_order_assoc`;
CREATE TABLE `qlty_warhorse_product_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '报告单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 56 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '战马成品检验结果关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_warhorse_product_order_batch_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_warhorse_product_order_batch_detail`;
CREATE TABLE `qlty_warhorse_product_order_batch_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '报告单ID',
  `batch_info_id` int(10) NULL DEFAULT NULL COMMENT '批次明细id',
  `check_detail_id` int(10) NULL DEFAULT NULL COMMENT '微生物检验记录明细id',
  `batch` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号+批次',
  `check_order_id` int(10) NULL DEFAULT NULL COMMENT '微生物检验单id',
  `batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次',
  `batch_number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批号',
  `check_res` tinyint(1) NULL DEFAULT NULL COMMENT '检测结果；0：不合格；1：合格',
  `physical_mmrb_res` tinyint(1) NULL DEFAULT NULL COMMENT '理化及微生物结果 0 不合格 1 合格',
  `composition_analysis_res` tinyint(1) NULL DEFAULT NULL COMMENT '成分分析检验结果 0 不合格 1 合格',
  `product_roll_inspection_res` tinyint(1) NULL DEFAULT NULL COMMENT '成品卷封检验结果 0 不合格 1 合格',
  `product_label_identify_res` tinyint(1) NULL DEFAULT NULL COMMENT '标签标识检验结果 0 不合格 1 合格',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `sku` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别id',
  `line` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别名称',
  `is_send` tinyint(1) NULL DEFAULT 0 COMMENT '是否发货；0：未发货；1：已发货',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `phys_net_val` decimal(18, 4) NULL DEFAULT NULL COMMENT '净含量实测值',
  `phys_internal_pressure_val` decimal(18, 4) NULL DEFAULT NULL COMMENT '内压实测值',
  `ph_val` decimal(18, 4) NULL DEFAULT NULL COMMENT 'PH实测值',
  `soluble_solids_val` decimal(18, 4) NULL DEFAULT NULL COMMENT '可溶性固形物实测值',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `batch_no`(`batch_no`, `batch_number`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 121 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '战马成品检验结果批号信息明细' ROW_FORMAT = DYNAMIC;

