  `senses_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '感官性状和一般化学指标',
  `senses_ret` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '感官性状和一般化学指标 是否合格',
  `microbe_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '微生物检验结果（合格打\"√\"，不合格打\"×\"）',
  `microbe_ret` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '微生物检验结果  是否合格',
  `open_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '启用情况',
  `pca` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培养基批次-PCA',
  `m_endo` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培养基批次-M-endo',
  `mea` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培养基批次-MEA',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `oid`(`oid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '水处理微生物检验信息' ROW_FORMAT = Dynamic;

