  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 170 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_week_check_count
-- ----------------------------
DROP TABLE IF EXISTS `qlty_week_check_count`;
CREATE TABLE `qlty_week_check_count`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '汇总类型 0 公司级 1部门级',
  `check_date` date NOT NULL COMMENT '检查日期',
  `check_start_date` date NOT NULL COMMENT '排查周期-开始时间',
  `check_end_date` date NULL DEFAULT NULL COMMENT '排查周期-结束时间',
  `check_month` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查月份',
  `check_week` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查周',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果 0 不合格 1合格 2 部分合格',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人签字',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检查人ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人名称',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_no`(`type`, `order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_ret`(`check_ret`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 587 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据-汇总' ROW_FORMAT = Dynamic;

