-- ----------------------------
-- Table structure for qlty_week_check_group_setting
-- ----------------------------
DROP TABLE IF EXISTS `qlty_week_check_group_setting`;
CREATE TABLE `qlty_week_check_group_setting`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '设置类型 0 公司级 1 部门级',
  `rule` tinyint(1) NOT NULL DEFAULT 1 COMMENT '自查规则 1 自定义',
  `time` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '自查发起时间',
  `is_remind` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否开启提醒功能 0 关闭 1 开启',
  `remind_start_time` tinyint(1) NULL DEFAULT 0 COMMENT '提醒开始时间 0 按创建时间',
  `remind_type` tinyint(1) NULL DEFAULT 0 COMMENT '提醒类型 0 按天 1 按小时',
  `remind_cycle` int(3) NULL DEFAULT NULL COMMENT '提醒周期(小时/次)',
  `remind_times` int(3) NULL DEFAULT NULL COMMENT '提醒次数',
  `no_remind` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否开启节假日不提醒功能 0 关闭 1 开启',
  `remind_uid` int(11) NULL DEFAULT NULL COMMENT '是否提醒自查人 0 否 1 是',
  `pg_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品管接收人，多个用逗号隔开',
  `sc_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产接收人，多个用逗号隔开',
  `cy_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '储运接收人，多个用逗号隔开',
  `xz_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政接收人，多个用逗号隔开',
  `is_overdue` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否开启逾期预警 0 关闭 1 开启',
  `overdue_day` int(3) NULL DEFAULT NULL COMMENT '于逾期多少天开启',
  `overdue_cycle` int(3) NULL DEFAULT NULL COMMENT '逾期周期(小时/次)',
  `overdue_remind_times` int(3) NULL DEFAULT NULL COMMENT '逾期提醒次数',
  `overdue_pg_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逾期品管接收人，多个用逗号隔开',
  `overdue_sc_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逾期生产接收人，多个用逗号隔开',
  `overdue_cy_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逾期储运接收人，多个用逗号隔开',
  `overdue_xz_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '逾期行政接收人，多个用逗号隔开',
  `overdue_remind_uid` int(11) NOT NULL COMMENT '是否逾期提醒自查人 0 否 1 是',
  `rectify_uids` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改信息接收人，多个用逗号隔开',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`, `overdue_remind_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '食品安全周自查-项目组-预警及信息通知' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_week_check_list
-- ----------------------------
DROP TABLE IF EXISTS `qlty_week_check_list`;
CREATE TABLE `qlty_week_check_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `p_id` int(11) NOT NULL COMMENT '汇总ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '单据类型 0 公司及自查记录 1 品管部自查记录 2 生产部自查记录 3 储运部自查记录 4 行政部自查记录',
  `check_date` date NOT NULL COMMENT '检查日期',
  `check_start_date` date NOT NULL COMMENT '排查周期-开始时间',
  `check_end_date` date NULL DEFAULT NULL COMMENT '排查周期-结束时间',
  `check_month` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查月份',
  `check_week` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查周',
  `check_ret` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查结果 NULL 未开始 0 不合规 1合规 2 部分合规 3 自查中',
  `assign_status` tinyint(1) NULL DEFAULT 0 COMMENT '指派状态 0 待指派 1 已指派 2 无需指派',
  `rectify_status` tinyint(1) NULL DEFAULT NULL COMMENT '整改结果 0 未整改 1 已整改 2 部分整改 3 整改中',
  `finish_date` date NULL DEFAULT NULL COMMENT '排查完成日期',
  `check_sign1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查人签字1',
  `check_sign2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查人签字2',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检查人ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人',
  `commit_uid` int(11) NULL DEFAULT NULL COMMENT '提交人ID',
  `commit_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人名称',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `reviewer_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批备注',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `is_report` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成报告',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_no`(`order_no`, `type`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_ret`(`check_ret`) USING BTREE,
  INDEX `p_id`(`p_id`) USING BTREE,
  INDEX `assign_status`(`assign_status`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10518 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_week_check_list_set
-- ----------------------------
DROP TABLE IF EXISTS `qlty_week_check_list_set`;
CREATE TABLE `qlty_week_check_list_set`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `type` tinyint(1) NOT NULL COMMENT '类型 0 公司级 1 部门级',
  `rule` tinyint(1) NOT NULL DEFAULT 1 COMMENT '自查规则 0 每天 1 生产日',
  `time` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '自查发起时间',
  `is_remind` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否开启提醒功能 0 关闭 1 开启',
  `remind_start_time` tinyint(1) NOT NULL DEFAULT 0 COMMENT '提醒开始时间 0 按创建时间',
  `remind_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '提醒类型 0 按天 1 按小时',
  `remind_cycle` int(3) NOT NULL COMMENT '提醒周期(小时/次)',
  `remind_times` int(3) NOT NULL COMMENT '提醒次数',
  `rc_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接收人，多个用逗号隔开',
  `is_overdue` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否开启逾期预警 0 关闭 1 开启',
  `overdue_day` int(3) NOT NULL COMMENT '于逾期多少天开启',
  `overdue_cycle` int(3) NOT NULL COMMENT '逾期周期(小时/次)',
  `overdue_remind_times` int(3) NOT NULL COMMENT '逾期提醒次数',
  `overdue_rc_uids` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '逾期接收人，多个用逗号隔开',
  `rectify_uids` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '整改信息接收人，多个用逗号隔开',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10510 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据提醒设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_week_check_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_week_check_log`;
CREATE TABLE `qlty_week_check_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '日志类型 0 操作类型 1 审批类型',
  `act` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日志信息',
  `act_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `assoc_id`(`order_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 341 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_weighing_assoc`;
CREATE TABLE `qlty_weighing_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 199 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重记录关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_detail
-- ----------------------------
DROP TABLE IF EXISTS `qlty_weighing_detail`;
CREATE TABLE `qlty_weighing_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `s_index` int(11) NULL DEFAULT NULL COMMENT '称重领用唯一索引',
  `order_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '称重记录ID',
  `batch_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号，多个用,隔开',
  `stock_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库存ID，多个用,隔开',
  `supplier_names` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称，多个用,隔开',
  `sup_names` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称，多个用逗号隔开',
  `original_ph_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配方编号',
  `sort` int(11) NULL DEFAULT NULL COMMENT '配方编号顺序',
  `single_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '单个重量(克)',
  `pro_date` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `dev_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '偏差值(克)',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '是否合格；0：不合格；1：合格',
  `weigher` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称量人(复核人)',
  `is_mixed_batch` tinyint(1) NULL DEFAULT NULL COMMENT '是否混批；0：不是；1：是',
  `mixed_str` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '混批重量计算公式',
  `weigher_time` datetime NULL DEFAULT NULL COMMENT '称重时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '创建UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3101 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_detail_mixed
-- ----------------------------
DROP TABLE IF EXISTS `qlty_weighing_detail_mixed`;
CREATE TABLE `qlty_weighing_detail_mixed`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `s_index` int(11) NULL DEFAULT NULL COMMENT '领用明细索引',
  `p_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '称重明细-ID',
  `batch_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `supplier_names` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `sup_names` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配方编号',
  `weight_v` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '重量(克)',
  `pro_date` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '货品id',
  `stock_id` int(11) NULL DEFAULT NULL COMMENT '库存id',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `p_id`(`p_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 301 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重明细-混批记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_weighing_log`;
CREATE TABLE `qlty_weighing_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1066 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重记录单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_period_residue
-- ----------------------------
DROP TABLE IF EXISTS `qlty_weighing_period_residue`;
CREATE TABLE `qlty_weighing_period_residue`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `stock_id` int(11) NULL DEFAULT NULL COMMENT '库存id',
  `category_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品类',
  `barcode` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '条码',
  `batch_num` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `pro_date` datetime NULL DEFAULT NULL COMMENT '生产日期',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料名称',
  `pre_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '上期剩余(克)',
  `is_done` tinyint(4) NULL DEFAULT 0 COMMENT '是否已用完；0：未用完；1：已用完；',
  `order_id` int(11) NULL DEFAULT NULL COMMENT '物料称重单据id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人uid',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人uid',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 104 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重上期剩余记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_post_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_weighing_post_log`;
CREATE TABLE `qlty_weighing_post_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 155 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重记录传参日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_record
-- ----------------------------
DROP TABLE IF EXISTS `qlty_weighing_record`;
CREATE TABLE `qlty_weighing_record`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '物料id(货品id)',
  `weigher` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称量人',
  `weigher_id` int(11) NULL DEFAULT NULL COMMENT 'weigher_id',
  `reviewer` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核人',
  `reviewer_id` int(11) NULL DEFAULT NULL COMMENT '复核人ID',
  `weigher_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '称量人编号',
  `weigher_date` date NULL DEFAULT NULL COMMENT '称重日期',
  `pre_residue_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '上期剩余单号',
  `pre_residue_v` decimal(18, 4) NULL DEFAULT NULL COMMENT '上期剩余(KG)',
  `ct_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料名称',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单号',
  `warehouse_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库编码',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `return_balance_status` tinyint(4) NULL DEFAULT NULL COMMENT '退结余状态：NULL未发起,0已发起,1待审核,2已完成,3已驳回,4已撤回',
  `return_balance_weight` decimal(18, 6) NULL DEFAULT NULL COMMENT '退结余重量',
  `return_balance_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退库单号TK',
  `spec` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `out_wh_id` int(11) NULL DEFAULT NULL COMMENT '称料领出库id',
  `in_wh_id` int(11) NULL DEFAULT NULL COMMENT '配方入库id',
  `ref_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '参考值(克)(配方重量)',
  `err_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '误差值(克)',
  `rec_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '领料重量(克)',
  `dev_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '总误差(克)',
  `total_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '总重量(克)',
  `max_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '最大值(克)',
  `min_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '最小值(克)',
  `avg_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '平均值(克)',
  `rem_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '理论剩余重量(克)',
  `num` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '计量份数',
  `real_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '实际剩余重量(克)',
  `pre_v` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '上期剩余(克)',
  `dep_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '理论损耗(克)',
  `t_weight` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '理论称重',
  `total_weight` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '称重总重量',
  `a_quantity` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '实际分装用量',
  `less_weight` decimal(18, 4) NULL DEFAULT NULL COMMENT '原料结余',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `measure_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签字',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 2 COMMENT '保留小数',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `scale_id` int(11) UNSIGNED NULL DEFAULT NULL COMMENT '电子秤ID',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT NULL COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `sku` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品类sku',
  `category_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品类',
  `is_multi_scale_sync` tinyint(1) NULL DEFAULT 0 COMMENT '是否开启多称同步；0：否；1：是',
  `merge_identify` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标识一样，表示合并',
  `original_ph_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `unit_rand_str` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参考范围',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人uid',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '用户创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `sample_weight` decimal(12, 4) NULL DEFAULT NULL COMMENT '留样重量',
  `actual_loss` decimal(12, 4) NULL DEFAULT NULL COMMENT '实际损耗',
  `total_use_weight` decimal(12, 4) NULL DEFAULT NULL COMMENT '领用总重量',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `is_multi_scale_sync`(`is_multi_scale_sync`, `merge_identify`) USING BTREE,
  INDEX `category_name`(`category_name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 105 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物料称重记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_weighing_record_return
