  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据id',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '重量检测记录关联表日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_wip_order
-- ----------------------------
DROP TABLE IF EXISTS `qlty_wip_order`;
CREATE TABLE `qlty_wip_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `pro_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产订单号',
  `batch_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次',
  `batch_number` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批号',
  `product_type` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品名称 ND1-1 红牛维生素功能饮料 ND1-2 红牛维生素功能饮料（牛磺酸强化型） ND2-1 战马能量型维生素饮料',
  `brand` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品品牌 ND1 红牛 ND2 战马',
  `sku` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型 ND1-1 普通型 ND1-2 强化型 ND2-1 战马灌装 ND2-2 战马瓶装',
  `line_id` int(11) NOT NULL COMMENT '线别ID',
  `line_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '线别名称',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '版本ID',
  `version_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '版本名称',
  `workshop_id` tinyint(11) NULL DEFAULT NULL COMMENT '车间ID 1 - 3 ',
  `workshop_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名称车间一 -  车间三',
  `group_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班组',
  `class_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '班次',
  `pro_date` date NULL DEFAULT NULL COMMENT '生产日期',
  `order_date` date NULL DEFAULT NULL COMMENT '订单日期',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不及格 1及格',
  `check_date` date NOT NULL COMMENT '检测完成日期',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态 0 未完成 1已完成',
  `recheck_status` tinyint(1) NULL DEFAULT 0 COMMENT '复检状态 0 未复检 1 复检中 2 复检合格 3 复检部分合格 4 复检不合格',
  `total_cylinders` int(11) NULL DEFAULT NULL COMMENT '总缸数',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `batch_no`(`batch_no`) USING BTREE,
  INDEX `line_id`(`line_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 222 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '半成品检测单据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_wip_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `qlty_wip_order_assoc`;
CREATE TABLE `qlty_wip_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `assoc_id` int(10) UNSIGNED NOT NULL COMMENT '单据ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5提审抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `repair_id`(`assoc_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`, `assoc_id`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '半成品检测关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for qlty_wip_order_checkinfo
-- ----------------------------
DROP TABLE IF EXISTS `qlty_wip_order_checkinfo`;
CREATE TABLE `qlty_wip_order_checkinfo`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `oid` int(11) NOT NULL COMMENT '单据ID',
  `check_time` varchar(9) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测时间',
  `batch_no` char(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批次',
  `batch_num` char(8) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '批号',
  `color` tinyint(1) NULL DEFAULT NULL COMMENT '颜色 0 不合格 1合格',
  `scent` tinyint(1) NULL DEFAULT NULL COMMENT '滋味和气味 0 不合格 1合格',
  `look` tinyint(1) NULL DEFAULT NULL COMMENT '外观 0 不合格 1合格',
  `impurity` tinyint(1) NULL DEFAULT NULL COMMENT '杂质 0 无 1 有',
  `Brix` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'Brix(%)',
  `pH` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'pH',
  `CT` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'CT',
  `picture` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片',
  `sample` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '样品',
  `delta` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'CT - sample 差值',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员签字',
  `sample_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检时间',
  `sample_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送样人签名',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检验员ID',
  `check_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验员',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检验结果 0 不合格 1合格',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态 0 异常 1 正常',
  `excep_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常描述',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `oid`(`oid`, `batch_no`, `batch_num`, `check_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 238 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '半成品检验信息' ROW_FORMAT = Dynamic;

-- ----------------------------
