) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '称配料空气沉降检测记录关联表' ROW_FORMAT = Dynamic;

