  `formula_storage_room_2_val` int(11) NULL DEFAULT NULL COMMENT '配方暂存间实测值2',
  `sugar_conversion_room_2_val` int(11) NULL DEFAULT NULL COMMENT '化糖间实测值2',
  `charge_mixture_room1_2_val` int(11) NULL DEFAULT NULL COMMENT '配料间1实测值2',
