-- Table structure for qlty_wt_ingredient_air_settling_order_log
-- ----------------------------
DROP TABLE IF EXISTS `qlty_wt_ingredient_air_settling_order_log`;
CREATE TABLE `qlty_wt_ingredient_air_settling_order_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据id',
