-- ----------------------------
-- Table structure for report_acct
-- ----------------------------
DROP TABLE IF EXISTS `report_acct`;
CREATE TABLE `report_acct`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `month` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '月份',
  `title` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品编码',
  `spec` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `in_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '入库金额',
  `in_num` int(10) NULL DEFAULT 0 COMMENT '入库数量',
  `out_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '出库金额',
  `out_num` int(10) NULL DEFAULT 0 COMMENT '出库数量',
  `res_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '结存金额',
  `res_num` int(10) NULL DEFAULT 0 COMMENT '结存数量',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
