  UNIQUE INDEX `mb`(`month`, `barcode`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存核算' ROW_FORMAT = Dynamic;

