  `operate_end_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业时间结束',
  `operate_local` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业地点',
  `operate_unit` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业单位',
  `special_operate` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '涉及的其他特殊作业',
  `operate_scope` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '作业范围',
  `operate_scope_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '作业范围附图',
  `operate_scope_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业范围确认人签字图片',
  `site_hazard_identify` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '施工现场危害辨识',
  `safety_measures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全防范措施',
  `confirm_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '确认人签字图片',
  `guardian_verification_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监护人现场核查签字图片',
  `safety_education_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实施安全教育人签字图片',
  `educated_person_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接受教育人签字图片',
  `apply_unit_opinion_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请单位意见签字图片',
  `apply_unit_sign_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请单位意见签字时间',
  `operate_unit_opinion_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业单位意见签字图片',
  `operate_unit_sign_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业单位意见签字时间',
  `related_dept_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有关水、电、汽、工艺、设备等部门会签意见签字图片',
  `related_dept_sign_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有关水、电、汽、工艺、设备等部门会签意见签字时间',
  `before_operate_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '事前照片',
  `during_operate_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '事中照片',
  `after_operate_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '事后照片',
  `operate_unit_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业实施单位签字图片',
  `pro_leader_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目负责人签字图片',
  `dept_head_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业点所在部门负责人签字图片',
  `safe_measures_confirm_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全措施现场确认JSON数据',
  `sign_status` tinyint(1) NULL DEFAULT 0 COMMENT '签字状态；0：待现场确认签字；1：待项目负责人签字；2：待完工验收签字；3：签字已完成',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态；0：暂存；1：进行中；2：已完成；',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '建单部门id',
  `review_uid` int(11) NULL DEFAULT NULL,
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 42 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '动土作业记录表' ROW_FORMAT = Dynamic;

