  `accident_reason_analysis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '事故原因分析',
  `rel_dust_user_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '相关责任人员json数据',
  `rel_dust_user_id` int(11) NULL DEFAULT NULL COMMENT '相关责任人uid',
