  `pick` tinyint(1) NULL DEFAULT NULL COMMENT '接班叉车司机',
  `car_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车号',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `result` tinyint(1) NULL DEFAULT NULL COMMENT '电池 0=异常；1=正常',
  `result2` tinyint(1) NULL DEFAULT NULL COMMENT '电机 0=异常；1=正常',
  `result3` tinyint(1) NULL DEFAULT NULL COMMENT '制动装置轮胎 0=异常；1=正常',
  `result4` tinyint(1) NULL DEFAULT NULL COMMENT '倒车装置喇叭 0=异常；1=正常',
  `result5` tinyint(1) NULL DEFAULT NULL COMMENT '照明装置仪表 0=异常；1=正常',
  `result6` tinyint(1) NULL DEFAULT NULL COMMENT '车身是否异常 0=异常；1=正常',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常说明',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '电叉车日常检查' ROW_FORMAT = Dynamic;

