-- ----------------------------
-- Table structure for sec_ext_inspect_plan
-- ----------------------------
DROP TABLE IF EXISTS `sec_ext_inspect_plan`;
CREATE TABLE `sec_ext_inspect_plan`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `plan_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划编号',
  `executive_rule_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '执行规则类型；0：按上次执行时间；',
  `cycle_type` tinyint(2) NULL DEFAULT 0 COMMENT '循环周期,N代表N个月；',
  `plan_details_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计划明细单号',
  `plan_start_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间',
  `executor_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检验操作人id，多个用,隔开',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 2 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `notice_day` int(11) NULL DEFAULT 0 COMMENT '提醒时间（天数），提前N天通知提醒，默认0则不提前通知',
  `last_start_time` datetime NULL DEFAULT NULL COMMENT '上次执行时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '计划状态；0未开始；1：待检查；2：检查中；3：待审核；4：停用',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `plan_type` tinyint(1) NULL DEFAULT NULL COMMENT '检验计划名1计量器具检验；2特种设备检验',
  `check_type` tinyint(1) NULL DEFAULT NULL COMMENT '检验方式 1：外检；2：内检；3：年检',
  `check_unit_id` int(11) NULL DEFAULT NULL COMMENT '检验单位ID',
  `check_unit` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验单位',
  `check_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `turn_remind` int(10) NULL DEFAULT NULL COMMENT '转单提醒天数',
  `lq_remind` int(10) NULL DEFAULT NULL COMMENT '临期提醒天数',
  `lq_uids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '临期通知人ID，多个用,分隔',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `cycle_type`(`cycle_type`) USING BTREE,
  INDEX `plan_start_time`(`plan_start_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 38 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '外检计划表' ROW_FORMAT = Dynamic;

