-- ----------------------------
-- Table structure for sec_ext_inspect_record
-- ----------------------------
DROP TABLE IF EXISTS `sec_ext_inspect_record`;
CREATE TABLE `sec_ext_inspect_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检验单号',
  `check_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '检验方式；1外检、2内检、',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检验人',
  `check_date` date NULL DEFAULT NULL COMMENT '送检日期',
  `check_unit` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验单位',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系电话',
  `verification_date` date NULL DEFAULT NULL COMMENT '检定日期',
  `receive_date` date NULL DEFAULT NULL COMMENT '接收日期',
  `certificate_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '证书类型；1检定、2校准、',
  `other_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '其他费用',
  `total_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '合计总费用',
  `order_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态；0：待提审；1：待审核；2：已审核；3：待确认送检；4：待确认接收；5驳回；6撤回；7已完成',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '审核状态；状态 0=待确认送检；1=待确认报告(待提审)；2=审批中；3=审批撤回；4=审批通过(完成)；5=审批驳回',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '单据备注',
  `reject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回内容',
  `next_start_date` date NULL DEFAULT NULL COMMENT '下一次执行时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `order_status`(`order_status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '检查记录' ROW_FORMAT = DYNAMIC;

