-- ----------------------------
-- Table structure for sec_external_check_record_detail
-- ----------------------------
DROP TABLE IF EXISTS `sec_external_check_record_detail`;
CREATE TABLE `sec_external_check_record_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '库存记录id',
  `place_id` int(11) NULL DEFAULT NULL COMMENT '检查区域id',
  `place` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置',
  `scene_photo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场照片',
  `scene_video` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场视频',
  `describe` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全隐患描述',
  `measure` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '整改措施',
  `scale` tinyint(1) NULL DEFAULT 0 COMMENT '评估分级；1：一般事故隐患，2：重大事故隐患',
  `risk_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '风险类别；1：人的不安全行为；2：物的不安全状态；3管理上的缺陷；4环境的不安全因素',
  `risk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '存在风险',
  `danger_cate` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隐患类别',
  `legal_basis` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '法律法规依据',
  `duty_dept_id` int(11) NULL DEFAULT NULL COMMENT '检查部门',
  `dept_uid` int(11) NULL DEFAULT NULL COMMENT '检查部门负责人',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `dept_uid_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门负责人签字',
  `s_h_id` int(11) NULL DEFAULT NULL COMMENT '隐患整改单id',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 47 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '外部检查记录-明细' ROW_FORMAT = Dynamic;

-- ----------------------------
