-- ----------------------------
-- Table structure for sec_finite_space
-- ----------------------------
DROP TABLE IF EXISTS `sec_finite_space`;
CREATE TABLE `sec_finite_space`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `work_number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '作业票编号',
  `apply_unit_id` int(11) NULL DEFAULT NULL COMMENT '申请部门ID',
  `apply_unit_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请部门名称',
  `affiliated_unit` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有限空间所属单位',
  `space_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有限空间名称',
  `toxic_harmful_medium` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有毒有害介质-标准',
  `combustible_gas` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '可燃气-标准',
  `oxygen_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '氧含量-标准',
  `original_medium` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有限空间内原有介质名称',
  `operation_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业内容',
  `dept_manager` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业点所在部门现场负责人',
  `guardian_uid` int(11) NULL DEFAULT NULL COMMENT '监护人uid',
  `guardian_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监护人名字',
  `operation_staff_uid` int(11) NULL DEFAULT NULL COMMENT '参加作业人员uid',
  `operate_staff_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参加作业人员名字',
  `special_operations` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '涉及的其他特殊作业',
  `operate_local` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业地点及内容',
  `operate_start_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业实施时间开始',
  `operate_end_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业实施时间结束',
  `site_hazard_identify` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '施工现场危害辨识',
  `safety_measures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全防范措施',
  `confirm_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危害辨识及防范-确认人签字图片',
  `safe_measures_confirm_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全措施现场确认JSON数据',
  `guardian_verification_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全措施现场确认-监护人现场核查签字图片',
  `safety_education_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全措施现场确认-实施安全教育人签字图片',
  `educated_person_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全措施现场确认-接受教育人签字图片',
  `apply_unit_opinion_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责人签字确认-作业申请单位意见签字图片',
  `apply_unit_sign_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责人签字确认-作业申请单位意见签字时间',
  `construction_unit_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责人签字确认-作业点所在部门现场负责人签字图片',
  `construction_unit_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '负责人签字确认-作业点所在部门现场负责人签字时间',
  `before_operate_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '事前照片',
  `during_operate_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '事中照片',
  `after_operate_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '事后照片',
  `operate_unit_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完工验收签字确认-作业实施单位签字图片',
  `pro_leader_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完工验收签字确认-项目负责人签字图片',
  `dept_head_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完工验收签字确认-作业点所在部门负责人签字图片',
  `sign_status` tinyint(1) NULL DEFAULT 0 COMMENT '签字状态；0：待安全措施确认签字；1：待负责人确认签字；2：待完工验收确认签字；',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态；0：暂存；1：进行中；2：已完成；',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '建单部门id',
  `review_uid` int(11) NULL DEFAULT NULL,
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '有限空间作业记录表' ROW_FORMAT = Dynamic;

