-- ----------------------------
-- Table structure for sec_finite_space_gas_check
-- ----------------------------
DROP TABLE IF EXISTS `sec_finite_space_gas_check`;
CREATE TABLE `sec_finite_space_gas_check`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态：0暂存，1审批中，2已完成，3驳回，4撤回，5反审，6作废',
  `check_date` date NULL DEFAULT NULL COMMENT '检测日期',
  `check_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '检测人员uid',
  `check_user_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测人员姓名',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人签字图片',
  `check_user_sign_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人签字时间',
  `rel_work_number` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联作业证编号',
  `environment_is_qualified` tinyint(1) NULL DEFAULT NULL COMMENT '作业环境是否合格：1合格，2不合格',
  `h2s_unit_type` tinyint(1) NOT NULL DEFAULT 2 COMMENT '硫化氢单位选项：1=PPM，2=mg/m³',
  `co_unit_type` tinyint(1) NOT NULL DEFAULT 2 COMMENT '一氧化碳单位选项：1=PPM，2=mg/m³',
  `review_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '提审人uid',
  `reviewer_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人签字',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程数据',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单部门id',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除：0否，1是',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '创建人uid',
  `ct_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新人uid',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `check_uid`(`check_uid`) USING BTREE,
  INDEX `env_qualified`(`environment_is_qualified`) USING BTREE,
  INDEX `rel_work_order_no`(`rel_work_number`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '有限空间气体检测' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sec_finite_space_gas_check_assoc
-- ----------------------------
DROP TABLE IF EXISTS `sec_finite_space_gas_check_assoc`;
CREATE TABLE `sec_finite_space_gas_check_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
