-- ----------------------------
-- Table structure for sec_finite_space_gas_check_detail
-- ----------------------------
DROP TABLE IF EXISTS `sec_finite_space_gas_check_detail`;
CREATE TABLE `sec_finite_space_gas_check_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '所属单据id',
  `node_type` tinyint(1) NOT NULL COMMENT '节点类型：1作业前初始气体检测，2作业前再次气体检测，3作业中气体检测数据',
  `node_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '节点名称文本',
  `sort_no` int(10) UNSIGNED NOT NULL DEFAULT 1 COMMENT '节点内排序',
  `check_location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测位置',
  `check_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测时间',
  `oxygen_val` decimal(6, 1) NULL DEFAULT NULL COMMENT '氧气(%VOL)',
  `combustible_val` decimal(6, 1) NULL DEFAULT NULL COMMENT '可燃气体(%LEL)',
  `h2s_val` decimal(6, 1) NULL DEFAULT NULL COMMENT '硫化氢 mg/m³',
  `co_val` decimal(6, 1) NULL DEFAULT NULL COMMENT '一氧化碳 mg/m³',
  `oxygen_is_pass` tinyint(1) NULL DEFAULT NULL COMMENT '氧气是否合格：1合格，2不合格',
  `combustible_is_pass` tinyint(1) NULL DEFAULT NULL COMMENT '可燃气是否合格：1合格，2不合格',
  `h2s_is_pass` tinyint(1) NULL DEFAULT NULL COMMENT '硫化氢是否合格：1合格，2不合格',
  `co_is_pass` tinyint(1) NULL DEFAULT NULL COMMENT '一氧化碳是否合格：1合格，2不合格',
  `row_is_qualified` tinyint(1) NULL DEFAULT NULL COMMENT '当前行是否合格：1合格，2不合格',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人uid',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '更新人uid',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `order_node_sort`(`order_id`, `node_type`, `sort_no`) USING BTREE,
  INDEX `check_time`(`check_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 52 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '有限空间气体检测明细表' ROW_FORMAT = Dynamic;

