-- ----------------------------
-- Table structure for sec_hazard_report
-- ----------------------------
DROP TABLE IF EXISTS `sec_hazard_report`;
CREATE TABLE `sec_hazard_report`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `place` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置名称',
  `place_id` int(11) NULL DEFAULT NULL COMMENT '位置id',
  `place_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详情位置',
  `describe` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '隐患描述',
  `suggest` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '整改建议',
  `involve_dept_id` int(10) NULL DEFAULT NULL COMMENT '涉及部门id',
  `involve_dept_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '涉及部门',
  `involve_job_id` int(10) NULL DEFAULT NULL COMMENT '涉及岗位id',
  `involve_job_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '涉及岗位',
  `risk_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '风险类别；1：人的不安全行为；2：物的不安全状态；3管理上的缺陷；4环境的不安全因素',
  `scene_photo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场照片',
  `duty_dept_id` int(11) NULL DEFAULT NULL COMMENT '检查部门',
  `dept_uid` int(11) NULL DEFAULT NULL COMMENT '检查部门负责人',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `reason` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '不采纳原因',
  `amend_status` tinyint(1) NOT NULL COMMENT '整改状态:0--，1无需整改；2整改中；3整改完成',
  `status` tinyint(1) NOT NULL COMMENT '审核状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；',
  `order_status` tinyint(1) NOT NULL COMMENT '订单状态；0：暂存；1：待确认处理；2已确认，3：不采纳；4：已撤回',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `user_type` tinyint(1) NOT NULL COMMENT '用户类别 1内部员工 2访客',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `s_h_id` int(11) NULL DEFAULT NULL COMMENT '关联整改单id',
  `is_new` tinyint(1) NULL DEFAULT 0 COMMENT '1是加审批流后的新单',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_dept_id` int(11) NULL DEFAULT NULL COMMENT '创建人部门',
  `job_id` int(10) NULL DEFAULT NULL COMMENT '创建人岗位',
  `video_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '视频地址',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `dept_id`(`duty_dept_id`) USING BTREE,
  INDEX `user_type`(`user_type`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 236 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '安全隐患上报' ROW_FORMAT = Dynamic;

