-- ----------------------------
-- Table structure for sec_hazard_supervise_list
-- ----------------------------
DROP TABLE IF EXISTS `sec_hazard_supervise_list`;
CREATE TABLE `sec_hazard_supervise_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `hazard_id` int(10) NOT NULL COMMENT '危化清单id',
  `hazard_mat_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '危化品名称',
  `hazard_category` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险性类别,多个用逗号分隔',
  `hazard_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '危险性说明,多个用逗号分隔',
  `prevent_instruct` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '防范说明,多个用逗号分隔',
  `hazard_prop` tinyint(1) NULL DEFAULT NULL COMMENT '危险特性；1：易制爆；2：易制毒',
  `material_state` tinyint(1) NULL DEFAULT NULL COMMENT '物品特性状态；1：固态、2：液态、3：半固体、4：其他',
  `spec` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格（固体单位统一为g）',
  `hazard_props` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '企业具体负责人、现场负责人uid，多个用逗号隔开',
  `is_double_lock` tinyint(1) NULL DEFAULT NULL COMMENT '是否执行双人双锁；1：否；2：是',
  `is_fire_prevent` tinyint(1) NULL DEFAULT NULL COMMENT '储存环节是否具备技防；1：否；2：是',
  `is_resp_person` tinyint(1) NULL DEFAULT NULL COMMENT '储存环节是否有安全评价；1：否；2：是',
  `resp_person_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '《安全设施竣工验收评价报告》备注信息',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详细地址',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `file_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `ct_name`(`ct_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '危化品监管列表' ROW_FORMAT = Dynamic;

