-- ----------------------------
-- Table structure for sec_inspect_order
-- ----------------------------
DROP TABLE IF EXISTS `sec_inspect_order`;
CREATE TABLE `sec_inspect_order`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `maintenance_order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '保养单号',
  `plan_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划编号',
  `plan_id` int(11) NOT NULL COMMENT '计划id',
  `plan_details_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计划明细单号',
  `equipment_type_id` int(11) NOT NULL COMMENT '设备类型id',
  `equipment_type_title` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备类型名称',
  `equipment_id` int(11) NOT NULL COMMENT '设备id',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '保养状态；0待提审；1：待验证；2：已完成；3：已驳回；4：已撤回',
  `maintenance_start_time` datetime NULL DEFAULT NULL COMMENT '保养开始时间',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '保养完成时间',
  `plan_start_time` datetime NULL DEFAULT NULL COMMENT '计划执行时间',
  `reminder_time` datetime NULL DEFAULT NULL COMMENT '﻿提醒时间',
  `maintenance_level` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '保养级别',
  `maintenance_cost` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '保养费用',
  `equipment_cost` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '备件费用',
  `cycle_type` tinyint(2) NOT NULL COMMENT '周期类型；0：1个月；1：3个月；2：12个月；3：24个月',
  `director_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养负责人id，多个用,隔开',
  `other_uid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其它保养人id，多个用,隔开',
  `bar_title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备名称',
  `barcode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '设备条码',
  `img_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片信息',
  `plan_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养计划名称',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '固定资产编号',
  `use_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门id，层级用逗号隔开',
  `save_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置，用逗号隔开',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备型号',
  `is_replace` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '是否更换备件；0：不更换；1：更换；',
  `outsourced_units` int(11) NULL DEFAULT NULL COMMENT '外委单位',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `maintenance_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '保养描述',
  `chage_date` datetime NULL DEFAULT NULL COMMENT '换上时间',
  `down_date` datetime NULL DEFAULT NULL COMMENT '换下时间',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `equipment_type_id`(`equipment_type_id`) USING BTREE,
  INDEX `equipment_id`(`equipment_id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `main_order_no`(`maintenance_order_no`) USING BTREE,
  INDEX `plan_no`(`plan_no`) USING BTREE,
  INDEX `maintenance_level`(`maintenance_level`) USING BTREE,
  INDEX `equipment_type_id_2`(`equipment_type_id`, `status`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 73 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养工单表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sec_inspect_order_assoc
-- ----------------------------
DROP TABLE IF EXISTS `sec_inspect_order_assoc`;
CREATE TABLE `sec_inspect_order_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `maintenance_order_id` int(10) UNSIGNED NOT NULL COMMENT '采购单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `maintenance_order_id`, `type`) USING BTREE,
  INDEX `maintenance_order_id`(`maintenance_order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 453 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养工单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sec_inspect_order_details
-- ----------------------------
DROP TABLE IF EXISTS `sec_inspect_order_details`;
CREATE TABLE `sec_inspect_order_details`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `maintenance_order_id` int(11) NOT NULL COMMENT '检验工单id',
  `plan_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检验计划id',
  `plan_start_time` datetime NULL DEFAULT NULL COMMENT '计划开始时间',
  `next_maintenance_time` datetime NULL DEFAULT NULL COMMENT '下次计划保养时间',
  `check_res` tinyint(1) NULL DEFAULT 0 COMMENT '检验结论；1：合格；2：维修；3：报废；',
  `maintenance_area` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '保养部位',
  `maintenance_requirements` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '保养要求/标准',
  `maintenance_project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '保养项目标准名称',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 1 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `plan_id`(`plan_id`) USING BTREE,
  INDEX `is_maintain`(`check_res`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 123 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养计划表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sec_inspect_order_log
-- ----------------------------
DROP TABLE IF EXISTS `sec_inspect_order_log`;
CREATE TABLE `sec_inspect_order_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `maintenance_order_id` int(10) UNSIGNED NOT NULL COMMENT '保养工单id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `procure_id`(`maintenance_order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 276 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '保养工单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sec_inspection_plan
-- ----------------------------
DROP TABLE IF EXISTS `sec_inspection_plan`;
CREATE TABLE `sec_inspection_plan`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `start_time` date NULL DEFAULT NULL COMMENT '组织体检时间-开始',
  `end_time` date NULL DEFAULT NULL COMMENT '组织体检时间-结束',
  `company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '体检机构',
  `order_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报告编号',
  `physical_exam_type` tinyint(1) NULL DEFAULT 1 COMMENT '体检项目类型 1-常规体检 2-职业病体检',
  `job_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工种类型，多个用,隔开',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据备注',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=暂存；1=待审核；2=已完成；3=已驳回；4=已撤回；5=已作废',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '0=正常；1=已删除',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程数据',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `reviewer_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `is_delete`(`is_delete`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `start_time`(`start_time`) USING BTREE,
  INDEX `end_time`(`end_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '体检计划' ROW_FORMAT = Dynamic;

