-- ----------------------------
-- Table structure for sec_labor_protection_check
-- ----------------------------
DROP TABLE IF EXISTS `sec_labor_protection_check`;
CREATE TABLE `sec_labor_protection_check`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `number` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `check_time` datetime NOT NULL COMMENT '检查时间',
  `check_userid` int(10) NOT NULL COMMENT '检查人ID',
  `check_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检查人',
  `manager_uid` int(10) NOT NULL COMMENT '当班主管ID',
  `manager_user_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '当班主管',
  `manager_check_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主管签字',
  `check_result` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果1、未检---没有检查记录 2、部分正常---存在异常和正常 3、正常---全部正常 4、异常---全部异常',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态 1-暂存 2-待主管确认 3-已完成 4-已撤回 5-已驳回',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `check_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '签字',
  `ct_dept_id` int(10) NOT NULL COMMENT '创建人部门id',
  `ct_dept_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人部门',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `check_time`(`check_time`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `number`(`number`) USING BTREE,
  INDEX `check_result`(`check_result`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '生产劳保佩戴安全检查表' ROW_FORMAT = Dynamic;

