CREATE TABLE `sec_occupational_disease_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `declaration_type_id` tinyint(1) NOT NULL COMMENT '基本信息-申报类型id',
  `declaration_type_text` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-申报类型文本',
  `declaration_year` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基本信息-申报年份，格式如：2025',
  `declaration_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基本信息-申报日期，格式如：2025-12',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-单位名称',
  `credit_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-统一社会代码（信用代码）',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-单位注册地址（单位地址）',
  `work_place` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-作业场所地址（单位地址）',
  `enterprise_scale` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-企业规模',
  `economic_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-经济类型',
  `industry_category` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-行业分类',
  `filler_uid` int(11) NULL DEFAULT NULL COMMENT '基本信息-填报人ID',
  `filler_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-填报人姓名',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-填报人联系电话',
  `legal_representative` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-法定代表人',
  `legal_contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-法人联系电话',
  `occ_health_manager_uid` int(11) NULL DEFAULT NULL COMMENT '基本信息-职业卫生管理联系人ID',
  `occ_health_manager_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-职业卫生管理联系人姓名',
  `manager_mobile` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '基本信息-管理人手机号码',
  `registered_employee_num` int(11) NULL DEFAULT NULL COMMENT '基本信息-本单位在册工总数',
  `outsourced_employee_num` int(11) NULL DEFAULT NULL COMMENT '基本信息-外委人员总数',
  `registered_injured_num` int(11) NULL DEFAULT NULL COMMENT '基本信息-在册接害人数',
  `outsourced_injured_num` int(11) NULL DEFAULT NULL COMMENT '基本信息-外委接害人数',
  `total_injured_num` int(11) NULL DEFAULT NULL COMMENT '基本信息-接害总人数(含外委)',
  `cum_occ_num` int(11) NULL DEFAULT NULL COMMENT '基本信息-职业病累计人数',
  `occ_health_situation` int(11) NULL DEFAULT NULL COMMENT '职业卫生培训情况-职业病累计人数',
  `principal_trained` tinyint(1) NULL DEFAULT 1 COMMENT '职业卫生培训情况-主要负责人培训；1：未培训；2：已培训',
  `occ_health_staff_trained` tinyint(1) NULL DEFAULT 1 COMMENT '职业卫生培训情况-职业卫生管理人员培训；1：未培训；2：已培训',
  `exposed_pers_training_total` int(11) NULL DEFAULT NULL COMMENT '职业卫生培训情况-接触职业病危害因素年度培训总人数',
  `exposed_pers_training_rate` decimal(5, 2) NULL DEFAULT 0.00 COMMENT '职业卫生培训情况-接害人数培训率（百分比）',
  `military_secret_product` tinyint(1) NULL DEFAULT 2 COMMENT '主要产品-军工等涉密产品；1：是；2：否',
  `occ_type_dust_has` tinyint(1) NULL DEFAULT 2 COMMENT '职业病危害因素种类-粉尘-是否有粉尘，；1：是；2：否',
  `occ_type_dust_exposed_total_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-粉尘-接触总人数',
  `occ_type_dust_other_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-粉尘-其他粉尘接触人数',
  `occ_type_chem_has` tinyint(1) NULL DEFAULT 1 COMMENT '职业病危害因素种类-化学物质-是否有化学物质；1：无；2：有',
  `occ_type_chem_exposed_total_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-接触总人数',
  `occ_type_chem_ammonia_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-氨接触人数',
  `occ_type_chem_n_hexane_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-正己烷接触人数',
  `occ_type_chem_ipr_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-异丙酮接触人数',
  `occ_type_chem_ald_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-乙醛接触人数',
  `occ_type_chem_ethyl_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-乙酸乙酯接触人数',
  `occ_type_chem_hydrogen_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-硫化氢接触人数',
  `occ_type_chem_methanol_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-甲醇接触人数',
  `occ_type_chem_sodium_exposed_num` int(11) NULL DEFAULT NULL COMMENT '职业病危害因素种类-化学物质-氢氧化钠接触人数',
