CREATE TABLE `sec_pre_holiday_safety_inspection_detail`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '节前安全检查id',
  `item_id` int(10) NULL DEFAULT NULL COMMENT '节前安全检查-不符合问题描述id',
  `place_id` int(11) NULL DEFAULT NULL COMMENT '检查区域id',
