  `legal_basis` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '法律法规',
  `duty_dept_id` int(11) NULL DEFAULT NULL COMMENT '检查部门',
