  `review_user_signature` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人签字',
  `put_uid` int(10) NULL DEFAULT NULL COMMENT '检查人ID',
  `put_user` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '部门ID',
  `dept` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '异常说明',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查位置',
  `result` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果1 0=异常；1=正常',
  `result2` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果2 0=异常；1=正常',
  `result3` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果3 0=异常；1=正常',
  `result4` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果4 0=异常；1=正常',
  `result5` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果5 0=异常；1=正常',
  `result6` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果6 0=异常；1=正常',
  `result7` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果7 0=异常；1=正常',
  `result8` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果8 0=异常；1=正常',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `put_uid`(`put_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '隐患排查清单' ROW_FORMAT = Dynamic;

