-- ----------------------------
-- Table structure for sec_safety_education_detail
-- ----------------------------
DROP TABLE IF EXISTS `sec_safety_education_detail`;
CREATE TABLE `sec_safety_education_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_id` int(11) NOT NULL COMMENT '所属单据id',
  `date_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训时间',
  `education_level_id` tinyint(1) NOT NULL COMMENT '教育级别id，1：公司（厂）；2：部门 (车间)； 3：班组',
  `education_level_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '教育级别文本',
  `education_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '教育内容',
  `evaluation_res_id` tinyint(1) NOT NULL COMMENT '考核判定id，1：优秀；2：良好；3：合格；4：重考',
  `evaluation_res_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核判定文本',
  `review_method_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '考核方式id，多个用逗号隔开，1：提问；2：试卷考试（必需）；3：实地操作；4：演练',
  `review_method_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '考核方式文本',
  `class_hours` int(11) NULL DEFAULT NULL COMMENT '培训课时',
  `instructor_id` int(11) NOT NULL COMMENT '授课人uid',
  `instructor_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '授课人名字',
  `instructor_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '授课人签名图片',
  `trainee_id` int(11) NULL DEFAULT NULL COMMENT '被培训人uid',
  `trainee_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '被培训人名字',
  `trainee_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '被培训人签名图片',
  `trainee_signature_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '被培训人签字时间',
  `note` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 28 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '三级安全教育记录表明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sec_safety_education_file
-- ----------------------------
