-- ----------------------------
-- Table structure for sec_safety_education_record
-- ----------------------------
DROP TABLE IF EXISTS `sec_safety_education_record`;
CREATE TABLE `sec_safety_education_record`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `training_uid` int(11) NOT NULL COMMENT '培训人uid',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培训人姓名',
  `employee_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '工号',
  `gender` tinyint(1) NULL DEFAULT NULL COMMENT '性别,1:男;2:女',
  `allocation_dept_id` tinyint(1) NULL DEFAULT NULL COMMENT '分配部门id',
  `allocation_dept_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分配部门文本',
  `job_id` tinyint(1) NULL DEFAULT NULL COMMENT '岗位id',
  `job_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岗位文本',
  `in_company_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入公司时间',
  `sign_status` tinyint(1) NULL DEFAULT 0 COMMENT '签字状态；0：未签字；1：部分签字；2：全部签字；',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据备注',
  `education_level_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '教育级别文本',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态；0：暂存；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `dept_id` int(10) NOT NULL COMMENT '创建人部门ID',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `approve_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批备注',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 1-是 0-否',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '三级安全教育记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for sec_safety_hazard
-- ----------------------------
DROP TABLE IF EXISTS `sec_safety_hazard`;
CREATE TABLE `sec_safety_hazard`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `point_id` int(11) NULL DEFAULT NULL COMMENT '点检单ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `check_date` date NULL DEFAULT NULL COMMENT '检查日期',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '检查人',
  `duty_dept_id` int(11) NULL DEFAULT NULL COMMENT '检查部门',
  `dept_uid` int(11) NULL DEFAULT NULL COMMENT '检查部门负责人',
  `place_id` int(11) NULL DEFAULT NULL COMMENT '检查区域id',
  `place` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置',
  `place_detail` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '详情位置',
  `describe` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '安全隐患描述',
  `scale` tinyint(1) NULL DEFAULT 0 COMMENT '评估分级；1：一般事故隐患，2：重大事故隐患',
  `risk_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '风险类别；1：人的不安全行为；2：物的不安全状态；3管理上的缺陷；4环境的不安全因素',
  `risk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '存在风险',
  `danger_cate` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '隐患类别（安全整改建议）',
  `legal_basis` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '法律法规依据',
  `scene_photo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场照片',
  `measure` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '整改措施',
  `duty_uid` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改责任人',
  `execute_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '实施人uid,多个用逗号隔开',
  `plan` tinyint(1) NULL DEFAULT NULL COMMENT '整改计划；1：限时整改。2：暂不处理',
  `time_limit` tinyint(1) NULL DEFAULT 0 COMMENT '整改时限；1：立即整改，2：计划整改，',
  `planned_completion_time` date NULL DEFAULT NULL COMMENT '计划完成时间',
  `emergency_measure` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '应急处置措施',
  `capital` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '整改资金',
  `amend_time` datetime NULL DEFAULT NULL COMMENT '整改时间',
  `amend_feedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整改反馈',
  `after_photo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整改后照片',
  `accept_time` datetime NULL DEFAULT NULL COMMENT '验收时间',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `order_status` tinyint(1) NULL DEFAULT NULL COMMENT '订单状态；0：暂存；1：待部门确认；2已撤回，3：待执行整改；4：待审核；5：已驳回；6:已完成；',
  `status` tinyint(1) NULL DEFAULT NULL COMMENT '审核状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；7：入库待确认',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检测员签名图片',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '复核员签名图片，多个用,隔开',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `h_r_id` int(11) NULL DEFAULT NULL COMMENT '关联单id',
  `order_type` tinyint(1) NULL DEFAULT 0 COMMENT '关联单据类型0隐患上报1外部检查记录2节前安全检查3设备点检单(点检异常记录)',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `video_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '现场视频',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '风险类型',
  `choose` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险选项数据',
  `risk_level` tinyint(1) NULL DEFAULT NULL COMMENT '风险等级，0=1级；1=2级；2=3级；3=4级；4=5级',
  `level_type_id` tinyint(1) NULL DEFAULT NULL COMMENT '级别下标，0=厂级；1=部门级；2=班组级',
  `level_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '级别名称',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `dept_id`(`duty_dept_id`) USING BTREE,
  INDEX `duty_uid`(`duty_uid`) USING BTREE,
  INDEX `order_status`(`order_status`) USING BTREE,
  INDEX `scale`(`scale`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 518 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '安全隐患' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for sec_safety_hazard_assoc
-- ----------------------------
DROP TABLE IF EXISTS `sec_safety_hazard_assoc`;
CREATE TABLE `sec_safety_hazard_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
