-- ----------------------------
-- Table structure for secure_access_control_config
-- ----------------------------
DROP TABLE IF EXISTS `secure_access_control_config`;
CREATE TABLE `secure_access_control_config`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `rel_id` int(11) NULL DEFAULT 0 COMMENT '采集表名id',
  `rel_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采集表名',
  `rel_key` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备配置的key，IP+端口+站号',
  `direction` tinyint(1) NULL DEFAULT NULL COMMENT '进出方向；1：进；2：出',
  `last_gather_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最近采集时间',
  `num` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '读数',
  `ip` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'IP',
  `port` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '端口',
  `max_user_num` int(11) NULL DEFAULT 0 COMMENT '门禁用户数',
  `rel_user_num` int(11) NULL DEFAULT 0 COMMENT '授权关联用户数',
  `notice_user_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息通知人uid,多个用逗号隔开',
  `notice_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息通知人文本',
  `use_addr_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用地点id（区域位置）',
  `use_addr_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用地点文本（区域位置）',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人ID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `rel_id`(`rel_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '门禁配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for secure_access_control_config_rel_detail
-- ----------------------------
