-- ----------------------------
-- Table structure for secure_check_detail
-- ----------------------------
DROP TABLE IF EXISTS `secure_check_detail`;
CREATE TABLE `secure_check_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `group_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '自查组',
  `serial` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '序号',
  `check_self_item` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查项目',
  `check_self_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查内容',
  `check_self_method` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查方法',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '是否合规 0 否 1 是',
  `question_num` int(11) NULL DEFAULT NULL COMMENT '问题数',
  `question` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存在问题',
  `question_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '问题图片',
  `after_question` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问题调整之后',
  `rectify_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改措施',
  `rectify_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整改图片',
  `rectify_ret` tinyint(1) NULL DEFAULT NULL COMMENT '整改结果 0 未整改 1 已整改 2 整改中',
  `rectify_user_id` int(11) NULL DEFAULT NULL COMMENT '整改人ID',
  `rectify_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改人',
  `accept_uid` int(11) NULL DEFAULT NULL COMMENT '验收人ID',
  `accept_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '验收人名称',
  `accept_date` date NULL DEFAULT NULL COMMENT '验收时间',
  `rectify_time` datetime NULL DEFAULT NULL COMMENT '整改时间',
  `after_rectify_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改措施之后',
  `type_id` int(11) NULL DEFAULT NULL COMMENT '问题类型ID',
  `type_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问题类型名称',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇总备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '每日自查单据信息' ROW_FORMAT = DYNAMIC;

