-- ----------------------------
-- Table structure for secure_risk_plan_detail
-- ----------------------------
DROP TABLE IF EXISTS `secure_risk_plan_detail`;
CREATE TABLE `secure_risk_plan_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '所属单据id',
  `risk_detail_id` int(11) NOT NULL COMMENT '风险点清单管理明细id',
  `risk_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险点编码（如：FXD25120510）',
  `risk_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险点名称（如：宿舍）',
  `addr_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所在区域名称（如：宿舍）',
  `rel_addr_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联地点名称（如：办公室）',
  `rel_addr_id` int(11) NULL DEFAULT NULL COMMENT '关联地点id',
  `level` int(1) NULL DEFAULT NULL COMMENT '风险等级 1 重大风险 2 较大风险 3 一般风险 4 低风险 5 其他',
  `level_text` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险等级文本（如：重大风险、一般风险）',
  `endanger` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '危险因素（危害因素描述）',
  `measure` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '主要控制措施',
  `cycle` tinyint(1) NULL DEFAULT NULL COMMENT '管控周期 1 每日 2 每月 3 每周',
  `dust_dept_id` int(11) NULL DEFAULT NULL COMMENT '责任部门id',
  `dust_dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任部门名称',
  `dust_uid` int(11) NULL DEFAULT NULL COMMENT '责任人uid',
  `dust_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任人姓名',
  `control_level` tinyint(1) NULL DEFAULT NULL COMMENT '管控层级 1 公司级 2 部门 3 车间 4 班组 5 岗位',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件图片（JSON数组或URL列表）',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人ID',
  `ct_uid` int(11) NOT NULL COMMENT '创建人ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人名称',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `risk_code`(`risk_code`) USING BTREE,
  INDEX `level_text`(`level_text`) USING BTREE,
  INDEX `cycle`(`cycle`) USING BTREE,
  INDEX `control_level`(`control_level`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风险管控计划(清单)单据明细' ROW_FORMAT = Dynamic;

