) ENGINE = InnoDB AUTO_INCREMENT = 70 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风险点清单管理' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for secure_risk_poit_info
-- ----------------------------
DROP TABLE IF EXISTS `secure_risk_poit_info`;
CREATE TABLE `secure_risk_poit_info`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `endanger` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '危害因素',
  `type_id` tinyint(1) NULL DEFAULT NULL COMMENT '所属分类ID',
  `type_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属分类名称',
  `accident_type_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事故类型ID,多个用逗号隔开',
  `accident_type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '事故类型名称,多个用逗号隔开',
  `measure` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '主要管控措施',
  `dust_uid` int(11) NULL DEFAULT NULL COMMENT '责任人ID',
  `dust_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任人名称',
  `cycle` tinyint(1) NULL DEFAULT NULL COMMENT '管控周期 1 每日 2 每月 3 每周',
  `time` tinyint(1) NULL DEFAULT NULL COMMENT '管控频次',
  `level_mode` tinyint(1) NULL DEFAULT NULL COMMENT '风险分级模型 0 风险矩阵分析法 1 作业条件危险性分析法 2 风险程度分析法 3 其他（自定义定级）',
  `l_level` int(11) NULL DEFAULT NULL COMMENT '事故发生的可能性（L）',
  `s_level` int(11) NULL DEFAULT NULL COMMENT '事件后果严重性（S）',
  `c_level` int(11) NULL DEFAULT NULL COMMENT '发生事故事件的后果严重性（C）',
  `risk_val` int(11) NULL DEFAULT NULL COMMENT '风险值(R)=L×S ',
  `risk_text` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险等级 ',
  `level_index` int(11) NULL DEFAULT NULL COMMENT '风险等级数值',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 112 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '风险点清单管理-辨识记录' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for secure_space_work
-- ----------------------------
DROP TABLE IF EXISTS `secure_space_work`;
CREATE TABLE `secure_space_work`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `date` date NULL DEFAULT NULL COMMENT '日期',
  `number` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '编号',
  `work_level` tinyint(1) NULL DEFAULT NULL COMMENT '作业级别 0=一级；1=二级',
  `apply_company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '申请部门',
  `work_company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业单位',
  `work_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业内容及地点',
  `work_start_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业开始时间',
  `work_end_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业结束时间',
  `work_space` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '受限空间内原有介质',
  `work_uid` int(10) NULL DEFAULT NULL COMMENT '作业人id',
  `work_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业人',
  `work_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '动火人签字',
  `guardian_id` int(10) NULL DEFAULT NULL COMMENT '监护人id',
  `guardian_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监护人',
  `guardian_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监护人签字',
  `safe_uid` int(10) NULL DEFAULT NULL COMMENT '安全教育人id',
  `safe_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全教育人',
  `safe_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全教育人签字',
  `harm` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危害辨识',
  `risk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他风险',
  `work_result` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result2` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result3` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result4` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result5` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result6` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result7` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result8` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result9` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result10` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result10_choose` varchar(800) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业监护措施选择项',
  `work_result11` tinyint(1) NULL DEFAULT NULL COMMENT '0=不涉及；1=涉及',
  `work_result12` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '其他安全措施',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提交人签字',
  `review_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审核人签字',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0=待提交；1=待审核；2=已完成；3=驳回；4=撤回；5=作废；6=已确认',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `up_uid` int(10) NULL DEFAULT NULL COMMENT '修改人id',
  `sh_uid` int(10) NULL DEFAULT NULL COMMENT '作业负责审核人id',
  `sh_result` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批意见',
  `sh_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业部审核签字',
  `sh_date` datetime NULL DEFAULT NULL COMMENT '作业部审核时间',
  `sh2_uid` int(10) NULL DEFAULT NULL COMMENT '作业部经理审核人id',
  `sh2_result` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批意见',
  `sh2_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业部经理审核签字',
  `sh2_date` datetime NULL DEFAULT NULL COMMENT '作业部经理审核时间',
  `sh3_uid` int(10) NULL DEFAULT NULL COMMENT '安全部审核人id',
  `sh3_result` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批意见',
  `sh3_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安全部审核签字',
  `sh3_date` datetime NULL DEFAULT NULL COMMENT '安全部审核时间',
  `sh4_uid` int(10) NULL DEFAULT NULL COMMENT '行政副总经理id',
  `sh4_result` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政副总经理审批意见',
  `sh4_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行政副总经理签字',
  `sh4_date` datetime NULL DEFAULT NULL COMMENT '行政副总经理审核时间',
  `sh5_uid` int(10) NULL DEFAULT NULL COMMENT '属地负责人id',
  `sh5_result` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '属地负责人审批意见',
  `sh5_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '属地负责人签字',
  `sh5_date` datetime NULL DEFAULT NULL COMMENT '属地负责人审批时间',
  `sh6_uid` int(10) NULL DEFAULT NULL COMMENT '属地验收人id',
  `sh6_result` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '属地验收人审批意见',
  `sh6_result2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作业结束需确认的项目',
  `sh6_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '属地验收人签字',
  `sh6_date` datetime NULL DEFAULT NULL COMMENT '属地验收人审批时间',
  `sign_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '签字状态 0=-；1=作业部负责人签字；2=作业部经理签字；3=安全管理签字；4=行政部副总经理签字；5=属地负责人签字；6=属地验收人签字',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `file_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `date`(`date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '有限空间安全作业证(湖北、广东)' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for secure_space_work_assoc
-- ----------------------------
DROP TABLE IF EXISTS `secure_space_work_assoc`;
CREATE TABLE `secure_space_work_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '有限空间安全作业证(湖北、广东)关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for secure_space_work_detail
-- ----------------------------
DROP TABLE IF EXISTS `secure_space_work_detail`;
CREATE TABLE `secure_space_work_detail`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NULL DEFAULT NULL COMMENT '关联单据id',
  `value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '硫化氢',
  `value2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '一氧化碳',
  `value3` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '氧含量',
  `value4` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '爆炸下限',
  `time` time NULL DEFAULT NULL COMMENT '分析时间',
  `value5` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分析部位',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分析人签字',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '有限空间安全作业证详情' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for secure_space_work_log
-- ----------------------------
DROP TABLE IF EXISTS `secure_space_work_log`;
CREATE TABLE `secure_space_work_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_in_id`(`order_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 44 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '有限空间安全作业证(湖北、广东)日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for secure_visitor_access_list
-- ----------------------------
DROP TABLE IF EXISTS `secure_visitor_access_list`;
CREATE TABLE `secure_visitor_access_list`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '记录编号',
  `in_out_time` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进/出时间',
  `in_out_mode` tinyint(1) NULL DEFAULT 2 COMMENT '进/出方式；1：人工扫码；2：门禁扫码',
  `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸图像',
  `register_worker_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '访客工号',
  `uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '访客id',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '访客姓名',
  `unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '访客单位',
  `receiver_dept_id` int(10) NULL DEFAULT NULL COMMENT '接待部门id',
  `receiver_dept_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接待部门',
  `interviewee` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接待人',
  `reason_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '访问事由 1参观；2检查；3调研；4作业；5其他',
  `register_order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联预约单',
  `rel_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '门禁名称',
  `direction` tinyint(1) NULL DEFAULT NULL COMMENT '进/出方向；1：进；2：出',
  `e_event_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸时间推送数据-事件流水号（唯一数）',
  `e_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸时间推送数据-时间',
  `e_vent_staff_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸时间推送数据-工号',
  `e_event_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸时间推送数据-动作代码',
  `e_event_action` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '人脸时间推送数据-动作含义，部分动作代码没有解析出对应的动作可能为空',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '单据状态；0：待提审；1：待审核；2：已审核；3：已驳回；4：已撤回；5：已反审；6：已作废；',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_order_no`(`order_no`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '访客进出记录' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for secure_week_check_assoc
-- ----------------------------
DROP TABLE IF EXISTS `secure_week_check_assoc`;
CREATE TABLE `secure_week_check_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL,
