  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for secure_week_check_count
-- ----------------------------
DROP TABLE IF EXISTS `secure_week_check_count`;
CREATE TABLE `secure_week_check_count`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '汇总类型 0 公司级 1部门级',
  `check_date` date NOT NULL COMMENT '检查日期',
  `check_start_date` date NOT NULL COMMENT '排查周期-开始时间',
  `check_end_date` date NULL DEFAULT NULL COMMENT '排查周期-结束时间',
  `check_month` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查月份',
  `check_week` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '排查周',
  `check_ret` tinyint(1) NULL DEFAULT NULL COMMENT '检查结果 0 不合格 1合格 2 部分合格',
  `check_sign` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人签字',
  `check_user_id` int(11) NULL DEFAULT NULL COMMENT '检查人ID',
  `check_user_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人名称',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态 0 暂存 1待审核 2已审核 3审核不通过 4 撤回',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '制单人部门',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `order_no`(`type`, `order_no`) USING BTREE,
  INDEX `check_date`(`check_date`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `check_ret`(`check_ret`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据-汇总' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for secure_week_check_count_assoc
-- ----------------------------
DROP TABLE IF EXISTS `secure_week_check_count_assoc`;
CREATE TABLE `secure_week_check_count_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL,
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `up_id`(`ct_uid`, `order_id`, `type`, `assoc_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据-汇总-关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for secure_week_check_count_log
-- ----------------------------
DROP TABLE IF EXISTS `secure_week_check_count_log`;
CREATE TABLE `secure_week_check_count_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '日志类型 0 操作类型 1 审批类型',
  `act` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日志信息',
  `act_msg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `assoc_id`(`order_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据-汇总日志' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for secure_week_check_detail
-- ----------------------------
DROP TABLE IF EXISTS `secure_week_check_detail`;
CREATE TABLE `secure_week_check_detail`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `group_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '自查组',
  `push_item` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '推送组',
  `serial` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '序号',
  `check_self_item` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查项目',
  `check_self_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查内容',
  `check_self_method` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查方法',
  `check_ret` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '是否合规 0 否 1 是',
  `question_num` int(11) NULL DEFAULT NULL COMMENT '问题数',
  `question` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '存在问题',
  `risk` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险点',
  `question_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '问题图片',
  `question_addr` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问题地点',
  `after_question` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问题调整之后',
  `rectify_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改措施',
  `rectify_img` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '整改图片',
  `rectify_ret` tinyint(1) NULL DEFAULT NULL COMMENT '整改结果 0 未整改 1 已整改 2 整改中 3 待验收 4 整改不合格',
  `rectify_user_id` int(11) NULL DEFAULT NULL COMMENT '整改人ID',
  `rectify_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改人',
  `accept_uid` int(11) NULL DEFAULT NULL COMMENT '验收人ID',
  `accept_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '验收人',
  `rectify_time` datetime NULL DEFAULT NULL COMMENT '整改时间',
  `verify_time` datetime NULL DEFAULT NULL COMMENT '验收时间',
  `after_rectify_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '整改措施之后',
  `rectify_date` date NULL DEFAULT NULL COMMENT '整改期限',
  `type_id` int(11) NULL DEFAULT NULL COMMENT '问题类型ID',
  `type_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问题类型名称',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '汇总备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '周自查单据信息' ROW_FORMAT = DYNAMIC;

