  `group_id` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目组ID',
  `serial` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '序号',
  `risk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '风险点',
  `check_self_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查内容',
  `check_self_method` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自查方法',
  `check_depts` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '自查部门，公司类型为空,多个用逗号隔开；1 品管部 2 生产部 3 储运部 4 行政部',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
