-- ----------------------------
-- Table structure for split_assemble_list
-- ----------------------------
DROP TABLE IF EXISTS `split_assemble_list`;
CREATE TABLE `split_assemble_list`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `split_assemble_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '拆装单号',
  `before_num` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '拆前数量',
  `after_num` decimal(18, 4) NOT NULL COMMENT '拆后数量',
  `warehouse_id` int(11) NOT NULL COMMENT '仓库id',
  `split_assemble_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '拆装时间',
  `create_id` int(11) NOT NULL COMMENT '制单人id',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '最后更新人',
  `dept_id` int(11) NOT NULL COMMENT '部门id',
  `file_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{\"src\":\"\",\"name\":\"\"}' COMMENT '附件信息',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态 0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废,8待确认',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拆装单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for split_assemble_log
