  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  INDEX `parent_id`(`parent_id`) USING BTREE,
  INDEX `child_id`(`child_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '拆零关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for txc_eledata
-- ----------------------------
DROP TABLE IF EXISTS `txc_eledata`;
CREATE TABLE `txc_eledata`  (
  `id` bigint(20) NOT NULL,
  `device_relationid` bigint(20) NOT NULL DEFAULT 0 COMMENT '设备关联ID',
  `syscreatetime` datetime NOT NULL COMMENT '系统创建时间',
  `recordtime_prev` datetime NOT NULL COMMENT '上一次读取时间',
  `recordtime` datetime NULL DEFAULT NULL COMMENT '读取时间',
  `branch` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基地',
  `workshop` int(11) NOT NULL COMMENT '车间',
  `device_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备通信模的IMEI号',
  `m_var_prev` decimal(18, 2) NULL DEFAULT NULL COMMENT '上一次设备的读取值',
  `m_var` decimal(18, 2) NOT NULL COMMENT '数值',
  `a_facevoltage` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'a相电压',
  `b_facevoltage` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'b相电压',
  `c_facevoltage` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'c相电压',
  `a_facecurrent` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'a相电流',
  `b_facecurrent` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'b相电流',
  `c_facecurrent` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'c相电流',
  `ab_facevoltage` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'ab相电压',
  `bc_facevoltage` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'bc相电压',
  `ac_facevoltage` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT 'ac相电压',
  `fwdactivetotal` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '正向有功总电能',
  `revactivetotal` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '反向有功总电能',
  `fwdreactivetotal` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '正向无功总电能',
  `revreactivetotal` decimal(18, 2) NOT NULL DEFAULT 0.00 COMMENT '反向无功总电能',
  `update_time` datetime NULL DEFAULT NULL,
  `status` smallint(6) NOT NULL DEFAULT 0 COMMENT '状态：1有效，2无效，3设备断开',
  `instanttotalhavepower` decimal(18, 2) NULL DEFAULT NULL COMMENT '瞬时总有功功率',
  `instanttotalnotpower` decimal(18, 2) NULL DEFAULT NULL COMMENT '瞬时总无功功率',
  `instanttotalapparentpower` decimal(18, 2) NULL DEFAULT NULL COMMENT '瞬时总视在功率',
  `totalpowerfactor` decimal(18, 2) NULL DEFAULT NULL COMMENT '总功率因素',
  `gridfrequency` decimal(18, 2) NULL DEFAULT NULL COMMENT '电网频率',
  `fwdactivetotal_peak` decimal(18, 2) NULL DEFAULT NULL COMMENT '正向有功总电能_尖峰',
  `fwdactivetotal_high` decimal(18, 2) NULL DEFAULT NULL COMMENT '正向有功总电能_高峰',
  `fwdactivetotal_flat` decimal(18, 2) NULL DEFAULT NULL COMMENT '正向有功总电能_平段',
  `fwdactivetotal_low` decimal(18, 2) NULL DEFAULT NULL COMMENT '正向有功总电能_低谷',
  `revactivetotal_peak` decimal(18, 2) NULL DEFAULT NULL COMMENT '反向有功总电能_尖峰',
  `revactivetotal_high` decimal(18, 2) NULL DEFAULT NULL COMMENT '反向有功总电能_高峰',
  `revactivetotal_flat` decimal(18, 2) NULL DEFAULT NULL COMMENT '反向有功总电能_平段',
  `revactivetotal_low` decimal(18, 2) NULL DEFAULT NULL COMMENT '反向有功总电能_低谷',
  `reactivedegree_1` decimal(18, 2) NULL DEFAULT NULL COMMENT '1象无功电度',
  `reactivedegree_2` decimal(18, 2) NULL DEFAULT NULL COMMENT '2象无功电度',
  `reactivedegree_3` decimal(18, 2) NULL DEFAULT NULL COMMENT '3象无功电度',
  `reactivedegree_4` decimal(18, 2) NULL DEFAULT NULL COMMENT '4象无功电度',
  `combinedactivetotalenergy` decimal(18, 2) NULL DEFAULT NULL COMMENT '组合有功总电能',
  `reset_num` int(11) NOT NULL DEFAULT 0 COMMENT '重置次数',
  `upper_limit_range_val` decimal(18, 2) NULL DEFAULT NULL COMMENT '量程上限值',
  `cge_endval` decimal(18, 2) NULL DEFAULT NULL COMMENT '换表止码',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_qurylst`(`branch`, `workshop`, `device_relationid`, `recordtime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '电表数据（主动采集，包含福建基地）' ROW_FORMAT = Dynamic;

