-- ----------------------------
-- Table structure for txc_gasdata
-- ----------------------------
DROP TABLE IF EXISTS `txc_gasdata`;
CREATE TABLE `txc_gasdata`  (
  `id` bigint(20) NOT NULL,
  `syscreatetime` datetime NOT NULL COMMENT '系统创建时间',
  `recordtime` datetime NOT NULL COMMENT '采集时间',
  `branch` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基地',
  `workshop` int(11) NOT NULL COMMENT '车间',
  `standardaccruevar` decimal(18, 2) NOT NULL COMMENT '标况累计流量',
  `operatingaccruevar` decimal(18, 2) NOT NULL COMMENT '工况累计流量',
  `standardvar` decimal(18, 2) NOT NULL COMMENT '标况瞬时流量',
  `operatingvar` decimal(18, 2) NOT NULL COMMENT '工况瞬时流量',
  `standardvolumevar` decimal(18, 2) NOT NULL COMMENT '标况体积流量',
  `operatingvolumevar` decimal(18, 2) NOT NULL COMMENT '工况体积流量',
  `temperature` decimal(18, 2) NOT NULL COMMENT '温度',
  `pressure` decimal(18, 2) NOT NULL COMMENT '压力',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `device_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备通信模块标识',
  `device_relationid` bigint(20) NOT NULL DEFAULT 0 COMMENT '设备关联ID',
  `recordtime_prev` datetime NULL DEFAULT NULL COMMENT '上一次采集时间',
  `standardaccruevar_prev` decimal(18, 2) NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `status` smallint(6) NOT NULL DEFAULT 0 COMMENT '状态：1有效，2无效，3设备断开',
  `reset_num` int(11) NOT NULL DEFAULT 0 COMMENT '重置次数',
  `upper_limit_range_val` decimal(18, 2) NULL DEFAULT NULL COMMENT '量程上限值',
  `cge_endval` decimal(18, 2) NULL DEFAULT NULL COMMENT '换表止码',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_query`(`branch`, `workshop`, `recordtime`, `device_relationid`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '燃气表数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for txc_steamdata
-- ----------------------------
DROP TABLE IF EXISTS `txc_steamdata`;
CREATE TABLE `txc_steamdata`  (
  `id` bigint(20) NOT NULL,
  `syscreatetime` datetime NOT NULL COMMENT '系统创建时间',
  `recordtime_prev` datetime NOT NULL COMMENT '上一次采集时间',
  `recordtime` datetime NOT NULL COMMENT '采集时间',
  `branch` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基地',
  `workshop` int(11) NOT NULL COMMENT '车间',
  `addr` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '地址（站号M）',
  `type` smallint(2) NOT NULL COMMENT '1主流量，2配料流量',
  `code_work` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '功能代码',
  `code_warn` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '报警代码',
  `quality_total_prev` decimal(18, 2) NOT NULL COMMENT '上一次质量累计流量',
  `quality_total` decimal(18, 2) NOT NULL COMMENT '质量累计流量',
  `quality_moment` decimal(18, 2) NOT NULL COMMENT '质量瞬时流量',
  `heat_total` decimal(18, 2) NOT NULL COMMENT '热量累计流量',
  `heat_moment` decimal(18, 2) NOT NULL COMMENT '热量瞬时流量',
  `temperature` decimal(18, 2) NOT NULL COMMENT '温度',
  `pressure` decimal(18, 9) NOT NULL COMMENT '压力',
  `density` decimal(18, 7) NOT NULL COMMENT '蒸汽密度',
  `remarks` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `device_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备通信模的IMEI号',
  `device_relationid` bigint(20) NOT NULL DEFAULT 0 COMMENT '设备关联ID',
  `update_time` datetime NULL DEFAULT NULL,
  `status` smallint(6) NOT NULL DEFAULT 0 COMMENT '状态：1有效，2无效，3设备断开',
  `reset_num` int(11) NOT NULL DEFAULT 0 COMMENT '重置次数',
  `upper_limit_range_val` decimal(18, 2) NULL DEFAULT NULL COMMENT '量程上限值',
  `cge_endval` decimal(18, 2) NULL DEFAULT NULL COMMENT '换表止码',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_qurylst`(`branch`, `workshop`, `device_relationid`, `recordtime`) USING BTREE COMMENT '插入前找最后一条记录'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '蒸汽表数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for txc_thedata
-- ----------------------------
DROP TABLE IF EXISTS `txc_thedata`;
CREATE TABLE `txc_thedata`  (
  `id` bigint(20) NOT NULL,
