  `b15_S` decimal(18, 2) NOT NULL COMMENT '15栋南',
  `b16_N` decimal(18, 2) NOT NULL COMMENT '16栋北',
  `b16_S` decimal(18, 2) NOT NULL COMMENT '16栋南',
