  `chargemixture` decimal(18, 2) NOT NULL COMMENT '配料',
  `chargingstation` decimal(18, 2) NOT NULL COMMENT '充电桩',
  `k1` decimal(18, 2) NOT NULL COMMENT 'k1',
  `k2` decimal(18, 2) NOT NULL COMMENT 'k2',
  `k3` decimal(18, 2) NOT NULL COMMENT 'k3',
  `k9` decimal(18, 2) NOT NULL COMMENT 'k4',
  `mains` decimal(18, 2) NOT NULL COMMENT '总配电柜',
  `maintenanceroom` decimal(18, 2) NOT NULL COMMENT '维修间',
  `sewage` decimal(18, 2) NOT NULL COMMENT '污水',
  `sewage2` decimal(18, 2) NOT NULL COMMENT '污水2',
  `ventilator` decimal(18, 2) NOT NULL COMMENT '通风',
  `waterproduction` decimal(18, 2) NOT NULL COMMENT '制水',
  `line1_apv` decimal(18, 2) NOT NULL COMMENT '1线APV',
  `line1_cooler` decimal(18, 2) NOT NULL COMMENT '1线冷却机',
  `line1_coolingtower` decimal(18, 2) NOT NULL COMMENT '1线冷却塔',
  `line1_destacking` decimal(18, 2) NOT NULL COMMENT '1线卸垛',
  `line1_canning` decimal(18, 2) NOT NULL COMMENT '1线罐装',
  `line1_heatshrink` decimal(18, 2) NOT NULL COMMENT '1线热缩',
  `line1_oven` decimal(18, 2) NOT NULL COMMENT '1线烘炉',
  `line1_package` decimal(18, 2) NOT NULL COMMENT '1线包装',
  `line1_stack` decimal(18, 2) NOT NULL COMMENT '1线码垛',
  `line1_transportline` decimal(18, 2) NOT NULL COMMENT '1线输送线',
  `line2_apv` decimal(18, 2) NOT NULL COMMENT '2线APV',
  `line2_cooler` decimal(18, 2) NOT NULL COMMENT '2线冷却机',
  `line2_canning` decimal(18, 2) NOT NULL COMMENT '2线罐装',
  `line2_coolingtower` decimal(18, 2) NOT NULL COMMENT '2线冷却塔',
  `line2_destacking` decimal(18, 2) NOT NULL COMMENT '2线卸垛',
  `line2_heatshrink` decimal(18, 2) NOT NULL COMMENT '2线热缩',
  `line2_oven` decimal(18, 2) NOT NULL COMMENT '2线烘炉',
  `line2_package` decimal(18, 2) NOT NULL COMMENT '2线包装',
  `line2_stack` decimal(18, 2) NOT NULL COMMENT '2线码垛',
  `line2_transportline` decimal(18, 2) NOT NULL COMMENT '2线输送线',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_query`(`recordtime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '电表数据（贵阳基地本地读取）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for txc_waterdata
-- ----------------------------
DROP TABLE IF EXISTS `txc_waterdata`;
CREATE TABLE `txc_waterdata`  (
  `id` bigint(20) NOT NULL,
  `device_relationid` bigint(20) NOT NULL DEFAULT 0 COMMENT '设备关联ID',
  `syscreatetime` datetime NOT NULL COMMENT '系统创建时间',
  `recordtime_prev` datetime NOT NULL COMMENT '上一次读取时间',
  `recordtime` datetime NOT NULL COMMENT '读取时间',
  `branch` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '基地',
  `workshop` int(11) NOT NULL COMMENT '车间',
  `device_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备通信模的IMEI号',
  `voltage` decimal(18, 2) NULL DEFAULT NULL COMMENT '设备电压',
  `m_var_prev` decimal(18, 2) NULL DEFAULT NULL COMMENT '上一次设备图片识别的读取值',
  `m_var` decimal(18, 2) NOT NULL COMMENT '设备图片识别的读取值',
  `imgpath` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图片地址',
  `cosimgpath` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '云图片',
  `update_time` datetime NULL DEFAULT NULL,
  `status` smallint(6) NOT NULL DEFAULT 0 COMMENT '状态：1有效，2无效',
  `instFlow` decimal(18, 2) NULL DEFAULT NULL COMMENT '瞬时流量',
  `instVelocity` decimal(18, 2) NULL DEFAULT NULL COMMENT '瞬时流速',
  `flowPercent` decimal(18, 2) NULL DEFAULT NULL COMMENT '流量百分比',
  `fluidCond` decimal(18, 2) NULL DEFAULT NULL COMMENT '流体电导率',
  `posCumul` decimal(18, 2) NULL DEFAULT NULL COMMENT '正向累积量',
  `negCumul` decimal(18, 2) NULL DEFAULT NULL COMMENT '反向累积量',
  `reset_num` int(11) NOT NULL DEFAULT 0 COMMENT '重置次数',
  `upper_limit_range_val` decimal(18, 2) NULL DEFAULT NULL COMMENT '量程上限值',
  `cge_endval` decimal(18, 2) NULL DEFAULT NULL COMMENT '换表止码',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_qurylst`(`branch`, `workshop`, `device_relationid`, `recordtime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '水表数据' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for use_place
-- ----------------------------
DROP TABLE IF EXISTS `use_place`;
CREATE TABLE `use_place`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `place_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '地点名称',
  `pid` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '父id,0顶级',
  `top_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '最顶级ID',
  `rank` int(10) NULL DEFAULT 0 COMMENT '菜单排序,越大越前',
  `principal_uid` int(10) NULL DEFAULT NULL COMMENT '负责人uid',
  `cost_center` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成本中心	',
  `addr_label_ids` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置标签id，多个用逗号隔开',
  `addr_label_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置标签文本',
  `create_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `update_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `rank`(`rank`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1333 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '使用地点' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for warehouse_class
-- ----------------------------
DROP TABLE IF EXISTS `warehouse_class`;
CREATE TABLE `warehouse_class`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '仓库名称',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_type` tinyint(2) UNSIGNED NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `code` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库编码',
  `sap_code` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP工厂编码',
  `sort_val` int(11) NULL DEFAULT NULL COMMENT '排序值，数值越大，越靠前',
  `labels` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库标签id，多个用逗号隔开',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '所属部门id',
  `wh_user_id` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '仓管员id，多个逗号隔开',
  `all_dept` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '部门查看仓库权限，多个逗号隔开',
  `all_user` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '人员查看仓库权限，多个逗号隔开',
  `location_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓储地点描述',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `name`(`name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for warehouse_measure_class
-- ----------------------------
DROP TABLE IF EXISTS `warehouse_measure_class`;
CREATE TABLE `warehouse_measure_class`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计量名称',
