  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE,
  INDEX `name`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '计量单位' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for warehouse_measure_class_test
-- ----------------------------
DROP TABLE IF EXISTS `warehouse_measure_class_test`;
CREATE TABLE `warehouse_measure_class_test`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '计量名称',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `module_type`(`module_type`) USING BTREE,
  INDEX `name`(`name`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 264 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '计量单位' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for waste_inventory
-- ----------------------------
DROP TABLE IF EXISTS `waste_inventory`;
CREATE TABLE `waste_inventory`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) UNSIGNED NOT NULL COMMENT '商品id',
  `warehouse_id` int(11) UNSIGNED NOT NULL COMMENT '仓库id',
  `stock` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '库存数量',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '危废库存总表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for waste_inventory_detail
-- ----------------------------
DROP TABLE IF EXISTS `waste_inventory_detail`;
CREATE TABLE `waste_inventory_detail`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `inventory_id` int(11) NOT NULL COMMENT '库存总表id',
  `document_type` smallint(2) NOT NULL COMMENT '单据交易类型 1：危废入库单；2：危废出库单',
  `document_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `transaction_type` smallint(2) UNSIGNED NOT NULL DEFAULT 1 COMMENT '交易类型 1入库 2出库 3恢复库存',
  `transaction_quantity` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '交易数量',
  `in_batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库批次',
  `pro_batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批次',
  `balance_quantity` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '结余数量',
  `transaction_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '交易日期',
  `warehouse_id` int(11) NOT NULL COMMENT '仓库id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细表id',
  `ws_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '货架位',
  `industry_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '行业俗称或单位内部名称',
  `measure_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位，如：千克、吨、升、瓶、桶等',
  `waste_barcode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危废条码',
  `waste_category_id` int(10) NULL DEFAULT NULL COMMENT '废物类别ID',
  `waste_category_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '废物类别文本',
  `hazardous_properties` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险特性（危废条码基础资料）',
  `industry_source` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行业来源（危废条码基础资料）',
  `hazardous_waste` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '危险废物（危废条码基础资料）',
  `waste_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '废物代码',
  `container_type_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '容器类型ID',
  `container_type_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器类型文本',
  `material_type` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '容器材质ID',
  `material_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器材质文本',
  `capacity_type_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '容器容量类型ID',
  `capacity_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器容量类型文本',
  `constituent_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有害成分名称',
  `state_matter` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '形态',
  `hazard_property` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险特性',
  `available_status` tinyint(1) NULL DEFAULT 0 COMMENT '可用状态；0：可用；1：待修；2：报废；3：限制',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 116 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '危废库存明细流水表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for waste_inventory_stocks
-- ----------------------------
DROP TABLE IF EXISTS `waste_inventory_stocks`;
CREATE TABLE `waste_inventory_stocks`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `inventory_id` int(11) NOT NULL COMMENT '库存总表id',
  `batch_number` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批次号',
  `document_type` smallint(2) NOT NULL COMMENT '单据交易类型 1：危废入库单；2：危废出库单',
  `document_num` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `stock_qty` decimal(18, 4) UNSIGNED NOT NULL DEFAULT 0.0000 COMMENT '库存数量',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称(上线时候去掉这个字段)',
  `transaction_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '交易日期',
  `in_batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库批次编码',
  `pro_batch_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产批次',
  `warehouse_id` int(11) NOT NULL COMMENT '仓库id',
  `goods_id` int(11) NOT NULL COMMENT '商品id',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_uid` int(10) NULL DEFAULT NULL COMMENT '创建人UID',
  `industry_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '行业俗称或单位内部名称',
  `measure_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位，如：千克、吨、升、瓶、桶等',
  `waste_barcode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危废条码',
  `waste_category_id` int(10) NULL DEFAULT NULL COMMENT '废物类别ID',
  `waste_category_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '废物类别文本',
  `hazardous_properties` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险特性（危废条码基础资料）',
  `industry_source` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '行业来源（危废条码基础资料）',
  `hazardous_waste` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '危险废物（危废条码基础资料）',
  `waste_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '废物代码',
  `container_type_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '容器类型ID',
  `container_type_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器类型文本',
  `material_type` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '容器材质ID',
  `material_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器材质文本',
  `capacity_type_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '容器容量类型ID',
  `capacity_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器容量类型文本',
  `constituent_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有害成分名称',
  `state_matter` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '形态',
  `hazard_property` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险特性',
  `in_wh_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库单号（记录初始入库单号）',
  `price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '单价',
  `stock_price` decimal(18, 3) NULL DEFAULT 0.000 COMMENT '在库金额',
  `in_wh_date` datetime NULL DEFAULT NULL COMMENT '入库日期',
  `stock_id` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '库存明细id,记录入库时通过哪个库存明细入库的',
  `available_status` tinyint(1) NULL DEFAULT 0 COMMENT '可用状态；0：可用（非限制）；1：待修；2：报废；3：限制（质量检查）；4：冻结',
  `initial_in_wh_date` datetime NULL DEFAULT NULL COMMENT '初始入库日期，记录最早的入库日期',
  `initial_stock_id` int(11) NULL DEFAULT NULL COMMENT '初始入库库存id',
  `detail_ctime` datetime NULL DEFAULT NULL COMMENT '从库存出入明细同步过来的create_time,留作后期备用',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `in_use_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '占用数（单据占用）',
  `use_qty` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已用数（单据完结）',
  `reserve_decimal` tinyint(1) NULL DEFAULT 0 COMMENT '保留小数',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `inventory_id`(`inventory_id`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '危废库存明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_batch_coding_rule
-- ----------------------------
DROP TABLE IF EXISTS `wh_batch_coding_rule`;
CREATE TABLE `wh_batch_coding_rule`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `sup_id` int(10) NOT NULL COMMENT '供应商id',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '供应商',
  `firm_id` int(10) NOT NULL COMMENT '厂商id',
  `firm_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '厂商',
  `good_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '适用产品类型 1-红牛 2-战马,多个用逗号隔开',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) NOT NULL COMMENT '创建人UID',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名字',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `good_type`(`good_type`) USING BTREE,
  INDEX `sup_id`(`sup_id`) USING BTREE,
  INDEX `firm_id`(`firm_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原厂批次编码规则' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_batch_coding_rule_config
-- ----------------------------
DROP TABLE IF EXISTS `wh_batch_coding_rule_config`;
CREATE TABLE `wh_batch_coding_rule_config`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(11) NOT NULL COMMENT '送检报告标准配置id',
  `rule_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规则名称',
  `level` tinyint(1) NULL DEFAULT NULL COMMENT '优先级',
  `config_val` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '可视化配置信息',
  `regular` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '正则表达式',
  `current_rule` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当前规则',
  `example` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '示例',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名字',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `level`(`level`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 74 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原厂批次编码规则-规则配置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_batch_coding_rule_good
-- ----------------------------
DROP TABLE IF EXISTS `wh_batch_coding_rule_good`;
CREATE TABLE `wh_batch_coding_rule_good`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(11) NOT NULL COMMENT '原厂批次编码规则id',
  `goods_id` int(10) UNSIGNED NOT NULL COMMENT '货品id',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `barcode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品条码',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名字',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 118 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原厂批次编码规则-物料信息' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_batt_chg_assoc
-- ----------------------------
DROP TABLE IF EXISTS `wh_batt_chg_assoc`;
CREATE TABLE `wh_batt_chg_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '所属单据id',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5调出仓库待确认,6调出仓库确认,7调出仓库驳回,8调入仓库待确认,9调入仓库确认,10调入仓库驳回,',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：调出仓确认；3：调入仓确认；4：抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '电池充电记录表关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_batt_chg_detail
-- ----------------------------
DROP TABLE IF EXISTS `wh_batt_chg_detail`;
CREATE TABLE `wh_batt_chg_detail`  (
