  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3498 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '内容物发料单身份标识' ROW_FORMAT = Dynamic;

