-- ----------------------------
-- Table structure for wh_equipment_in_goods
-- ----------------------------
DROP TABLE IF EXISTS `wh_equipment_in_goods`;
CREATE TABLE `wh_equipment_in_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) NOT NULL DEFAULT 0,
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '资产入库申请单列表ID',
  `procure_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单列表ID',
  `procure_goods_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单商品ID',
  `in_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '入库数量',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量(变动)',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id,记录入库时是通过哪个库存明细入库的',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  `asset_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '唯一码',
  `barcode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '资产(物料)条码',
  `title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '资产(物料)名称',
  `brand` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '品牌',
  `spec` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '型号',
  `equipment_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '设备编码',
  `equipment_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备类型，层级用逗号隔开',
  `equipment_type_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备类型id',
  `sn` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '序列号',
  `factory_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出厂编号',
  `export_type` tinyint(1) NULL DEFAULT NULL COMMENT '出口类型 1国产 2进口',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图片',
  `product_line` int(11) NULL DEFAULT NULL COMMENT '所属产线',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '可用状态 0停用 1正常 2闲置 3待报废 4已报废',
  `num` decimal(18, 4) NULL DEFAULT 1.0000 COMMENT '数量',
  `use_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门ID，层级用逗号隔开',
  `duty_dept_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任部门ID，层级用逗号隔开',
  `use_duty_user` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '使用负责人ID,多个用逗号隔开',
  `open_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '资本化日期',
  `use_year` int(5) NULL DEFAULT NULL COMMENT '折旧年限(年)',
  `expire_date` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '预计到期',
  `save_addr` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '存放位置，用逗号隔开',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商ID 来源物流基础资料供应商',
  `production_id` int(11) NULL DEFAULT NULL COMMENT '生产厂商ID 来源物流基础资料供应商',
  `purchase_uid` int(11) NULL DEFAULT NULL COMMENT '采购人员ID',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '原始价值',
  `spoiled_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '残值率',
  `spolied` decimal(9, 2) NULL DEFAULT NULL COMMENT '残值',
  `depreciation_type` tinyint(2) NULL DEFAULT NULL COMMENT '折旧方法 1 不计提折旧 2 平均年限法 3 年数总和法 4 双倍余额法',
  `accout_type` tinyint(1) NULL DEFAULT NULL COMMENT '会计分类 1 费用化资产 2 资本化资产',
  `sap_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP类别',
  `sap_cost_center` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP成本中心',
  `status_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '可用状态文本',
  `use_dept_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用部门文本',
  `duty_dept_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任部门文本',
  `use_duty_user_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用负责人文本',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `is_add` tinyint(1) NULL DEFAULT 0 COMMENT '0未入库,1已入库',
  `dept_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求部门id，多个用逗号隔开',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `procure_id`(`procure_id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '资产入库申请单商品' ROW_FORMAT = Dynamic;

