-- ----------------------------
-- Table structure for wh_equipment_rec_in_goods
-- ----------------------------
DROP TABLE IF EXISTS `wh_equipment_rec_in_goods`;
CREATE TABLE `wh_equipment_rec_in_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '备件退库单id',
  `equipment_order_id` int(10) NULL DEFAULT NULL COMMENT '备件领用单id',
  `equipment_detail_id` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '备件领用单明细id',
  `goods_id` int(10) NOT NULL COMMENT '商品id',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '商品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品编码',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '单价',
  `rec_num` decimal(18, 4) NOT NULL DEFAULT 0.0000 COMMENT '退库数量',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量(变动)',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ph_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次号',
  `warehouse_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '退入仓库ID',
  `warehouse_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '退入仓库名称',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细表id',
  `original_ph_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  `available_status` tinyint(1) NULL DEFAULT NULL COMMENT '可用状态；0：可用（非限制）；1：待修；2：报废；3：限制（质量检查）；4：冻结',
  `in_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库日期',
  `ws_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '库位',
  `line_id` int(11) NULL DEFAULT NULL COMMENT '线别id',
  `line_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别名称',
  `spares_inventory_detail_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '使用的备件库存明细id，多个用逗号隔开；',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `dept_id` int(10) NULL DEFAULT NULL COMMENT '部门id',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `class_name`(`class_name`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `stock_id`(`stock_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 35 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '备件退库单货品明细' ROW_FORMAT = Dynamic;

