  `cloud_warehouse_number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '云仓编号',
  `receiver_uid` int(10) NULL DEFAULT NULL COMMENT '领用人uid',
  `receiver_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '领用人名字',
  `receiver_dept_id` int(11) NULL DEFAULT NULL COMMENT '领用人部门id',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `file_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `post_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '推送的数据（无人仓推送，用于排查问题）',
  `goods_match` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '库存匹配结果集（无人仓推送，用于排查问题）',
  `is_internal` tinyint(1) NULL DEFAULT 1 COMMENT '是否通过接口创建；1：否；2：是',
  `request_ip` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '请求端ip，仅通过无人仓推送等场景才记录',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废,8待出库确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 159 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '备件领用单记录' ROW_FORMAT = Dynamic;

