  `container_type_id` int(10) UNSIGNED NOT NULL COMMENT '容器类型ID',
  `container_type_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器类型文本',
  `material_type` int(10) UNSIGNED NOT NULL COMMENT '容器材质ID',
  `material_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器材质文本',
  `capacity_type_id` int(10) UNSIGNED NOT NULL COMMENT '容器容量类型ID',
  `capacity_type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '容器容量类型文本',
  `constituent_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '有害成分名称',
  `state_matter` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '形态',
  `hazard_property` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '危险特性',
  `ct_uid` int(11) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(11) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `waste_category_id`(`waste_category_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10015 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '危废基础资料' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_in_assoc
-- ----------------------------
DROP TABLE IF EXISTS `wh_in_assoc`;
CREATE TABLE `wh_in_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `wh_in_id` int(10) UNSIGNED NOT NULL COMMENT '采购入库单列表ID',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5仓库待确认,6仓库确认,7仓库驳回',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：仓库确认；3：抄送',
  `join_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_in_id`(`wh_in_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_id`(`ct_uid`, `wh_in_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16834 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购入库单关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_in_file
-- ----------------------------
DROP TABLE IF EXISTS `wh_in_file`;
CREATE TABLE `wh_in_file`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_id` int(11) NOT NULL COMMENT '单据ID',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件名',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '文件链接',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `upload_time` datetime NULL DEFAULT NULL COMMENT '上传时间',
  `download_num` int(11) NULL DEFAULT 0 COMMENT '下载次数',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '上传者',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 495 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '入库单据日志文件表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_in_goods
-- ----------------------------
DROP TABLE IF EXISTS `wh_in_goods`;
CREATE TABLE `wh_in_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) NULL DEFAULT 0,
  `wh_in_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购入库单列表ID',
  `procure_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单列表ID',
  `procure_goods_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单商品ID',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品编码',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `produce_batch` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '大批次，原厂批次的前面部分',
  `batch_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次',
  `pack_no` int(11) NULL DEFAULT NULL COMMENT '包号',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '采购单价（含税单价）',
  `total_price` decimal(18, 2) NULL DEFAULT NULL COMMENT '采购金额小计（含税小计）',
  `in_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '入库数量',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量(变动)',
  `raw_rem_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '剩余可冲销数量',
  `is_send_check` tinyint(1) NULL DEFAULT 1 COMMENT '是否已送检；-1：免检；1：未送检；2：已送检',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `duplicate_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次重复原因',
  `factory_id` int(11) NULL DEFAULT NULL COMMENT '厂商id（供应商id）',
  `factory_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `delivery_time` datetime NULL DEFAULT NULL COMMENT '交货期',
  `pro_time` datetime NULL DEFAULT NULL COMMENT '生产日期',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同号',
  `check_method` tinyint(1) NULL DEFAULT 1 COMMENT '检验方式；1：到货检验；2：型式检验',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批次号（内部批次）',
  `original_ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `warehouse_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '仓库ID',
  `warehouse_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `factory_label_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商标签编号',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `is_add` tinyint(1) NULL DEFAULT 0 COMMENT '0未入库,1已入库',
  `goods_all_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '总商品库ID',
  `dept_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求部门id，多个用逗号隔开',
  `exp_time` datetime NULL DEFAULT NULL COMMENT '到期日期',
  `ws_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '库位',
  `is_gen_uniq` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成唯一；0:不生成,1:生成',
  `exp_day` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '保质期',
  `available_status` tinyint(1) NULL DEFAULT 0 COMMENT '可用状态；0：可用（非限制）；1：待修；2：报废；3：限制（质量检查）；4：冻结',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id,记录入库时是通过哪个库存明细入库的',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  `supplier_id` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '供应商id',
  `go_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '去税单价',
  `go_tax_total_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '去税小计',
  `tax_rate` tinyint(2) NULL DEFAULT NULL COMMENT '税率,默认13',
  `request_ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '建单端ip',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `wh_in_id`(`wh_in_id`) USING BTREE,
  INDEX `procure_id`(`procure_id`) USING BTREE,
  INDEX `procure_goods_id`(`procure_goods_id`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `warehouse_name`(`warehouse_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `ws_code`(`ws_code`) USING BTREE,
  INDEX `is_gen_uniq`(`is_gen_uniq`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4659 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购入库单商品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_in_list
-- ----------------------------
DROP TABLE IF EXISTS `wh_in_list`;
CREATE TABLE `wh_in_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `wh_in_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '采购入库单号',
  `brand` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品大类;ND1 红牛 ND2 战马',
  `procure_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采购单号',
  `all_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '采购总价',
  `all_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '采购数量',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `file_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废,7入库待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `sup_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `in_time` datetime NULL DEFAULT NULL COMMENT '入库日期',
  `in_wh_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '入库仓库ID',
  `in_wh_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库仓库名称',
  `order_send_check_status` tinyint(1) NULL DEFAULT 1 COMMENT '送检状态；-1：免检；1：未送检；2：部分送检；3：已送检',
  `send_check_type` tinyint(1) NULL DEFAULT NULL COMMENT '送检类型；1、空罐信息确认单;2、顶/底盖检测报告;3、纸皮进货检验报告;4、热缩膜检验报告;5、白砂糖微生物检测报告;6、香精入厂检测报告;7、内容物使用通知单;8、咖啡因送检；9、免检物料清单',
  `procure_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单ID',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '入库类型；0：其他出库单/采购入库；1：冲销入库；2：食堂消耗入库',
  `sap_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP采购凭证',
  `sap_wl_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP物料凭证',
  `sap_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP凭证日期',
  `is_batch` tinyint(1) NULL DEFAULT 0 COMMENT '是否多批次录入；0：不是；1：是',
  `mvt_id` tinyint(2) NULL DEFAULT NULL COMMENT 'MvT移动类型id',
  `mvt_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'MvT移动类型名称',
  `method` tinyint(1) NULL DEFAULT 0 COMMENT '采购方式；0：直接采购；1：按需采购；3：供应链推送',
  `source_order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源单据编号',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `wh_in_no`(`wh_in_no`) USING BTREE,
  INDEX `procure_no`(`procure_no`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `ct_name`(`ct_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1859 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购入库单列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_in_log
-- ----------------------------
DROP TABLE IF EXISTS `wh_in_log`;
CREATE TABLE `wh_in_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `wh_in_id` int(10) UNSIGNED NOT NULL COMMENT '采购入库单列表ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_in_id`(`wh_in_id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6965 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购入库单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
