-- ----------------------------
-- Table structure for wh_inspection_report_config
-- ----------------------------
DROP TABLE IF EXISTS `wh_inspection_report_config`;
CREATE TABLE `wh_inspection_report_config`  (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `project_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '送检报告项目',
  `project_type` tinyint(1) NOT NULL COMMENT '送检报告项目类型,1：空罐信息确认单；2：顶/底盖检测报告；3：纸皮进货检验报告；4：热缩膜检验报告；5：白砂糖微生物检测报告；6：香精入厂检测报告；7：内容物使用通知单；8：咖啡因送检；9：免检物料清单',
  `check_method` tinyint(1) NOT NULL COMMENT '送检方式 1-按比例 2-批固定数 3-按原厂报告 4-按原厂报告并送检',
  `check_method_text` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '送检方式文本',
  `check_thresh_val` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检阈值',
  `check_thresh_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检阈值单位',
  `check_need_val` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应抽检数值',
  `check_need_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应抽检数单位',
  `max_val` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最大值',
  `check_desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验标准描述',
  `is_push` tinyint(1) NULL DEFAULT NULL COMMENT '是否推送 0-否 1-是',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ct_uid` int(10) NOT NULL COMMENT '创建人UID',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名字',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '送检报告标准配置' ROW_FORMAT = Dynamic;

