-- ----------------------------
DROP TABLE IF EXISTS `wh_procure_pro_discuss_record`;
CREATE TABLE `wh_procure_pro_discuss_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单据编号',
  `discuss_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '洽商日期',
  `discuss_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '洽商编号',
  `discuss_pro` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洽商项目',
  `discuss_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洽商时间',
  `discuss_location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洽商地点',
  `party_a` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洽商双方-甲方公司名称',
  `party_b` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洽商双方-乙方公司名称',
  `total_quote` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商内容-项目总报价',
  `tech_service_demand` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商内容-技术及服务要求',
  `delivery_period` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商内容-工期或货期',
  `after_sales_service` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商内容-售后服务',
  `invoice_type` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商内容-发票形式',
  `pay_method` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商内容-付款方式',
  `other_terms` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商内容-其他',
  `final_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '洽商结果-双方最终确定价格',
  `final_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '洽商结果-内容',
  `party_a_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洽商人员确认-甲方签字图片',
  `party_b_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '洽商人员确认-乙方签字图片',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0待确认,3已完成',
  `sign_status` tinyint(1) NULL DEFAULT 0 COMMENT '签字状态；0：未签字；1：部分签字；2：全部签字；',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '建单部门id',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人uid',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `sign_status`(`sign_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '采购项目洽商记录表' ROW_FORMAT = Dynamic;

