  `measure_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单位',
  `stock_qty` int(11) NULL DEFAULT 0 COMMENT '库存数量',
  `box_serial_number_start` int(11) NULL DEFAULT NULL COMMENT '箱序列号-开始箱号',
  `box_serial_number_end` int(11) NULL DEFAULT 0 COMMENT '箱序列号-结束箱号',
