) ENGINE = InnoDB AUTO_INCREMENT = 43 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '成品托盘记录表日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_product_tray_record
-- ----------------------------
DROP TABLE IF EXISTS `wh_product_tray_record`;
CREATE TABLE `wh_product_tray_record`  (
