  `return_num` decimal(18, 4) NOT NULL COMMENT '返厂数量',
  `no_return_num` decimal(18, 4) NOT NULL COMMENT '未还数量',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间id',
  `workshop_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名字',
  `consignee_uid` int(11) NOT NULL COMMENT '签收人uid ',
