) ENGINE = InnoDB AUTO_INCREMENT = 600 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料质检单日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_qlty_inspect_order
-- ----------------------------
DROP TABLE IF EXISTS `wh_qlty_inspect_order`;
CREATE TABLE `wh_qlty_inspect_order`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '单据编号',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物料名称',
  `brand` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品大类 ND1 红牛 ND2 战马	',
  `select_detail_id` int(11) NULL DEFAULT NULL COMMENT '选择的商品明细id',
  `select_in_wh_id` int(11) NULL DEFAULT NULL COMMENT '选择的入库仓库ID',
  `select_in_wh_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '选择的入库仓库名称',
  `select_in_wh_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '选择的入库日期',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '单据状态；0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `goods_id` int(10) UNSIGNED NOT NULL COMMENT '货品id',
  `barcode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '物料条码',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格型号',
  `spec_val` decimal(18, 4) NULL DEFAULT NULL COMMENT '外包装规格-数值',
  `spec_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外包装规格-单位',
  `goods_class` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '货品分类',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `std_val` decimal(18, 4) NULL DEFAULT NULL COMMENT '抽检标准-值',
  `std_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检标准-单位',
  `sup_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `sup_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `in_wh_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库仓库名称',
  `in_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库日期',
  `in_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '入库总量',
  `check_uid` int(11) NULL DEFAULT NULL COMMENT '抽检员uid',
  `check_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检员名字',
  `check_date` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检日期',
  `check_rate` decimal(18, 2) NULL DEFAULT NULL COMMENT '检测率',
  `pass_rate` decimal(18, 2) NULL DEFAULT NULL COMMENT '合格率',
  `spot_rate` decimal(18, 2) NULL DEFAULT NULL COMMENT '抽检率',
  `comment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评价',
  `check_std_id` tinyint(1) NULL DEFAULT NULL COMMENT '检验标准id',
  `check_method` tinyint(1) NULL DEFAULT NULL COMMENT '抽检方式；1：按比例抽检；2：固定抽检',
  `check_type` tinyint(1) NULL DEFAULT NULL COMMENT '检验类型；1：上下浮动(±)；2：数量等于',
  `check_thresh_val` int(11) NULL DEFAULT NULL COMMENT '抽检阈值',
  `check_need_val` int(11) NULL DEFAULT NULL COMMENT '应抽检数值',
  `check_need_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应抽检数单位',
  `check_thresh_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检阈值单位',
  `check_desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验标准描述',
  `error_limit_val` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '允许误差',
  `check_note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检验备注',
  `dept_id` int(11) NULL DEFAULT NULL COMMENT '建单人部门id',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `up_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改人名字',
  `ct_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名字',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6245 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料质检单（原料入库抽检报告）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_qlty_inspect_std
-- ----------------------------
DROP TABLE IF EXISTS `wh_qlty_inspect_std`;
CREATE TABLE `wh_qlty_inspect_std`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `goods_id` int(10) UNSIGNED NOT NULL COMMENT '检验项目type;1：纸皮；2：热缩膜；3：白砂糖；4：热熔胶',
