  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '物料单位',
  `check_method` tinyint(1) NOT NULL COMMENT '抽检方式；1：按比例抽检；2：固定抽检',
  `check_type` tinyint(1) NOT NULL COMMENT '检验类型；1：上下浮动(±)；2：数量等于',
  `check_thresh_val` int(11) NULL DEFAULT NULL COMMENT '抽检阈值',
  `check_need_val` int(11) NOT NULL COMMENT '应抽检数值',
  `check_need_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应抽检数单位',
  `check_thresh_unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抽检阈值单位',
  `check_desc` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检验标准描述',
  `std_val` decimal(18, 4) NULL DEFAULT NULL COMMENT '标准值1',
  `std_val_2` decimal(18, 4) NULL DEFAULT NULL COMMENT '标准值2',
  `std_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标准单位',
