  `std_price` decimal(18, 4) NULL DEFAULT NULL COMMENT '标准单价',
  `warehouse_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属仓库id，多个用逗号隔开',
  `warehouse_type_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '归属仓库类型，多个用逗号隔开',
  `warehouse_type_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '归属仓库类型文本，多个用逗号隔开',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
