  `assoc_status_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联状态单号',
  `deal_reason` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '处置原因',
  `available_status` tinyint(1) NULL DEFAULT NULL COMMENT '可用状态；0：可用（非限制）；1：待修；2：报废；3：限制（质量检查）；4：冻结 ；5 占用',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细表id',
