  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '采购单价',
  `total_price` decimal(18, 2) NULL DEFAULT NULL COMMENT '采购金额小计',
  `rec_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '出库数量/样品数量',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量(变动)',
  `wh_detail_id` int(11) NULL DEFAULT NULL COMMENT '原料入库单明细id',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `factory_id` int(11) NULL DEFAULT NULL COMMENT '厂商id（供应商id）',
  `factory_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '厂商名称',
  `delivery_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交货期',
  `pro_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同号',
  `pack_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '包含',
  `ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批次号（内部批次）',
  `film` int(11) NULL DEFAULT NULL COMMENT '送检报告信息-类型 1 普通版 2 强化版 3 PE彩膜',
  `original_ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `warehouse_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '仓库ID',
  `warehouse_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `goods_all_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '总商品库ID',
  `exp_time` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '到期日期',
  `ws_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '库位',
  `in_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库日期',
  `is_gen_uniq` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成唯一；0:不生成,1:生成',
  `exp_day` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '保质期',
  `available_status` tinyint(1) NULL DEFAULT 0 COMMENT '可用状态；0：可用（非限制）；1：待修；2：报废；3：限制（质量检查）；4：冻结',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id,记录入库时是通过哪个库存明细入库的',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `ct_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人名字',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `dept_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求部门id，多个用逗号隔开',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `goods_id`(`goods_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1992 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料入库送检出库明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_raw_send_check_list
-- ----------------------------
DROP TABLE IF EXISTS `wh_raw_send_check_list`;
CREATE TABLE `wh_raw_send_check_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `wh_in_id` int(11) NOT NULL COMMENT '采购入库单id（原料采购入库单id）',
  `wh_in_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采购入库单号（原料采购入库单号）',
  `procure_id` int(11) NULL DEFAULT NULL COMMENT '采购单id',
  `procure_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采购单号',
  `is_confirm` tinyint(1) NULL DEFAULT NULL COMMENT '是否确认核实，1：未确认；2：已确认；主要用于标记原厂批次确认核实无误',
  `qlty_order_ids` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联的品质单据id',
  `supplier_id` int(11) NULL DEFAULT NULL COMMENT '供应商id（采购单的供应商id）',
  `sup_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称（采购单的供应商）',
  `send_check_type` tinyint(2) NULL DEFAULT NULL COMMENT '送检类型；1、空罐信息确认单;2、顶/底盖检测报告;3、纸皮进货检验报告;4、热缩膜检验报告;5、白砂糖微生物检测报告;6、香精入厂检测报告;7、内容物使用通知单;8、咖啡因送检;9、免检物料清单',
  `check_config_id` int(11) NULL DEFAULT NULL COMMENT '送检批次(出库)信息-送检报告配置id',
  `check_method` tinyint(1) NULL DEFAULT NULL COMMENT '送检批次(出库)信息-送检方式 1-按比例 2-批固定数 3-按原厂报告 4-按原厂报告并送检',
  `check_method_text` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检批次(出库)信息-送检方式文本',
  `check_need_val` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检批次(出库)信息-应送检数',
  `max_val` int(11) NULL DEFAULT NULL COMMENT '送检批次(出库)信息-最大值',
  `send_uid` int(11) NULL DEFAULT NULL COMMENT '送检批次(出库)信息-送检人uid',
  `send_user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检批次(出库)信息-送检人名字',
  `out_wh_date` datetime NULL DEFAULT NULL COMMENT '送检批次(出库)信息-出库日期',
  `out_wh_id` int(11) NULL DEFAULT NULL COMMENT '送检批次(出库)信息-出库仓库id',
  `out_wh_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检批次(出库)信息-出库仓库名称',
  `check_type` tinyint(1) NULL DEFAULT NULL COMMENT '送检批次(出库)信息-检测类型,1：外检；2：内检',
  `factory_id` int(11) NULL DEFAULT NULL COMMENT '送检报告信息-厂商id（供应商id）',
  `factory_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-厂商名称',
  `sample_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-样品日期',
  `check_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-检验日期',
  `check_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '送检报告信息-送检数',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '送检报告信息-使用车间ID',
  `workshop_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-使用车间名字',
  `system_serial_number` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '送检报告信息-系统流水号',
  `empty_can_line_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-空罐线别id',
  `empty_can_line_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-空罐线别名称',
  `barcode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-物料条码',
  `brand` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-产品大类;ND1:红牛;ND2:战马',
  `sku` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-产品类型;ND1-1:普通红牛;ND1-2:强化红牛;ND2-1:战马',
  `empty_can_size` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-空罐尺寸',
  `size_id` int(11) NULL DEFAULT NULL COMMENT '送检报告信息-空罐尺寸id',
  `version_id` int(11) NULL DEFAULT NULL COMMENT '送检报告信息-空罐版本id/顶、底盖版本id',
  `version_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-空罐版本号/顶、底盖版本号',
  `version_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-空罐版本号/顶、底盖版本名称',
  `item` tinyint(1) NULL DEFAULT NULL COMMENT '送检报告信息-顶/底盖类型 1 促销型 2 非促销',
  `class` tinyint(2) NULL DEFAULT NULL COMMENT '送检报告信息-产品类别 1 箱内码 2 无箱内码',
  `film` tinyint(1) NULL DEFAULT NULL COMMENT '送检报告信息-类型 1 普通版 2 强化版 3 PE彩膜',
  `top_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-顶盖图片地址/空罐信息确认单顶盖图片地址',
  `can_body_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-罐身图片地址/空罐信息确认单罐身图片地址',
  `bottom_cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-底盖图片地址/空罐信息确认单底盖图片地址',
  `paper_id` int(11) NULL DEFAULT NULL COMMENT '送检报告信息-纸皮版本id',
  `paper_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-纸皮纸皮图片地址',
  `mvt_id` tinyint(2) NULL DEFAULT NULL COMMENT '送检报告信息-MvT移动类型id',
  `mvt_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-MvT移动类型名称',
  `hot_shrink_type` tinyint(1) NULL DEFAULT NULL COMMENT '送检报告信息-热缩膜类型',
  `hot_shrink_type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-热缩膜类型名称',
  `pro_time` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检报告信息-生产日期',
  `all_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '采购总价',
  `all_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '总数',
  `in_num_total` decimal(18, 4) NULL DEFAULT NULL COMMENT '入库总数',
  `total_batch` int(11) NULL DEFAULT NULL COMMENT '入库批数',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `nullify_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '作废原因',
  `qlty_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因（品质那边驳回）',
  `qlty_return_status` tinyint(1) NULL DEFAULT 1 COMMENT '品质驳回状态；1：未驳回；2：已驳回；',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `send_check_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '送检日期',
  `sap_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP采购凭证',
  `sap_wl_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP物料凭证',
  `in_time` datetime NULL DEFAULT NULL COMMENT '入库日期',
  `in_wh_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '入库仓库ID',
  `in_wh_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '入库仓库名称',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `ct_name`(`ct_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 796 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料入库送检记录列表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_raw_send_check_log
-- ----------------------------
DROP TABLE IF EXISTS `wh_raw_send_check_log`;
CREATE TABLE `wh_raw_send_check_log`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '单据id',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `act` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作动作',
  `act_msg` varchar(999) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提示',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5235 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料入库送检记录单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_raw_stock_check_assoc
-- ----------------------------
DROP TABLE IF EXISTS `wh_raw_stock_check_assoc`;
CREATE TABLE `wh_raw_stock_check_assoc`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) UNSIGNED NOT NULL COMMENT '所属单据id',
  `assoc_type` tinyint(1) NULL DEFAULT 0 COMMENT '0查看,1创建人,2待审批,3已审批,4抄送,5调出仓库待确认,6调出仓库确认,7调出仓库驳回,8调入仓库待确认,9调入仓库确认,10调入仓库驳回,',
  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：调出仓确认；3：调入仓确认；4：抄送',
  `ct_uid` int(10) UNSIGNED NOT NULL COMMENT '关联人UID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE,
  INDEX `assoc_type`(`assoc_type`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1661 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原材料入库检查表关联表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_raw_stock_check_file
-- ----------------------------
DROP TABLE IF EXISTS `wh_raw_stock_check_file`;
CREATE TABLE `wh_raw_stock_check_file`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `order_id` int(10) NOT NULL COMMENT '事故事件登记表ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件名称',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件名称',
  `file_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '文件链接',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `upload_time` datetime NULL DEFAULT NULL COMMENT '上传时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `oid`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原材料入库检查表相关附件' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_raw_stock_check_goods
-- ----------------------------
DROP TABLE IF EXISTS `wh_raw_stock_check_goods`;
CREATE TABLE `wh_raw_stock_check_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
