-- ----------------------------
-- Table structure for wh_raw_write_off_goods
-- ----------------------------
DROP TABLE IF EXISTS `wh_raw_write_off_goods`;
CREATE TABLE `wh_raw_write_off_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_id` int(10) NULL DEFAULT NULL COMMENT '所属单据id',
  `goods_id` int(10) NULL DEFAULT 0 COMMENT '货品id',
  `wh_in_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '原料入库单ID',
  `wh_in_detail_id` int(10) NULL DEFAULT NULL COMMENT '原料入库单货品明细id',
  `procure_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单列表ID',
  `procure_goods_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单商品ID',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品编码',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '采购单价',
  `total_price` decimal(18, 2) NULL DEFAULT NULL COMMENT '采购金额小计',
  `in_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '入库数量（原料入库单入库数量）',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量',
  `out_num` decimal(18, 4) NULL DEFAULT NULL COMMENT '本次冲销数量',
  `sup_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `delivery_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '交货期',
  `pro_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '生产日期',
  `contract_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同号',
  `ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '批次号（内部批次）',
  `original_ph_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原厂批次',
  `warehouse_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '仓库ID',
  `warehouse_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `goods_all_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '总商品库ID',
  `dept_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '需求部门id，多个用逗号隔开',
  `exp_time` datetime NULL DEFAULT NULL COMMENT '到期日期',
  `ws_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '库位',
  `is_gen_uniq` tinyint(1) NULL DEFAULT 0 COMMENT '是否生成唯一；0:不生成,1:生成',
  `exp_day` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '保质期',
  `available_status` tinyint(1) NULL DEFAULT 0 COMMENT '可用状态；0：可用（非限制）；1：待修；2：报废；3：限制（质量检查）；4：冻结',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id,记录入库时是通过哪个库存明细入库的',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `wh_in_id`(`wh_in_id`) USING BTREE,
  INDEX `procure_id`(`procure_id`) USING BTREE,
  INDEX `procure_goods_id`(`procure_goods_id`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `warehouse_name`(`warehouse_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `ws_code`(`ws_code`) USING BTREE,
  INDEX `is_gen_uniq`(`is_gen_uniq`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 170 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '原料入库冲销单货品明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_raw_write_off_list
-- ----------------------------
DROP TABLE IF EXISTS `wh_raw_write_off_list`;
CREATE TABLE `wh_raw_write_off_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冲销单号',
  `wh_in_id` int(11) NULL DEFAULT NULL COMMENT '入库单ID',
  `wh_in_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联入库单号',
  `write_off_type` tinyint(1) NULL DEFAULT 1 COMMENT '冲销单据类型；1、原料入库冲销；2：采购入库冲销；',
  `procure_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '采购单号',
  `reason_type` tinyint(1) NULL DEFAULT NULL COMMENT '冲销原因；1：订单错误；2：质量问题；',
  `date_time` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '冲销日期',
  `all_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '冲销总价',
  `all_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '冲销数量',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `file_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `in_time` datetime NULL DEFAULT NULL COMMENT '入库日期（原料入库单的入库日期）',
  `out_wh_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '出库仓库ID（原料入库单的入库仓）',
  `out_wh_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出库仓库名称（原料入库单的入库仓）',
  `procure_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '采购单ID',
  `mvt_id` tinyint(2) NULL DEFAULT NULL COMMENT 'MvT移动类型id',
  `mvt_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'MvT移动类型名称',
  `sap_code` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP采购凭证',
  `sap_wl_code` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP物料凭证',
  `sap_date` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'SAP凭证日期',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `procure_no`(`procure_no`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `order_no`(`order_no`) USING BTREE,
  INDEX `reason_type`(`reason_type`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `wh_in_no`(`wh_in_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 112 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '入库冲销单记录' ROW_FORMAT = Dynamic;

