  `type` tinyint(1) NULL DEFAULT 0 COMMENT '操作标识，0：创建；1：审批；2：最终审批人；3：仓库确认；4：领料人确认；5：抄送',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `wh_ret_id`(`wh_rec_id`) USING BTREE,
  INDEX `update_time`(`update_time`) USING BTREE,
  INDEX `uin_rid`(`ct_uid`, `wh_rec_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3456 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '领料出库单关联表' ROW_FORMAT = Dynamic;

