-- ----------------------------
-- Table structure for wh_rec_goods
-- ----------------------------
DROP TABLE IF EXISTS `wh_rec_goods`;
CREATE TABLE `wh_rec_goods`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `wh_rec_id` int(10) UNSIGNED NOT NULL COMMENT '领料出库单列表ID',
  `goods_all_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '总商品库ID',
  `insepect_id` int(10) NULL DEFAULT NULL COMMENT '点巡检id',
  `picture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关联图片',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品名称',
  `barcode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '商品编码',
  `spec` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `brand` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '品牌',
  `measure_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '计量单位',
  `class_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分类名称',
  `price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '采购单价（含税单价）',
  `repair_type_id` tinyint(1) NULL DEFAULT NULL COMMENT '维修类型id',
  `repair_type_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '维修类型文本',
  `rec_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '领用说明',
  `rec_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '领料出库数量（申领数量）',
  `rem_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '剩余数量(变动)',
  `sup_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '供应商名称',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `ph_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批次号',
  `warehouse_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '仓库ID',
  `warehouse_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  `warehouse_confirm` int(10) UNSIGNED NULL DEFAULT 0 COMMENT '仓库0初始1确认2驳回',
  `in_goods` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '领料出库绑定商品ID',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '商品id',
  `refundable_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '可退数量(暂时用不上)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `use_place_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用地点id，多个用,号隔开',
  `use_places` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '使用地点文本',
  `received_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已领料总数量',
  `issue_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '已发料总数量',
  `is_received_end` tinyint(1) NULL DEFAULT 0 COMMENT '是否领料完结，0：否，1：是',
  `stock_id` int(10) NULL DEFAULT NULL COMMENT '库存明细id,记录出库时是通过哪个库存明细出库的',
  `reserve_decimal` tinyint(1) UNSIGNED NULL DEFAULT 0 COMMENT '保留小数',
  `avg_before_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '平均单价(去税)',
  `avg_go_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '平均单价(含税)',
  `go_tax_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '去税单价',
  `go_tax_total_price` decimal(18, 7) NULL DEFAULT NULL COMMENT '去税小计',
  `tax_rate` tinyint(2) NULL DEFAULT NULL COMMENT '税率,默认13',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `wh_rec_id`(`wh_rec_id`) USING BTREE,
  INDEX `barcode`(`barcode`) USING BTREE,
  INDEX `ph_no`(`ph_no`) USING BTREE,
  INDEX `warehouse_id`(`warehouse_id`) USING BTREE,
  INDEX `warehouse_name`(`warehouse_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 762 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '领料出库单商品' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_rec_list
-- ----------------------------
DROP TABLE IF EXISTS `wh_rec_list`;
CREATE TABLE `wh_rec_list`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `wh_rec_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '领料出库单号',
  `all_price` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '总价',
  `all_num` decimal(18, 4) NULL DEFAULT 0.0000 COMMENT '数量',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `file_info` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `dept_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '制单人部门ID',
  `out_time` datetime NULL DEFAULT NULL COMMENT '出库日期',
  `receiver_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '领料人(制单人)',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废,7已审批(个人),8待领料(出库),9已确认(仓库),10,待确认',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `rp_uid` int(10) NULL DEFAULT NULL COMMENT '领料申请人uid，不填则为制单人',
  `ar_uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '指定领取人uid，多个用,号隔开',
  `ap_uid` int(10) NULL DEFAULT NULL COMMENT '最终审批人uid，只能一个',
  `rec_type` tinyint(1) UNSIGNED NULL DEFAULT NULL COMMENT '领料类型；1、物业；2、维修；3、保养',
  `receive_qrcode_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '领取确认小程序二维码',
  `is_force_receive` tinyint(1) NULL DEFAULT 0 COMMENT '是否强制完结；0：否；1：是；',
  `warehouse_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '仓库ID',
  `warehouse_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '仓库名称',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `wh_rec_no`(`wh_rec_no`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `dept_id`(`dept_id`) USING BTREE,
  INDEX `ct_name`(`ct_name`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 493 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '领料出库单列表' ROW_FORMAT = Dynamic;

