-- ----------------------------
-- Table structure for wh_rec_material_issue_record
-- ----------------------------
DROP TABLE IF EXISTS `wh_rec_material_issue_record`;
CREATE TABLE `wh_rec_material_issue_record`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '记录id',
  `rec_goods_rid` int(10) UNSIGNED NOT NULL COMMENT '领料明细id,wh_rec_goods主键id',
  `wh_rec_id` int(10) UNSIGNED NOT NULL COMMENT '领料出库单列表id',
