  INDEX `rec_goods_rid`(`rec_goods_rid`) USING BTREE,
  INDEX `receive_status`(`receive_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 313 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '领料出库单发料明细' ROW_FORMAT = DYNAMIC;

