  `order_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '单据ID',
  `detail_id` int(10) NOT NULL COMMENT '明细id',
  `goods_id` int(11) NULL DEFAULT NULL COMMENT '商品id',
  `stock_id` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '库存明细id',
  `operate_status` tinyint(1) NULL DEFAULT NULL COMMENT '操作类型；0：新增/编辑-未完成；1：删除-未完成 2：审批-已完成',
  `order_type` smallint(5) NULL DEFAULT NULL COMMENT '单据类型；1采购入库 2退货出库 3领料出库 4退料入库 5调拨 6盘点 7报废 8采购单 9采购退货单 10采购换货单 11设备维修单 12保养工单 13自主点检报修单',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '更换类型；1：换上设备；2：换下设备；3：领料',
  `unique_code` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '唯一标签',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `up_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '修改人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 441 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '库存唯一标签记录明细' ROW_FORMAT = DYNAMIC;

