-- ----------------------------
-- Table structure for wh_warehouse_safety_check_record
-- ----------------------------
DROP TABLE IF EXISTS `wh_warehouse_safety_check_record`;
CREATE TABLE `wh_warehouse_safety_check_record`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `order_no` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '单号',
  `check_date` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '检查日期（年月日）',
  `check_uids` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查组成员uid,多个用逗号隔开',
  `check_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查组成员文本',
  `dust_dept_id` int(11) NOT NULL COMMENT '责任部门id',
  `dust_dept_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '责任部门名称',
  `use_place_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用地点id（区域位置），多个用逗号隔开',
  `use_place_text` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '使用地点文本（区域位置）',
  `check_warehouse_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查仓库id，多个用逗号隔开',
  `check_warehouse_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查仓库文本',
  `desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查说明',
  `file_info` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附件信息',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `is_delete` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除；0：未删除；1：已删除	',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '状态；0待提审,1待审核,3已完成,4已撤回,5已驳回,6已作废；',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程信息',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '制单人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 32 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓库安全检查记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_warehouse_shift_record
-- ----------------------------
DROP TABLE IF EXISTS `wh_warehouse_shift_record`;
CREATE TABLE `wh_warehouse_shift_record`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `order_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '单据编号',
  `date_time` date NOT NULL COMMENT '交接日期',
  `group_id` int(10) NOT NULL COMMENT '班组id',
  `group_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '班组',
  `class_no` tinyint(1) NOT NULL COMMENT '班次 1-早 2-中 3-晚',
  `on_duty_uid` int(10) NULL DEFAULT NULL COMMENT '当班仓管员id',
  `on_duty_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '当班仓管员',
  `take_over_uid` int(10) NULL DEFAULT NULL COMMENT '接班仓管员id',
  `take_over_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '接班仓管员',
  `handover_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接班时间',
  `eq_op_stat` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '设备设施运行情况',
  `curr_shift_staff` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '当班人员情况',
  `fork_op_stat` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '叉车作业情况',
  `inv_storage` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '物资存储情况',
  `prod_prog` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '生产进度',
  `others` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '其它',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态；0：待提审；1：待审核；3：已完成；4：已撤回；5：已驳回；6：已作废；',
  `is_record_temp` tinyint(1) NULL DEFAULT 1 COMMENT '是否记录温度；1：是；2：否',
  `check_user_signature` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '提审人签名',
  `reviewer_user_signature` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审核人签名',
  `raw_wh_temp` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原材料仓库温度',
  `raw_wh_humidity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原材料仓库湿度',
  `product_wh_temp` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品仓库温度',
  `product_wh_humidity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '成品仓库湿度',
  `workshop_id` int(11) NULL DEFAULT NULL COMMENT '车间id',
  `workshop_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '车间名字',
  `raw_warehouse_id` int(11) NULL DEFAULT NULL COMMENT '原料库id',
  `raw_warehouse_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '原料库文本',
  `online_warehouse_id` int(11) NULL DEFAULT NULL COMMENT '在线库id',
  `online_warehouse_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '在线库文本',
  `line_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别id，多个用逗号隔开',
  `line` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '线别文本',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已删除 0-否 1-是',
  `review_uid` int(11) NULL DEFAULT NULL COMMENT '提审人id',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人id',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `ct_uid` int(11) NOT NULL COMMENT '创建人id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `process_arr` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '审批流程',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `status`(`status`) USING BTREE,
  INDEX `group_id`(`group_id`) USING BTREE,
  INDEX `date`(`date_time`) USING BTREE,
  INDEX `number`(`order_no`) USING BTREE,
  INDEX `class_no`(`class_no`) USING BTREE,
  INDEX `on_duty_uid`(`on_duty_uid`) USING BTREE,
  INDEX `take_over_uid`(`take_over_uid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓管员交接班记录' ROW_FORMAT = Dynamic;

