) ENGINE = InnoDB AUTO_INCREMENT = 69 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '仓管员交接班记录-原材料入库' ROW_FORMAT = Dynamic;

