  INDEX `create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '危废仓库分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for wh_workshop_contents_stock_take_assoc
-- ----------------------------
DROP TABLE IF EXISTS `wh_workshop_contents_stock_take_assoc`;
