  `transaction_type` tinyint(1) NULL DEFAULT NULL COMMENT '盈亏类型 1盘盈 2盘亏',
  `reserve_decimal` tinyint(1) NULL DEFAULT 4 COMMENT '保留小数点个数',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
