  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '内容',
  `ct_uid` int(10) UNSIGNED NULL DEFAULT NULL COMMENT '创建人UID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ct_uid`(`ct_uid`) USING BTREE,
  INDEX `create_time`(`create_time`) USING BTREE,
  INDEX `order_id`(`order_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '车间内容物盘点单单据日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for work_message
-- ----------------------------
DROP TABLE IF EXISTS `work_message`;
CREATE TABLE `work_message`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `document_type` int(11) NOT NULL COMMENT '单据类型 -2 品质库存预警 -1任务管理中心 1采购单;2采购退货单;3采购换货单;4采购入库单;5领料出库单;6退货出库单;7退料入库单;8拆装单;9调拨单;10盘点单;11报废单;12其它入库单;13退库清单;14维修工单；15:保养工单;16:巡点检记录;17空罐卷封检验报告 18内涂模检验报告 19顶盖/底盖检验报告 20热缩膜检验报告 21纸皮进货验报告 22原料标签标识报告 23空罐进货检验报告 24战马空罐检验报告 25原材料使用通知单 ;26保养计划；27点巡检计划28电表抄表记录；29水表抄表记录；30蒸汽表抄表记录；31燃气表抄表记录；',
  `document_id` int(11) NOT NULL COMMENT '单据id',
  `child_id` int(11) NULL DEFAULT NULL COMMENT '子id',
  `push_user_id` int(11) NULL DEFAULT NULL COMMENT '消息推送人id',
  `document_status` tinyint(1) NULL DEFAULT 0 COMMENT '推送消息时单据的状态',
  `user_id` int(10) NOT NULL COMMENT '消息接收者id',
  `jump_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '消息跳转类型；0：查看列表；1：查看详情（目前小程序只有领料单才能进入详情，所以先用这个做标识）',
  `operate_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '操作类型 0：待审批；1：仓库待确认；2：待确认领料；3：待查看（抄送推送）;4：待处理；5：待执行；6：提醒；7：异常提醒 8 待确认',
  `node_mark` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '流程节点标识(用于区分同单据多抄送节点)',
  `msg_content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '消息内容',
  `meter_type` tinyint(1) NULL DEFAULT NULL COMMENT '采集表类型 0：电表；1：水表；2：蒸汽表 3：燃气表；4：柴油',
  `note` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '附加信息',
  `is_read` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已读 0：未读；1：已读',
  `is_invalid` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否无效 0 否 1 是',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `is_read`(`is_read`) USING BTREE,
  INDEX `document_type`(`document_type`, `operate_type`, `is_read`) USING BTREE,
  INDEX `user_id`(`user_id`) USING BTREE,
  INDEX `meter_type`(`meter_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1043054 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for work_pending
-- ----------------------------
DROP TABLE IF EXISTS `work_pending`;
CREATE TABLE `work_pending`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `document_type` int(11) NOT NULL COMMENT '单据类型 -1 任务管理中心1采购单;2采购退货单;3采购换货单;4采购入库单;5领料出库单;6退货出库单;7退料入库单;8拆装单;9调拨单;10盘点单;11报废单;12其它入库单;13退库清单;14维修工单；15:保养工单;16:巡点检记录;17空罐卷封检验报告;18内涂模检验报告;19顶盖/底盖检验报告;20热缩膜检验报告;21纸皮进货验报告;22原料标签标识报告;23空罐进货检验报告;24战马空罐检验报告;25原材料使用通知单26保养计划单;27点巡检计划单;28电表抄表记录；29水表抄表记录；30蒸汽表抄表记录；31燃气表抄表记录；',
  `document_id` int(11) NOT NULL COMMENT '单据id',
  `detail_id` int(11) NULL DEFAULT NULL COMMENT '附加表id',
  `type` tinyint(1) NULL DEFAULT NULL COMMENT '单据细分类型',
  `user_id` int(10) NOT NULL COMMENT '处理人id',
  `trigger_user_id` int(10) NULL DEFAULT 0 COMMENT '触发人id',
  `document_status` tinyint(1) NULL DEFAULT 0 COMMENT '加入待办时单据的状态',
  `jump_type` tinyint(1) NULL DEFAULT 0 COMMENT '消息跳转类型；0：查看列表；1：查看详情（目前小程序只有领料单才能进入详情，所以先用这个做标识）',
  `operate_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '操作类型 0：待审批；1：仓库待确认；2：待确认领料；3：我发起；4：待检查；5：待执行；6：提醒 7: 异常提醒 8：待处理 9：待查看 10：待维修 11：待执行维修',
  `type_mark` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标识，用于判断是否重复推送的场景',
  `reason_type` tinyint(1) NULL DEFAULT NULL COMMENT '能源采集异常类型；1：数据采集异常；2：连接异常（小曾-无效）；3：连接异常（小曾-设备断开）；4：连接异常（监控时长报警）；5：用量超限',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附加信息',
  `is_deal` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否已处理 0：未处理；1：已处理',
  `is_invalid` tinyint(1) NULL DEFAULT 0 COMMENT '是否无效 0：有效；1：无效',
  `module_type` tinyint(2) UNSIGNED NOT NULL DEFAULT 0 COMMENT '所属模块；0：物料管理；1：设备管理；2：安全管理；3：质量管理；4：生产管理系统；5：能源管理系统',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `document_type_2`(`is_invalid`, `is_deal`) USING BTREE,
  INDEX `user_id`(`user_id`) USING BTREE,
  INDEX `document_type`(`document_id`, `document_type`, `user_id`, `trigger_user_id`, `operate_type`, `is_invalid`, `jump_type`) USING BTREE,
  INDEX `operate_type`(`operate_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 174807 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '待办表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for work_task
-- ----------------------------
DROP TABLE IF EXISTS `work_task`;
CREATE TABLE `work_task`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务编号',
  `task_type` tinyint(1) NULL DEFAULT 0 COMMENT '任务类型 0 常规任务 1 父子任务',
  `title` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务名称',
  `type` int(11) NOT NULL COMMENT '任务类型 来源work_task_setting.type = 1',
  `type_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务类型名称',
  `source` int(11) NOT NULL COMMENT '来源渠道 来源work_task_setting.type = 2',
  `source_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源名称',
  `question` int(11) NULL DEFAULT NULL COMMENT '问题分类 来源work_task_setting.type = 3',
  `question_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '问题分类名称',
  `similar` int(11) NULL DEFAULT NULL COMMENT '重复/相似类型 work_task_setting.type = 4',
  `similar_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '重复/相似类型名称',
  `start_date` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '开始时间',
  `end_date` datetime NULL DEFAULT NULL,
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '任务状态 -1 删除 0 未开始 1 待执行 2 执行中 3 待验收 4 已验收 5 已终止',
  `accep_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '验收人多个用逗号隔开',
  `over_accep_user` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '已完成验收人多个用逗号隔开',
  `exec_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '执行人多个用逗号隔开',
  `copy_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '抄送人多个用逗号隔开',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
  `measures` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '解决措施',
  `files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '附件',
  `remind` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '提醒时间',
  `release_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `exec_time` datetime NULL DEFAULT NULL COMMENT '执行时间',
  `exec_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行人',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `finish_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成人',
  `accep_time` datetime NULL DEFAULT NULL COMMENT '验收时间',
  `accep_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '验收人',
  `stop_time` datetime NULL DEFAULT NULL COMMENT '终止时间',
  `stop_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终止人',
  `stop_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终止原因',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `task_no`(`task_no`) USING BTREE,
  INDEX `type`(`type`) USING BTREE,
  INDEX `source`(`source`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 245 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务管理中心' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for work_task_chat
-- ----------------------------
DROP TABLE IF EXISTS `work_task_chat`;
CREATE TABLE `work_task_chat`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `assoc_id` int(11) NOT NULL COMMENT '单据ID',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '沟通信息',
  `files` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '沟通文件',
  `push_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '@人ID',
  `is_del` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除 0 否 1是',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人',
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `assoc_id`(`assoc_id`) USING BTREE,
  INDEX `is_del`(`is_del`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 117 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务管理中心沟通/动态' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for work_task_child
-- ----------------------------
DROP TABLE IF EXISTS `work_task_child`;
CREATE TABLE `work_task_child`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `p_id` int(11) NOT NULL COMMENT '父级ID',
  `task_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务编号',
  `title` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子任务名称',
  `status` tinyint(1) NULL DEFAULT 0 COMMENT '任务状态 -1 删除 0 未开始 1 待执行 2 执行中 3 待验收 4 已验收 5 已终止',
  `start_date` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_date` datetime NULL DEFAULT NULL,
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
  `exec_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '执行人多个用逗号隔开',
  `release_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `exec_time` datetime NULL DEFAULT NULL COMMENT '执行时间',
  `exec_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '执行人',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `finish_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '完成人',
  `accep_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '验收人',
  `accep_time` datetime NULL DEFAULT NULL COMMENT '验收时间',
  `accep_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '验收人',
  `stop_time` datetime NULL DEFAULT NULL COMMENT '终止时间',
  `stop_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终止人',
  `stop_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '终止原因',
  `reject_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `measures` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '解决措施',
  `ct_uid` int(11) NOT NULL COMMENT '创建人',
  `ct_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建人',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `p_id`(`p_id`) USING BTREE,
  INDEX `task_no`(`task_no`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 94 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务管理中心-子级任务' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for work_task_log
-- ----------------------------
DROP TABLE IF EXISTS `work_task_log`;
CREATE TABLE `work_task_log`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `assoc_id` int(11) NOT NULL COMMENT '单据ID',
  `type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作类型',
  `content` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '日志信息',
  `name` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '操作人',
  `ct_uid` int(11) NOT NULL COMMENT '操作人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `assoc_id`(`assoc_id`, `type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 209519 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务管理中心日志' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for work_task_setting
-- ----------------------------
DROP TABLE IF EXISTS `work_task_setting`;
CREATE TABLE `work_task_setting`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL DEFAULT 1 COMMENT '任务设置类型 1 任务类型 2 来源渠道3 问题分类 4 重复/相似类型 5 默认抄送人',
  `color` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '类型颜色',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '任务类型名称',
  `copy_user` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '默认抄送人',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态',
  `sort` int(11) NULL DEFAULT 0 COMMENT '显示顺序',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `order_module` tinyint(1) NULL DEFAULT NULL COMMENT '1 公司级年度重点工作 2 部门级年度重点工作',
  `ct_uid` int(11) NULL DEFAULT NULL COMMENT '创建人',
  `ct_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `up_uid` int(11) NULL DEFAULT NULL COMMENT '更新人',
  `up_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `type_2`(`type`, `name`) USING BTREE,
  UNIQUE INDEX `type_3`(`type`, `color`) USING BTREE,
  INDEX `type`(`type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务中心-设置' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for work_third_todo_map
-- ----------------------------
DROP TABLE IF EXISTS `work_third_todo_map`;
CREATE TABLE `work_third_todo_map`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '平台标识，例如 ding',
  `work_pending_id` int(10) UNSIGNED NOT NULL COMMENT '本地待办ID(work_pending.id)',
  `document_type` int(11) NOT NULL DEFAULT 0 COMMENT '单据类型',
  `document_id` int(11) NOT NULL DEFAULT 0 COMMENT '单据ID',
  `user_id` int(10) UNSIGNED NOT NULL COMMENT '本地待办所属用户ID',
  `operate_type` tinyint(1) NOT NULL DEFAULT 0 COMMENT '本地待办operate_type',
  `detail_id` int(11) NULL DEFAULT NULL COMMENT '附加表id(可空)',
  `ding_unionid` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '钉钉unionId(用于状态更新路径)',
  `ding_task_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '钉钉待办taskId',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0未完成1已完成(镜像状态)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_platform_pending`(`platform`, `work_pending_id`) USING BTREE,
  INDEX `idx_doc`(`platform`, `document_type`, `document_id`) USING BTREE,
  INDEX `idx_user`(`platform`, `user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 407 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '第三方待办映射表' ROW_FORMAT = Dynamic;

SET FOREIGN_KEY_CHECKS = 1;
